insert into ruleset_entries (ruleset_id, entry_type, human_readable, structured_data)
values
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'ability-scores', '{"name":"STR","desc":["Strength measures bodily power, athletic training, and the extent to which you can exert raw physical force.","A Strength check can model any attempt to lift, push, pull, or break something, to force your body through a space, or to otherwise apply brute force to a situation. The Athletics skill reflects aptitude in certain kinds of Strength checks."]}'::jsonb, '{"index":"str","name":"STR","full_name":"Strength","desc":["Strength measures bodily power, athletic training, and the extent to which you can exert raw physical force.","A Strength check can model any attempt to lift, push, pull, or break something, to force your body through a space, or to otherwise apply brute force to a situation. The Athletics skill reflects aptitude in certain kinds of Strength checks."],"skills":[{"name":"Athletics","index":"athletics","url":"/api/2014/skills/athletics"}],"url":"/api/2014/ability-scores/str"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'ability-scores', '{"name":"DEX","desc":["Dexterity measures agility, reflexes, and balance.","A Dexterity check can model any attempt to move nimbly, quickly, or quietly, or to keep from falling on tricky footing. The Acrobatics, Sleight of Hand, and Stealth skills reflect aptitude in certain kinds of Dexterity checks."]}'::jsonb, '{"index":"dex","name":"DEX","full_name":"Dexterity","desc":["Dexterity measures agility, reflexes, and balance.","A Dexterity check can model any attempt to move nimbly, quickly, or quietly, or to keep from falling on tricky footing. The Acrobatics, Sleight of Hand, and Stealth skills reflect aptitude in certain kinds of Dexterity checks."],"skills":[{"name":"Acrobatics","index":"acrobatics","url":"/api/2014/skills/acrobatics"},{"name":"Sleight of Hand","index":"sleight-of-hand","url":"/api/2014/skills/sleight-of-hand"},{"name":"Stealth","index":"stealth","url":"/api/2014/skills/stealth"}],"url":"/api/2014/ability-scores/dex"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'ability-scores', '{"name":"CON","desc":["Constitution measures health, stamina, and vital force.","Constitution checks are uncommon, and no skills apply to Constitution checks, because the endurance this ability represents is largely passive rather than involving a specific effort on the part of a character or monster."]}'::jsonb, '{"index":"con","name":"CON","full_name":"Constitution","desc":["Constitution measures health, stamina, and vital force.","Constitution checks are uncommon, and no skills apply to Constitution checks, because the endurance this ability represents is largely passive rather than involving a specific effort on the part of a character or monster."],"skills":[],"url":"/api/2014/ability-scores/con"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'ability-scores', '{"name":"INT","desc":["Intelligence measures mental acuity, accuracy of recall, and the ability to reason.","An Intelligence check comes into play when you need to draw on logic, education, memory, or deductive reasoning. The Arcana, History, Investigation, Nature, and Religion skills reflect aptitude in certain kinds of Intelligence checks."]}'::jsonb, '{"index":"int","name":"INT","full_name":"Intelligence","desc":["Intelligence measures mental acuity, accuracy of recall, and the ability to reason.","An Intelligence check comes into play when you need to draw on logic, education, memory, or deductive reasoning. The Arcana, History, Investigation, Nature, and Religion skills reflect aptitude in certain kinds of Intelligence checks."],"skills":[{"name":"Arcana","index":"arcana","url":"/api/2014/skills/arcana"},{"name":"History","index":"history","url":"/api/2014/skills/history"},{"name":"Investigation","index":"investigation","url":"/api/2014/skills/investigation"},{"name":"Nature","index":"nature","url":"/api/2014/skills/nature"},{"name":"Religion","index":"religion","url":"/api/2014/skills/religion"}],"url":"/api/2014/ability-scores/int"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'ability-scores', '{"name":"WIS","desc":["Wisdom reflects how attuned you are to the world around you and represents perceptiveness and intuition.","A Wisdom check might reflect an effort to read body language, understand someone''s feelings, notice things about the environment, or care for an injured person. The Animal Handling, Insight, Medicine, Perception, and Survival skills reflect aptitude in certain kinds of Wisdom checks."]}'::jsonb, '{"index":"wis","name":"WIS","full_name":"Wisdom","desc":["Wisdom reflects how attuned you are to the world around you and represents perceptiveness and intuition.","A Wisdom check might reflect an effort to read body language, understand someone''s feelings, notice things about the environment, or care for an injured person. The Animal Handling, Insight, Medicine, Perception, and Survival skills reflect aptitude in certain kinds of Wisdom checks."],"skills":[{"name":"Animal Handling","index":"animal-handling","url":"/api/2014/skills/animal-handling"},{"name":"Insight","index":"insight","url":"/api/2014/skills/insight"},{"name":"Medicine","index":"medicine","url":"/api/2014/skills/medicine"},{"name":"Perception","index":"perception","url":"/api/2014/skills/perception"},{"name":"Survival","index":"survival","url":"/api/2014/skills/survival"}],"url":"/api/2014/ability-scores/wis"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'ability-scores', '{"name":"CHA","desc":["Charisma measures your ability to interact effectively with others. It includes such factors as confidence and eloquence, and it can represent a charming or commanding personality.","A Charisma check might arise when you try to influence or entertain others, when you try to make an impression or tell a convincing lie, or when you are navigating a tricky social situation. The Deception, Intimidation, Performance, and Persuasion skills reflect aptitude in certain kinds of Charisma checks."]}'::jsonb, '{"index":"cha","name":"CHA","full_name":"Charisma","desc":["Charisma measures your ability to interact effectively with others. It includes such factors as confidence and eloquence, and it can represent a charming or commanding personality.","A Charisma check might arise when you try to influence or entertain others, when you try to make an impression or tell a convincing lie, or when you are navigating a tricky social situation. The Deception, Intimidation, Performance, and Persuasion skills reflect aptitude in certain kinds of Charisma checks."],"skills":[{"name":"Deception","index":"deception","url":"/api/2014/skills/deception"},{"name":"Intimidation","index":"intimidation","url":"/api/2014/skills/intimidation"},{"name":"Performance","index":"performance","url":"/api/2014/skills/performance"},{"name":"Persuasion","index":"persuasion","url":"/api/2014/skills/persuasion"}],"url":"/api/2014/ability-scores/cha"}'::jsonb);
insert into ruleset_entries (ruleset_id, entry_type, human_readable, structured_data)
values
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'alignments', '{"name":"Lawful Good","desc":"Lawful good (LG) creatures can be counted on to do the right thing as expected by society. Gold dragons, paladins, and most dwarves are lawful good."}'::jsonb, '{"index":"lawful-good","name":"Lawful Good","abbreviation":"LG","desc":"Lawful good (LG) creatures can be counted on to do the right thing as expected by society. Gold dragons, paladins, and most dwarves are lawful good.","url":"/api/2014/alignments/lawful-good"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'alignments', '{"name":"Neutral Good","desc":"Neutral good (NG) folk do the best they can to help others according to their needs. Many celestials, some cloud giants, and most gnomes are neutral good."}'::jsonb, '{"index":"neutral-good","name":"Neutral Good","abbreviation":"NG","desc":"Neutral good (NG) folk do the best they can to help others according to their needs. Many celestials, some cloud giants, and most gnomes are neutral good.","url":"/api/2014/alignments/neutral-good"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'alignments', '{"name":"Chaotic Good","desc":"Chaotic good (CG) creatures act as their conscience directs, with little regard for what others expect. Copper dragons, many elves, and unicorns are chaotic good."}'::jsonb, '{"index":"chaotic-good","name":"Chaotic Good","abbreviation":"CG","desc":"Chaotic good (CG) creatures act as their conscience directs, with little regard for what others expect. Copper dragons, many elves, and unicorns are chaotic good.","url":"/api/2014/alignments/chaotic-good"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'alignments', '{"name":"Lawful Neutral","desc":"Lawful neutral (LN) individuals act in accordance with law, tradition, or personal codes. Many monks and some wizards are lawful neutral."}'::jsonb, '{"index":"lawful-neutral","name":"Lawful Neutral","abbreviation":"LN","desc":"Lawful neutral (LN) individuals act in accordance with law, tradition, or personal codes. Many monks and some wizards are lawful neutral.","url":"/api/2014/alignments/lawful-neutral"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'alignments', '{"name":"Neutral","desc":"Neutral (N) is the alignment of those who prefer to steer clear of moral questions and don''t take sides, doing what seems best at the time. Lizardfolk, most druids, and many humans are neutral."}'::jsonb, '{"index":"neutral","name":"Neutral","abbreviation":"N","desc":"Neutral (N) is the alignment of those who prefer to steer clear of moral questions and don''t take sides, doing what seems best at the time. Lizardfolk, most druids, and many humans are neutral.","url":"/api/2014/alignments/neutral"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'alignments', '{"name":"Chaotic Neutral","desc":"Chaotic neutral (CN) creatures follow their whims, holding their personal freedom above all else. Many barbarians and rogues, and some bards, are chaotic neutral."}'::jsonb, '{"index":"chaotic-neutral","name":"Chaotic Neutral","abbreviation":"CN","desc":"Chaotic neutral (CN) creatures follow their whims, holding their personal freedom above all else. Many barbarians and rogues, and some bards, are chaotic neutral.","url":"/api/2014/alignments/chaotic-neutral"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'alignments', '{"name":"Lawful Evil","desc":"Lawful evil (LE) creatures methodically take what they want, within the limits of a code of tradition, loyalty, or order. Devils, blue dragons, and hobgoblins are lawful evil."}'::jsonb, '{"index":"lawful-evil","name":"Lawful Evil","abbreviation":"LE","desc":"Lawful evil (LE) creatures methodically take what they want, within the limits of a code of tradition, loyalty, or order. Devils, blue dragons, and hobgoblins are lawful evil.","url":"/api/2014/alignments/lawful-evil"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'alignments', '{"name":"Neutral Evil","desc":"Neutral evil (NE) is the alignment of those who do whatever they can get away with, without compassion or qualms. Many drow, some cloud giants, and goblins are neutral evil."}'::jsonb, '{"index":"neutral-evil","name":"Neutral Evil","abbreviation":"NE","desc":"Neutral evil (NE) is the alignment of those who do whatever they can get away with, without compassion or qualms. Many drow, some cloud giants, and goblins are neutral evil.","url":"/api/2014/alignments/neutral-evil"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'alignments', '{"name":"Chaotic Evil","desc":"Chaotic evil (CE) creatures act with arbitrary violence, spurred by their greed, hatred, or bloodlust. Demons, red dragons, and orcs are chaotic evil."}'::jsonb, '{"index":"chaotic-evil","name":"Chaotic Evil","abbreviation":"CE","desc":"Chaotic evil (CE) creatures act with arbitrary violence, spurred by their greed, hatred, or bloodlust. Demons, red dragons, and orcs are chaotic evil.","url":"/api/2014/alignments/chaotic-evil"}'::jsonb);
insert into ruleset_entries (ruleset_id, entry_type, human_readable, structured_data)
values
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'backgrounds', '{"name":"Acolyte","desc":null}'::jsonb, '{"index":"acolyte","name":"Acolyte","starting_proficiencies":[{"index":"skill-insight","name":"Skill: Insight","url":"/api/2014/proficiencies/skill-insight"},{"index":"skill-religion","name":"Skill: Religion","url":"/api/2014/proficiencies/skill-religion"}],"language_options":{"choose":2,"type":"languages","from":{"option_set_type":"resource_list","resource_list_url":"/api/2014/languages"}},"starting_equipment":[{"equipment":{"index":"clothes-common","name":"Clothes, common","url":"/api/2014/equipment/clothes-common"},"quantity":1},{"equipment":{"index":"pouch","name":"Pouch","url":"/api/2014/equipment/pouch"},"quantity":1}],"starting_gold":{"quantity":15,"unit":"gp"},"starting_equipment_options":[{"choose":1,"type":"equipment","from":{"option_set_type":"equipment_category","equipment_category":{"index":"holy-symbols","name":"Holy Symbols","url":"/api/2014/equipment-categories/holy-symbols"}}}],"feature":{"name":"Shelter of the Faithful","desc":["As an acolyte, you command the respect of those who share your faith, and you can perform the religious ceremonies of your deity. You and your adventuring companions can expect to receive free healing and care at a temple, shrine, or other established presence of your faith, though you must provide any material components needed for spells. Those who share your religion will support you (but only you) at a modest lifestyle.","You might also have ties to a specific temple dedicated to your chosen deity or pantheon, and you have a residence there. This could be the temple where you used to serve, if you remain on good terms with it, or a temple where you have found a new home. While near your temple, you can call upon the priests for assistance, provided the assistance you ask for is not hazardous and you remain in good standing with your temple."]},"personality_traits":{"choose":2,"type":"personality_traits","from":{"option_set_type":"options_array","options":[{"option_type":"string","string":"I idolize a particular hero of my faith, and constantly refer to that person''s deeds and example."},{"option_type":"string","string":"I can find common ground between the fiercest enemies, empathizing with them and always working toward peace."},{"option_type":"string","string":"I see omens in every event and action. The gods try to speak to us, we just need to listen."},{"option_type":"string","string":"Nothing can shake my optimistic attitude."},{"option_type":"string","string":"I quote (or misquote) sacred texts and proverbs in almost every situation."},{"option_type":"string","string":"I am tolerant (or intolerant) of other faiths and respect (or condemn) the worship of other gods."},{"option_type":"string","string":"I''ve enjoyed fine food, drink, and high society among my temple''s elite. Rough living grates on me."},{"option_type":"string","string":"I''ve spent so long in the temple that I have little practical experience dealing with people in the outside world."}]}},"ideals":{"choose":1,"type":"ideals","from":{"option_set_type":"options_array","options":[{"option_type":"ideal","desc":"Tradition. The ancient traditions of worship and sacrifice must be preserved and upheld.","alignments":[{"index":"lawful-good","name":"Lawful Good","url":"/api/2014/alignments/lawful-good"},{"index":"lawful-neutral","name":"Lawful Neutral","url":"/api/2014/alignments/lawful-neutral"},{"index":"lawful-evil","name":"Lawful Evil","url":"/api/2014/alignments/lawful-evil"}]},{"option_type":"ideal","desc":"Charity. I always try to help those in need, no matter what the personal cost.","alignments":[{"index":"lawful-good","name":"Lawful Good","url":"/api/2014/alignments/lawful-good"},{"index":"neutral-good","name":"Neutral Good","url":"/api/2014/alignments/neutral-good"},{"index":"chaotic-good","name":"Chaotic Good","url":"/api/2014/alignments/chaotic-good"}]},{"option_type":"ideal","desc":"Change. We must help bring about the changes the gods are constantly working in the world.","alignments":[{"index":"chaotic-good","name":"Chaotic Good","url":"/api/2014/alignments/chaotic-good"},{"index":"chaotic-neutral","name":"Chaotic Neutral","url":"/api/2014/alignments/chaotic-neutral"},{"index":"chaotic-evil","name":"Chaotic Evil","url":"/api/2014/alignments/chaotic-evil"}]},{"option_type":"ideal","desc":"Power. I hope to one day rise to the top of my faith''s religious hierarchy.","alignments":[{"index":"lawful-good","name":"Lawful Good","url":"/api/2014/alignments/lawful-good"},{"index":"lawful-neutral","name":"Lawful Neutral","url":"/api/2014/alignments/lawful-neutral"},{"index":"lawful-evil","name":"Lawful Evil","url":"/api/2014/alignments/lawful-evil"}]},{"option_type":"ideal","desc":"Faith. I trust that my deity will guide my actions. I have faith that if I work hard, things will go well.","alignments":[{"index":"lawful-good","name":"Lawful Good","url":"/api/2014/alignments/lawful-good"},{"index":"lawful-neutral","name":"Lawful Neutral","url":"/api/2014/alignments/lawful-neutral"},{"index":"lawful-evil","name":"Lawful Evil","url":"/api/2014/alignments/lawful-evil"}]},{"option_type":"ideal","desc":"Aspiration. I seek to prove myself worthy of my god''s favor by matching my actions against his or her teachings.","alignments":[{"index":"lawful-good","name":"Lawful Good","url":"/api/2014/alignments/lawful-good"},{"index":"neutral-good","name":"Neutral Good","url":"/api/2014/alignments/neutral-good"},{"index":"chaotic-good","name":"Chaotic Good","url":"/api/2014/alignments/chaotic-good"},{"index":"lawful-neutral","name":"Lawful Neutral","url":"/api/2014/alignments/lawful-neutral"},{"index":"neutral","name":"Neutral","url":"/api/2014/alignments/neutral"},{"index":"chaotic-neutral","name":"Chaotic Neutral","url":"/api/2014/alignments/chaotic-neutral"},{"index":"lawful-evil","name":"Lawful Evil","url":"/api/2014/alignments/lawful-evil"},{"index":"neutral-evil","name":"Neutral Evil","url":"/api/2014/alignments/neutral-evil"},{"index":"chaotic-evil","name":"Chaotic Evil","url":"/api/2014/alignments/chaotic-evil"}]}]}},"bonds":{"choose":1,"type":"bonds","from":{"option_set_type":"options_array","options":[{"option_type":"string","string":"I would die to recover an ancient relic of my faith that was lost long ago."},{"option_type":"string","string":"I will someday get revenge on the corrupt temple hierarchy who branded me a heretic."},{"option_type":"string","string":"I owe my life to the priest who took me in when my parents died."},{"option_type":"string","string":"Everything I do is for the common people."},{"option_type":"string","string":"I will do anything to protect the temple where I served."},{"option_type":"string","string":"I seek to preserve a sacred text that my enemies consider heretical and seek to destroy."}]}},"flaws":{"choose":1,"type":"flaws","from":{"option_set_type":"options_array","options":[{"option_type":"string","string":"I judge others harshly, and myself even more severely."},{"option_type":"string","string":"I put too much trust in those who wield power within my temple''s hierarchy."},{"option_type":"string","string":"My piety sometimes leads me to blindly trust those that profess faith in my god."},{"option_type":"string","string":"I am inflexible in my thinking."},{"option_type":"string","string":"I am suspicious of strangers and expect the worst of them."},{"option_type":"string","string":"Once I pick a goal, I become obsessed with it to the detriment of everything else in my life."}]}},"url":"/api/2014/backgrounds/acolyte"}'::jsonb);
insert into ruleset_entries (ruleset_id, entry_type, human_readable, structured_data)
values
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'classes', '{"name":"Barbarian","desc":null}'::jsonb, '{"index":"barbarian","name":"Barbarian","hit_die":12,"proficiency_choices":[{"desc":"Choose two from Animal Handling, Athletics, Intimidation, Nature, Perception, and Survival","choose":2,"type":"proficiencies","from":{"option_set_type":"options_array","options":[{"option_type":"reference","item":{"index":"skill-animal-handling","name":"Skill: Animal Handling","url":"/api/2014/proficiencies/skill-animal-handling"}},{"option_type":"reference","item":{"index":"skill-athletics","name":"Skill: Athletics","url":"/api/2014/proficiencies/skill-athletics"}},{"option_type":"reference","item":{"index":"skill-intimidation","name":"Skill: Intimidation","url":"/api/2014/proficiencies/skill-intimidation"}},{"option_type":"reference","item":{"index":"skill-nature","name":"Skill: Nature","url":"/api/2014/proficiencies/skill-nature"}},{"option_type":"reference","item":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"option_type":"reference","item":{"index":"skill-survival","name":"Skill: Survival","url":"/api/2014/proficiencies/skill-survival"}}]}}],"proficiencies":[{"index":"light-armor","name":"Light Armor","url":"/api/2014/proficiencies/light-armor"},{"index":"medium-armor","name":"Medium Armor","url":"/api/2014/proficiencies/medium-armor"},{"index":"shields","name":"Shields","url":"/api/2014/proficiencies/shields"},{"index":"simple-weapons","name":"Simple Weapons","url":"/api/2014/proficiencies/simple-weapons"},{"index":"martial-weapons","name":"Martial Weapons","url":"/api/2014/proficiencies/martial-weapons"},{"index":"saving-throw-str","name":"Saving Throw: STR","url":"/api/2014/proficiencies/saving-throw-str"},{"index":"saving-throw-con","name":"Saving Throw: CON","url":"/api/2014/proficiencies/saving-throw-con"}],"saving_throws":[{"index":"str","name":"STR","url":"/api/2014/ability-scores/str"},{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"}],"starting_equipment":[{"equipment":{"index":"explorers-pack","name":"Explorer''s Pack","url":"/api/2014/equipment/explorers-pack"},"quantity":1},{"equipment":{"index":"javelin","name":"Javelin","url":"/api/2014/equipment/javelin"},"quantity":4}],"starting_equipment_options":[{"desc":"(a) a greataxe or (b) any martial melee weapon","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":1,"of":{"index":"greataxe","name":"Greataxe","url":"/api/2014/equipment/greataxe"}},{"option_type":"choice","choice":{"desc":"any martial melee weapon","choose":1,"type":"equipment","from":{"option_set_type":"equipment_category","equipment_category":{"index":"martial-melee-weapons","name":"Martial Melee Weapons","url":"/api/2014/equipment-categories/martial-melee-weapons"}}}}]}},{"desc":"(a) two handaxes or (b) any simple weapon","choose":1,"type":"equipment","from":{"option_set_type":"options_array","options":[{"option_type":"counted_reference","count":2,"of":{"index":"handaxe","name":"Handaxe","url":"/api/2014/equipment/handaxe"}},{"option_type":"choice","choice":{"desc":"any simple weapon","choose":1,"type":"equipment","from":{"option_set_type":"equipment_category","equipment_category":{"index":"simple-weapons","name":"Simple Weapons","url":"/api/2014/equipment-categories/simple-weapons"}}}}]}}],"class_levels":"/api/2014/classes/barbarian/levels","multi_classing":{"prerequisites":[{"ability_score":{"index":"str","name":"STR","url":"/api/2014/ability-scores/str"},"minimum_score":13}],"proficiencies":[{"index":"shields","name":"Shields","url":"/api/2014/proficiencies/shields"},{"index":"simple-weapons","name":"Simple Weapons","url":"/api/2014/proficiencies/simple-weapons"},{"index":"martial-weapons","name":"Martial Weapons","url":"/api/2014/proficiencies/martial-weapons"}]},"subclasses":[{"index":"berserker","name":"Berserker","url":"/api/2014/subclasses/berserker"}],"url":"/api/2014/classes/barbarian"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'classes', '{"name":"Bard","desc":null}'::jsonb, '{"index":"bard","name":"Bard","hit_die":8,"proficiency_choices":[{"desc":"Choose any three","choose":3,"type":"proficiencies","from":{"option_set_type":"options_array","options":[{"option_type":"reference","item":{"index":"skill-acrobatics","name":"Skill: Acrobatics","url":"/api/2014/proficiencies/skill-acrobatics"}},{"option_type":"reference","item":{"index":"skill-animal-handling","name":"Skill: Animal Handling","url":"/api/2014/proficiencies/skill-animal-handling"}},{"option_type":"reference","item":{"index":"skill-arcana","name":"Skill: Arcana","url":"/api/2014/proficiencies/skill-arcana"}},{"option_type":"reference","item":{"index":"skill-athletics","name":"Skill: Athletics","url":"/api/2014/proficiencies/skill-athletics"}},{"option_type":"reference","item":{"index":"skill-deception","name":"Skill: Deception","url":"/api/2014/proficiencies/skill-deception"}},{"option_type":"reference","item":{"index":"skill-history","name":"Skill: History","url":"/api/2014/proficiencies/skill-history"}},{"option_type":"reference","item":{"index":"skill-insight","name":"Skill: Insight","url":"/api/2014/proficiencies/skill-insight"}},{"option_type":"reference","item":{"index":"skill-intimidation","name":"Skill: Intimidation","url":"/api/2014/proficiencies/skill-intimidation"}},{"option_type":"reference","item":{"index":"skill-investigation","name":"Skill: Investigation","url":"/api/2014/proficiencies/skill-investigation"}},{"option_type":"reference","item":{"index":"skill-medicine","name":"Skill: Medicine","url":"/api/2014/proficiencies/skill-medicine"}},{"option_type":"reference","item":{"index":"skill-nature","name":"Skill: Nature","url":"/api/2014/proficiencies/skill-nature"}},{"option_type":"reference","item":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"option_type":"reference","item":{"index":"skill-performance","name":"S