  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'damage-types', '{"name":"Force","desc":["Force is pure magical energy focused into a damaging form. Most effects that deal force damage are spells, including magic missile and spiritual weapon."]}'::jsonb, '{"index":"force","name":"Force","desc":["Force is pure magical energy focused into a damaging form. Most effects that deal force damage are spells, including magic missile and spiritual weapon."],"url":"/api/2014/damage-types/force"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'damage-types', '{"name":"Lightning","desc":["A lightning bolt spell and a blue dragon''s breath deal lightning damage."]}'::jsonb, '{"index":"lightning","name":"Lightning","desc":["A lightning bolt spell and a blue dragon''s breath deal lightning damage."],"url":"/api/2014/damage-types/lightning"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'damage-types', '{"name":"Necrotic","desc":["Necrotic damage, dealt by certain undead and a spell such as chill touch, withers matter and even the soul."]}'::jsonb, '{"index":"necrotic","name":"Necrotic","desc":["Necrotic damage, dealt by certain undead and a spell such as chill touch, withers matter and even the soul."],"url":"/api/2014/damage-types/necrotic"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'damage-types', '{"name":"Piercing","desc":["Puncturing and impaling attacks, including spears and monsters'' bites, deal piercing damage."]}'::jsonb, '{"index":"piercing","name":"Piercing","desc":["Puncturing and impaling attacks, including spears and monsters'' bites, deal piercing damage."],"url":"/api/2014/damage-types/piercing"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'damage-types', '{"name":"Poison","desc":["Venomous stings and the toxic gas of a green dragon''s breath deal poison damage."]}'::jsonb, '{"index":"poison","name":"Poison","desc":["Venomous stings and the toxic gas of a green dragon''s breath deal poison damage."],"url":"/api/2014/damage-types/poison"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'damage-types', '{"name":"Psychic","desc":["Mental abilities such as a psionic blast deal psychic damage."]}'::jsonb, '{"index":"psychic","name":"Psychic","desc":["Mental abilities such as a psionic blast deal psychic damage."],"url":"/api/2014/damage-types/psychic"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'damage-types', '{"name":"Radiant","desc":["Radiant damage, dealt by a cleric''s flame strike spell or an angel''s smiting weapon, sears the flesh like fire and overloads the spirit with power."]}'::jsonb, '{"index":"radiant","name":"Radiant","desc":["Radiant damage, dealt by a cleric''s flame strike spell or an angel''s smiting weapon, sears the flesh like fire and overloads the spirit with power."],"url":"/api/2014/damage-types/radiant"}'::jsonb),
