  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'equipment', '{"name":"Component pouch","desc":["A component pouch is a small, watertight leather belt pouch that has compartments to hold all the material components and other special items you need to cast your spells, except for those components that have a specific cost (as indicated in a spell''s description)."]}'::jsonb, '{"index":"component-pouch","name":"Component pouch","equipment_category":{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2014/equipment-categories/adventuring-gear"},"gear_category":{"index":"standard-gear","name":"Standard Gear","url":"/api/2014/equipment-categories/standard-gear"},"cost":{"quantity":25,"unit":"gp"},"weight":2,"desc":["A component pouch is a small, watertight leather belt pouch that has compartments to hold all the material components and other special items you need to cast your spells, except for those components that have a specific cost (as indicated in a spell''s description)."],"url":"/api/2014/equipment/component-pouch"}'::jsonb),
