  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'equipment', '{"name":"Saddle, Exotic","desc":["An exotic saddle is required for riding any aquatic or flying mount."]}'::jsonb, '{"index":"saddle-exotic","name":"Saddle, Exotic","equipment_category":{"index":"mounts-and-vehicles","name":"Mounts and Vehicles","url":"/api/2014/equipment-categories/mounts-and-vehicles"},"vehicle_category":"Tack, Harness, and Drawn Vehicles","cost":{"quantity":60,"unit":"gp"},"weight":50,"desc":["An exotic saddle is required for riding any aquatic or flying mount."],"url":"/api/2014/equipment/saddle-exotic"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'equipment', '{"name":"Saddle, Military","desc":["A military saddle braces the rider, helping you keep your seat on an active mount in battle. It gives you advantage on any check you make to remain mounted."]}'::jsonb, '{"index":"saddle-military","name":"Saddle, Military","equipment_category":{"index":"mounts-and-vehicles","name":"Mounts and Vehicles","url":"/api/2014/equipment-categories/mounts-and-vehicles"},"vehicle_category":"Tack, Harness, and Drawn Vehicles","cost":{"quantity":20,"unit":"gp"},"weight":30,"desc":["A military saddle braces the rider, helping you keep your seat on an active mount in battle. It gives you advantage on any check you make to remain mounted."],"url":"/api/2014/equipment/saddle-military"}'::jsonb),
