  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'equipment', '{"name":"Wagon","desc":null}'::jsonb, '{"index":"wagon","name":"Wagon","equipment_category":{"index":"mounts-and-vehicles","name":"Mounts and Vehicles","url":"/api/2014/equipment-categories/mounts-and-vehicles"},"vehicle_category":"Tack, Harness, and Drawn Vehicles","cost":{"quantity":35,"unit":"gp"},"weight":400,"url":"/api/2014/equipment/wagon"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'equipment', '{"name":"Galley","desc":null}'::jsonb, '{"index":"galley","name":"Galley","equipment_category":{"index":"mounts-and-vehicles","name":"Mounts and Vehicles","url":"/api/2014/equipment-categories/mounts-and-vehicles"},"vehicle_category":"Waterborne Vehicles","cost":{"quantity":30000,"unit":"gp"},"speed":{"quantity":4,"unit":"mph"},"url":"/api/2014/equipment/galley"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'equipment', '{"name":"Keelboat","desc":["Keelboats and rowboats are used on lakes and rivers. If going downstream, add the speed of the current (typically 3 miles per hour) to the speed of the vehicle. These vehicles can''t be rowed against any significant current, but they can be pulled upstream by draft animals on the shores. A rowboat weighs 100 pounds, in case adventurers carry it over land."]}'::jsonb, '{"index":"keelboat","name":"Keelboat","equipment_category":{"index":"mounts-and-vehicles","name":"Mounts and Vehicles","url":"/api/2014/equipment-categories/mounts-and-vehicles"},"vehicle_category":"Waterborne Vehicles","cost":{"quantity":3000,"unit":"gp"},"speed":{"quantity":1,"unit":"mph"},"desc":["Keelboats and rowboats are used on lakes and rivers. If going downstream, add the speed of the current (typically 3 miles per hour) to the speed of the vehicle. These vehicles can''t be rowed against any significant current, but they can be pulled upstream by draft animals on the shores. A rowboat weighs 100 pounds, in case adventurers carry it over land."],"url":"/api/2014/equipment/keelboat"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'equipment', '{"name":"Longship","desc":null}'::jsonb, '{"index":"longship","name":"Longship","equipment_category":{"index":"mounts-and-vehicles","name":"Mounts and Vehicles","url":"/api/2014/equipment-categories/mounts-and-vehicles"},"vehicle_category":"Waterborne Vehicles","cost":{"quantity":10000,"unit":"gp"},"speed":{"quantity":3,"unit":"mph"},"url":"/api/2014/equipment/longship"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'equipment', '{"name":"Rowboat","desc":["Keelboats and rowboats are used on lakes and rivers. If going downstream, add the speed of the current (typically 3 miles per hour) to the speed of the vehicle. These vehicles can''t be rowed against any significant current, but they can be pulled upstream by draft animals on the shores. A rowboat weighs 100 pounds, in case adventurers carry it over land."]}'::jsonb, '{"index":"rowboat","name":"Rowboat","equipment_category":{"index":"mounts-and-vehicles","name":"Mounts and Vehicles","url":"/api/2014/equipment-categories/mounts-and-vehicles"},"vehicle_category":"Waterborne Vehicles","cost":{"quantity":50,"unit":"gp"},"speed":{"quantity":1.5,"unit":"mph"},"desc":["Keelboats and rowboats are used on lakes and rivers. If going downstream, add the speed of the current (typically 3 miles per hour) to the speed of the vehicle. These vehicles can''t be rowed against any significant current, but they can be pulled upstream by draft animals on the shores. A rowboat weighs 100 pounds, in case adventurers carry it over land."],"url":"/api/2014/equipment/rowboat"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'equipment', '{"name":"Sailing ship","desc":null}'::jsonb, '{"index":"sailing-ship","name":"Sailing ship","equipment_category":{"index":"mounts-and-vehicles","name":"Mounts and Vehicles","url":"/api/2014/equipment-categories/mounts-and-vehicles"},"vehicle_category":"Waterborne Vehicles","cost":{"quantity":10000,"unit":"gp"},"speed":{"quantity":2,"unit":"mph"},"url":"/api/2014/equipment/sailing-ship"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'equipment', '{"name":"Warship","desc":null}'::jsonb, '{"index":"warship","name":"Warship","equipment_category":{"index":"mounts-and-vehicles","name":"Mounts and Vehicles","url":"/api/2014/equipment-categories/mounts-and-vehicles"},"vehicle_category":"Waterborne Vehicles","cost":{"quantity":25000,"unit":"gp"},"speed":{"quantity":2.5,"unit":"mph"},"url":"/api/2014/equipment/warship"}'::jsonb);
insert into ruleset_entries (ruleset_id, entry_type, human_readable, structured_data)
values
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'feats', '{"name":"Grappler","desc":["You’ve developed the Skills necessary to hold your own in close--quarters Grappling. You gain the following benefits:","- You have advantage on Attack Rolls against a creature you are Grappling.","- You can use your action to try to pin a creature Grappled by you. To do so, make another grapple check. If you succeed, you and the creature are both Restrained until the grapple ends."]}'::jsonb, '{"index":"grappler","name":"Grappler","prerequisites":[{"ability_score":{"index":"str","name":"STR","url":"/api/2014/ability-scores/str"},"minimum_score":13}],"desc":["You’ve developed the Skills necessary to hold your own in close--quarters Grappling. You gain the following benefits:","- You have advantage on Attack Rolls against a creature you are Grappling.","- You can use your action to try to pin a creature Grappled by you. To do so, make another grapple check. If you succeed, you and the creature are both Restrained until the grapple ends."],"url":"/api/2014/feats/grappler"}'::jsonb);
insert into ruleset_entries (ruleset_id, entry_type, human_readable, structured_data)
values
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Rage","desc":["In battle, you fight with primal ferocity. On your turn, you can enter a rage as a bonus action. While raging, you gain the following benefits if you aren''t wearing heavy armor:","- You have advantage on Strength checks and Strength saving throws.","- When you make a melee weapon Attack using Strength, you gain a +2 bonus to the damage roll. This bonus increases as you level.","- You have Resistance to bludgeoning, piercing, and slashing damage.","If you are able to cast Spells, you can''t cast them or concentrate on them while raging.","Your rage lasts for 1 minute. It ends early if you are knocked Unconscious or if Your Turn ends and you haven''t attacked a hostile creature since your last turn or taken damage since then. You can also end your rage on Your Turn as a Bonus Action.","Once you have raged the maximum number of times for your barbarian level, you must finish a Long Rest before you can rage again. You may rage 2 times at 1st level, 3 at 3rd, 4 at 6th, 5 at 12th, and 6 at 17th."]}'::jsonb, '{"index":"rage","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"name":"Rage","level":1,"prerequisites":[],"desc":["In battle, you fight with primal ferocity. On your turn, you can enter a rage as a bonus action. While raging, you gain the following benefits if you aren''t wearing heavy armor:","- You have advantage on Strength checks and Strength saving throws.","- When you make a melee weapon Attack using Strength, you gain a +2 bonus to the damage roll. This bonus increases as you level.","- You have Resistance to bludgeoning, piercing, and slashing damage.","If you are able to cast Spells, you can''t cast them or concentrate on them while raging.","Your rage lasts for 1 minute. It ends early if you are knocked Unconscious or if Your Turn ends and you haven''t attacked a hostile creature since your last turn or taken damage since then. You can also end your rage on Your Turn as a Bonus Action.","Once you have raged the maximum number of times for your barbarian level, you must finish a Long Rest before you can rage again. You may rage 2 times at 1st level, 3 at 3rd, 4 at 6th, 5 at 12th, and 6 at 17th."],"url":"/api/2014/features/rage"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Unarmored Defense","desc":["While you are not wearing any armor, your Armor Class equals 10 + your Dexterity modifier + your Constitution modifier. You can use a shield and still gain this benefit."]}'::jsonb, '{"index":"barbarian-unarmored-defense","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"name":"Unarmored Defense","level":1,"prerequisites":[],"desc":["While you are not wearing any armor, your Armor Class equals 10 + your Dexterity modifier + your Constitution modifier. You can use a shield and still gain this benefit."],"url":"/api/2014/features/barbarian-unarmored-defense"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Reckless Attack","desc":["Starting at 2nd level, you can throw aside all concern for defense to attack with fierce desperation. When you make your first attack on your turn, you can decide to attack recklessly. Doing so gives you advantage on melee weapon attack rolls using Strength during this turn, but attack rolls against you have advantage until your next turn."]}'::jsonb, '{"index":"reckless-attack","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"name":"Reckless Attack","level":2,"prerequisites":[],"desc":["Starting at 2nd level, you can throw aside all concern for defense to attack with fierce desperation. When you make your first attack on your turn, you can decide to attack recklessly. Doing so gives you advantage on melee weapon attack rolls using Strength during this turn, but attack rolls against you have advantage until your next turn."],"url":"/api/2014/features/reckless-attack"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Danger Sense","desc":["At 2nd level, you gain an uncanny sense of when things nearby aren''t as they should be, giving you an edge when you dodge away from danger. You have advantage on Dexterity saving throws against effects that you can see, such as traps and spells. To gain this benefit, you can''t be blinded, deafened, or incapacitated."]}'::jsonb, '{"index":"danger-sense","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"name":"Danger Sense","level":2,"prerequisites":[],"desc":["At 2nd level, you gain an uncanny sense of when things nearby aren''t as they should be, giving you an edge when you dodge away from danger. You have advantage on Dexterity saving throws against effects that you can see, such as traps and spells. To gain this benefit, you can''t be blinded, deafened, or incapacitated."],"url":"/api/2014/features/danger-sense"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Primal Path","desc":["At 3rd level, you choose a path that shapes the nature of your rage. Choose the Path of the Berserker or the Path of the Totem Warrior, both detailed at the end of the class description. Your choice grants you features at 3rd level and again at 6th, 10th, and 14th levels."]}'::jsonb, '{"index":"primal-path","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"name":"Primal Path","level":3,"prerequisites":[],"desc":["At 3rd level, you choose a path that shapes the nature of your rage. Choose the Path of the Berserker or the Path of the Totem Warrior, both detailed at the end of the class description. Your choice grants you features at 3rd level and again at 6th, 10th, and 14th levels."],"url":"/api/2014/features/primal-path"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Frenzy","desc":["Starting when you choose this path at 3rd level, you can go into a frenzy when you rage. If you do so, for the duration of your rage you can make a single melee weapon attack as a bonus action on each of your turns after this one. When your rage ends, you suffer one level of exhaustion (as described in appendix A)."]}'::jsonb, '{"index":"frenzy","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"subclass":{"index":"berserker","name":"Berserker","url":"/api/2014/subclasses/berserker"},"name":"Frenzy","level":3,"prerequisites":[],"desc":["Starting when you choose this path at 3rd level, you can go into a frenzy when you rage. If you do so, for the duration of your rage you can make a single melee weapon attack as a bonus action on each of your turns after this one. When your rage ends, you suffer one level of exhaustion (as described in appendix A)."],"url":"/api/2014/features/frenzy"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Ability Score Improvement","desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."]}'::jsonb, '{"index":"barbarian-ability-score-improvement-1","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"name":"Ability Score Improvement","level":4,"prerequisites":[],"desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."],"url":"/api/2014/features/barbarian-ability-score-improvement-1"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Extra Attack","desc":["Beginning at 5th level, you can attack twice, instead of once, whenever you take the Attack action on your turn."]}'::jsonb, '{"index":"barbarian-extra-attack","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"name":"Extra Attack","level":5,"prerequisites":[],"desc":["Beginning at 5th level, you can attack twice, instead of once, whenever you take the Attack action on your turn."],"url":"/api/2014/features/barbarian-extra-attack"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Fast Movement","desc":["Starting at 5th level, your speed increases by 10 feet while you aren''t wearing heavy armor."]}'::jsonb, '{"index":"fast-movement","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"name":"Fast Movement","level":5,"prerequisites":[],"desc":["Starting at 5th level, your speed increases by 10 feet while you aren''t wearing heavy armor."],"url":"/api/2014/features/fast-movement"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Mindless Rage","desc":["Beginning at 6th level, you can''t be charmed or frightened while raging. If you are charmed or frightened when you enter your rage, the effect is suspended for the duration of the rage."]}'::jsonb, '{"index":"mindless-rage","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"subclass":{"index":"berserker","name":"Berserker","url":"/api/2014/subclasses/berserker"},"name":"Mindless Rage","level":6,"prerequisites":[],"desc":["Beginning at 6th level, you can''t be charmed or frightened while raging. If you are charmed or frightened when you enter your rage, the effect is suspended for the duration of the rage."],"url":"/api/2014/features/mindless-rage"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Path feature","desc":["At 3rd level, you choose a path that shapes the nature of your rage. Choose the Path of the Berserker or the Path of the Totem Warrior, both detailed at the end of the class description. Your choice grants you features at 3rd level and again at 6th, 10th, and 14th levels."]}'::jsonb, '{"index":"primal-path-improvement-1","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"name":"Path feature","level":6,"prerequisites":[],"desc":["At 3rd level, you choose a path that shapes the nature of your rage. Choose the Path of the Berserker or the Path of the Totem Warrior, both detailed at the end of the class description. Your choice grants you features at 3rd level and again at 6th, 10th, and 14th levels."],"url":"/api/2014/features/primal-path-improvement-1"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Feral Instinct","desc":["By 7th level, your instincts are so honed that you have advantage on initiative rolls.","Additionally, if you are surprised at the beginning of combat and aren''t incapacitated, you can act normally on your first turn, but only if you enter your rage before doing anything else on that turn."]}'::jsonb, '{"index":"feral-instinct","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"name":"Feral Instinct","level":7,"prerequisites":[],"desc":["By 7th level, your instincts are so honed that you have advantage on initiative rolls.","Additionally, if you are surprised at the beginning of combat and aren''t incapacitated, you can act normally on your first turn, but only if you enter your rage before doing anything else on that turn."],"url":"/api/2014/features/feral-instinct"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Ability Score Improvement","desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."]}'::jsonb, '{"index":"barbarian-ability-score-improvement-2","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"name":"Ability Score Improvement","level":8,"prerequisites":[],"desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."],"url":"/api/2014/features/barbarian-ability-score-improvement-2"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Brutal Critical (1 die)","desc":["Beginning at 9th level, you can roll one additional weapon damage die when determining the extra damage for a critical hit with a melee attack. This increases to two additional dice at 13th level and three additional dice at 17th level."]}'::jsonb, '{"index":"brutal-critical-1-die","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"name":"Brutal Critical (1 die)","level":9,"prerequisites":[],"desc":["Beginning at 9th level, you can roll one additional weapon damage die when determining the extra damage for a critical hit with a melee attack. This increases to two additional dice at 13th level and three additional dice at 17th level."],"url":"/api/2014/features/brutal-critical-1-die"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Intimidating Presence","desc":["Beginning at 10th level, you can use your action to frighten someone with your menacing presence. When you do so, choose one creature that you can see within 30 feet of you. If the creature can see or hear you, it must succeed on a Wisdom saving throw (DC equal to 8 + your proficiency bonus + your Charisma modifier) or be frightened of you until the end of your next turn. On subsequent turns, you can use your action to extend the duration of this effect on the frightened creature until the end of your next turn. This effect ends if the creature ends its turn out of line of sight or more than 60 feet away from you."," If the creature succeeds on its saving throw, you can''t use this feature on that creature again for 24 hours."]}'::jsonb, '{"index":"intimidating-presence","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"subclass":{"index":"berserker","name":"Berserker","url":"/api/2014/subclasses/berserker"},"name":"Intimidating Presence","level":10,"prerequisites":[],"desc":["Beginning at 10th level, you can use your action to frighten someone with your menacing presence. When you do so, choose one creature that you can see within 30 feet of you. If the creature can see or hear you, it must succeed on a Wisdom saving throw (DC equal to 8 + your proficiency bonus + your Charisma modifier) or be frightened of you until the end of your next turn. On subsequent turns, you can use your action to extend the duration of this effect on the frightened creature until the end of your next turn. This effect ends if the creature ends its turn out of line of sight or more than 60 feet away from you."," If the creature succeeds on its saving throw, you can''t use this feature on that creature again for 24 hours."],"url":"/api/2014/features/intimidating-presence"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Path feature","desc":["At 3rd level, you choose a path that shapes the nature of your rage. Choose the Path of the Berserker or the Path of the Totem Warrior, both detailed at the end of the class description. Your choice grants you features at 3rd level and again at 6th, 10th, and 14th levels."]}'::jsonb, '{"index":"primal-path-improvement-2","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"name":"Path feature","level":10,"prerequisites":[],"desc":["At 3rd level, you choose a path that shapes the nature of your rage. Choose the Path of the Berserker or the Path of the Totem Warrior, both detailed at the end of the class description. Your choice grants you features at 3rd level and again at 6th, 10th, and 14th levels."],"url":"/api/2014/features/primal-path-improvement-2"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Relentless Rage","desc":["Starting at 11th level, your rage can keep you fighting despite grievous wounds. If you drop to 0 hit points while you''re raging and don''t die outright, you can make a DC 10 Constitution saving throw. If you succeed, you drop to 1 hit point instead.","Each time you use this feature after the first, the DC increases by 5. When you finish a short or long rest, the DC resets to 10."]}'::jsonb, '{"index":"relentless-rage","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"name":"Relentless Rage","level":11,"prerequisites":[],"desc":["Starting at 11th level, your rage can keep you fighting despite grievous wounds. If you drop to 0 hit points while you''re raging and don''t die outright, you can make a DC 10 Constitution saving throw. If you succeed, you drop to 1 hit point instead.","Each time you use this feature after the first, the DC increases by 5. When you finish a short or long rest, the DC resets to 10."],"url":"/api/2014/features/relentless-rage"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Ability Score Improvement","desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."]}'::jsonb, '{"index":"barbarian-ability-score-improvement-3","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"name":"Ability Score Improvement","level":12,"prerequisites":[],"desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."],"url":"/api/2014/features/barbarian-ability-score-improvement-3"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Brutal Critical (2 dice)","desc":["Beginning at 9th level, you can roll one additional weapon damage die when determining the extra damage for a critical hit with a melee attack. This increases to two additional dice at 13th level and three additional dice at 17th level."]}'::jsonb, '{"index":"brutal-critical-2-dice","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"name":"Brutal Critical (2 dice)","level":13,"prerequisites":[],"desc":["Beginning at 9th level, you can roll one additional weapon damage die when determining the extra damage for a critical hit with a melee attack. This increases to two additional dice at 13th level and three additional dice at 17th level."],"url":"/api/2014/features/brutal-critical-2-dice"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Retaliation","desc":["Starting at 14th level, when you take damage from a creature that is within 5 feet of you, you can use your reaction to make a melee weapon Attack against that creature."]}'::jsonb, '{"index":"retaliation","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"subclass":{"index":"berserker","name":"Berserker","url":"/api/2014/subclasses/berserker"},"name":"Retaliation","level":14,"prerequisites":[],"desc":["Starting at 14th level, when you take damage from a creature that is within 5 feet of you, you can use your reaction to make a melee weapon Attack against that creature."],"url":"/api/2014/features/retaliation"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Path feature","desc":["At 3rd level, you choose a path that shapes the nature of your rage. Choose the Path of the Berserker or the Path of the Totem Warrior, both detailed at the end of the class description. Your choice grants you features at 3rd level and again at 6th, 10th, and 14th levels."]}'::jsonb, '{"index":"primal-path-improvement-3","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"name":"Path feature","level":14,"prerequisites":[],"desc":["At 3rd level, you choose a path that shapes the nature of your rage. Choose the Path of the Berserker or the Path of the Totem Warrior, both detailed at the end of the class description. Your choice grants you features at 3rd level and again at 6th, 10th, and 14th levels."],"url":"/api/2014/features/primal-path-improvement-3"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Persistent Rage","desc":["Beginning at 15th level, your rage is so fierce that it ends early only if you fall unconscious or if you choose to end it."]}'::jsonb, '{"index":"persistent-rage","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"name":"Persistent Rage","level":15,"prerequisites":[],"desc":["Beginning at 15th level, your rage is so fierce that it ends early only if you fall unconscious or if you choose to end it."],"url":"/api/2014/features/persistent-rage"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Ability Score Improvement","desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."]}'::jsonb, '{"index":"barbarian-ability-score-improvement-4","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"name":"Ability Score Improvement","level":16,"prerequisites":[],"desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."],"url":"/api/2014/features/barbarian-ability-score-improvement-4"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Brutal Critical (3 dice)","desc":["Beginning at 9th level, you can roll one additional weapon damage die when determining the extra damage for a critical hit with a melee attack. This increases to two additional dice at 13th level and three additional dice at 17th level."]}'::jsonb, '{"index":"brutal-critical-3-dice","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"name":"Brutal Critical (3 dice)","level":17,"prerequisites":[],"desc":["Beginning at 9th level, you can roll one additional weapon damage die when determining the extra damage for a critical hit with a melee attack. This increases to two additional dice at 13th level and three additional dice at 17th level."],"url":"/api/2014/features/brutal-critical-3-dice"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Indomitable Might","desc":["Beginning at 18th level, if your total for a Strength check is less than your Strength score, you can use that score in place of the total."]}'::jsonb, '{"index":"indomitable-might","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"name":"Indomitable Might","level":18,"prerequisites":[],"desc":["Beginning at 18th level, if your total for a Strength check is less than your Strength score, you can use that score in place of the total."],"url":"/api/2014/features/indomitable-might"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Ability Score Improvement","desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."]}'::jsonb, '{"index":"barbarian-ability-score-improvement-5","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"name":"Ability Score Improvement","level":19,"prerequisites":[],"desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."],"url":"/api/2014/features/barbarian-ability-score-improvement-5"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Primal Champion","desc":["At 20th level, you embody the power of the wilds. Your Strength and Constitution scores increase by 4. Your maximum for those scores is now 24."]}'::jsonb, '{"index":"primal-champion","class":{"index":"barbarian","name":"Barbarian","url":"/api/2014/classes/barbarian"},"name":"Primal Champion","level":20,"prerequisites":[],"desc":["At 20th level, you embody the power of the wilds. Your Strength and Constitution scores increase by 4. Your maximum for those scores is now 24."],"url":"/api/2014/features/primal-champion"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Spellcasting: Bard","desc":["You have learned to untangle and reshape the fabric of reality in harmony with your wishes and music. Your spells are part of your vast repertoire, magic that you can tune to different situations."]}'::jsonb, '{"index":"spellcasting-bard","class":{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},"name":"Spellcasting: Bard","level":1,"prerequisites":[],"desc":["You have learned to untangle and reshape the fabric of reality in harmony with your wishes and music. Your spells are part of your vast repertoire, magic that you can tune to different situations."],"reference":"/api/2014/classes/bard/spellcasting","url":"/api/2014/features/spellcasting-bard"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Bardic Inspiration (d6)","desc":["You can inspire others through stirring words or music. To do so, you use a bonus action on your turn to choose one creature other than yourself within 60 feet of you who can hear you. That creature gains one Bardic Inspiration die, a d6. Once within the next 10 minutes, the creature can roll the die and add the number rolled to one ability check, attack roll, or saving throw it makes. The creature can wait until after it rolls the d20 before deciding to use the Bardic Inspiration die, but must decide before the GM says whether the roll succeeds or fails. Once the Bardic Inspiration die is rolled, it is lost. A creature can have only one Bardic Inspiration die at a time.","You can use this feature a number of times equal to your Charisma modifier (a minimum of once). You regain any expended uses when you finish a long rest. ","Your Bardic Inspiration die changes when you reach certain levels in this class. The die becomes a d8 at 5th level, a d10 at 10th level, and a d12 at 15th level."]}'::jsonb, '{"index":"bardic-inspiration-d6","class":{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},"name":"Bardic Inspiration (d6)","level":1,"prerequisites":[],"desc":["You can inspire others through stirring words or music. To do so, you use a bonus action on your turn to choose one creature other than yourself within 60 feet of you who can hear you. That creature gains one Bardic Inspiration die, a d6. Once within the next 10 minutes, the creature can roll the die and add the number rolled to one ability check, attack roll, or saving throw it makes. The creature can wait until after it rolls the d20 before deciding to use the Bardic Inspiration die, but must decide before the GM says whether the roll succeeds or fails. Once the Bardic Inspiration die is rolled, it is lost. A creature can have only one Bardic Inspiration die at a time.","You can use this feature a number of times equal to your Charisma modifier (a minimum of once). You regain any expended uses when you finish a long rest. ","Your Bardic Inspiration die changes when you reach certain levels in this class. The die becomes a d8 at 5th level, a d10 at 10th level, and a d12 at 15th level."],"url":"/api/2014/features/bardic-inspiration-d6"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Jack of All Trades","desc":["Starting at 2nd level, you can add half your proficiency bonus, rounded down, to any ability check you make that doesn''t already include your proficiency bonus."]}'::jsonb, '{"index":"jack-of-all-trades","class":{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},"name":"Jack of All Trades","level":2,"prerequisites":[],"desc":["Starting at 2nd level, you can add half your proficiency bonus, rounded down, to any ability check you make that doesn''t already include your proficiency bonus."],"url":"/api/2014/features/jack-of-all-trades"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Song of Rest (d6)","desc":["Beginning at 2nd level, you can use soothing music or oration to help revitalize your wounded allies during a short rest. If you or any friendly creatures who can hear your performance regain hit points at the end of the short rest by spending one or more Hit Dice, each of those creatures regains an extra 1d6 hit points. ","The extra hit points increase when you reach certain levels in this class: to 1d8 at 9th level, to 1d10 at 13th level, and to 1d12 at 17th level."]}'::jsonb, '{"index":"song-of-rest-d6","class":{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},"name":"Song of Rest (d6)","level":2,"prerequisites":[],"desc":["Beginning at 2nd level, you can use soothing music or oration to help revitalize your wounded allies during a short rest. If you or any friendly creatures who can hear your performance regain hit points at the end of the short rest by spending one or more Hit Dice, each of those creatures regains an extra 1d6 hit points. ","The extra hit points increase when you reach certain levels in this class: to 1d8 at 9th level, to 1d10 at 13th level, and to 1d12 at 17th level."],"url":"/api/2014/features/song-of-rest-d6"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Bard College","desc":["At 3rd level, you delve into the advanced techniques of a bard college of your choice, such as the College of Lore. Your choice grants you features at 3rd level and again at 6th and 14th level."]}'::jsonb, '{"index":"bard-college","class":{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},"name":"Bard College","level":3,"prerequisites":[],"desc":["At 3rd level, you delve into the advanced techniques of a bard college of your choice, such as the College of Lore. Your choice grants you features at 3rd level and again at 6th and 14th level."],"url":"/api/2014/features/bard-college"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Bonus Proficiencies","desc":["When you join the College of Lore at 3rd level, you gain proficiency with three skills of your choice."]}'::jsonb, '{"index":"bonus-proficiencies","class":{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},"subclass":{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},"name":"Bonus Proficiencies","level":3,"prerequisites":[],"desc":["When you join the College of Lore at 3rd level, you gain proficiency with three skills of your choice."],"url":"/api/2014/features/bonus-proficiencies"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Cutting Words","desc":["Also at 3rd level, you learn how to use your wit to distract, confuse, and otherwise sap the confidence and competence of others.","When a creature that you can see within 60 feet of you makes an attack roll, an ability check, or a damage roll, you can use your reaction to expend one of your uses of Bardic Inspiration, rolling a Bardic Inspiration die and subtracting the number rolled from the creature''s roll.","You can choose to use this feature after the creature makes its roll, but before the GM determines whether the attack roll or ability check succeeds or fails, or before the creature deals its damage. The creature is immune if it can''t hear you or if it''s immune to being charmed."]}'::jsonb, '{"index":"cutting-words","class":{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},"subclass":{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},"name":"Cutting Words","level":3,"prerequisites":[],"desc":["Also at 3rd level, you learn how to use your wit to distract, confuse, and otherwise sap the confidence and competence of others.","When a creature that you can see within 60 feet of you makes an attack roll, an ability check, or a damage roll, you can use your reaction to expend one of your uses of Bardic Inspiration, rolling a Bardic Inspiration die and subtracting the number rolled from the creature''s roll.","You can choose to use this feature after the creature makes its roll, but before the GM determines whether the attack roll or ability check succeeds or fails, or before the creature deals its damage. The creature is immune if it can''t hear you or if it''s immune to being charmed."],"url":"/api/2014/features/cutting-words"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Expertise","desc":["At 3rd level, choose two of your skill proficiencies. Your proficiency bonus is doubled for any ability check you make that uses either of the chosen proficiencies. At 10th level, you can choose another two skill proficiencies to gain this benefit."]}'::jsonb, '{"index":"bard-expertise-1","class":{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},"name":"Expertise","level":3,"prerequisites":[],"desc":["At 3rd level, choose two of your skill proficiencies. Your proficiency bonus is doubled for any ability check you make that uses either of the chosen proficiencies. At 10th level, you can choose another two skill proficiencies to gain this benefit."],"feature_specific":{"expertise_options":{"choose":2,"type":"proficiency","from":{"option_set_type":"options_array","options":[{"option_type":"reference","item":{"index":"skill-acrobatics","name":"Skill: Acrobatics","url":"/api/2014/proficiencies/skill-acrobatics"}},{"option_type":"reference","item":{"index":"skill-animal-handling","name":"Skill: Animal Handling","url":"/api/2014/proficiencies/skill-animal-handling"}},{"option_type":"reference","item":{"index":"skill-arcana","name":"Skill: Arcana","url":"/api/2014/proficiencies/skill-arcana"}},{"option_type":"reference","item":{"index":"skill-athletics","name":"Skill: Athletics","url":"/api/2014/proficiencies/skill-athletics"}},{"option_type":"reference","item":{"index":"skill-deception","name":"Skill: Deception","url":"/api/2014/proficiencies/skill-deception"}},{"option_type":"reference","item":{"index":"skill-history","name":"Skill: History","url":"/api/2014/proficiencies/skill-history"}},{"option_type":"reference","item":{"index":"skill-insight","name":"Skill: Insight","url":"/api/2014/proficiencies/skill-insight"}},{"option_type":"reference","item":{"index":"skill-intimidation","name":"Skill: Intimidation","url":"/api/2014/proficiencies/skill-intimidation"}},{"option_type":"reference","item":{"index":"skill-investigation","name":"Skill: Investigation","url":"/api/2014/proficiencies/skill-investigation"}},{"option_type":"reference","item":{"index":"skill-medicine","name":"Skill: Medicine","url":"/api/2014/proficiencies/skill-medicine"}},{"option_type":"reference","item":{"index":"skill-nature","name":"Skill: Nature","url":"/api/2014/proficiencies/skill-nature"}},{"option_type":"reference","item":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"option_type":"reference","item":{"index":"skill-performance","name":"Skill: Performance","url":"/api/2014/proficiencies/skill-performance"}},{"option_type":"reference","item":{"index":"skill-persuasion","name":"Skill: Persuasion","url":"/api/2014/proficiencies/skill-persuasion"}},{"option_type":"reference","item":{"index":"skill-religion","name":"Skill: Religion","url":"/api/2014/proficiencies/skill-religion"}},{"option_type":"reference","item":{"index":"skill-sleight-of-hand","name":"Skill: Sleight of Hand","url":"/api/2014/proficiencies/skill-sleight-of-hand"}},{"option_type":"reference","item":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}},{"option_type":"reference","item":{"index":"skill-survival","name":"Skill: Survival","url":"/api/2014/proficiencies/skill-survival"}}]}}},"url":"/api/2014/features/bard-expertise-1"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Ability Score Improvement","desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."]}'::jsonb, '{"index":"bard-ability-score-improvement-1","class":{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},"name":"Ability Score Improvement","level":4,"prerequisites":[],"desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."],"url":"/api/2014/features/bard-ability-score-improvement-1"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Bardic Inspiration (d8)","desc":["You can inspire others through stirring words or music. To do so, you use a bonus action on your turn to choose one creature other than yourself within 60 feet of you who can hear you. That creature gains one Bardic Inspiration die, a d6. Once within the next 10 minutes, the creature can roll the die and add the number rolled to one ability check, attack roll, or saving throw it makes. The creature can wait until after it rolls the d20 before deciding to use the Bardic Inspiration die, but must decide before the GM says whether the roll succeeds or fails. Once the Bardic Inspiration die is rolled, it is lost. A creature can have only one Bardic Inspiration die at a time.","You can use this feature a number of times equal to your Charisma modifier (a minimum of once). You regain any expended uses when you finish a long rest. ","Your Bardic Inspiration die changes when you reach certain levels in this class. The die becomes a d8 at 5th level, a d10 at 10th level, and a d12 at 15th level."]}'::jsonb, '{"index":"bardic-inspiration-d8","class":{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},"name":"Bardic Inspiration (d8)","level":5,"prerequisites":[],"desc":["You can inspire others through stirring words or music. To do so, you use a bonus action on your turn to choose one creature other than yourself within 60 feet of you who can hear you. That creature gains one Bardic Inspiration die, a d6. Once within the next 10 minutes, the creature can roll the die and add the number rolled to one ability check, attack roll, or saving throw it makes. The creature can wait until after it rolls the d20 before deciding to use the Bardic Inspiration die, but must decide before the GM says whether the roll succeeds or fails. Once the Bardic Inspiration die is rolled, it is lost. A creature can have only one Bardic Inspiration die at a time.","You can use this feature a number of times equal to your Charisma modifier (a minimum of once). You regain any expended uses when you finish a long rest. ","Your Bardic Inspiration die changes when you reach certain levels in this class. The die becomes a d8 at 5th level, a d10 at 10th level, and a d12 at 15th level."],"url":"/api/2014/features/bardic-inspiration-d8"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Font of Inspiration","desc":["Beginning when you reach 5th level, you regain all of your expended uses of Bardic Inspiration when you finish a short or long rest."]}'::jsonb, '{"index":"font-of-inspiration","class":{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},"name":"Font of Inspiration","level":5,"prerequisites":[],"desc":["Beginning when you reach 5th level, you regain all of your expended uses of Bardic Inspiration when you finish a short or long rest."],"url":"/api/2014/features/font-of-inspiration"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Countercharm","desc":["At 6th level, you gain the ability to use musical notes or words of power to disrupt mind-influencing effects. As an action, you can start a performance that lasts until the end of your next turn. During that time, you and any friendly creatures within 30 feet of you have advantage on saving throws against being frightened or charmed. A creature must be able to hear you to gain this benefit. The performance ends early if you are incapacitated or silenced or if you voluntarily end it (no action required)."]}'::jsonb, '{"index":"countercharm","class":{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},"name":"Countercharm","level":6,"prerequisites":[],"desc":["At 6th level, you gain the ability to use musical notes or words of power to disrupt mind-influencing effects. As an action, you can start a performance that lasts until the end of your next turn. During that time, you and any friendly creatures within 30 feet of you have advantage on saving throws against being frightened or charmed. A creature must be able to hear you to gain this benefit. The performance ends early if you are incapacitated or silenced or if you voluntarily end it (no action required)."],"url":"/api/2014/features/countercharm"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Bard College feature","desc":["At 3rd level, you delve into the advanced techniques of a bard college of your choice, such as the College of Lore. Your choice grants you features at 3rd level and again at 6th and 14th level."]}'::jsonb, '{"index":"bard-college-improvement-1","class":{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},"name":"Bard College feature","level":6,"prerequisites":[],"desc":["At 3rd level, you delve into the advanced techniques of a bard college of your choice, such as the College of Lore. Your choice grants you features at 3rd level and again at 6th and 14th level."],"url":"/api/2014/features/bard-college-improvement-1"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Additional Magical Secrets","desc":["At 6th level, you learn two spells of your choice from any class. A spell you choose must be of a level you can cast, as shown on the Bard table, or a cantrip. The chosen spells count as bard spells for you but don''t count against the number of bard spells you know."]}'::jsonb, '{"index":"additional-magical-secrets","class":{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},"subclass":{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},"name":"Additional Magical Secrets","level":6,"prerequisites":[],"desc":["At 6th level, you learn two spells of your choice from any class. A spell you choose must be of a level you can cast, as shown on the Bard table, or a cantrip. The chosen spells count as bard spells for you but don''t count against the number of bard spells you know."],"url":"/api/2014/features/additional-magical-secrets"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Ability Score Improvement","desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."]}'::jsonb, '{"index":"bard-ability-score-improvement-2","class":{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},"name":"Ability Score Improvement","level":8,"prerequisites":[],"desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."],"url":"/api/2014/features/bard-ability-score-improvement-2"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Song of Rest (d8)","desc":["Beginning at 2nd level, you can use soothing music or oration to help revitalize your wounded allies during a short rest. If you or any friendly creatures who can hear your performance regain hit points at the end of the short rest by spending one or more Hit Dice, each of those creatures regains an extra 1d6 hit points. ","The extra hit points increase when you reach certain levels in this class: to 1d8 at 9th level, to 1d10 at 13th level, and to 1d12 at 17th level."]}'::jsonb, '{"index":"song-of-rest-d8","class":{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},"name":"Song of Rest (d8)","level":9,"prerequisites":[],"desc":["Beginning at 2nd level, you can use soothing music or oration to help revitalize your wounded allies during a short rest. If you or any friendly creatures who can hear your performance regain hit points at the end of the short rest by spending one or more Hit Dice, each of those creatures regains an extra 1d6 hit points. ","The extra hit points increase when you reach certain levels in this class: to 1d8 at 9th level, to 1d10 at 13th level, and to 1d12 at 17th level."],"url":"/api/2014/features/song-of-rest-d8"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Bardic Inspiration (d10)","desc":["You can inspire others through stirring words or music. To do so, you use a bonus action on your turn to choose one creature other than yourself within 60 feet of you who can hear you. That creature gains one Bardic Inspiration die, a d6. Once within the next 10 minutes, the creature can roll the die and add the number rolled to one ability check, attack roll, or saving throw it makes. The creature can wait until after it rolls the d20 before deciding to use the Bardic Inspiration die, but must decide before the GM says whether the roll succeeds or fails. Once the Bardic Inspiration die is rolled, it is lost. A creature can have only one Bardic Inspiration die at a time.","You can use this feature a number of times equal to your Charisma modifier (a minimum of once). You regain any expended uses when you finish a long rest. ","Your Bardic Inspiration die changes when you reach certain levels in this class. The die becomes a d8 at 5th level, a d10 at 10th level, and a d12 at 15th level."]}'::jsonb, '{"index":"bardic-inspiration-d10","class":{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},"name":"Bardic Inspiration (d10)","level":10,"prerequisites":[],"desc":["You can inspire others through stirring words or music. To do so, you use a bonus action on your turn to choose one creature other than yourself within 60 feet of you who can hear you. That creature gains one Bardic Inspiration die, a d6. Once within the next 10 minutes, the creature can roll the die and add the number rolled to one ability check, attack roll, or saving throw it makes. The creature can wait until after it rolls the d20 before deciding to use the Bardic Inspiration die, but must decide before the GM says whether the roll succeeds or fails. Once the Bardic Inspiration die is rolled, it is lost. A creature can have only one Bardic Inspiration die at a time.","You can use this feature a number of times equal to your Charisma modifier (a minimum of once). You regain any expended uses when you finish a long rest. ","Your Bardic Inspiration die changes when you reach certain levels in this class. The die becomes a d8 at 5th level, a d10 at 10th level, and a d12 at 15th level."],"url":"/api/2014/features/bardic-inspiration-d10"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Expertise","desc":["At 3rd level, choose two of your skill proficiencies. Your proficiency bonus is doubled for any ability check you make that uses either of the chosen proficiencies. At 10th level, you can choose another two skill proficiencies to gain this benefit."]}'::jsonb, '{"index":"bard-expertise-2","class":{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},"name":"Expertise","level":10,"prerequisites":[],"desc":["At 3rd level, choose two of your skill proficiencies. Your proficiency bonus is doubled for any ability check you make that uses either of the chosen proficiencies. At 10th level, you can choose another two skill proficiencies to gain this benefit."],"feature_specific":{"expertise_options":{"choose":2,"type":"proficiency","from":{"option_set_type":"options_array","options":[{"option_type":"reference","item":{"index":"skill-acrobatics","name":"Skill: Acrobatics","url":"/api/2014/proficiencies/skill-acrobatics"}},{"option_type":"reference","item":{"index":"skill-animal-handling","name":"Skill: Animal Handling","url":"/api/2014/proficiencies/skill-animal-handling"}},{"option_type":"reference","item":{"index":"skill-arcana","name":"Skill: Arcana","url":"/api/2014/proficiencies/skill-arcana"}},{"option_type":"reference","item":{"index":"skill-athletics","name":"Skill: Athletics","url":"/api/2014/proficiencies/skill-athletics"}},{"option_type":"reference","item":{"index":"skill-deception","name":"Skill: Deception","url":"/api/2014/proficiencies/skill-deception"}},{"option_type":"reference","item":{"index":"skill-history","name":"Skill: History","url":"/api/2014/proficiencies/skill-history"}},{"option_type":"reference","item":{"index":"skill-insight","name":"Skill: Insight","url":"/api/2014/proficiencies/skill-insight"}},{"option_type":"reference","item":{"index":"skill-intimidation","name":"Skill: Intimidation","url":"/api/2014/proficiencies/skill-intimidation"}},{"option_type":