  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Peerless Skill","desc":["Starting at 14th level, when you make an ability check, you can expend one use of Bardic Inspiration. Roll a Bardic Inspiration die and add the number rolled to your ability check. You can choose to do so after you roll the die for the ability check, but before the GM tells you whether you succeed or fail."]}'::jsonb, '{"index":"peerless-skill","class":{"index":"bard","name":"Bard","url":"/api/2014/classes/bard"},"subclass":{"index":"lore","name":"Lore","url":"/api/2014/subclasses/lore"},"name":"Peerless Skill","level":14,"prerequisites":[],"desc":["Starting at 14th level, when you make an ability check, you can expend one use of Bardic Inspiration. Roll a Bardic Inspiration die and add the number rolled to your ability check. You can choose to do so after you roll the die for the ability check, but before the GM tells you whether you succeed or fail."],"url":"/api/2014/features/peerless-skill"}'::jsonb),
