  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Eldritch Invocation: Sculptor of Flesh","desc":["You can cast polymorph once using a warlock spell slot. You can''t do so again until you finish a long rest."]}'::jsonb, '{"index":"eldritch-invocation-sculptor-of-flesh","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Eldritch Invocation: Sculptor of Flesh","level":7,"prerequisites":[{"type":"level","level":7}],"desc":["You can cast polymorph once using a warlock spell slot. You can''t do so again until you finish a long rest."],"parent":{"index":"eldritch-invocations","name":"Eldritch Invocations","url":"/api/2014/features/eldritch-invocations"},"url":"/api/2014/features/eldritch-invocation-sculptor-of-flesh"}'::jsonb),
