  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Eldritch Invocation: Minions of Chaos","desc":["You can cast conjure elemental once using a warlock spell slot. You can''t do so again until you finish a long rest."]}'::jsonb, '{"index":"eldritch-invocation-minions-of-chaos","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Eldritch Invocation: Minions of Chaos","level":9,"prerequisites":[{"type":"level","level":9}],"desc":["You can cast conjure elemental once using a warlock spell slot. You can''t do so again until you finish a long rest."],"parent":{"index":"eldritch-invocations","name":"Eldritch Invocations","url":"/api/2014/features/eldritch-invocations"},"url":"/api/2014/features/eldritch-invocation-minions-of-chaos"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Eldritch Invocation: Otherworldly Leap","desc":["You can cast jump on yourself at will, without expending a spell slot or material components."]}'::jsonb, '{"index":"eldritch-invocation-otherworldly-leap","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Eldritch Invocation: Otherworldly Leap","level":9,"prerequisites":[{"type":"level","level":9}],"desc":["You can cast jump on yourself at will, without expending a spell slot or material components."],"parent":{"index":"eldritch-invocations","name":"Eldritch Invocations","url":"/api/2014/features/eldritch-invocations"},"url":"/api/2014/features/eldritch-invocation-otherworldly-leap"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Eldritch Invocation: Whispers of the Grave","desc":["You can cast speak with dead at will, without expending a spell slot."]}'::jsonb, '{"index":"eldritch-invocation-whispers-of-the-grave","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Eldritch Invocation: Whispers of the Grave","level":9,"prerequisites":[{"type":"level","level":9}],"desc":["You can cast speak with dead at will, without expending a spell slot."],"parent":{"index":"eldritch-invocations","name":"Eldritch Invocations","url":"/api/2014/features/eldritch-invocations"},"url":"/api/2014/features/eldritch-invocation-whispers-of-the-grave"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Otherworldly Patron feature","desc":["At 1st level, you have struck a bargain with an otherworldly being of your choice, such as the Fiend. Your choice grants you features at 1st level and again at 6th, 10th, and 14th level."]}'::jsonb, '{"index":"otherworldly-patron-improvement-2","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Otherworldly Patron feature","level":10,"prerequisites":[],"desc":["At 1st level, you have struck a bargain with an otherworldly being of your choice, such as the Fiend. Your choice grants you features at 1st level and again at 6th, 10th, and 14th level."],"url":"/api/2014/features/otherworldly-patron-improvement-2"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Eldritch Invocation: Lifedrinker","desc":["When you hit a creature with your pact weapon, the creature takes extra necrotic damage equal to your Charisma modifier (minimum 1)."]}'::jsonb, '{"index":"eldritch-invocation-lifedrinker","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Eldritch Invocation: Lifedrinker","level":12,"prerequisites":[{"type":"level","level":12},{"type":"feature","feature":"/api/2014/features/pact-of-the-blade"}],"desc":["When you hit a creature with your pact weapon, the creature takes extra necrotic damage equal to your Charisma modifier (minimum 1)."],"parent":{"index":"eldritch-invocations","name":"Eldritch Invocations","url":"/api/2014/features/eldritch-invocations"},"url":"/api/2014/features/eldritch-invocation-lifedrinker"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Otherworldly Patron feature","desc":["At 1st level, you have struck a bargain with an otherworldly being of your choice, such as the Fiend. Your choice grants you features at 1st level and again at 6th, 10th, and 14th level."]}'::jsonb, '{"index":"otherworldly-patron-improvement-3","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Otherworldly Patron feature","level":14,"prerequisites":[],"desc":["At 1st level, you have struck a bargain with an otherworldly being of your choice, such as the Fiend. Your choice grants you features at 1st level and again at 6th, 10th, and 14th level."],"url":"/api/2014/features/otherworldly-patron-improvement-3"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Eldritch Invocation: Chains of Carceri","desc":["You can cast hold monster at will--targeting a celestial, fiend, or elemental--without expending a spell slot or material components. You must finish a long rest before you can use this invocation on the same creature again."]}'::jsonb, '{"index":"eldritch-invocation-chains-of-carceri","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Eldritch Invocation: Chains of Carceri","level":15,"prerequisites":[{"type":"level","level":15},{"type":"feature","feature":"/api/2014/features/pact-of-the-chain"}],"desc":["You can cast hold monster at will--targeting a celestial, fiend, or elemental--without expending a spell slot or material components. You must finish a long rest before you can use this invocation on the same creature again."],"parent":{"index":"eldritch-invocations","name":"Eldritch Invocations","url":"/api/2014/features/eldritch-invocations"},"url":"/api/2014/features/eldritch-invocation-chains-of-carceri"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Eldritch Invocation: Master of Myriad Forms","desc":["You can cast alter self at will, without expending a spell slot."]}'::jsonb, '{"index":"eldritch-invocation-master-of-myriad-forms","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Eldritch Invocation: Master of Myriad Forms","level":15,"prerequisites":[{"type":"level","level":15}],"desc":["You can cast alter self at will, without expending a spell slot."],"parent":{"index":"eldritch-invocations","name":"Eldritch Invocations","url":"/api/2014/features/eldritch-invocations"},"url":"/api/2014/features/eldritch-invocation-master-of-myriad-forms"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Eldritch Invocation: Visions of Distant Realms","desc":["You can cast arcane eye at will, without expending a spell slot."]}'::jsonb, '{"index":"eldritch-invocation-visions-of-distant-realms","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Eldritch Invocation: Visions of Distant Realms","level":15,"prerequisites":[{"type":"level","level":15}],"desc":["You can cast arcane eye at will, without expending a spell slot."],"parent":{"index":"eldritch-invocations","name":"Eldritch Invocations","url":"/api/2014/features/eldritch-invocations"},"url":"/api/2014/features/eldritch-invocation-visions-of-distant-realms"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Eldritch Invocation: Witch Sight","desc":["You can see the true form of any shapechanger or creature concealed by illusion or transmutation magic while the creature is within 30 feet of you and within line of sight."]}'::jsonb, '{"index":"eldritch-invocation-witch-sight","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Eldritch Invocation: Witch Sight","level":15,"prerequisites":[{"type":"level","level":15}],"desc":["You can see the true form of any shapechanger or creature concealed by illusion or transmutation magic while the creature is within 30 feet of you and within line of sight."],"parent":{"index":"eldritch-invocations","name":"Eldritch Invocations","url":"/api/2014/features/eldritch-invocations"},"url":"/api/2014/features/eldritch-invocation-witch-sight"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Pact Boon","desc":["At 3rd level, your otherworldly patron bestows a gift upon you for your loyal service. You gain one of the following features of your choice."]}'::jsonb, '{"index":"pact-boon","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Pact Boon","level":3,"prerequisites":[],"desc":["At 3rd level, your otherworldly patron bestows a gift upon you for your loyal service. You gain one of the following features of your choice."],"feature_specific":{"subfeature_options":{"choose":1,"type":"feature","from":{"option_set_type":"options_array","options":[{"option_type":"reference","item":{"index":"pact-of-the-chain","name":"Pact of the Chain","url":"/api/2014/features/pact-of-the-chain"}},{"option_type":"reference","item":{"index":"pact-of-the-blade","name":"Pact of the Blade","url":"/api/2014/features/pact-of-the-blade"}},{"option_type":"reference","item":{"index":"pact-of-the-tome","name":"Pact of the Tome","url":"/api/2014/features/pact-of-the-tome"}}]}}},"url":"/api/2014/features/pact-boon"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Pact of the Chain","desc":["You learn the find familiar spell and can cast it as a ritual. The spell doesn''t count against your number of spells known.","When you cast the spell, you can choose one of the normal forms for your familiar or one of the following special forms: imp, pseudodragon, quasit, or sprite.","Additionally, when you take the Attack action, you can forgo one of your own attacks to allow your familiar to make one attack of its own with its reaction.","Your familiar is more cunning than a typical familiar. Its default form can be a reflection of your patron, with imps and quasits tied to the Fiend."]}'::jsonb, '{"index":"pact-of-the-chain","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Pact of the Chain","level":3,"prerequisites":[],"desc":["You learn the find familiar spell and can cast it as a ritual. The spell doesn''t count against your number of spells known.","When you cast the spell, you can choose one of the normal forms for your familiar or one of the following special forms: imp, pseudodragon, quasit, or sprite.","Additionally, when you take the Attack action, you can forgo one of your own attacks to allow your familiar to make one attack of its own with its reaction.","Your familiar is more cunning than a typical familiar. Its default form can be a reflection of your patron, with imps and quasits tied to the Fiend."],"parent":{"index":"pact-boon","name":"Pact Boon","url":"/api/2014/features/pact-boon"},"url":"/api/2014/features/pact-of-the-chain"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Pact of the Blade","desc":["You can use your action to create a pact weapon in your empty hand. You can choose the form that this melee weapon takes each time you create it. You are proficient with it while you wield it. This weapon counts as magical for the purpose of overcoming resistance and immunity to nonmagical attacks and damage.","Your pact weapon disappears if it is more than 5 feet away from you for 1 minute or more. It also disappears if you use this feature again, if you dismiss the weapon (no action required), or if you die.","You can transform one magic weapon into your pact weapon by performing a special ritual while you hold the weapon. You perform the ritual over the course of 1 hour, which can be done during a short rest. You can then dismiss the weapon, shunting it into an extradimensional space, and it appears whenever you create your pact weapon thereafter. You can''t affect an artifact or a sentient weapon in this way. The weapon ceases being your pact weapon if you die, if you perform the 1-hour ritual on a different weapon, or if you use a 1-hour ritual to break your bond to it. The weapon appears at your feet if it is in the extradimensional space when the bond breaks.","If you serve the Fiend, your weapon could be an axe made of black metal and adorned with decorative flames."]}'::jsonb, '{"index":"pact-of-the-blade","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Pact of the Blade","level":3,"prerequisites":[],"desc":["You can use your action to create a pact weapon in your empty hand. You can choose the form that this melee weapon takes each time you create it. You are proficient with it while you wield it. This weapon counts as magical for the purpose of overcoming resistance and immunity to nonmagical attacks and damage.","Your pact weapon disappears if it is more than 5 feet away from you for 1 minute or more. It also disappears if you use this feature again, if you dismiss the weapon (no action required), or if you die.","You can transform one magic weapon into your pact weapon by performing a special ritual while you hold the weapon. You perform the ritual over the course of 1 hour, which can be done during a short rest. You can then dismiss the weapon, shunting it into an extradimensional space, and it appears whenever you create your pact weapon thereafter. You can''t affect an artifact or a sentient weapon in this way. The weapon ceases being your pact weapon if you die, if you perform the 1-hour ritual on a different weapon, or if you use a 1-hour ritual to break your bond to it. The weapon appears at your feet if it is in the extradimensional space when the bond breaks.","If you serve the Fiend, your weapon could be an axe made of black metal and adorned with decorative flames."],"parent":{"index":"pact-boon","name":"Pact Boon","url":"/api/2014/features/pact-boon"},"url":"/api/2014/features/pact-of-the-blade"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Pact of the Tome","desc":["Your patron gives you a grimoire called a Book of Shadows. When you gain this feature, choose three cantrips from any class''s spell list (the three needn''t be from the same list). While the book is on your person, you can cast those cantrips at will. They don''t count against your number of cantrips known. If they don''t appear on the warlock spell list, they are nonetheless warlock spells for you.","If you lose your Book of Shadows, you can perform a 1-hour ceremony to receive a replacement from your patron. This ceremony can be performed during a short or long rest, and it destroys the previous book. The book turns to ash when you die.","Your Book of Shadows could be a weighty tome bound in demon hide studded with iron, holding spells of conjuration and a wealth of forbidden lore about the sinister regions of the cosmos, a gift of the Fiend."]}'::jsonb, '{"index":"pact-of-the-tome","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Pact of the Tome","level":3,"prerequisites":[],"desc":["Your patron gives you a grimoire called a Book of Shadows. When you gain this feature, choose three cantrips from any class''s spell list (the three needn''t be from the same list). While the book is on your person, you can cast those cantrips at will. They don''t count against your number of cantrips known. If they don''t appear on the warlock spell list, they are nonetheless warlock spells for you.","If you lose your Book of Shadows, you can perform a 1-hour ceremony to receive a replacement from your patron. This ceremony can be performed during a short or long rest, and it destroys the previous book. The book turns to ash when you die.","Your Book of Shadows could be a weighty tome bound in demon hide studded with iron, holding spells of conjuration and a wealth of forbidden lore about the sinister regions of the cosmos, a gift of the Fiend."],"parent":{"index":"pact-boon","name":"Pact Boon","url":"/api/2014/features/pact-boon"},"url":"/api/2014/features/pact-of-the-tome"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Ability Score Improvement","desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."]}'::jsonb, '{"index":"warlock-ability-score-improvement-1","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Ability Score Improvement","level":4,"prerequisites":[],"desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."],"url":"/api/2014/features/warlock-ability-score-improvement-1"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Dark One''s Own Luck","desc":["Starting at 6th level, you can call on your patron to alter fate in your favor. When you make an ability check or a saving throw, you can use this feature to add a d10 to your roll. You can do so after seeing the initial roll but before any of the roll''s effects occur.","Once you use this feature, you can''t use it again until you finish a short or long rest."]}'::jsonb, '{"index":"dark-ones-own-luck","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"subclass":{"index":"fiend","name":"Fiend","url":"/api/2014/subclasses/fiend"},"name":"Dark One''s Own Luck","level":6,"prerequisites":[],"desc":["Starting at 6th level, you can call on your patron to alter fate in your favor. When you make an ability check or a saving throw, you can use this feature to add a d10 to your roll. You can do so after seeing the initial roll but before any of the roll''s effects occur.","Once you use this feature, you can''t use it again until you finish a short or long rest."],"url":"/api/2014/features/dark-ones-own-luck"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Ability Score Improvement","desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."]}'::jsonb, '{"index":"warlock-ability-score-improvement-2","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Ability Score Improvement","level":8,"prerequisites":[],"desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."],"url":"/api/2014/features/warlock-ability-score-improvement-2"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Fiendish Resilience","desc":["Starting at 10th level, you can choose one damage type when you finish a short or long rest. You gain resistance to that damage type until you choose a different one with this feature. Damage from magical weapons or silver weapons ignores this resistance."]}'::jsonb, '{"index":"fiendish-resilience","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"subclass":{"index":"fiend","name":"Fiend","url":"/api/2014/subclasses/fiend"},"name":"Fiendish Resilience","level":10,"prerequisites":[],"desc":["Starting at 10th level, you can choose one damage type when you finish a short or long rest. You gain resistance to that damage type until you choose a different one with this feature. Damage from magical weapons or silver weapons ignores this resistance."],"url":"/api/2014/features/fiendish-resilience"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Mystic Arcanum (6th level)","desc":["At 11th level, your patron bestows upon you a magical secret called an arcanum. Choose one 6th- level spell from the warlock spell list as this arcanum.","You can cast your arcanum spell once without expending a spell slot. You must finish a long rest before you can do so again.","At higher levels, you gain more warlock spells of your choice that can be cast in this way: one 7th- level spell at 13th level, one 8th-level spell at 15th level, and one 9th-level spell at 17th level. You regain all uses of your Mystic Arcanum when you finish a long rest."]}'::jsonb, '{"index":"mystic-arcanum-6th-level","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Mystic Arcanum (6th level)","level":11,"prerequisites":[],"desc":["At 11th level, your patron bestows upon you a magical secret called an arcanum. Choose one 6th- level spell from the warlock spell list as this arcanum.","You can cast your arcanum spell once without expending a spell slot. You must finish a long rest before you can do so again.","At higher levels, you gain more warlock spells of your choice that can be cast in this way: one 7th- level spell at 13th level, one 8th-level spell at 15th level, and one 9th-level spell at 17th level. You regain all uses of your Mystic Arcanum when you finish a long rest."],"url":"/api/2014/features/mystic-arcanum-6th-level"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Ability Score Improvement","desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."]}'::jsonb, '{"index":"warlock-ability-score-improvement-3","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Ability Score Improvement","level":12,"prerequisites":[],"desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."],"url":"/api/2014/features/warlock-ability-score-improvement-3"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Mystic Arcanum (7th level)","desc":["At 11th level, your patron bestows upon you a magical secret called an arcanum. Choose one 6th- level spell from the warlock spell list as this arcanum.","You can cast your arcanum spell once without expending a spell slot. You must finish a long rest before you can do so again.","At higher levels, you gain more warlock spells of your choice that can be cast in this way: one 7th- level spell at 13th level, one 8th-level spell at 15th level, and one 9th-level spell at 17th level. You regain all uses of your Mystic Arcanum when you finish a long rest."]}'::jsonb, '{"index":"mystic-arcanum-7th-level","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Mystic Arcanum (7th level)","level":13,"prerequisites":[],"desc":["At 11th level, your patron bestows upon you a magical secret called an arcanum. Choose one 6th- level spell from the warlock spell list as this arcanum.","You can cast your arcanum spell once without expending a spell slot. You must finish a long rest before you can do so again.","At higher levels, you gain more warlock spells of your choice that can be cast in this way: one 7th- level spell at 13th level, one 8th-level spell at 15th level, and one 9th-level spell at 17th level. You regain all uses of your Mystic Arcanum when you finish a long rest."],"url":"/api/2014/features/mystic-arcanum-7th-level"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Hurl Through Hell","desc":["Starting at 14th level, when you hit a creature with an attack, you can use this feature to instantly transport the target through the lower planes. The creature disappears and hurtles through a nightmare landscape.","At the end of your next turn, the target returns to the space it previously occupied, or the nearest unoccupied space. If the target is not a fiend, it takes 10d10 psychic damage as it reels from its horrific experience.","Once you use this feature, you can''t use it again until you finish a long rest."]}'::jsonb, '{"index":"hurl-through-hell","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"subclass":{"index":"fiend","name":"Fiend","url":"/api/2014/subclasses/fiend"},"name":"Hurl Through Hell","level":14,"prerequisites":[],"desc":["Starting at 14th level, when you hit a creature with an attack, you can use this feature to instantly transport the target through the lower planes. The creature disappears and hurtles through a nightmare landscape.","At the end of your next turn, the target returns to the space it previously occupied, or the nearest unoccupied space. If the target is not a fiend, it takes 10d10 psychic damage as it reels from its horrific experience.","Once you use this feature, you can''t use it again until you finish a long rest."],"url":"/api/2014/features/hurl-through-hell"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Mystic Arcanum (8th level)","desc":["At 11th level, your patron bestows upon you a magical secret called an arcanum. Choose one 6th- level spell from the warlock spell list as this arcanum.","You can cast your arcanum spell once without expending a spell slot. You must finish a long rest before you can do so again.","At higher levels, you gain more warlock spells of your choice that can be cast in this way: one 7th- level spell at 13th level, one 8th-level spell at 15th level, and one 9th-level spell at 17th level. You regain all uses of your Mystic Arcanum when you finish a long rest."]}'::jsonb, '{"index":"mystic-arcanum-8th-level","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Mystic Arcanum (8th level)","level":15,"prerequisites":[],"desc":["At 11th level, your patron bestows upon you a magical secret called an arcanum. Choose one 6th- level spell from the warlock spell list as this arcanum.","You can cast your arcanum spell once without expending a spell slot. You must finish a long rest before you can do so again.","At higher levels, you gain more warlock spells of your choice that can be cast in this way: one 7th- level spell at 13th level, one 8th-level spell at 15th level, and one 9th-level spell at 17th level. You regain all uses of your Mystic Arcanum when you finish a long rest."],"url":"/api/2014/features/mystic-arcanum-8th-level"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Ability Score Improvement","desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."]}'::jsonb, '{"index":"warlock-ability-score-improvement-4","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Ability Score Improvement","level":16,"prerequisites":[],"desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."],"url":"/api/2014/features/warlock-ability-score-improvement-4"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Mystic Arcanum (9th level)","desc":["At 11th level, your patron bestows upon you a magical secret called an arcanum. Choose one 6th- level spell from the warlock spell list as this arcanum.","You can cast your arcanum spell once without expending a spell slot. You must finish a long rest before you can do so again.","At higher levels, you gain more warlock spells of your choice that can be cast in this way: one 7th- level spell at 13th level, one 8th-level spell at 15th level, and one 9th-level spell at 17th level. You regain all uses of your Mystic Arcanum when you finish a long rest."]}'::jsonb, '{"index":"mystic-arcanum-9th-level","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Mystic Arcanum (9th level)","level":17,"prerequisites":[],"desc":["At 11th level, your patron bestows upon you a magical secret called an arcanum. Choose one 6th- level spell from the warlock spell list as this arcanum.","You can cast your arcanum spell once without expending a spell slot. You must finish a long rest before you can do so again.","At higher levels, you gain more warlock spells of your choice that can be cast in this way: one 7th- level spell at 13th level, one 8th-level spell at 15th level, and one 9th-level spell at 17th level. You regain all uses of your Mystic Arcanum when you finish a long rest."],"url":"/api/2014/features/mystic-arcanum-9th-level"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Ability Score Improvement","desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."]}'::jsonb, '{"index":"warlock-ability-score-improvement-5","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Ability Score Improvement","level":19,"prerequisites":[],"desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."],"url":"/api/2014/features/warlock-ability-score-improvement-5"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Eldritch Master","desc":["At 20th level, you can draw on your inner reserve of mystical power while entreating your patron to regain expended spell slots. You can spend 1 minute entreating your patron for aid to regain all your expended spell slots from your Pact Magic feature.","Once you regain spell slots with this feature, you must finish a long rest before you can do so again."]}'::jsonb, '{"index":"eldritch-master","class":{"index":"warlock","name":"Warlock","url":"/api/2014/classes/warlock"},"name":"Eldritch Master","level":20,"prerequisites":[],"desc":["At 20th level, you can draw on your inner reserve of mystical power while entreating your patron to regain expended spell slots. You can spend 1 minute entreating your patron for aid to regain all your expended spell slots from your Pact Magic feature.","Once you regain spell slots with this feature, you must finish a long rest before you can do so again."],"url":"/api/2014/features/eldritch-master"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Spellcasting: Wizard","desc":["As a student of arcane magic, you have a spellbook containing spells that show the first glimmerings of your true power."]}'::jsonb, '{"index":"spellcasting-wizard","class":{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"},"name":"Spellcasting: Wizard","level":1,"prerequisites":[],"desc":["As a student of arcane magic, you have a spellbook containing spells that show the first glimmerings of your true power."],"reference":"/api/2014/classes/wizard/spellcasting","url":"/api/2014/features/spellcasting-wizard"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Arcane Recovery","desc":["You have learned to regain some of your magical energy by studying your spellbook. Once per day when you finish a short rest, you can choose expended spell slots to recover. The spell slots can have a combined level that is equal to or less than half your wizard level (rounded up), and none of the slots can be 6th level or higher.","For example, if you''re a 4th-level wizard, you can recover up to two levels worth of spell slots. You can recover either a 2nd-level spell slot or two 1st-level spell slots."]}'::jsonb, '{"index":"arcane-recovery","class":{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"},"name":"Arcane Recovery","level":1,"prerequisites":[],"desc":["You have learned to regain some of your magical energy by studying your spellbook. Once per day when you finish a short rest, you can choose expended spell slots to recover. The spell slots can have a combined level that is equal to or less than half your wizard level (rounded up), and none of the slots can be 6th level or higher.","For example, if you''re a 4th-level wizard, you can recover up to two levels worth of spell slots. You can recover either a 2nd-level spell slot or two 1st-level spell slots."],"url":"/api/2014/features/arcane-recovery"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Arcane Tradition","desc":["When you reach 2nd level, you choose an arcane tradition, shaping your practice of magic through one of eight schools, such as Evocation.","Your choice grants you features at 2nd level and again at 6th, 10th, and 14th level."]}'::jsonb, '{"index":"arcane-tradition","class":{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"},"name":"Arcane Tradition","level":2,"prerequisites":[],"desc":["When you reach 2nd level, you choose an arcane tradition, shaping your practice of magic through one of eight schools, such as Evocation.","Your choice grants you features at 2nd level and again at 6th, 10th, and 14th level."],"url":"/api/2014/features/arcane-tradition"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Evocation Savant","desc":["Beginning when you select this school at 2nd level, the gold and time you must spend to copy an evocation spell into your spellbook is halved."]}'::jsonb, '{"index":"evocation-savant","class":{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"},"subclass":{"index":"evocation","name":"Evocation","url":"/api/2014/subclasses/evocation"},"name":"Evocation Savant","level":2,"prerequisites":[],"desc":["Beginning when you select this school at 2nd level, the gold and time you must spend to copy an evocation spell into your spellbook is halved."],"url":"/api/2014/features/evocation-savant"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Sculpt Spells","desc":["Beginning at 2nd level, you can create pockets of relative safety within the effects of your evocation spells. When you cast an evocation spell that affects other creatures that you can see, you can choose a number of them equal to 1 + the spell''s level. The chosen creatures automatically succeed on their saving throws against the spell, and they take no damage if they would normally take half damage on a successful save."]}'::jsonb, '{"index":"sculpt-spells","class":{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"},"subclass":{"index":"evocation","name":"Evocation","url":"/api/2014/subclasses/evocation"},"name":"Sculpt Spells","level":2,"prerequisites":[],"desc":["Beginning at 2nd level, you can create pockets of relative safety within the effects of your evocation spells. When you cast an evocation spell that affects other creatures that you can see, you can choose a number of them equal to 1 + the spell''s level. The chosen creatures automatically succeed on their saving throws against the spell, and they take no damage if they would normally take half damage on a successful save."],"url":"/api/2014/features/sculpt-spells"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Ability Score Improvement","desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."]}'::jsonb, '{"index":"wizard-ability-score-improvement-1","class":{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"},"name":"Ability Score Improvement","level":4,"prerequisites":[],"desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."],"url":"/api/2014/features/wizard-ability-score-improvement-1"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Arcane Tradition feature","desc":["When you reach 2nd level, you choose an arcane tradition, shaping your practice of magic through one of eight schools, such as Evocation.","Your choice grants you features at 2nd level and again at 6th, 10th, and 14th level."]}'::jsonb, '{"index":"arcane-tradition-improvement-1","class":{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"},"name":"Arcane Tradition feature","level":6,"prerequisites":[],"desc":["When you reach 2nd level, you choose an arcane tradition, shaping your practice of magic through one of eight schools, such as Evocation.","Your choice grants you features at 2nd level and again at 6th, 10th, and 14th level."],"url":"/api/2014/features/arcane-tradition-improvement-1"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Potent Cantrip","desc":["Starting at 6th level, your damaging cantrips affect even creatures that avoid the brunt of the effect. When a creature succeeds on a saving throw against your cantrip, the creature takes half the cantrip''s damage (if any) but suffers no additional effect from the cantrip."]}'::jsonb, '{"index":"potent-cantrip","class":{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"},"subclass":{"index":"evocation","name":"Evocation","url":"/api/2014/subclasses/evocation"},"name":"Potent Cantrip","level":6,"prerequisites":[],"desc":["Starting at 6th level, your damaging cantrips affect even creatures that avoid the brunt of the effect. When a creature succeeds on a saving throw against your cantrip, the creature takes half the cantrip''s damage (if any) but suffers no additional effect from the cantrip."],"url":"/api/2014/features/potent-cantrip"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Ability Score Improvement","desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."]}'::jsonb, '{"index":"wizard-ability-score-improvement-2","class":{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"},"name":"Ability Score Improvement","level":8,"prerequisites":[],"desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."],"url":"/api/2014/features/wizard-ability-score-improvement-2"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Arcane Tradition feature","desc":["When you reach 2nd level, you choose an arcane tradition, shaping your practice of magic through one of eight schools, such as Evocation.","Your choice grants you features at 2nd level and again at 6th, 10th, and 14th level."]}'::jsonb, '{"index":"arcane-tradition-improvement-2","class":{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"},"name":"Arcane Tradition feature","level":10,"prerequisites":[],"desc":["When you reach 2nd level, you choose an arcane tradition, shaping your practice of magic through one of eight schools, such as Evocation.","Your choice grants you features at 2nd level and again at 6th, 10th, and 14th level."],"url":"/api/2014/features/arcane-tradition-improvement-2"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Empowered Evocation","desc":["Beginning at 10th level, you can add your Intelligence modifier to one damage roll of any wizard evocation spell you cast."]}'::jsonb, '{"index":"empowered-evocation","class":{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"},"subclass":{"index":"evocation","name":"Evocation","url":"/api/2014/subclasses/evocation"},"name":"Empowered Evocation","level":10,"prerequisites":[],"desc":["Beginning at 10th level, you can add your Intelligence modifier to one damage roll of any wizard evocation spell you cast."],"url":"/api/2014/features/empowered-evocation"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Ability Score Improvement","desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."]}'::jsonb, '{"index":"wizard-ability-score-improvement-3","class":{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"},"name":"Ability Score Improvement","level":12,"prerequisites":[],"desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."],"url":"/api/2014/features/wizard-ability-score-improvement-3"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Arcane Tradition feature","desc":["When you reach 2nd level, you choose an arcane tradition, shaping your practice of magic through one of eight schools, such as Evocation.","Your choice grants you features at 2nd level and again at 6th, 10th, and 14th level."]}'::jsonb, '{"index":"arcane-tradition-improvement-3","class":{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"},"name":"Arcane Tradition feature","level":14,"prerequisites":[],"desc":["When you reach 2nd level, you choose an arcane tradition, shaping your practice of magic through one of eight schools, such as Evocation.","Your choice grants you features at 2nd level and again at 6th, 10th, and 14th level."],"url":"/api/2014/features/arcane-tradition-improvement-3"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Overchannel","desc":["Starting at 14th level, you can increase the power of your simpler spells. When you cast a wizard spell of 1st through 5th level that deals damage, you can deal maximum damage with that spell.","The first time you do so, you suffer no adverse effect. If you use this feature again before you finish a long rest, you take 2d12 necrotic damage for each level of the spell, immediately after you cast it. Each time you use this feature again before finishing a long rest, the necrotic damage per spell level increases by 1d12. This damage ignores resistance and immunity."]}'::jsonb, '{"index":"overchannel","class":{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"},"subclass":{"index":"evocation","name":"Evocation","url":"/api/2014/subclasses/evocation"},"name":"Overchannel","level":14,"prerequisites":[],"desc":["Starting at 14th level, you can increase the power of your simpler spells. When you cast a wizard spell of 1st through 5th level that deals damage, you can deal maximum damage with that spell.","The first time you do so, you suffer no adverse effect. If you use this feature again before you finish a long rest, you take 2d12 necrotic damage for each level of the spell, immediately after you cast it. Each time you use this feature again before finishing a long rest, the necrotic damage per spell level increases by 1d12. This damage ignores resistance and immunity."],"url":"/api/2014/features/overchannel"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Ability Score Improvement","desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."]}'::jsonb, '{"index":"wizard-ability-score-improvement-4","class":{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"},"name":"Ability Score Improvement","level":16,"prerequisites":[],"desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."],"url":"/api/2014/features/wizard-ability-score-improvement-4"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Spell Mastery","desc":["At 18th level, you have achieved such mastery over certain spells that you can cast them at will. Choose a 1st-level wizard spell and a 2nd-level wizard spell that are in your spellbook. You can cast those spells at their lowest level without expending a spell slot when you have them prepared. If you want to cast either spell at a higher level, you must expend a spell slot as normal.","By spending 8 hours in study, you can exchange one or both of the spells you chose for different spells of the same levels."]}'::jsonb, '{"index":"spell-mastery","class":{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"},"name":"Spell Mastery","level":18,"prerequisites":[],"desc":["At 18th level, you have achieved such mastery over certain spells that you can cast them at will. Choose a 1st-level wizard spell and a 2nd-level wizard spell that are in your spellbook. You can cast those spells at their lowest level without expending a spell slot when you have them prepared. If you want to cast either spell at a higher level, you must expend a spell slot as normal.","By spending 8 hours in study, you can exchange one or both of the spells you chose for different spells of the same levels."],"url":"/api/2014/features/spell-mastery"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Ability Score Improvement","desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."]}'::jsonb, '{"index":"wizard-ability-score-improvement-5","class":{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"},"name":"Ability Score Improvement","level":19,"prerequisites":[],"desc":["When you reach 4th level, and again at 8th, 12th, 16th, and 19th level, you can increase one ability score of your choice by 2, or you can increase two ability scores of your choice by 1. As normal, you can''t increase an ability score above 20 using this feature."],"url":"/api/2014/features/wizard-ability-score-improvement-5"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'features', '{"name":"Signature Spell","desc":["When you reach 20th level, you gain mastery over two powerful spells and can cast them with little effort. Choose two 3rd-level wizard spells in your spellbook as your signature spells. You always have these spells prepared, they don''t count against the number of spells you have prepared, and you can cast each of them once at 3rd level without expending a spell slot. When you do so, you can''t do so again until you finish a short or long rest.","If you want to cast either spell at a higher level, you must expend a spell slot as normal."]}'::jsonb, '{"index":"signature-spell","class":{"index":"wizard","name":"Wizard","url":"/api/2014/classes/wizard"},"name":"Signature Spell","level":20,"prerequisites":[],"desc":["When you reach 20th level, you gain mastery over two powerful spells and can cast them with little effort. Choose two 3rd-level wizard spells in your spellbook as your signature spells. You always have these spells prepared, they don''t count against the number of spells you have prepared, and you can cast each of them once at 3rd level without expending a spell slot. When you do so, you can''t do so again until you finish a short or long rest.","If you want to cast either spell at a higher level, you must expend a spell slot as normal."],"url":"/api/2014/features/signature-spell"}'::jsonb);
