values
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'languages', '{"name":"Common","desc":null}'::jsonb, '{"index":"common","name":"Common","type":"Standard","typical_speakers":["Humans"],"script":"Common","url":"/api/2014/languages/common"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'languages', '{"name":"Dwarvish","desc":"Dwarvish is full of hard consonants and guttural sounds."}'::jsonb, '{"index":"dwarvish","name":"Dwarvish","desc":"Dwarvish is full of hard consonants and guttural sounds.","type":"Standard","typical_speakers":["Dwarves"],"script":"Dwarvish","url":"/api/2014/languages/dwarvish"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'languages', '{"name":"Elvish","desc":"Elvish is fluid, with subtle intonations and intricate grammar. Elven literature is rich and varied, and their songs and poems are famous among other races. Many bards learn their language so they can add Elvish ballads to their repertoires."}'::jsonb, '{"index":"elvish","name":"Elvish","desc":"Elvish is fluid, with subtle intonations and intricate grammar. Elven literature is rich and varied, and their songs and poems are famous among other races. Many bards learn their language so they can add Elvish ballads to their repertoires.","type":"Standard","typical_speakers":["Elves"],"script":"Elvish","url":"/api/2014/languages/elvish"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'languages', '{"name":"Giant","desc":null}'::jsonb, '{"index":"giant","name":"Giant","type":"Standard","typical_speakers":["Ogres","Giants"],"script":"Dwarvish","url":"/api/2014/languages/giant"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'languages', '{"name":"Gnomish","desc":"The Gnomish language, which uses the Dwarvish script, is renowned for its technical treatises and its catalogs of knowledge about the natural world."}'::jsonb, '{"index":"gnomish","name":"Gnomish","desc":"The Gnomish language, which uses the Dwarvish script, is renowned for its technical treatises and its catalogs of knowledge about the natural world.","type":"Standard","typical_speakers":["Gnomes"],"script":"Dwarvish","url":"/api/2014/languages/gnomish"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'languages', '{"name":"Goblin","desc":null}'::jsonb, '{"index":"goblin","name":"Goblin","type":"Standard","typical_speakers":["Goblinoids"],"script":"Dwarvish","url":"/api/2014/languages/goblin"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'languages', '{"name":"Halfling","desc":"The Halfling language isn''t secret, but halflings are loath to share it with others. They write very little, so they don''t have a rich body of literature. Their oral tradition, however, is very strong."}'::jsonb, '{"index":"halfling","name":"Halfling","desc":"The Halfling language isn''t secret, but halflings are loath to share it with others. They write very little, so they don''t have a rich body of literature. Their oral tradition, however, is very strong.","type":"Standard","typical_speakers":["Halflings"],"script":"Common","url":"/api/2014/languages/halfling"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'languages', '{"name":"Orc","desc":"Orc is a harsh, grating language with hard consonants. It has no script of its own but is written in the Dwarvish script."}'::jsonb, '{"index":"orc","name":"Orc","desc":"Orc is a harsh, grating language with hard consonants. It has no script of its own but is written in the Dwarvish script.","type":"Standard","typical_speakers":["Orcs"],"script":"Dwarvish","url":"/api/2014/languages/orc"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'languages', '{"name":"Abyssal","desc":null}'::jsonb, '{"index":"abyssal","name":"Abyssal","type":"Exotic","typical_speakers":["Demons"],"script":"Infernal","url":"/api/2014/languages/abyssal"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'languages', '{"name":"Celestial","desc":null}'::jsonb, '{"index":"celestial","name":"Celestial","type":"Exotic","typical_speakers":["Celestials"],"script":"Celestial","url":"/api/2014/languages/celestial"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'languages', '{"name":"Draconic","desc":"Draconic is thought to be one of the oldest languages and is often used in the study of magic. The language sounds harsh to most other creatures and includes numerous hard consonants and sibilants."}'::jsonb, '{"index":"draconic","name":"Draconic","desc":"Draconic is thought to be one of the oldest languages and is often used in the study of magic. The language sounds harsh to most other creatures and includes numerous hard consonants and sibilants.","type":"Exotic","typical_speakers":["Dragons","Dragonborn"],"script":"Draconic","url":"/api/2014/languages/draconic"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'languages', '{"name":"Deep Speech","desc":null}'::jsonb, '{"index":"deep-speech","name":"Deep Speech","type":"Exotic","typical_speakers":["Aboleths","Cloakers"],"url":"/api/2014/languages/deep-speech"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'languages', '{"name":"Infernal","desc":null}'::jsonb, '{"index":"infernal","name":"Infernal","type":"Exotic","typical_speakers":["Devils"],"script":"Infernal","url":"/api/2014/languages/infernal"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'languages', '{"name":"Primordial","desc":null}'::jsonb, '{"index":"primordial","name":"Primordial","type":"Exotic","typical_speakers":["Elementals"],"script":"Dwarvish","url":"/api/2014/languages/primordial"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'languages', '{"name":"Sylvan","desc":null}'::jsonb, '{"index":"sylvan","name":"Sylvan","type":"Exotic","typical_speakers":["Fey creatures"],"script":"Elvish","url":"/api/2014/languages/sylvan"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'languages', '{"name":"Undercommon","desc":null}'::jsonb, '{"index":"undercommon","name":"Undercommon","type":"Exotic","typical_speakers":["Underdark traders"],"script":"Elvish","url":"/api/2014/languages/undercommon"}'::jsonb);
