  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'magic-items', '{"name":"Potion of Cloud Giant Strength","desc":["Potion, very rare","When you drink this potion, your Strength score changes to 27 for 1 hour. The potion has no effect on you if your Strength is equal to or greater than that score.","This potion''s transparent liquid has floating in it a sliver of fingernail from a cloud giant."]}'::jsonb, '{"index":"potion-of-giant-strength-cloud","name":"Potion of Cloud Giant Strength","equipment_category":{"index":"potion","name":"Potion","url":"/api/2014/equipment-categories/potion"},"rarity":{"name":"Very Rare"},"variants":[],"variant":true,"desc":["Potion, very rare","When you drink this potion, your Strength score changes to 27 for 1 hour. The potion has no effect on you if your Strength is equal to or greater than that score.","This potion''s transparent liquid has floating in it a sliver of fingernail from a cloud giant."],"url":"/api/2014/magic-items/potion-of-giant-strength-cloud"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'magic-items', '{"name":"Potion of Storm Giant Strength","desc":["Potion, legendary","When you drink this potion, your Strength score changes to 29 for 1 hour. The potion has no effect on you if your Strength is equal to or greater than that score.","This potion''s transparent liquid has floating in it a sliver of fingernail from a storm giant."]}'::jsonb, '{"index":"potion-of-giant-strength-storm","name":"Potion of Storm Giant Strength","equipment_category":{"index":"potion","name":"Potion","url":"/api/2014/equipment-categories/potion"},"rarity":{"name":"Legendary"},"variants":[],"variant":true,"desc":["Potion, legendary","When you drink this potion, your Strength score changes to 29 for 1 hour. The potion has no effect on you if your Strength is equal to or greater than that score.","This potion''s transparent liquid has floating in it a sliver of fingernail from a storm giant."],"url":"/api/2014/magic-items/potion-of-giant-strength-storm"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'magic-items', '{"name":"Potion of Growth","desc":["Potion, uncommon","When you drink this potion, you gain the \"enlarge\" effect of the enlarge/reduce spell for 1d4 hours (no concentration required). The red in the potion''s liquid continuously expands from a tiny bead to color the clear liquid around it and then contracts. Shaking the bottle fails to interrupt this process."]}'::jsonb, '{"index":"potion-of-growth","name":"Potion of Growth","equipment_category":{"index":"potion","name":"Potion","url":"/api/2014/equipment-categories/potion"},"rarity":{"name":"Uncommon"},"variants":[],"variant":false,"desc":["Potion, uncommon","When you drink this potion, you gain the \"enlarge\" effect of the enlarge/reduce spell for 1d4 hours (no concentration required). The red in the potion''s liquid continuously expands from a tiny bead to color the clear liquid around it and then contracts. Shaking the bottle fails to interrupt this process."],"url":"/api/2014/magic-items/potion-of-growth"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'magic-items', '{"name":"Potion of Healing","desc":["Potion, varies","You regain hit points when you drink this potion. The number of hit points depends on the potion''s rarity, as shown in the Potions of Healing table. Whatever its potency, the potion''s red liquid glimmers when agitated.","Potions of Healing (table)","| Potion of ... | Rarity | HP Regained |","|---|---|---|","| Healing | Common | 2d4 + 2 |","| Greater healing | Uncommon | 4d4 + 4 |","| Superior healing | Rare | 8d4 + 8 |","| Supreme healing | Very rare | 10d4 + 20 |"]}'::jsonb, '{"index":"potion-of-healing","name":"Potion of Healing","equipment_category":{"index":"potion","name":"Potion","url":"/api/2014/equipment-categories/potion"},"rarity":{"name":"Varies"},"variants":[{"index":"potion-of-healing-common","name":"Potion of Healing","url":"/api/2014/magic-items/potion-of-healing-common"},{"index":"potion-of-healing-greater","name":"Potion of Greater Healing","url":"/api/2014/magic-items/potion-of-healing-greater"},{"index":"potion-of-healing-superior","name":"Potion of Superior Healing","url":"/api/2014/magic-items/potion-of-healing-superior"},{"index":"potion-of-healing-supreme","name":"Potion of Supreme Healing","url":"/api/2014/magic-items/potion-of-healing-supreme"}],"variant":false,"desc":["Potion, varies","You regain hit points when you drink this potion. The number of hit points depends on the potion''s rarity, as shown in the Potions of Healing table. Whatever its potency, the potion''s red liquid glimmers when agitated.","Potions of Healing (table)","| Potion of ... | Rarity | HP Regained |","|---|---|---|","| Healing | Common | 2d4 + 2 |","| Greater healing | Uncommon | 4d4 + 4 |","| Superior healing | Rare | 8d4 + 8 |","| Supreme healing | Very rare | 10d4 + 20 |"],"url":"/api/2014/magic-items/potion-of-healing"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'magic-items', '{"name":"Potion of Healing","desc":["Potion, common","You regain 2d4 + 2 hit points when you drink this potion. The potion''s red liquid glimmers when agitated."]}'::jsonb, '{"index":"potion-of-healing-common","name":"Potion of Healing","equipment_category":{"index":"potion","name":"Potion","url":"/api/2014/equipment-categories/potion"},"rarity":{"name":"Common"},"variants":[],"variant":true,"desc":["Potion, common","You regain 2d4 + 2 hit points when you drink this potion. The potion''s red liquid glimmers when agitated."],"url":"/api/2014/magic-items/potion-of-healing-common"}'::jsonb),
