  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Archmage","desc":"Archmages are powerful (and usually quite old) spellcasters dedicated to the study of the arcane arts. Benevolent ones counsel kings and queens, while evil ones rule as tyrants and pursue lichdom. Those who are neither good nor evil sequester themselves in remote towers to practice their magic without interruption. \n\nAn archmage typically has one or more apprentice mages, and an archmage’s abode has numerous magical wards and guardians to discourage interlopers."}'::jsonb, '{"index":"archmage","name":"Archmage","desc":"Archmages are powerful (and usually quite old) spellcasters dedicated to the study of the arcane arts. Benevolent ones counsel kings and queens, while evil ones rule as tyrants and pursue lichdom. Those who are neither good nor evil sequester themselves in remote towers to practice their magic without interruption. \n\nAn archmage typically has one or more apprentice mages, and an archmage’s abode has numerous magical wards and guardians to discourage interlopers.","size":"Medium","type":"humanoid","subtype":"any race","alignment":"any alignment","armor_class":[{"type":"dex","value":12},{"type":"spell","value":15,"spell":{"index":"mage-armor","name":"Mage Armor","url":"/api/2014/spells/mage-armor"}}],"hit_points":99,"hit_dice":"18d8","hit_points_roll":"18d8+18","speed":{"walk":"30 ft."},"strength":10,"dexterity":14,"constitution":12,"intelligence":20,"wisdom":15,"charisma":16,"proficiencies":[{"value":9,"proficiency":{"index":"saving-throw-int","name":"Saving Throw: INT","url":"/api/2014/proficiencies/saving-throw-int"}},{"value":6,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}},{"value":13,"proficiency":{"index":"skill-arcana","name":"Skill: Arcana","url":"/api/2014/proficiencies/skill-arcana"}},{"value":13,"proficiency":{"index":"skill-history","name":"Skill: History","url":"/api/2014/proficiencies/skill-history"}}],"damage_vulnerabilities":[],"damage_resistances":["damage from spells","bludgeoning, piercing, and slashing from nonmagical attacks (from stoneskin)"],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":12},"languages":"any six languages","challenge_rating":12,"proficiency_bonus":4,"xp":8400,"special_abilities":[{"name":"Magic Resistance","desc":"The archmage has advantage on saving throws against spells and other magical effects."},{"name":"Spellcasting","desc":"The archmage is an 18th-level spellcaster. Its spellcasting ability is Intelligence (spell save DC 17, +9 to hit with spell attacks). The archmage can cast disguise self and invisibility at will and has the following wizard spells prepared:\n\n- Cantrips (at will): fire bolt, light, mage hand, prestidigitation, shocking grasp\n- 1st level (4 slots): detect magic, identify, mage armor*, magic missile\n- 2nd level (3 slots): detect thoughts, mirror image, misty step\n- 3rd level (3 slots): counterspell, fly, lightning bolt\n- 4th level (3 slots): banishment, fire shield, stoneskin*\n- 5th level (3 slots): cone of cold, scrying, wall of force\n- 6th level (1 slot): globe of invulnerability\n- 7th level (1 slot): teleport\n- 8th level (1 slot): mind blank*\n- 9th level (1 slot): time stop\n* The archmage casts these spells on itself before combat.","spellcasting":{"level":18,"ability":{"index":"int","name":"INT","url":"/api/2014/ability-scores/int"},"dc":17,"modifier":9,"components_required":["V","S","M"],"school":"wizard","slots":{"1":4,"2":3,"3":3,"4":3,"5":3,"6":1,"7":1,"8":1,"9":1},"spells":[{"name":"Disguise Self","level":1,"url":"/api/2014/spells/disguise-self","usage":{"type":"at will"}},{"name":"Invisibility","level":2,"url":"/api/2014/spells/invisibility","usage":{"type":"at will"}},{"name":"Fire Bolt","level":0,"url":"/api/2014/spells/fire-bolt"},{"name":"Light","level":0,"url":"/api/2014/spells/light"},{"name":"Mage Hand","level":0,"url":"/api/2014/spells/mage-hand"},{"name":"Prestidigitation","level":0,"url":"/api/2014/spells/prestidigitation"},{"name":"Shocking Grasp","level":0,"url":"/api/2014/spells/shocking-grasp"},{"name":"Detect Magic","level":1,"url":"/api/2014/spells/detect-magic"},{"name":"Identify","level":1,"url":"/api/2014/spells/identify"},{"name":"Mage Armor","level":1,"url":"/api/2014/spells/mage-armor","notes":"Cast on self before combat"},{"name":"Magic Missile","level":1,"url":"/api/2014/spells/magic-missile"},{"name":"Detect Thoughts","level":2,"url":"/api/2014/spells/detect-thoughts"},{"name":"Mirror Image","level":2,"url":"/api/2014/spells/mirror-image"},{"name":"Misty Step","level":2,"url":"/api/2014/spells/misty-step"},{"name":"Counterspell","level":3,"url":"/api/2014/spells/counterspell"},{"name":"Fly","level":3,"url":"/api/2014/spells/fly"},{"name":"Lightning Bolt","level":3,"url":"/api/2014/spells/lightning-bolt"},{"name":"Banishment","level":4,"url":"/api/2014/spells/banishment"},{"name":"Fire Shield","level":4,"url":"/api/2014/spells/fire-shield"},{"name":"Stoneskin","level":4,"url":"/api/2014/spells/stoneskin","notes":"Cast on self before combat"},{"name":"Cone of Cold","level":5,"url":"/api/2014/spells/cone-of-cold"},{"name":"Scrying","level":5,"url":"/api/2014/spells/scrying"},{"name":"Wall of Force","level":5,"url":"/api/2014/spells/wall-of-force"},{"name":"Globe of Invulnerability","level":6,"url":"/api/2014/spells/globe-of-invulnerability"},{"name":"Teleport","level":7,"url":"/api/2014/spells/teleport"},{"name":"Mind Blank","level":8,"url":"/api/2014/spells/mind-blank","notes":"Cast on self before combat"},{"name":"Time Stop","level":9,"url":"/api/2014/spells/time-stop"}]}}],"actions":[{"name":"Dagger","desc":"Melee or Ranged Weapon Attack: +6 to hit, reach 5 ft. or range 20/60 ft., one target. Hit: 4 (1d4 + 2) piercing damage.","attack_bonus":6,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d4+2"}]}],"image":"/api/images/monsters/archmage.png","url":"/api/2014/monsters/archmage"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Assassin","desc":"Trained in the use of poison, assassins are remorseless killers who work for nobles, guildmasters, sovereigns, and anyone else who can afford them."}'::jsonb, '{"index":"assassin","name":"Assassin","desc":"Trained in the use of poison, assassins are remorseless killers who work for nobles, guildmasters, sovereigns, and anyone else who can afford them.","size":"Medium","type":"humanoid","subtype":"any race","alignment":"any non-good alignment","armor_class":[{"type":"armor","value":15,"armor":[{"index":"studded-leather-armor","name":"Studded Leather Armor","url":"/api/2014/equipment/studded-leather-armor"}]}],"hit_points":78,"hit_dice":"12d8","hit_points_roll":"12d8+24","speed":{"walk":"30 ft."},"strength":11,"dexterity":16,"constitution":14,"intelligence":13,"wisdom":11,"charisma":10,"proficiencies":[{"value":6,"proficiency":{"index":"saving-throw-dex","name":"Saving Throw: DEX","url":"/api/2014/proficiencies/saving-throw-dex"}},{"value":4,"proficiency":{"index":"saving-throw-int","name":"Saving Throw: INT","url":"/api/2014/proficiencies/saving-throw-int"}},{"value":6,"proficiency":{"index":"skill-acrobatics","name":"Skill: Acrobatics","url":"/api/2014/proficiencies/skill-acrobatics"}},{"value":3,"proficiency":{"index":"skill-deception","name":"Skill: Deception","url":"/api/2014/proficiencies/skill-deception"}},{"value":3,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"value":9,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":["poison"],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":13},"languages":"Thieves'' cant plus any two languages","challenge_rating":8,"proficiency_bonus":3,"xp":3900,"special_abilities":[{"name":"Assassinate","desc":"During its first turn, the ass