  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Axe Beak","desc":"An axe beak is a tall flightless bird with strong legs and a heavy, wedge-shaped beak. It has a nasty disposition and tends to attack any unfamiliar creature that wanders too close."}'::jsonb, '{"index":"axe-beak","name":"Axe Beak","desc":"An axe beak is a tall flightless bird with strong legs and a heavy, wedge-shaped beak. It has a nasty disposition and tends to attack any unfamiliar creature that wanders too close.","size":"Large","type":"beast","alignment":"unaligned","armor_class":[{"type":"dex","value":11}],"hit_points":19,"hit_dice":"3d10","hit_points_roll":"3d10+3","speed":{"walk":"50 ft."},"strength":14,"dexterity":12,"constitution":12,"intelligence":2,"wisdom":10,"charisma":5,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":10},"languages":"","challenge_rating":0.25,"proficiency_bonus":2,"xp":50,"actions":[{"name":"Beak","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 6 (1d8 + 2) slashing damage.","attack_bonus":4,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"1d8+2"}]}],"image":"/api/images/monsters/axe-beak.png","url":"/api/2014/monsters/axe-beak"}'::jsonb),
