  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Balor","desc":null}'::jsonb, '{"index":"balor","name":"Balor","size":"Huge","type":"fiend","subtype":"demon","alignment":"chaotic evil","armor_class":[{"type":"natural","value":19}],"hit_points":262,"hit_dice":"21d12","hit_points_roll":"21d12+126","speed":{"walk":"40 ft.","fly":"80 ft."},"strength":26,"dexterity":15,"constitution":22,"intelligence":20,"wisdom":16,"charisma":22,"proficiencies":[{"value":14,"proficiency":{"index":"saving-throw-str","name":"Saving Throw: STR","url":"/api/2014/proficiencies/saving-throw-str"}},{"value":12,"proficiency":{"index":"saving-throw-con","name":"Saving Throw: CON","url":"/api/2014/proficiencies/saving-throw-con"}},{"value":9,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}},{"value":12,"proficiency":{"index":"saving-throw-cha","name":"Saving Throw: CHA","url":"/api/2014/proficiencies/saving-throw-cha"}}],"damage_vulnerabilities":[],"damage_resistances":["cold","lightning","bludgeoning, piercing, and slashing from nonmagical weapons"],"damage_immunities":["fire","poison"],"condition_immunities":[{"index":"poisoned","name":"Poisoned","url":"/api/2014/conditions/poisoned"}],"senses":{"truesight":"120 ft.","passive_perception":13},"languages":"Abyssal, telepathy 120 ft.","challenge_rating":19,"proficiency_bonus":6,"xp":22000,"special_abilities":[{"name":"Death Throes","desc":"When the balor dies, it explodes, and each creature within 30 feet of it must make a DC 20 Dexterity saving throw, taking 70 (20d6) fire damage on a failed save, or half as much damage on a successful one. The explosion ignites flammable objects in that area that aren''t being worn or carried, and it destroys the balor''s weapons.","dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_value":20,"success_type":"half"},"damage":[{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_dice":"20d6"}]},{"name":"Fire Aura","desc":"At the start of each of the balor''s turns, each creature within 5 feet of it takes 10 (3d6) fire damage, and flammable objects in the aura that aren''t being worn or carried ignite. A creature that touches the balor or hits it with a melee attack while within 5 feet of it takes 10 (3d6) fire damage.","damage":[{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_dice":"3d6"}]},{"name":"Magic Resistance","desc":"The balor has advantage on saving throws against spells and other magical effects."},{"name":"Magic Weapons","desc":"The balor''s weapon attacks are magical."}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The balor makes two attacks: one with its longsword and one with its whip.","actions":[{"action_name":"Longsword","count":1,"type":"melee"},{"action_name":"Whip","count":1,"type":"melee"}]},{"name":"Longsword","desc":"Melee Weapon Attack: +14 to hit, reach 10 ft., one target. Hit: 21 (3d8 + 8) slashing damage plus 13 (3d8) lightning damage. If the balor scores a critical hit, it rolls damage dice three times, instead of twice.","attack_bonus":14,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"3d8+8"},{"damage_type":{"index":"lightning","name":"Lightning","url":"/api/2014/damage-types/lightning"},"damage_dice":"3d8"}]},{"name":"Whip","desc":"Melee Weapon Attack: +14 to hit, reach 30 ft., one target. Hit: 15 (2d6 + 8) slashing damage plus 10 (3d6) fire damage, and the target must succeed on a DC 20 Strength saving throw or be pulled up to 25 feet toward the balor.","attack_bonus":14,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"2d6+8"},{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_dice":"3d6"}]},{"name":"Teleport","desc":"The balor magically teleports, along with any equipment it is wearing or carrying, up to 120 feet to an unoccupied space it can see."}],"image":"/api/images/monsters/balor.png","url":"/api/2014/monsters/balor"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Bandit","desc":"**Bandits** rove in gangs and are sometimes led by thugs, veterans, or spellcasters. Not all bandits are evil. Oppression, drought, disease, or famine can often drive otherwise honest folk to a life of banditry.\n\n**Pirates** are bandits of the high seas. They might be freebooters interested only in treasure and murder, or they might be privateers sanctioned by the crown to attack and plunder an enemy nation’s vessels."}'::jsonb, '{"index":"bandit","name":"Bandit","desc":"**Bandits** rove in gangs and are sometimes led by thugs, veterans, or spellcasters. Not all bandits are evil. Oppression, drought, disease, or famine can often drive otherwise honest folk to a life of banditry.\n\n**Pirates** are bandits of the high seas. They might be freebooters interested only in treasure and murder, or they might be privateers sanctioned by the crown to attack and plunder an enemy nation’s vessels.","size":"Medium","type":"humanoid","subtype":"any race","alignment":"any non-lawful alignment","armor_class":[{"type":"armor","value":12,"armor":[{"index":"leather-armor","name":"Leather Armor","url":"/api/2014/equipment/leather-armor"}]}],"hit_points":11,"hit_dice":"2d8","hit_points_roll":"2d8+2","speed":{"walk":"30 ft."},"strength":11,"dexterity":12,"constitution":12,"intelligence":10,"wisdom":10,"charisma":10,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":10},"languages":"any one language (usually Common)","challenge_rating":0.125,"proficiency_bonus":2,"xp":25,"actions":[{"name":"Scimitar","desc":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 4 (1d6 + 1) slashing damage.","attack_bonus":3,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"1d6+1"}]},{"name":"Light Crossbow","desc":"Ranged Weapon Attack: +3 to hit, range 80/320 ft., one target. Hit: 5 (1d8 + 1) piercing damage.","attack_bonus":3,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d8+1"}]}],"image":"/api/images/monsters/bandit.png","url":"/api/2014/monsters/bandit"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Bandit Captain","desc":"It takes a strong personality, ruthless cunning, and a silver tongue to keep a gang of bandits in line. The **bandit captain** has these qualities in spades.\n\nIn addition to managing a crew of selfish malcontents, the **pirate captain** is a variation of the bandit captain, with a ship to protect and command. To keep the crew in line, the captain must mete out rewards and punishment on a regular basis.\n\nMore than treasure, a bandit captain or pirate captain craves infamy. A prisoner who appeals to the captain’s vanity or ego is more likely to be treated fairly than a prisoner who does not or claims not to know anything of the captain’s colorful reputation."}'::jsonb, '{"index":"bandit-captain","name":"Bandit Captain","desc":"It takes a strong personality, ruthless cunning, and a silver tongue to keep a gang of bandits in line. The **bandit captain** has these qualities in spades.\n\nIn addition to managing a crew of selfish malcontents, the **pirate captain** is a variation of the bandit captain, with a ship to protect and command. To keep the crew in line, the captain must mete out rewards and punishment on a regular basis.\n\nMore than treasure, a bandit captain or pirate captain craves infamy. A prisoner who appeals to the captain’s vanity or ego is more likely to be treated fairly than a prisoner who does not or claims not to know anything of the captain’s colorful reputation.","size":"Medium","type":"humanoid","subtype":"any race","alignment":"any non-lawful alignment","armor_class":[{"type":"armor","value":15,"armor":[{"index":"studded-leather-armor","name":"Studded Leather Armor","url":"/api/2014/equipment/studded-leather-armor"}]}],"hit_points":65,"hit_dice":"10d8","hit_points_roll":"10d8+20","speed":{"walk":"30 ft."},"strength":15,"dexterity":16,"constitution":14,"intelligence":14,"wisdom":11,"charisma":14,"proficiencies":[{"value":4,"proficiency":{"index":"saving-throw-str","name":"Saving Throw: STR","url":"/api/2014/proficiencies/saving-throw-str"}},{"value":5,"proficiency":{"index":"saving-throw-dex","name":"Saving Throw: DEX","url":"/api/2014/proficiencies/saving-throw-dex"}},{"value":2,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}},{"value":4,"proficiency":{"index":"skill-athletics","name":"Skill: Athletics","url":"/api/2014/proficiencies/skill-athletics"}},{"value":4,"proficiency":{"index":"skill-deception","name":"Skill: Deception","url":"/api/2014/proficiencies/skill-deception"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":10},"languages":"any two languages","challenge_rating":2,"proficiency_bonus":2,"xp":450,"actions":[{"name":"Multiattack","multiattack_type":"action_options","desc":"The captain makes three melee attacks: two with its scimitar and one with its dagger. Or the captain makes two ranged attacks with its daggers.","action_options":{"choose":1,"type":"action","from":{"option_set_type":"options_array","options":[{"option_type":"multiple","items":[{"option_type":"action","action_name":"Scimitar","count":2,"type":"melee"},{"option_type":"action","action_name":"Dagger","count":1,"type":"melee"}]},{"option_type":"action","action_name":"Dagger","count":2,"type":"ranged"}]}}},{"name":"Scimitar","desc":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) slashing damage.","attack_bonus":5,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"1d6+3"}]},{"name":"Dagger","desc":"Melee or Ranged Weapon Attack: +5 to hit, reach 5 ft. or range 20/60 ft., one target. Hit: 5 (1d4 + 3) piercing damage.","attack_bonus":5,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d4+3"}]}],"reactions":[{"name":"Parry","desc":"The captain adds 2 to its AC against one melee attack that would hit it. To do so, the captain must see the attacker and be wielding a melee weapon."}],"image":"/api/images/monsters/bandit-captain.png","url":"/api/2014/monsters/bandit-captain"}'::jsonb),
