  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Bulette","desc":null}'::jsonb, '{"index":"bulette","name":"Bulette","size":"Large","type":"monstrosity","alignment":"unaligned","armor_class":[{"type":"natural","value":17}],"hit_points":94,"hit_dice":"9d10","hit_points_roll":"9d10+45","speed":{"walk":"40 ft.","burrow":"40 ft."},"strength":19,"dexterity":11,"constitution":21,"intelligence":2,"wisdom":10,"charisma":5,"proficiencies":[{"value":6,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"60 ft.","tremorsense":"60 ft.","passive_perception":16},"languages":"","challenge_rating":5,"proficiency_bonus":3,"xp":1800,"special_abilities":[{"name":"Standing Leap","desc":"The bulette''s long jump is up to 30 ft. and its high jump is up to 15 ft., with or without a running start."}],"actions":[{"name":"Bite","desc":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 30 (4d12 + 4) piercing damage.","attack_bonus":7,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"4d12+4"}]},{"name":"Deadly Leap","desc":"If the bulette jumps at least 15 ft. as part of its movement, it can then use this action to land on its feet in a space that contains one or more other creatures. Each of those creatures must succeed on a DC 16 Strength or Dexterity saving throw (target''s choice) or be knocked prone and take 14 (3d6 + 4) bludgeoning damage plus 14 (3d6 + 4) slashing damage. On a successful save, the creature takes only half the damage, isn''t knocked prone, and is pushed 5 ft. out of the bulette''s space into an unoccupied space of the creature''s choice. If no unoccupied space is within range, the creature instead falls prone in the bulette''s space."}],"image":"/api/images/monsters/bulette.png","url":"/api/2014/monsters/bulette"}'::jsonb),
