  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Cockatrice","desc":null}'::jsonb, '{"index":"cockatrice","name":"Cockatrice","size":"Small","type":"monstrosity","alignment":"unaligned","armor_class":[{"type":"dex","value":11}],"hit_points":27,"hit_dice":"6d6","hit_points_roll":"6d6+6","speed":{"walk":"20 ft.","fly":"40 ft."},"strength":6,"dexterity":12,"constitution":12,"intelligence":2,"wisdom":13,"charisma":5,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"60 ft.","passive_perception":11},"languages":"","challenge_rating":0.5,"proficiency_bonus":2,"xp":100,"actions":[{"name":"Bite","desc":"Melee Weapon Attack: +3 to hit, reach 5 ft., one creature. Hit: 3 (1d4 + 1) piercing damage, and the target must succeed on a DC 11 Constitution saving throw against being magically petrified. On a failed save, the creature begins to turn to stone and is restrained. It must repeat the saving throw at the end of its next turn. On a success, the effect ends. On a failure, the creature is petrified for 24 hours.","attack_bonus":3,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d4+1"}]}],"image":"/api/images/monsters/cockatrice.png","url":"/api/2014/monsters/cockatrice"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Commoner","desc":"Commoners include peasants, serfs, slaves, servants, pilgrims, merchants, artisans, and hermits."}'::jsonb, '{"index":"commoner","name":"Commoner","desc":"Commoners include peasants, serfs, slaves, servants, pilgrims, merchants, artisans, and hermits.","size":"Medium","type":"humanoid","subtype":"any race","alignment":"any alignment","armor_class":[{"type":"dex","value":10}],"hit_points":4,"hit_dice":"1d8","hit_points_roll":"1d8","speed":{"walk":"30 ft."},"strength":10,"dexterity":10,"constitution":10,"intelligence":10,"wisdom":10,"charisma":10,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":10},"languages":"any one language (usually Common)","challenge_rating":0,"proficiency_bonus":2,"xp":10,"actions":[{"name":"Club","desc":"Melee Weapon Attack: +2 to hit, reach 5 ft., one target. Hit: 2 (1d4) bludgeoning damage.","attack_bonus":2,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"1d4"}]}],"image":"/api/images/monsters/commoner.png","url":"/api/2014/monsters/commoner"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Constrictor Snake","desc":null}'::jsonb, '{"index":"constrictor-snake","name":"Constrictor Snake","size":"Large","type":"beast","alignment":"unaligned","armor_class":[{"type":"dex","value":12}],"hit_points":13,"hit_dice":"2d10","hit_points_roll":"2d10+2","speed":{"walk":"30 ft.","swim":"30 ft."},"strength":15,"dexterity":14,"constitution":12,"intelligence":1,"wisdom":10,"charisma":3,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"blindsight":"10 ft.","passive_perception":10},"languages":"","challenge_rating":0.25,"proficiency_bonus":2,"xp":50,"actions":[{"name":"Bite","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 5 (1d6 + 2) piercing damage.","attack_bonus":4,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d6+2"}]},{"name":"Constrict","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 6 (1d8 + 2) bludgeoning damage, and the target is grappled (escape DC 14). Until this grapple ends, the creature is restrained, and the snake can''t constrict another target.","attack_bonus":4,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"1d8+2"}]}],"image":"/api/images/monsters/constrictor-snake.png","url":"/api/2014/monsters/constrictor-snake"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Copper Dragon Wyrmling","desc":null}'::jsonb, '{"index":"copper-dragon-wyrmling","name":"Copper Dragon Wyrmling","size":"Medium","type":"dragon","alignment":"chaotic good","armor_class":[{"type":"natural","value":16}],"hit_points":22,"hit_dice":"4d8","hit_points_roll":"4d8+4","speed":{"walk":"30 ft.","climb":"30 ft.","fly":"60 ft."},"strength":15,"dexterity":12,"constitution":13,"intelligence":14,"wisdom":11,"charisma":13,"proficiencies":[{"value":3,"proficiency":{"index":"saving-throw-dex","name":"Saving Throw: DEX","url":"/api/2014/proficiencies/saving-throw-dex"}},{"value":3,"proficiency":{"index":"saving-throw-con","name":"Saving Throw: CON","url":"/api/2014/proficiencies/saving-throw-con"}},{"value":2,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}},{"value":3,"proficiency":{"index":"saving-throw-cha","name":"Saving Throw: CHA","url":"/api/2014/proficiencies/saving-throw-cha"}},{"value":4,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"value":3,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":["acid"],"condition_immunities":[],"senses":{"blindsight":"10 ft.","darkvision":"60 ft.","passive_perception":14},"languages":"Draconic","challenge_rating":1,"proficiency_bonus":2,"xp":200,"actions":[{"name":"Bite","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 7 (1d10 + 2) piercing damage.","attack_bonus":4,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d10+2"}]},{"name":"Breath Weapons","desc":"The dragon uses one of the following breath weapons.\nAcid Breath. The dragon exhales acid in an 20-foot line that is 5 feet wide. Each creature in that line must make a DC 11 Dexterity saving throw, taking 18 (4d8) acid damage on a failed save, or half as much damage on a successful one.\nSlowing Breath. The dragon exhales gas in a 15-foot cone. Each creature in that area must succeed on a DC 11 Constitution saving throw. On a failed save, the creature can''t use reactions, its speed is halved, and it can''t make more than one attack on its turn. In addition, the creature can use either an action or a bonus action on its turn, but not both. These effects last for 1 minute. The creature can repeat the saving throw at the end of each of its turns, ending the effect on itself with a successful save.","usage":{"type":"recharge on roll","dice":"1d6","min_value":5},"options":{"choose":1,"type":"attack","from":{"option_set_type":"options_array","options":[{"option_type":"breath","name":"Acid Breath","dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_value":11,"success_type":"half"},"damage":[{"damage_type":{"index":"acid","name":"Acid","url":"/api/2014/damage-types/acid"},"damage_dice":"4d8"}]},{"option_type":"breath","name":"Slowing Breath","dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_value":11,"success_type":"none"}}]}}}],"image":"/api/images/monsters/copper-dragon-wyrmling.png","url":"/api/2014/monsters/copper-dragon-wyrmling"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Couatl","desc":null}'::jsonb, '{"index":"couatl","name":"Couatl","size":"Medium","type":"celestial","alignment":"lawful good","armor_class":[{"type":"natural","value":19}],"hit_points":97,"hit_dice":"13d8","hit_points_roll":"13d8+39","speed":{"walk":"30 ft.","fly":"90 ft."},"strength":16,"dexterity":20,"constitution":17,"intelligence":18,"wisdom":20,"charisma":18,"proficiencies":[{"value":5,"proficiency":{"index":"saving-throw-con","name":"Saving Throw: CON","url":"/api/2014/proficiencies/saving-throw-con"}},{"value":7,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}},{"value":6,"proficiency":{"index":"saving-throw-cha","name":"Saving Throw: CHA","url":"/api/2014/proficiencies/saving-throw-cha"}}],"damage_vulnerabilities":[],"damage_resistances":["radiant"],"damage_immunities":["psychic","bludgeoning, piercing, and slashing from nonmagical weapons"],"condition_immunities":[],"senses":{"truesight":"120 ft.","passive_perception":15},"languages":"all, telepathy 120 ft.","challenge_rating":4,"proficiency_bonus":2,"xp":1100,"special_abilities":[{"name":"Innate Spellcasting","desc":"The couatl''s spellcasting ability is Charisma (spell save DC 14). It can innately cast the following spells, requiring only verbal components:\n\nAt will: detect evil and good, detect magic, detect thoughts\n3/day each: bless, create food and water, cure wounds, lesser restoration, protection from poison, sanctuary, shield\n1/day each: dream, greater restoration, scrying","spellcasting":{"ability":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"dc":14,"components_required":["V"],"spells":[{"name":"Detect Evil and Good","level":1,"url":"/api/2014/spells/detect-evil-and-good","usage":{"type":"at will"}},{"name":"Detect Magic","level":1,"url":"/api/2014/spells/detect-magic","usage":{"type":"at will"}},{"name":"Detect Thoughts","level":2,"url":"/api/2014/spells/detect-thoughts","usage":{"type":"at will"}},{"name":"Bless","level":1,"url":"/api/2014/spells/bless","usage":{"type":"per day","times":3}},{"name":"Create Food and Water","level":3,"url":"/api/2014/spells/create-food-and-water","usage":{"type":"per day","times":3}},{"name":"Cure Wounds","level":1,"url":"/api/2014/spells/cure-wounds","usage":{"type":"per day","times":3}},{"name":"Lesser Restoration","level":2,"url":"/api/2014/spells/lesser-restoration","usage":{"type":"per day","times":3}},{"name":"Protection from Poison","level":2,"url":"/api/2014/spells/protection-from-poison","usage":{"type":"per day","times":3}},{"name":"Sanctuary","level":1,"url":"/api/2014/spells/sanctuary","usage":{"type":"per day","times":3}},{"name":"Shield","level":1,"url":"/api/2014/spells/shield","usage":{"type":"per day","times":3}},{"name":"Dream","level":5,"url":"/api/2014/spells/dream","usage":{"type":"per day","times":1}},{"name":"Greater Restoration","level":5,"url":"/api/2014/spells/greater-restoration","usage":{"type":"per day","times":1}},{"name":"Scrying","level":5,"url":"/api/2014/spells/scrying","usage":{"type":"per day","times":1}}]}},{"name":"Magic Weapons","desc":"The couatl''s weapon attacks are magical."},{"name":"Shielded Mind","desc":"The couatl is immune to scrying and to any effect that would sense its emotions, read its thoughts, or detect its location."}],"actions":[{"name":"Bite","desc":"Melee Weapon Attack: +8 to hit, reach 5 ft., one creature. Hit: 8 (1d6 + 5) piercing damage, and the target must succeed on a DC 13 Constitution saving throw or be poisoned for 24 hours. Until this poison ends, the target is unconscious. Another creature can use an action to shake the target awake.","attack_bonus":8,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d6+5"}]},{"name":"Constrict","desc":"Melee Weapon Attack: +6 to hit, reach 10 ft., one Medium or smaller creature. Hit: 10 (2d6 + 3) bludgeoning damage, and the target is grappled (escape DC 15). Until this grapple ends, the target is restrained, and the couatl can''t constrict another target.","attack_bonus":6,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"2d6+3"}]},{"name":"Change Shape","desc":"The couatl magically polymorphs into a humanoid or beast that has a challenge rating equal to or less than its own, or back into its true form. It reverts to its true form if it dies. Any equipment it is wearing or carrying is absorbed or borne by the new form (the couatl''s choice).\nIn a new form, the couatl retains its game statistics and ability to speak, but its AC, movement modes, Strength, Dexterity, and other actions are replaced by those of the new form, and it gains any statistics and capabilities (except class features, legendary actions, and lair actions) that the new form has but that it lacks. If the new form has a bite attack, the couatl can use its bite in that form."}],"image":"/api/images/monsters/couatl.png","url":"/api/2014/monsters/couatl"}'::jsonb),
