  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Cult Fanatic","desc":"Fanatics are often part of a cult’s leadership, using their charisma and dogma to influence and prey on those of weak will. Most are interested in personal power above all else."}'::jsonb, '{"index":"cult-fanatic","name":"Cult Fanatic","desc":"Fanatics are often part of a cult’s leadership, using their charisma and dogma to influence and prey on those of weak will. Most are interested in personal power above all else.","size":"Medium","type":"humanoid","subtype":"any race","alignment":"any non-good alignment","armor_class":[{"type":"armor","value":13,"armor":[{"index":"leather-armor","name":"Leather Armor","url":"/api/2014/equipment/leather-armor"}]}],"hit_points":22,"hit_dice":"6d8","hit_points_roll":"6d8-5","speed":{"walk":"30 ft."},"strength":11,"dexterity":14,"constitution":12,"intelligence":10,"wisdom":13,"charisma":14,"proficiencies":[{"value":4,"proficiency":{"index":"skill-deception","name":"Skill: Deception","url":"/api/2014/proficiencies/skill-deception"}},{"value":4,"proficiency":{"index":"skill-persuasion","name":"Skill: Persuasion","url":"/api/2014/proficiencies/skill-persuasion"}},{"value":2,"proficiency":{"index":"skill-religion","name":"Skill: Religion","url":"/api/2014/proficiencies/skill-religion"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":11},"languages":"any one language (usually Common)","challenge_rating":2,"proficiency_bonus":2,"xp":450,"special_abilities":[{"name":"Dark Devotion","desc":"The fanatic has advantage on saving throws against being charmed or frightened."},{"name":"Spellcasting","desc":"The fanatic is a 4th-level spellcaster. Its spell casting ability is Wisdom (spell save DC 11, +3 to hit with spell attacks). The fanatic has the following cleric spells prepared:\n\nCantrips (at will): light, sacred flame, thaumaturgy\n- 1st level (4 slots): command, inflict wounds, shield of faith\n- 2nd level (3 slots): hold person, spiritual weapon","spellcasting":{"level":4,"ability":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc":11,"modifier":3,"components_required":["V","S","M"],"school":"cleric","slots":{"1":4,"2":3},"spells":[{"name":"Light","level":0,"url":"/api/2014/spells/light"},{"name":"Sacred Flame","level":0,"url":"/api/2014/spells/sacred-flame"},{"name":"Thaumaturgy","level":0,"url":"/api/2014/spells/thaumaturgy"},{"name":"Command","level":1,"url":"/api/2014/spells/command"},{"name":"Inflict Wounds","level":1,"url":"/api/2014/spells/inflict-wounds"},{"name":"Shield of Faith","level":1,"url":"/api/2014/spells/shield-of-faith"},{"name":"Hold Person","level":2,"url":"/api/2014/spells/hold-person"},{"name":"Spiritual Weapon","level":2,"url":"/api/2014/spells/spiritual-weapon"}]}}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The fanatic makes two melee attacks.","actions":[{"action_name":"Dagger","count":2,"type":"melee"}]},{"name":"Dagger","desc":"Melee or Ranged Weapon Attack: +4 to hit, reach 5 ft. or range 20/60 ft., one creature. Hit: 4 (1d4 + 2) piercing damage.","attack_bonus":4,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d4+2"}]}],"image":"/api/images/monsters/cult-fanatic.png","url":"/api/2014/monsters/cult-fanatic"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Cultist","desc":"Cultists swear allegiance to dark powers such as elemental princes, demon lords, or archdevils. Most conceal their loyalties to avoid being ostracized, imprisoned, or executed for their beliefs. Unlike evil acolytes, cultists often show signs of insanity in their beliefs and practices."}'::jsonb, '{"index":"cultist","name":"Cultist","desc":"Cultists swear allegiance to dark powers such as elemental princes, demon lords, or archdevils. Most conceal their loyalties to avoid being ostracized, imprisoned, or executed for their beliefs. Unlike evil acolytes, cultists often show signs of insanity in their beliefs and practices.","size":"Medium","type":"humanoid","subtype":"any race","alignment":"any non-good alignment","armor_class":[{"type":"armor","value":12,"armor":[{"index":"leather-armor","name":"Leather Armor","url":"/api/2014/equipment/leather-armor"}]}],"hit_points":9,"hit_dice":"2d8","hit_points_roll":"2d8","speed":{"walk":"30 ft."},"strength":11,"dexterity":12,"constitution":10,"intelligence":10,"wisdom":11,"charisma":10,"proficiencies":[{"value":2,"proficiency":{"index":"skill-deception","name":"Skill: Deception","url":"/api/2014/proficiencies/skill-deception"}},{"value":2,"proficiency":{"index":"skill-religion","name":"Skill: Religion","url":"/api/2014/proficiencies/skill-religion"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":10},"languages":"any one language (usually Common)","challenge_rating":0.125,"proficiency_bonus":2,"xp":25,"special_abilities":[{"name":"Dark Devotion","desc":"The cultist has advantage on saving throws against being charmed or frightened."}],"actions":[{"name":"Scimitar","desc":"Melee Weapon Attack: +3 to hit, reach 5 ft., one creature. Hit: 4 (1d6 + 1) slashing damage.","attack_bonus":3,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"1d6+1"}]}],"image":"/api/images/monsters/cultist.png","url":"/api/2014/monsters/cultist"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Darkmantle","desc":null}'::jsonb, '{"index":"darkmantle","name":"Darkmantle","size":"Small","type":"monstrosity","alignment":"unaligned","armor_class":[{"type":"dex","value":11}],"hit_points":22,"hit_dice":"5d6","hit_points_roll":"5d6+5","speed":{"walk":"10 ft.","fly":"30 ft."},"strength":16,"dexterity":12,"constitution":13,"intelligence":2,"wisdom":10,"charisma":5,"proficiencies":[{"value":3,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"blindsight":"60 ft.","passive_perception":10},"languages":"","challenge_rating":0.5,"proficiency_bonus":2,"xp":100,"special_abilities":[{"name":"Echolocation","desc":"The darkmantle can''t use its blindsight while deafened."},{"name":"False Appearance","desc":"While the darkmantle remains motionless, it is indistinguishable from a cave formation such as a stalactite or stalagmite."}],"actions":[{"name":"Crush","desc":"Melee Weapon Attack: +5 to hit, reach 5 ft., one creature. Hit: 6 (1d6 + 3) bludgeoning damage, and the darkmantle attaches to the target. If the target is Medium or smaller and the darkmantle has advantage on the attack roll, it attaches by engulfing the target''s head, and the target is also blinded and unable to breathe while the darkmantle is attached in this way.\nWhile attached to the target, the darkmantle can attack no other creature except the target but has advantage on its attack rolls. The darkmantle''s speed also becomes 0, it can''t benefit from any bonus to its speed, and it moves with the target.\nA creature can detach the darkmantle by making a successful DC 13 Strength check as an action. On its turn, the darkmantle can detach itself from the target by using 5 feet of movement.","attack_bonus":5,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"1d6+3"}]},{"name":"Darkness Aura","desc":"A 15-foot radius of magical darkness extends out from the darkmantle, moves with it, and spreads around corners. The darkness lasts as long as the darkmantle maintains concentration, up to 10 minutes (as if concentrating on a spell). Darkvision can''t penetrate this darkness, and no natural light can illuminate it. If any of the darkness overlaps with an area of light created by a spell of 2nd level or lower, the spell creating the light is dispelled.","usage":{"type":"per day","times":1}}],"image":"/api/images/monsters/darkmantle.png","url":"/api/2014/monsters/darkmantle"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Death Dog","desc":"A death dog is an ugly two-headed hound that roams plains, and deserts. Hate burns in a death dog’s heart, and a taste for humanoid flesh drives it to attack travelers and explorers. Death dog saliva carries a foul disease that causes a victim’s flesh to slowly rot off the bone."}'::jsonb, '{"index":"death-dog","name":"Death Dog","desc":"A death dog is an ugly two-headed hound that roams plains, and deserts. Hate burns in a death dog’s heart, and a taste for humanoid flesh drives it to attack travelers and explorers. Death dog saliva carries a foul disease that causes a victim’s flesh to slowly rot off the bone.","size":"Medium","type":"monstrosity","alignment":"neutral evil","armor_class":[{"type":"dex","value":12}],"hit_points":39,"hit_dice":"6d8","hit_points_roll":"6d8+12","speed":{"walk":"40 ft."},"strength":15,"dexterity":14,"constitution":14,"intelligence":3,"wisdom":13,"charisma":6,"proficiencies":[{"value":5,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"value":4,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"120 ft.","passive_perception":15},"languages":"","challenge_rating":1,"proficiency_bonus":2,"xp":200,"special_abilities":[{"name":"Two-Headed","desc":"The dog has advantage on Wisdom (Perception) checks and on saving throws against being blinded, charmed, deafened, frightened, stunned, or knocked unconscious."}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The dog makes two bite attacks.","actions":[{"action_name":"Bite","count":2,"type":"melee"}]},{"name":"Bite","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 5 (1d6 + 2) piercing damage. If the target is a creature, it must succeed on a DC 12 Constitution saving throw against disease or become poisoned until the disease is cured. Every 24 hours that elapse, the creature must repeat the saving throw, reducing its hit point maximum by 5 (1d10) on a failure. This reduction lasts until the disease is cured. The creature dies if the disease reduces its hit point maximum to 0.","attack_bonus":4,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d6+2"}]}],"image":"/api/images/monsters/death-dog.png","url":"/api/2014/monsters/death-dog"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Deep Gnome (Svirfneblin)","desc":null}'::jsonb, '{"index":"deep-gnome-svirfneblin","name":"Deep Gnome (Svirfneblin)","size":"Small","type":"humanoid","subtype":"gnome","alignment":"neutral good","armor_class":[{"type":"armor","value":15,"armor":[{"index":"chain-shirt","name":"Chain Shirt","url":"/api/2014/equipment/chain-shirt"}]}],"hit_points":16,"hit_dice":"3d6","hit_points_roll":"3d6+6","speed":{"walk":"20 ft."},"strength":15,"dexterity":14,"constitution":14,"intelligence":12,"wisdom":10,"charisma":9,"proficiencies":[{"value":3,"proficiency":{"index":"skill-investigation","name":"Skill: Investigation","url":"/api/2014/proficiencies/skill-investigation"}},{"value":2,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"value":4,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"120 ft.","passive_perception":12},"languages":"Gnomish, Terran, Undercommon","challenge_rating":0.5,"proficiency_bonus":2,"xp":50,"special_abilities":[{"name":"Stone Camouflage","desc":"The gnome has advantage on Dexterity (Stealth) checks made to hide in rocky terrain."},{"name":"Gnome Cunning","desc":"The gnome has advantage on Intelligence, Wisdom, and Charisma saving throws against magic."},{"name":"Innate Spellcasting","desc":"The gnome''s innate spellcasting ability is Intelligence (spell save DC 11). It can innately cast the following spells, requiring no material components:\nAt will: nondetection (self only)\n1/day each: blindness/deafness, blur, disguise self","spellcasting":{"ability":{"index":"int","name":"INT","url":"/api/2014/ability-scores/int"},"dc":11,"components_required":["V","S"],"spells":[{"name":"Nondetection","level":3,"notes":"Self only","url":"/api/2014/spells/nondetection","usage":{"type":"at will"}},{"name":"Blindness/Deafness","level":2,"url":"/api/2014/spells/blindness-deafness","usage":{"type":"per day","times":1}},{"name":"Blur","level":2,"url":"/api/2014/spells/blur","usage":{"type":"per day","times":1}},{"name":"Disguise Self","level":1,"url":"/api/2014/spells/disguise-self","usage":{"type":"per day","times":1}}]}}],"actions":[{"name":"War Pick","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 6 (1d8 + 2) piercing damage.","attack_bonus":4,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d8+2"}]},{"name":"Poisoned Dart","desc":"Ranged Weapon Attack: +4 to hit, range 30/120 ft., one creature. Hit: 4 (1d4 + 2) piercing damage, and the target must succeed on a DC 12 Constitution saving throw or be poisoned for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success","attack_bonus":4,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d4+2"}]}],"image":"/api/images/monsters/deep-gnome-svirfneblin.png","url":"/api/2014/monsters/deep-gnome-svirfneblin"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Deer","desc":null}'::jsonb, '{"index":"deer","name":"Deer","size":"Medium","type":"beast","alignment":"unaligned","armor_class":[{"type":"dex","value":13}],"hit_points":4,"hit_dice":"1d8","hit_points_roll":"1d8","speed":{"walk":"50 ft."},"strength":11,"dexterity":16,"constitution":11,"intelligence":2,"wisdom":14,"charisma":5,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":12},"languages":"","challenge_rating":0,"proficiency_bonus":2,"xp":10,"actions":[{"name":"Bite","desc":"Melee Weapon Attack: +2 to hit, reach 5 ft., one target. Hit: 2 (1d4) piercing damage.","attack_bonus":2,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d4"}]}],"image":"/api/images/monsters/deer.png","url":"/api/2014/monsters/deer"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Deva","desc":null}'::jsonb, '{"index":"deva","name":"Deva","size":"Medium","type":"celestial","alignment":"lawful good","armor_class":[{"type":"natural","value":17}],"hit_points":136,"hit_dice":"16d8","hit_points_roll":"16d8+64","speed":{"walk":"30 ft.","fly":"90 ft."},"strength":18,"dexterity":18,"constitution":18,"intelligence":17,"wisdom":20,"charisma":20,"proficiencies":[{"value":9,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}},{"value":9,"proficiency":{"index":"saving-throw-cha","name":"Saving Throw: CHA","url":"/api/2014/proficiencies/saving-throw-cha"}},{"value":9,"proficiency":{"index":"skill-insight","name":"Skill: Insight","url":"/api/2014/proficiencies/skill-insight"}},{"value":9,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}}],"damage_vulnerabilities":[],"damage_resistances":["radiant","bludgeoning, piercing, and slashing from nonmagical weapons"],"damage_immunities":[],"condition_immunities":[{"index":"charmed","name":"Charmed","url":"/api/2014/conditions/charmed"},{"index":"exhaustion","name":"Exhaustion","url":"/api/2014/conditions/exhaustion"},{"index":"frightened","name":"Frightened","url":"/api/2014/conditions/frightened"}],"senses":{"darkvision":"120 ft.","passive_perception":19},"languages":"all, telepathy 120 ft.","challenge_rating":10,"proficiency_bonus":4,"xp":5900,"special_abilities":[{"name":"Angelic Weapons","desc":"The deva''s weapon attacks are magical. When the deva hits with any weapon, the weapon deals an extra 4d8 radiant damage (included in the attack)."},{"name":"Innate Spellcasting","desc":"The deva''s spellcasting ability is Charisma (spell save DC 17). The deva can innately cast the following spells, requiring only verbal components:\nAt will: detect evil and good\n1/day each: commune, raise dead","spellcasting":{"ability":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"dc":17,"components_required":["V"],"spells":[{"name":"Detect Evil and Good","level":1,"url":"/api/2014/spells/detect-evil-and-good","usage":{"type":"at will"}},{"name":"Commune","level":5,"url":"/api/2014/spells/commune","usage":{"type":"per day","times":1}},{"name":"Raise Dead","level":5,"url":"/api/2014/spells/raise-dead","usage":{"type":"per day","times":1}}]}},{"name":"Magic Resistance","desc":"The deva has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The deva makes two melee attacks.","actions":[{"action_name":"Mace","count":2,"type":"melee"}]},{"name":"Mace","desc":"Melee Weapon Attack: +8 to hit, reach 5 ft., one target. Hit: 7 (1d6 + 4) bludgeoning damage plus 18 (4d8) radiant damage.","attack_bonus":8,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"1d6+4"},{"damage_type":{"index":"radiant","name":"Radiant","url":"/api/2014/damage-types/radiant"},"damage_dice":"4d8"}]},{"name":"Healing Touch","desc":"The deva touches another creature. The target magically regains 20 (4d8 + 2) hit points and is freed from any curse, disease, poison, blindness, or deafness.","usage":{"type":"per day","times":3}},{"name":"Change Shape","desc":"The deva magically polymorphs into a humanoid or beast that has a challenge rating equal to or less than its own, or back into its true form. It reverts to its true form if it dies. Any equipment it is wearing or carrying is absorbed or borne by the new form (the deva''s choice).\nIn a new form, the deva retains its game statistics and ability to speak, but its AC, movement modes, Strength, Dexterity, and special senses are replaced by those of the new form, and it gains any statistics and capabilities (except class features, legendary actions, and lair actions) that the new form has but that it lacks."}],"image":"/api/images/monsters/deva.png","url":"/api/2014/monsters/deva"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Dire Wolf","desc":null}'::jsonb, '{"index":"dire-wolf","name":"Dire Wolf","size":"Large","type":"beast","alignment":"unaligned","armor_class":[{"type":"natural","value":14}],"hit_points":37,"hit_dice":"5d10","hit_points_roll":"5d10+10","speed":{"walk":"50 ft."},"strength":17,"dexterity":15,"constitution":15,"intelligence":3,"wisdom":12,"charisma":7,"proficiencies":[{"value":3,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"value":4,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":13},"languages":"","challenge_rating":1,"proficiency_bonus":2,"xp":200,"special_abilities":[{"name":"Keen Hearing and Smell","desc":"The wolf has advantage on Wisdom (Perception) checks that rely on hearing or smell."},{"name":"Pack Tactics","desc":"The wolf has advantage on an attack roll against a creature if at least one of the wolf''s allies is within 5 ft. of the creature and the ally isn''t incapacitated."}],"actions":[{"name":"Bite","desc":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) piercing damage. If the target is a creature, it must succeed on a DC 13 Strength saving throw or be knocked prone.","attack_bonus":5,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"2d6+3"}]}],"image":"/api/images/monsters/dire-wolf.png","url":"/api/2014/monsters/dire-wolf"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Djinni","desc":null}'::jsonb, '{"index":"djinni","name":"Djinni","size":"Large","type":"elemental","alignment":"chaotic good","armor_class":[{"type":"natural","value":17}],"hit_points":161,"hit_dice":"14d10","hit_points_roll":"14d10+84","speed":{"walk":"30 ft.","fly":"90 ft."},"strength":21,"dexterity":15,"constitution":22,"intelligence":15,"wisdom":16,"charisma":20,"proficiencies":[{"value":6,"proficiency":{"index":"saving-throw-dex","name":"Saving Throw: DEX","url":"/api/2014/proficiencies/saving-throw-dex"}},{"value":7,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}},{"value":9,"proficiency":{"index":"saving-throw-cha","name":"Saving Throw: CHA","url":"/api/2014/proficiencies/saving-throw-cha"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":["lightning","thunder"],"condition_immunities":[],"senses":{"darkvision":"120 ft.","passive_perception":13},"languages":"Auran","challenge_rating":11,"proficiency_bonus":4,"xp":7200,"special_abilities":[{"name":"Elemental Demise","desc":"If the djinni dies, its body disintegrates into a warm breeze, leaving behind only equipment the djinni was wearing or carrying."},{"name":"Innate Spellcasting","desc":"The djinni''s innate spellcasting ability is Charisma (spell save DC 17, +9 to hit with spell attacks). It can innately cast the following spells, requiring no material components:\n\nAt will: detect evil and good, detect magic, thunderwave\n3/day each: create food and water (can create wine instead of water), tongues, wind walk\n1/day each: conjure elemental (air elemental only), creation, gaseous form, invisibility, major image, plane shift","spellcasting":{"ability":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"dc":17,"modifier":9,"components_required":["V","S"],"spells":[{"name":"Detect Evil and Good","level":1,"url":"/api/2014/spells/detect-evil-and-good","usage":{"type":"at will"}},{"name":"Detect Magic","level":1,"url":"/api/2014/spells/detect-magic","usage":{"type":"at will"}},{"name":"Thunderwave","level":1,"url":"/api/2014/spells/thunderwave","usage":{"type":"at will"}},{"name":"Create Food and Water","level":3,"notes":"Can create wine instead of water","url":"/api/2014/spells/create-food-and-water","usage":{"type":"per day","times":3}},{"name":"Tongues","level":3,"url":"/api/2014/spells/tongues","usage":{"type":"per day","times":3}},{"name":"Wind Walk","level":6,"url":"/api/2014/spells/wind-walk","usage":{"type":"per day","times":3}},{"name":"Conjure Elemental","level":5,"notes":"Air Elemental Only","url":"/api/2014/spells/conjure-elemental","usage":{"type":"per day","times":1}},{"name":"Creation","level":5,"url":"/api/2014/spells/creation","usage":{"type":"per day","times":1}},{"name":"Gaseous Form","level":3,"url":"/api/2014/spells/gaseous-form","usage":{"type":"per day","times":1}},{"name":"Invisibility","level":2,"url":"/api/2014/spells/invisibility","usage":{"type":"per day","times":1}},{"name":"Major Image","level":3,"url":"/api/2014/spells/major-image","usage":{"type":"per day","times":1}},{"name":"Plane Shift","level":7,"url":"/api/2014/spells/plane-shift","usage":{"type":"per day","times":1}}]}}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The djinni makes three scimitar attacks.","actions":[{"action_name":"Scimitar","count":3,"type":"melee"}]},{"name":"Scimitar","desc":"Melee Weapon Attack: +9 to hit, reach 5 ft., one target. Hit: 12 (2d6 + 5) slashing damage plus 3 (1d6) lightning or thunder damage (djinni''s choice).","attack_bonus":9,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"2d6+5"},{"choose":1,"type":"damage","from":{"option_set_type":"options_array","options":[{"option_type":"damage","damage_type":{"index":"lightning","name":"Lightning","url":"/api/2014/damage-types/lightning"},"damage_dice":"1d6"},{"option_type":"damage","damage_type":{"index":"thunder","name":"Thunder","url":"/api/2014/damage-types/thunder"},"damage_dice":"1d6"}]}}]},{"name":"Create Whirlwind","desc":"A 5-foot-radius, 30-foot-tall cylinder of swirling air magically forms on a point the djinni can see within 120 feet of it. The whirlwind lasts as long as the djinni maintains concentration (as if concentrating on a spell). Any creature but the djinni that enters the whirlwind must succeed on a DC 18 Strength saving throw or be restrained by it. The djinni can move the whirlwind up to 60 feet as an action, and creatures restrained by the whirlwind move with it. The whirlwind ends if the djinni loses sight of it.\nA creature can use its action to free a creature restrained by the whirlwind, including itself, by succeeding on a DC 18 Strength check. If the check succeeds, the creature is no longer restrained and moves to the nearest space outside the whirlwind.","dc":{"dc_type":{"index":"str","name":"STR","url":"/api/2014/ability-scores/str"},"dc_value":18,"success_type":"none"}}],"image":"/api/images/monsters/djinni.png","url":"/api/2014/monsters/djinni"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Doppelganger","desc":null}'::jsonb, '{"index":"doppelganger","name":"Doppelganger","size":"Medium","type":"monstrosity","subtype":"shapechanger","alignment":"unaligned","armor_class":[{"type":"dex","value":14}],"hit_points":52,"hit_dice":"8d8","hit_points_roll":"8d8+16","speed":{"walk":"30 ft."},"strength":11,"dexterity":18,"constitution":14,"intelligence":11,"wisdom":12,"charisma":14,"proficiencies":[{"value":6,"proficiency":{"index":"skill-deception","name":"Skill: Deception","url":"/api/2014/proficiencies/skill-deception"}},{"value":3,"proficiency":{"index":"skill-insight","name":"Skill: Insight","url":"/api/2014/proficiencies/skill-insight"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[{"index":"charmed","name":"Charmed","url":"/api/2014/conditions/charmed"}],"senses":{"darkvision":"60 ft.","passive_perception":11},"languages":"Common","challenge_rating":3,"proficiency_bonus":2,"xp":700,"special_abilities":[{"name":"Shapechanger","desc":"The doppelganger can use its action to polymorph into a Small or Medium humanoid it has seen, or back into its true form. Its statistics, other than its size, are the same in each form. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies."},{"name":"Ambusher","desc":"In the first round of combat, the doppelganger has advantage on attack rolls against any creature it has surprised."},{"name":"Surprise Attack","desc":"If the doppelganger surprises a creature and hits it with an attack during the first round of combat, the target takes an extra 10 (3d6) damage from the attack."}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The doppelganger makes two melee attacks.","actions":[{"action_name":"Slam","count":2,"type":"melee"}]},{"name":"Slam","desc":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 7 (1d6 + 4) bludgeoning damage.","attack_bonus":6,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"1d6+4"}]},{"name":"Read Thoughts","desc":"The doppelganger magically reads the surface thoughts of one creature within 60 ft. of it. The effect can penetrate barriers, but 3 ft. of wood or dirt, 2 ft. of stone, 2 inches of metal, or a thin sheet of lead blocks it. While the target is in range, the doppelganger can continue reading its thoughts, as long as the doppelganger''s concentration isn''t broken (as if concentrating on a spell). While reading the target''s mind, the doppelganger has advantage on Wisdom (Insight) and Charisma (Deception, Intimidation, and Persuasion) checks against the target."}],"image":"/api/images/monsters/doppelganger.png","url":"/api/2014/monsters/doppelganger"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Draft Horse","desc":null}'::jsonb, '{"index":"draft-horse","name":"Draft Horse","size":"Large","type":"beast","alignment":"unaligned","armor_class":[{"type":"dex","value":10}],"hit_points":19,"hit_dice":"3d10","hit_points_roll":"3d10+3","speed":{"walk":"40 ft."},"strength":18,"dexterity":10,"constitution":12,"intelligence":2,"wisdom":11,"charisma":7,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":10},"languages":"","challenge_rating":0.25,"proficiency_bonus":2,"xp":50,"actions":[{"name":"Hooves","desc":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 9 (2d4 + 4) bludgeoning damage.","attack_bonus":6,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"2d4+4"}]}],"image":"/api/images/monsters/draft-horse.png","url":"/api/2014/monsters/draft-horse"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Dragon Turtle","desc":null}'::jsonb, '{"index":"dragon-turtle","name":"Dragon Turtle","size":"Gargantuan","type":"dragon","alignment":"neutral","armor_class":[{"type":"natural","value":20}],"hit_points":341,"hit_dice":"22d20","hit_points_roll":"22d20+110","speed":{"walk":"20 ft.","swim":"40 ft."},"strength":25,"dexterity":10,"constitution":20,"intelligence":10,"wisdom":12,"charisma":12,"proficiencies":[{"value":6,"proficiency":{"index":"saving-throw-dex","name":"Saving Throw: DEX","url":"/api/2014/proficiencies/saving-throw-dex"}},{"value":11,"proficiency":{"index":"saving-throw-con","name":"Saving Throw: CON","url":"/api/2014/proficiencies/saving-throw-con"}},{"value":7,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}}],"damage_vulnerabilities":[],"damage_resistances":["fire"],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"120 ft.","passive_perception":11},"languages":"Aquan, Draconic","challenge_rating":17,"proficiency_bonus":6,"xp":18000,"special_abilities":[{"name":"Amphibious","desc":"The dragon turtle can breathe air and water."}],"actions":[{"name":"Multiattack","multiattack_type":"action_options","desc":"The dragon turtle makes three attacks: one with its bite and two with its claws. It can make one tail attack in place of its two claw attacks.","action_options":{"choose":1,"type":"action","from":{"option_set_type":"options_array","options":[{"option_type":"multiple","items":[{"option_type":"action","action_name":"Bite","count":1,"type":"melee"},{"option_type":"action","action_name":"Claws","count":2,"type":"melee"}]},{"option_type":"multiple","items":[{"option_type":"action","action_name":"Bite","count":1,"type":"melee"},{"option_type":"action","action_name":"Tail","count":1,"type":"melee"}]}]}}},{"name":"Bite","desc":"Melee Weapon Attack: +13 to hit, reach 15 ft., one target. Hit: 26 (3d12 + 7) piercing damage.","attack_bonus":13,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"3d12+7"}]},{"name":"Claw","desc":"Melee Weapon Attack: +13 to hit, reach 10 ft., one target. Hit: 16 (2d8 + 7) slashing damage.","attack_bonus":13,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"2d8+7"}]},{"name":"Tail","desc":"Melee Weapon Attack: +13 to hit, reach 15 ft., one target. Hit: 26 (3d12 + 7) bludgeoning damage. If the target is a creature, it must succeed on a DC 20 Strength saving throw or be pushed up to 10 feet away from the dragon turtle and knocked prone.","attack_bonus":13,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"3d12+7"}]},{"name":"Steam Breath","desc":"The dragon turtle exhales scalding steam in a 60-foot cone. Each creature in that area must make a DC 18 Constitution saving throw, taking 52 (15d6) fire damage on a failed save, or half as much damage on a successful one. Being underwater doesn''t grant resistance against this damage.","usage":{"type":"recharge on roll","dice":"1d6","min_value":5},"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_value":18,"success_type":"half"},"damage":[{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_dice":"15d6"}]}],"image":"/api/images/monsters/dragon-turtle.png","url":"/api/2014/monsters/dragon-turtle"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Dretch","desc":null}'::jsonb, '{"index":"dretch","name":"Dretch","size":"Small","type":"fiend","subtype":"demon","alignment":"chaotic evil","armor_class":[{"type":"natural","value":11}],"hit_points":18,"hit_dice":"4d6","hit_points_roll":"4d6+4","speed":{"walk":"20 ft."},"strength":11,"dexterity":11,"constitution":12,"intelligence":5,"wisdom":8,"charisma":3,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":["cold","fire","lightning"],"damage_immunities":["poison"],"condition_immunities":[{"index":"poisoned","name":"Poisoned","url":"/api/2014/conditions/poisoned"}],"senses":{"darkvision":"60 ft.","passive_perception":9},"languages":"Abyssal, telepathy 60 ft. (works only with creatures that understand Abyssal)","challenge_rating":0.25,"proficiency_bonus":2,"xp":25,"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The dretch makes two attacks: one with its bite and one with its claws.","actions":[{"action_name":"Bite","count":1,"type":"melee"},{"action_name":"Claws","count":1,"type":"melee"}]},{"name":"Bite","desc":"Melee Weapon Attack: +2 to hit, reach 5 ft., one target. Hit: 3 (1d6) piercing damage.","attack_bonus":2,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d6"}]},{"name":"Claws","desc":"Melee Weapon Attack: +2 to hit, reach 5 ft., one target. Hit: 5 (2d4) slashing damage.","attack_bonus":2,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"2d4"}]},{"name":"Fetid Cloud","desc":"A 10-foot radius of disgusting green gas extends out from the dretch. The gas spreads around corners, and its area is lightly obscured. It lasts for 1 minute or until a strong wind disperses it. Any creature that starts its turn in that area must succeed on a DC 11 Constitution saving throw or be poisoned until the start of its next turn. While poisoned in this way, the target can take either an action or a bonus action on its turn, not both, and can''t take reactions.","usage":{"type":"per day","times":1},"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_value":11,"success_type":"none"}}],"image":"/api/images/monsters/dretch.png","url":"/api/2014/monsters/dretch"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Drider","desc":null}'::jsonb, '{"index":"drider","name":"Drider","size":"Large","type":"monstrosity","alignment":"chaotic evil","armor_class":[{"type":"natural","value":19}],"hit_points":123,"hit_dice":"13d10","hit_points_roll":"13d10+52","speed":{"walk":"30 ft.","climb":"30 ft."},"strength":16,"dexterity":16,"constitution":18,"intelligence":13,"wisdom":14,"charisma":12,"proficiencies":[{"value":5,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"value":9,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"120 ft.","passive_perception":15},"languages":"Elvish, Undercommon","challenge_rating":6,"proficiency_bonus":3,"xp":2300,"special_abilities":[{"name":"Fey Ancestry","desc":"The drider has advantage on saving throws against being charmed, and magic can''t put the drider to sleep."},{"name":"Innate Spellcasting","desc":"The drider''s innate spellcasting ability is Wisdom (spell save DC 13). The drider can innately cast the following spells, requiring no material components:\nAt will: dancing lights\n1/day each: darkness, faerie fire","spellcasting":{"ability":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc":13,"components_required":["V","S"],"spells":[{"name":"Dancing Lights","level":1,"url":"/api/2014/spells/dancing-lights","usage":{"type":"at will"}},{"name":"Darkness","level":2,"url":"/api/2014/spells/darkness","usage":{"type":"per day","times":1}},{"name":"Faerie Fire","level":1,"url":"/api/2014/spells/faerie-fire","usage":{"type":"per day","times":1}}]}},{"name":"Spider Climb","desc":"The drider can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."},{"name":"Sunlight Sensitivity","desc":"While in sunlight, the drider has disadvantage on attack rolls, as well as on Wisdom (Perception) checks that rely on sight."},{"name":"Web Walker","desc":"The drider ignores movement restrictions caused by webbing."}],"actions":[{"name":"Multiattack","multiattack_type":"action_options","desc":"The drider makes three attacks, either with its longsword or its longbow. It can replace one of those attacks with a bite attack.","action_options":{"choose":1,"type":"action","from":{"option_set_type":"options_array","options":[{"option_type":"action","action_name":"Longsword","count":3,"type":"melee"},{"option_type":"action","action_name":"Longbow","count":3,"type":"ranged"},{"option_type":"multiple","items":[{"option_type":"action","action_name":"Longsword","count":2,"type":"melee"},{"option_type":"action","action_name":"Bite","count":1,"type":"melee"}]},{"option_type":"multiple","items":[{"option_type":"action","action_name":"Longbow","count":2,"type":"ranged"},{"option_type":"action","action_name":"Bite","count":1,"type":"melee"}]}]}}},{"name":"Bite","desc":"Melee Weapon Attack: +6 to hit, reach 5 ft., one creature. Hit: 2 (1d4) piercing damage plus 9 (2d8) poison damage.","attack_bonus":6,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d4"},{"damage_type":{"index":"poison","name":"Poison","url":"/api/2014/damage-types/poison"},"damage_dice":"2d8"}]},{"name":"Longsword","desc":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 7 (1d8 + 3) slashing damage, or 8 (1d10 + 3) slashing damage if used with two hands.","attack_bonus":6,"damage":[{"choose":1,"type":"damage","from":{"option_set_type":"options_array","options":[{"option_type":"damage","damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"1d8+3","notes":"One handed"},{"option_type":"damage","damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"1d10+3","notes":"Two handed"}]}}]},{"name":"Longbow","desc":"Ranged Weapon Attack: +6 to hit, range 150/600 ft., one target. Hit: 7 (1d8 + 3) piercing damage plus 4 (1d8) poison damage.","attack_bonus":6,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d8+3"},{"damage_type":{"index":"poison","name":"Poison","url":"/api/2014/damage-types/poison"},"damage_dice":"1d8"}]}],"image":"/api/images/monsters/drider.png","url":"/api/2014/monsters/drider"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Drow","desc":null}'::jsonb, '{"index":"drow","name":"Drow","size":"Medium","type":"humanoid","subtype":"elf","alignment":"neutral evil","armor_class":[{"type":"armor","value":15,"armor":[{"index":"chain-shirt","name":"Chain Shirt","url":"/api/2014/equipment/chain-shirt"}]}],"hit_points":13,"hit_dice":"3d8","hit_points_roll":"3d8","speed":{"walk":"30 ft."},"strength":10,"dexterity":14,"constitution":10,"intelligence":11,"wisdom":11,"charisma":12,"proficiencies":[{"value":2,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"value":4,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"120 ft.","passive_perception":12},"languages":"Elvish, Undercommon","challenge_rating":0.25,"proficiency_bonus":2,"xp":50,"special_abilities":[{"name":"Fey Ancestry","desc":"The drow has advantage on saving throws against being charmed, and magic can''t put the drow to sleep."},{"name":"Innate Spellcasting","desc":"The drow''s spellcasting ability is Charisma (spell save DC 11). It can innately cast the following spells, requiring no material components:\nAt will: dancing lights\n1/day each: darkness, faerie fire","spellcasting":{"ability":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"dc":11,"modifier":0,"components_required":["V","S"],"spells":[{"name":"Dancing Lights","level":0,"url":"/api/2014/spells/dancing-lights","usage":{"type":"at will"}},{"name":"Darkness","level":2,"url":"/api/2014/spells/darkness","usage":{"type":"per day","times":1}},{"name":"Faerie Fire","level":1,"url":"/api/2014/spells/faerie-fire","usage":{"type":"per day","times":1}}]}},{"name":"Sunlight Sensitivity","desc":"While in sunlight, the drow has disadvantage on attack rolls, as well as on Wisdom (Perception) checks that rely on sight."}],"actions":[{"name":"Shortsword","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 5 (1d6 + 2) piercing damage.","attack_bonus":4,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d6+2"}]},{"name":"Hand Crossbow","desc":"Ranged Weapon Attack: +4 to hit, range 30/120 ft., one target. Hit: 5 (1d6 + 2) piercing damage, and the target must succeed on a DC 13 Constitution saving throw or be poisoned for 1 hour. If the saving throw fails by 5 or more, the target is also unconscious while poisoned in this way. The target wakes up if it takes damage or if another creature takes an action to shake it awake.","attack_bonus":4,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d6+2"}]}],"image":"/api/images/monsters/drow.png","url":"/api/2014/monsters/drow"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Druid","desc":"**Druids** dwell in forests and other secluded wilderness locations, where they protect the natural world from monsters and the encroachment of civilization. Some are **tribal shamans** who heal the sick, pray to animal spirits, and provide spiritual guidance."}'::jsonb, '{"index":"druid","name":"Druid","desc":"**Druids** dwell in forests and other secluded wilderness locations, where they protect the natural world from monsters and the encroachment of civilization. Some are **tribal shamans** who heal the sick, pray to animal spirits, and provide spiritual guidance.","size":"Medium","type":"humanoid","subtype":"any race","alignment":"any alignment","armor_class":[{"type":"dex","value":11},{"type":"spell","value":16,"spell":{"index":"barkskin","name":"Barkskin","url":"/api/2014/spells/barkskin"}}],"hit_points":27,"hit_dice":"5d8","hit_points_roll":"5d8+5","speed":{"walk":"30 ft."},"strength":10,"dexterity":12,"constitution":13,"intelligence":12,"wisdom":15,"charisma":11,"proficiencies":[{"value":4,"proficiency":{"index":"skill-medicine","name":"Skill: Medicine","url":"/api/2014/proficiencies/skill-medicine"}},{"value":3,"proficiency":{"index":"skill-nature","name":"Skill: Nature","url":"/api/2014/proficiencies/skill-nature"}},{"value":4,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":14},"languages":"Druidic plus any two languages","challenge_rating":2,"proficiency_bonus":2,"xp":450,"special_abilities":[{"name":"Spellcasting","desc":"The druid is a 4th-level spellcaster. Its spellcasting ability is Wisdom (spell save DC 12, +4 to hit with spell attacks). It has the following druid spells prepared:\n\n- Cantrips (at will): druidcraft, produce flame, shillelagh\n- 1st level (4 slots): entangle, longstrider, speak with animals, thunderwave\n- 2nd level (3 slots): animal messenger, barkskin","spellcasting":{"level":4,"ability":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc":12,"modifier":4,"components_required":["V","S","M"],"school":"druid","slots":{"1":4,"2":3},"spells":[{"name":"Druidcraft","level":0,"url":"/api/2014/spells/druidcraft"},{"name":"Produce Flame","level":0,"url":"/api/2014/spells/produce-flame"},{"name":"Shillelagh","level":0,"url":"/api/2014/spells/shillelagh"},{"name":"Entangle","level":1,"url":"/api/2014/spells/entangle"},{"name":"Longstrider","level":1,"url":"/api/2014/spells/longstrider"},{"name":"Speak with Animals","level":1,"url":"/api/2014/spells/speak-with-animals"},{"name":"Thunderwave","level":1,"url":"/api/2014/spells/thunderwave"},{"name":"Animal Messenger","level":2,"url":"/api/2014/spells/animal-messenger"},{"name":"Barkskin","level":2,"url":"/api/2014/spells/barkskin"}]}}],"actions":[{"name":"Quarterstaff","desc":" Melee Weapon Attack: +2 to hit (+4 to hit with shillelagh), reach 5 ft., one target. Hit: 3 (1d6) bludgeoning damage, 4 (1d8) bludgeoning damage if wielded with two hands, or 6 (1d8 + 2) bludgeoning damage with shillelagh.","attack_bonus":2,"damage":[{"choose":1,"type":"damage","from":{"option_set_type":"options_array","options":[{"option_type":"damage","damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"1d6","notes":"One handed"},{"option_type":"damage","damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"1d8","notes":"Two handed"},{"option_type":"damage","damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"1d8+2","notes":"With shillelagh"}]}}]}],"image":"/api/images/monsters/druid.png","url":"/api/2014/monsters/druid"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Dryad","desc":null}'::jsonb, '{"index":"dryad","name":"Dryad","size":"Medium","type":"fey","alignment":"neutral","armor_class":[{"type":"dex","value":11},{"type":"spell","value":16,"spell":{"index":"barkskin","name":"Barkskin","url":"/api/2014/spells/barkskin"}}],"hit_points":22,"hit_dice":"5d8","hit_points_roll":"5d8","speed":{"walk":"30 ft."},"strength":10,"dexterity":12,"constitution":11,"intelligence":14,"wisdom":15,"charisma":18,"proficiencies":[{"value":4,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"value":5,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"60 ft.","passive_perception":14},"languages":"Elvish, Sylvan","challenge_rating":1,"proficiency_bonus":2,"xp":200,"special_abilities":[{"name":"Innate Spellcasting","desc":"The dryad''s innate spellcasting ability is Charisma (spell save DC 14). The dryad can innately cast the following spells, requiring no material components:\n\nAt will: druidcraft\n3/day each: entangle, goodberry\n1/day each: barkskin, pass without trace, shillelagh","spellcasting":{"ability":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"dc":14,"components_required":["V","S"],"spells":[{"name":"Druidcraft","level":0,"url":"/api/2014/spells/druidcraft","usage":{"type":"at will"}},{"name":"Entangle","level":1,"url":"/api/2014/spells/entangle","usage":{"type":"per day","times":3}},{"name":"Goodberry","level":1,"url":"/api/2014/spells/goodberry","usage":{"type":"per day","times":3}},{"name":"Barkskin","level":2,"url":"/api/2014/spells/barkskin","usage":{"type":"per day","times":1}},{"name":"Pass Without Trace","level":2,"url":"/api/2014/spells/pass-without-trace","usage":{"type":"per day","times":1}},{"name":"Shillelagh","level":0,"url":"/api/2014/spells/shillelagh","usage":{"type":"per day","times":1}}]}},{"name":"Magic Resistance","desc":"The dryad has advantage on saving throws against spells and other magical effects."},{"name":"Speak with Beasts and Plants","desc":"The dryad can communicate with beasts and plants as if they shared a language."},{"name":"Tree Stride","desc":"Once on her turn, the dryad can use 10 ft. of her movement to step magically into one living tree within her reach and emerge from a second living tree within 60 ft. of the first tree, appearing in an unoccupied space within 5 ft. of the second tree. Both trees must be large or bigger."}],"actions":[{"name":"Club","desc":"Melee Weapon Attack: +2 to hit (+6 to hit with shillelagh), reach 5 ft., one target. Hit: 2 (1d4) bludgeoning damage, or 8 (1d8 + 4) bludgeoning damage with shillelagh.","attack_bonus":2,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"1d4"}]},{"name":"Fey Charm","desc":"The dryad targets one humanoid or beast that she can see within 30 feet of her. If the target can see the dryad, it must succeed on a DC 14 Wisdom saving throw or be magically charmed. The charmed creature regards the dryad as a trusted friend to be heeded and protected. Although the target isn''t under the dryad''s control, it takes the dryad''s requests or actions in the most favorable way it can.\nEach time the dryad or its allies do anything harmful to the target, it can repeat the saving throw, ending the effect on itself on a success. Otherwise, the effect lasts 24 hours or until the dryad dies, is on a different plane of existence from the target, or ends the effect as a bonus action. If a target''s saving throw is successful, the target is immune to the dryad''s Fey Charm for the next 24 hours.\nThe dryad can have no more than one humanoid and up to three beasts charmed at a time.","dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_value":14,"success_type":"none"}}],"image":"/api/images/monsters/dryad.png","url":"/api/2014/monsters/dryad"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Duergar","desc":null}'::jsonb, '{"index":"duergar","name":"Duergar","size":"Medium","type":"humanoid","subtype":"dwarf","alignment":"lawful evil","armor_class":[{"type":"armor","value":16,"armor":[{"index":"scale-mail","name":"Scale Mail","url":"/api/2014/equipment/scale-mail"},{"index":"shield","name":"Shield","url":"/api/2014/equipment/shield"}]}],"hit_points":26,"hit_dice":"4d8","hit_points_roll":"4d8+8","speed":{"walk":"25 ft."},"strength":14,"dexterity":11,"constitution":14,"intelligence":11,"wisdom":10,"charisma":9,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":["poison"],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"120 ft.","passive_perception":10},"languages":"Dwarvish, Undercommon","challenge_rating":1,"proficiency_bonus":2,"xp":200,"special_abilities":[{"name":"Duergar Resilience","desc":"The duergar has advantage on saving throws against poison, spells, and illusions, as well as to resist being charmed or paralyzed."},{"name":"Sunlight Sensitivity","desc":"While in sunlight, the duergar has disadvantage on attack rolls, as well as on Wisdom (Perception) checks that rely on sight."}],"actions":[{"name":"Enlarge","desc":"For 1 minute, the duergar magically increases in size, along with anything it is wearing or carrying. While enlarged, the duergar is Large, doubles its damage dice on Strength-based weapon attacks (included in the attacks), and makes Strength checks and Strength saving throws with advantage. If the duergar lacks the room to become Large, it attains the maximum size possible in the space available.","usage":{"type":"recharge after rest","rest_types":["short","long"]}},{"name":"War Pick","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 6 (1d8 + 2) piercing damage, or 11 (2d8 + 2) piercing damage while enlarged.","attack_bonus":4,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d8+2"}]},{"name":"Javelin","desc":"Melee or Ranged Weapon Attack: +4 to hit, reach 5 ft. or range 30/120 ft., one target. Hit: 5 (1d6 + 2) piercing damage, or 9 (2d6 + 2) piercing damage while enlarged.","attack_bonus":4,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d6+2"}]},{"name":"Invisibility","desc":"The duergar magically turns invisible until it attacks, casts a spell, or uses its Enlarge, or until its concentration is broken, up to 1 hour (as if concentrating on a spell). Any equipment the duergar wears or carries is invisible with it.","usage":{"type":"recharge after rest","rest_types":["short","long"]}}],"image":"/api/images/monsters/duergar.png","url":"/api/2014/monsters/duergar"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Dust Mephit","desc":null}'::jsonb, '{"index":"dust-mephit","name":"Dust Mephit","size":"Small","type":"elemental","alignment":"neutral evil","armor_class":[{"type":"dex","value":12}],"hit_points":17,"hit_dice":"5d6","hit_points_roll":"5d6","speed":{"walk":"30 ft.","fly":"30 ft."},"strength":5,"dexterity":14,"constitution":10,"intelligence":9,"wisdom":11,"charisma":10,"proficiencies":[{"value":2,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"value":4,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":["fire"],"damage_resistances":[],"damage_immunities":["poison"],"condition_immunities":[{"index":"poisoned","name":"Poisoned","url":"/api/2014/conditions/poisoned"}],"senses":{"darkvision":"60 ft.","passive_perception":12},"languages":"Auran, Terran","challenge_rating":0.5,"proficiency_bonus":2,"xp":100,"special_abilities":[{"name":"Death Burst","desc":"When the mephit dies, it explodes in a burst of dust. Each creature within 5 ft. of it must then succeed on a DC 10 Constitution saving throw or be blinded for 1 minute. A blinded creature can repeat the saving throw on each of its turns, ending the effect on itself on a success.","dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_value":10,"success_type":"none"}},{"name":"Innate Spellcasting","desc":"The mephit can innately cast sleep, requiring no material components. Its innate spellcasting ability is Charisma.","spellcasting":{"ability":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"dc":10,"components_required":["V","S"],"spells":[{"name":"Sleep","level":1,"url":"/api/2014/spells/sleep","usage":{"type":"per day","times":1}}]}}],"actions":[{"name":"Claws","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 4 (1d4 + 2) slashing damage.","attack_bonus":4,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"1d4+2"}]},{"name":"Blinding Breath","desc":"The mephit exhales a 15-foot cone of blinding dust. Each creature in that area must succeed on a DC 10 Dexterity saving throw or be blinded for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","usage":{"type":"recharge on roll","dice":"1d6","min_value":6},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_value":10,"success_type":"none"}}],"image":"/api/images/monsters/dust-mephit.png","url":"/api/2014/monsters/dust-mephit"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Eagle","desc":null}'::jsonb, '{"index":"eagle","name":"Eagle","size":"Small","type":"beast","alignment":"unaligned","armor_class":[{"type":"dex","value":12}],"hit_points":3,"hit_dice":"1d6","hit_points_roll":"1d6","speed":{"walk":"10 ft.","fly":"60 ft."},"strength":6,"dexterity":15,"constitution":10,"intelligence":2,"wisdom":14,"charisma":7,"proficiencies":[{"value":4,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":14},"languages":"","challenge_rating":0,"proficiency_bonus":2,"xp":10,"special_abilities":[{"name":"Keen Sight","desc":"The eagle has advantage on Wisdom (Perception) checks that rely on sight."}],"actions":[{"name":"Talons","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 4 (1d4 + 2) slashing damage.","attack_bonus":4,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"1d4+2"}]}],"image":"/api/images/monsters/eagle.png","url":"/api/2014/monsters/eagle"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Earth Elemental","desc":null}'::jsonb, '{"index":"earth-elemental","name":"Earth Elemental","size":"Large","type":"elemental","alignment":"neutral","armor_class":[{"type":"natural","value":17}],"hit_points":126,"hit_dice":"12d10","hit_points_roll":"12d10+60","speed":{"walk":"30 ft.","burrow":"30 ft."},"strength":20,"dexterity":8,"constitution":20,"intelligence":5,"wisdom":10,"charisma":5,"proficiencies":[],"damage_vulnerabilities":["thunder"],"damage_resistances":["bludgeoning, piercing, and slashing from nonmagical weapons"],"damage_immunities":["poison"],"condition_immunities":[{"index":"exhaustion","name":"Exhaustion","url":"/api/2014/conditions/exhaustion"},{"index":"paralyzed","name":"Paralyzed","url":"/api/2014/conditions/paralyzed"},{"index":"petrified","name":"Petrified","url":"/api/2014/conditions/petrified"},{"index":"poisoned","name":"Poisoned","url":"/api/2014/conditions/poisoned"},{"index":"unconscious","name":"Unconscious","url":"/api/2014/conditions/unconscious"}],"senses":{"darkvision":"60 ft.","tremorsense":"60 ft.","passive_perception":10},"languages":"Terran","challenge_rating":5,"proficiency_bonus":3,"xp":1800,"special_abilities":[{"name":"Earth Glide","desc":"The elemental can burrow through nonmagical, unworked earth and stone. While doing so, the elemental doesn''t disturb the material it moves through."},{"name":"Siege Monster","desc":"The elemental deals double damage to objects and structures."}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The elemental makes two slam attacks.","actions":[{"action_name":"Slam","count":2,"type":"melee"}]},{"name":"Slam","desc":"Melee Weapon Attack: +8 to hit, reach 10 ft., one target. Hit: 14 (2d8 + 5) bludgeoning damage.","attack_bonus":8,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"2d8+5"}]}],"image":"/api/images/monsters/earth-elemental.png","url":"/api/2014/monsters/earth-elemental"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Efreeti","desc":null}'::jsonb, '{"index":"efreeti","name":"Efreeti","size":"Large","type":"elemental","alignment":"lawful evil","armor_class":[{"type":"natural","value":17}],"hit_points":200,"hit_dice":"16d10","hit_points_roll":"16d10+112","speed":{"walk":"40 ft.","fly":"60 ft."},"strength":22,"dexterity":12,"constitution":24,"intelligence":16,"wisdom":15,"charisma":16,"proficiencies":[{"value":7,"proficiency":{"index":"saving-throw-int","name":"Saving Throw: INT","url":"/api/2014/proficiencies/saving-throw-int"}},{"value":6,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}},{"value":7,"proficiency":{"index":"saving-throw-cha","name":"Saving Throw: CHA","url":"/api/2014/proficiencies/saving-throw-cha"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":["fire"],"condition_immunities":[],"senses":{"darkvision":"120 ft.","passive_perception":12},"languages":"Ignan","challenge_rating":11,"proficiency_bonus":4,"xp":7200,"special_abilities":[{"name":"Elemental Demise","desc":"If the efreeti dies, its body disintegrates in a flash of fire and puff of smoke, leaving behind only equipment the djinni was wearing or carrying."},{"name":"Innate Spellcasting","desc":"The efreeti''s innate spell casting ability is Charisma (spell save DC 15, +7 to hit with spell attacks). It can innately cast the following spells, requiring no material components:\n\nAt will: detect magic\n3/day: enlarge/reduce, tongues\n1/day each: conjure elemental (fire elemental only), gaseous form, invisibility, major image, plane shift, wall of fire","spellcasting":{"ability":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"dc":15,"modifier":7,"components_required":["V","S"],"spells":[{"name":"Detect Magic","level":1,"url":"/api/2014/spells/detect-magic","usage":{"type":"at will"}},{"name":"Enlarge/Reduce","level":2,"url":"/api/2014/spells/enlarge-reduce","usage":{"type":"per day","times":3}},{"name":"Tongues","level":3,"url":"/api/2014/spells/tongues","usage":{"type":"per day","times":3}},{"name":"Conjure Elemental","level":5,"notes":"Fire Elemental only","url":"/api/2014/spells/conjure-elemental","usage":{"type":"per day","times":1}},{"name":"Gaseous Form","level":3,"url":"/api/2014/spells/gaseous-form","usage":{"type":"per day","times":1}},{"name":"Invisibility","level":2,"url":"/api/2014/spells/invisibility","usage":{"type":"per day","times":1}},{"name":"Major Image","level":3,"url":"/api/2014/spells/major-image","usage":{"type":"per day","times":1}},{"name":"Plane Shift","level":7,"url":"/api/2014/spells/plane-shift","usage":{"type":"per day","times":1}},{"name":"Wall of Fire","level":4,"url":"/api/2014/spells/wall-of-fire","usage":{"type":"per day","times":1}}]}}],"actions":[{"name":"Multiattack","multiattack_type":"action_options","desc":"The efreeti makes two scimitar attacks or uses its Hurl Flame twice.","action_options":{"choose":1,"type":"action","from":{"option_set_type":"options_array","options":[{"option_type":"action","action_name":"Scimitar","count":2,"type":"melee"},{"option_type":"action","action_name":"Hurl Flame","count":2,"type":"ranged"}]}}},{"name":"Scimitar","desc":"Melee Weapon Attack: +10 to hit, reach 5 ft., one target. Hit: 13 (2d6 + 6) slashing damage plus 7 (2d6) fire damage.","attack_bonus":10,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"2d6+6"},{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_dice":"2d6"}]},{"name":"Hurl Flame","desc":"Ranged Spell Attack: +7 to hit, range 120 ft., one target. Hit: 17 (5d6) fire damage.","attack_bonus":7,"damage":[{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_dice":"5d6"}]}],"image":"/api/images/monsters/efreeti.png","url":"/api/2014/monsters/efreeti"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Elephant","desc":null}'::jsonb, '{"index":"elephant","name":"Elephant","size":"Huge","type":"beast","alignment":"unaligned","armor_class":[{"type":"natural","value":12}],"hit_points":76,"hit_dice":"8d12","hit_points_roll":"8d12+24","speed":{"walk":"40 ft."},"strength":22,"dexterity":9,"constitution":17,"intelligence":3,"wisdom":11,"charisma":6,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":10},"languages":"","challenge_rating":4,"proficiency_bonus":2,"xp":1100,"special_abilities":[{"name":"Trampling Charge","desc":"If the elephant moves at least 20 ft. straight toward a creature and then hits it with a gore attack on the same turn, that target must succeed on a DC 12 Strength saving throw or be knocked prone. If the target is prone, the elephant can make one stomp attack against it as a bonus action."}],"actions":[{"name":"Gore","desc":"Melee Weapon Attack: +8 to hit, reach 5 ft., one target. Hit: 19 (3d8 + 6) piercing damage.","attack_bonus":8,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"3d8+6"}]},{"name":"Stomp","desc":"Melee Weapon Attack: +8 to hit, reach 5 ft., one prone creature. Hit: 22 (3d10 + 6) bludgeoning damage.","attack_bonus":8,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"3d10+6"}]}],"image":"/api/images/monsters/elephant.png","url":"/api/2014/monsters/elephant"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Elk","desc":null}'::jsonb, '{"index":"elk","name":"Elk","size":"Large","type":"beast","alignment":"unaligned","armor_class":[{"type":"dex","value":10}],"hit_points":13,"hit_dice":"2d10","hit_points_roll":"2d10+2","speed":{"walk":"50 ft."},"strength":16,"dexterity":10,"constitution":12,"intelligence":2,"wisdom":10,"charisma":6,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":10},"languages":"","challenge_rating":0.25,"proficiency_bonus":2,"xp":50,"special_abilities":[{"name":"Charge","desc":"If the elk moves at least 20 ft. straight toward a target and then hits it with a ram attack on the same turn, the target takes an extra 7 (2d6) damage. If the target is a creature, it must succeed on a DC 13 Strength saving throw or be knocked prone."}],"actions":[{"name":"Ram","desc":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) bludgeoning damage.","attack_bonus":5,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"1d6+3"}]},{"name":"Hooves","desc":"Melee Weapon Attack: +5 to hit, reach 5 ft., one prone creature. Hit: 8 (2d4 + 3) bludgeoning damage.","attack_bonus":5,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"2d4+3"}]}],"image":"/api/images/monsters/elk.png","url":"/api/2014/monsters/elk"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Erinyes","desc":null}'::jsonb, '{"index":"erinyes","name":"Erinyes","size":"Medium","type":"fiend","subtype":"devil","alignment":"lawful evil","armor_class":[{"type":"armor","value":18,"armor":[{"index":"plate-armor","name":"Plate Armor","url":"/api/2014/equipment/plate-armor"}]}],"hit_points":153,"hit_dice":"18d8","hit_points_roll":"18d8+72","speed":{"walk":"30 ft.","fly":"60 ft."},"strength":18,"dexterity":16,"constitution":18,"intelligence":14,"wisdom":14,"charisma":18,"proficiencies":[{"value":7,"proficiency":{"index":"saving-throw-dex","name":"Saving Throw: DEX","url":"/api/2014/proficiencies/saving-throw-dex"}},{"value":8,"proficiency":{"index":"saving-throw-con","name":"Saving Throw: CON","url":"/api/2014/proficiencies/saving-throw-con"}},{"value":6,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}},{"value":8,"proficiency":{"index":"saving-throw-cha","name":"Saving Throw: CHA","url":"/api/2014/proficiencies/saving-throw-cha"}}],"damage_vulnerabilities":[],"damage_resistances":["cold","bludgeoning, piercing, and slashing from nonmagical weapons that aren''t silvered"],"damage_immunities":["fire","poison"],"condition_immunities":[{"index":"poisoned","name":"Poisoned","url":"/api/2014/conditions/poisoned"}],"senses":{"truesight":"120 ft.","passive_perception":12},"languages":"Infernal, telepathy 120 ft.","challenge_rating":12,"proficiency_bonus":4,"xp":8400,"special_abilities":[{"name":"Hellish Weapons","desc":"The erinyes''s weapon attacks are magical and deal an extra 13 (3d8) poison damage on a hit (included in the attacks)."},{"name":"Magic Resistance","desc":"The erinyes has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Multiattack","multiattack_type":"action_options","desc":"The erinyes makes three attacks","action_options":{"choose":1,"type":"action","from":{"option_set_type":"