  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Giant Rat","desc":null}'::jsonb, '{"index":"giant-rat","name":"Giant Rat","size":"Small","type":"beast","alignment":"unaligned","armor_class":[{"type":"dex","value":12}],"hit_points":7,"hit_dice":"2d6","hit_points_roll":"2d6","speed":{"walk":"30 ft."},"strength":7,"dexterity":15,"constitution":11,"intelligence":2,"wisdom":10,"charisma":4,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"60 ft.","passive_perception":10},"languages":"","challenge_rating":0.125,"proficiency_bonus":2,"xp":25,"special_abilities":[{"name":"Keen Smell","desc":"The rat has advantage on Wisdom (Perception) checks that rely on smell."},{"name":"Pack Tactics","desc":"The rat has advantage on an attack roll against a creature if at least one of the rat''s allies is within 5 ft. of the creature and the ally isn''t incapacitated."}],"actions":[{"name":"Bite","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 4 (1d4 + 2) piercing damage.","attack_bonus":4,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d4+2"}]}],"image":"/api/images/monsters/giant-rat.png","url":"/api/2014/monsters/giant-rat"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Giant Rat (Diseased)","desc":null}'::jsonb, '{"index":"giant-rat-diseased","name":"Giant Rat (Diseased)","size":"Small","type":"beast","alignment":"unaligned","armor_class":[{"type":"dex","value":12}],"hit_points":7,"hit_dice":"2d6","hit_points_roll":"2d6","speed":{"walk":"30 ft."},"strength":7,"dexterity":15,"constitution":11,"intelligence":2,"wisdom":10,"charisma":4,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"60 ft.","passive_perception":10},"languages":"","challenge_rating":0.125,"proficiency_bonus":2,"xp":25,"special_abilities":[{"name":"Keen Smell","desc":"The rat has advantage on Wisdom (Perception) checks that rely on smell."},{"name":"Pack Tactics","desc":"The rat has advantage on an attack roll against a creature if at least one of the rat''s allies is within 5 ft. of the creature and the ally isn''t incapacitated."}],"actions":[{"name":"Bite","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 3 (1d4 + 2) piercing damage. If the target is a creature, it must succeed on a DC 10 Constitution saving throw or contract a disease. Until the disease is cured, the target can''t regain hit points except by magical means, and the target''s hit point maximum decreases by 3 (1d6) every 24 hours. If the target''s hit point maximum drops to 0 as a result of this disease, the target dies.","attack_bonus":4,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d4+2"}]}],"image":"/api/images/monsters/giant-rat-diseased.png","url":"/api/2014/monsters/giant-rat-diseased"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Giant Scorpion","desc":null}'::jsonb, '{"index":"giant-scorpion","name":"Giant Scorpion","size":"Large","type":"beast","alignment":"unaligned","armor_class":[{"type":"natural","value":15}],"hit_points":52,"hit_dice":"7d10","hit_points_roll":"7d10+14","speed":{"walk":"40 ft."},"strength":15,"dexterity":13,"constitution":15,"intelligence":1,"wisdom":9,"charisma":3,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"blindsight":"60 ft.","passive_perception":9},"languages":"","challenge_rating":3,"proficiency_bonus":2,"xp":700,"actions":[{"name":"Claw","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 6 (1d8 + 2) bludgeoning damage, and the target is grappled (escape DC 12). The scorpion has two claws, each of which can grapple only one target.","attack_bonus":4,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"1d8+2"}]},{"name":"Multiattack","multiattack_type":"actions","desc":"The scorpion makes three attacks: two with its claws and one with its sting.","actions":[{"action_name":"Claw","count":2,"type":"melee"},{"action_name":"Sting","count":1,"type":"melee"}]},{"name":"Sting","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 7 (1d10 + 2) piercing damage, and the target must make a DC 12 Constitution saving throw, taking 22 (4d10) poison damage on a failed save, or half as much damage on a successful one.","attack_bonus":4,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d10+2"}]}],"image":"/api/images/monsters/giant-scorpion.png","url":"/api/2014/monsters/giant-scorpion"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Giant Sea Horse","desc":"Like their smaller kin, giant sea horses are shy, colorful fish with elongated bodies and curled tails. Aquatic elves train them as mounts."}'::jsonb, '{"index":"giant-sea-horse","name":"Giant Sea Horse","desc":"Like their smaller kin, giant sea horses are shy, colorful fish with elongated bodies and curled tails. Aquatic elves train them as mounts.","size":"Large","type":"beast","alignment":"unaligned","armor_class":[{"type":"natural","value":13}],"hit_points":16,"hit_dice":"3d10","hit_points_roll":"3d10","speed":{"walk":"0 ft.","swim":"40 ft."},"strength":12,"dexterity":15,"constitution":11,"intelligence":2,"wisdom":12,"charisma":5,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":11},"languages":"","challenge_rating":0.5,"proficiency_bonus":2,"xp":100,"special_abilities":[{"name":"Charge","desc":"If the sea horse moves at least 20 ft. straight toward a target and then hits it with a ram attack on the same turn, the target takes an extra 7 (2d6) bludgeoning damage. If the target is a creature, it must succeed on a DC 11 Strength saving throw or be knocked prone."},{"name":"Water Breathing","desc":"The sea horse can breathe only underwater."}],"actions":[{"name":"Ram","desc":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 4 (1d6 + 1) bludgeoning damage.","attack_bonus":3,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"1d6+1"}]}],"image":"/api/images/monsters/giant-sea-horse.png","url":"/api/2014/monsters/giant-sea-horse"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Giant Shark","desc":"A giant shark is 30 feet long and normally found in deep oceans. Utterly fearless, it preys on anything that crosses its path, including whales and ships."}'::jsonb, '{"index":"giant-shark","name":"Giant Shark","desc":"A giant shark is 30 feet long and normally found in deep oceans. Utterly fearless, it preys on anything that crosses its path, including whales and ships.","size":"Huge","type":"beast","alignment":"unaligned","armor_class":[{"type":"natural","value":13}],"hit_points":126,"hit_dice":"11d12","hit_points_roll":"11d12+55","speed":{"swim":"50 ft."},"strength":23,"dexterity":11,"constitution":21,"intelligence":1,"wisdom":10,"charisma":5,"proficiencies":[{"value":3,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"blindsight":"60 ft.","passive_perception":13},"languages":"","challenge_rating":5,"proficiency_bonus":3,"xp":1800,"special_abilities":[{"name":"Blood Frenzy","desc":"The shark has advantage on melee attack rolls against any creature that doesn''t have all its hit points."},{"name":"Water Breathing","desc":"The shark can breathe only underwater."}],"actions":[{"name":"Bite","desc":"Melee Weapon Attack: +9 to hit, reach 5 ft., one target. Hit: 22 (3d10 + 6) piercing damage.","attack_bonus":9,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"3d10+6"}]}],"image":"/api/images/monsters/giant-shark.png","url":"/api/2014/monsters/giant-shark"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Giant Spider","desc":"To snare its prey, a giant spider spins elaborate webs or shoots sticky strands of webbing from its abdomen. Giant spiders are most commonly found underground, making their lairs on ceilings or in dark, web-filled crevices. Such lairs are often festooned with web cocoons holding past victims."}'::jsonb, '{"index":"giant-spider","name":"Giant Spider","desc":"To snare its prey, a giant spider spins elaborate webs or shoots sticky strands of webbing from its abdomen. Giant spiders are most commonly found underground, making their lairs on ceilings or in dark, web-filled crevices. Such lairs are often festooned with web cocoons holding past victims.","size":"Large","type":"beast","alignment":"unaligned","armor_class":[{"type":"natural","value":14}],"hit_points":26,"hit_dice":"4d10","hit_points_roll":"4d10+4","speed":{"walk":"30 ft.","climb":"30 ft."},"strength":14,"dexterity":16,"constitution":12,"intelligence":2,"wisdom":11,"charisma":4,"proficiencies":[{"value":7,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"blindsight":"10 ft.","darkvision":"60 ft.","passive_perception":10},"languages":"","challenge_rating":1,"proficiency_bonus":2,"xp":200,"special_abilities":[{"name":"Spider Climb","desc":"The spider can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."},{"name":"Web Sense","desc":"While in contact with a web, the spider knows the exact location of any other creature in contact with the same web."},{"name":"Web Walker","desc":"The spider ignores movement restrictions caused by webbing."}],"actions":[{"name":"Bite","desc":"Melee Weapon Attack: +5 to hit, reach 5 ft., one creature. Hit: 7 (1d8 + 3) piercing damage, and the target must make a DC 11 Constitution saving throw, taking 9 (2d8) poison damage on a failed save, or half as much damage on a successful one. If the poison damage reduces the target to 0 hit points, the target is stable but poisoned for 1 hour, even after regaining hit points, and is paralyzed while poisoned in this way.","attack_bonus":5,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d8+3"}]},{"name":"Web","desc":"Ranged Weapon Attack: +5 to hit, range 30/60 ft., one creature. Hit: The target is restrained by webbing. As an action, the restrained target can make a DC 12 Strength check, bursting the webbing on a success. The webbing can also be attacked and destroyed (AC 10; hp 5; vulnerability to fire damage; immunity to bludgeoning, poison, and psychic damage).","usage":{"type":"recharge on roll","dice":"1d6","min_value":5},"attack_bonus":5}],"image":"/api/images/monsters/giant-spider.png","url":"/api/2014/monsters/giant-spider"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Giant Toad","desc":null}'::jsonb, '{"index":"giant-toad","name":"Giant Toad","size":"Large","type":"beast","alignment":"unaligned","armor_class":[{"type":"dex","value":11}],"hit_points":39,"hit_dice":"6d10","hit_points_roll":"6d10+6","speed":{"walk":"20 ft.","swim":"40 ft."},"strength":15,"dexterity":13,"constitution":13,"intelligence":2,"wisdom":10,"charisma":3,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"30 ft.","passive_perception":10},"languages":"","challenge_rating":1,"proficiency_bonus":2,"xp":200,"special_abilities":[{"name":"Amphibious","desc":"The toad can breathe air and water"},{"name":"Standing Leap","desc":"The toad''s long jump is up to 20 ft. and its high jump is up to 10 ft., with or without a running start."}],"actions":[{"name":"Bite","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 7 (1d10 + 2) piercing damage plus 5 (1d10) poison damage, and the target is grappled (escape DC 13). Until this grapple ends, the target is restrained, and the toad can''t bite another target.","attack_bonus":4,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d10+2"},{"damage_type":{"index":"poison","name":"Poison","url":"/api/2014/damage-types/poison"},"damage_dice":"1d10"}]},{"name":"Swallow","desc":"The toad makes one bite attack against a Medium or smaller target it is grappling. If the attack hits, the target is swallowed, and the grapple ends. The swallowed target is blinded and restrained, it has total cover against attacks and other effects outside the toad, and it takes 10 (3d6) acid damage at the start of each of the toad''s turns. The toad can have only one target swallowed at a time.\nIf the toad dies, a swallowed creature is no longer restrained by it and can escape from the corpse using 5 feet of movement, exiting prone."}],"image":"/api/images/monsters/giant-toad.png","url":"/api/2014/monsters/giant-toad"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Giant Vulture","desc":"A giant vulture has advanced intelligence and a malevolent bent. Unlike its smaller kin, it will attack a wounded creature to hasten its end. Giant vultures have been known to haunt a thirsty, starving creature for days to enjoy its suffering."}'::jsonb, '{"index":"giant-vulture","name":"Giant Vulture","desc":"A giant vulture has advanced intelligence and a malevolent bent. Unlike its smaller kin, it will attack a wounded creature to hasten its end. Giant vultures have been known to haunt a thirsty, starving creature for days to enjoy its suffering.","size":"Large","type":"beast","alignment":"neutral evil","armor_class":[{"type":"dex","value":10}],"hit_points":22,"hit_dice":"3d10","hit_points_roll":"3d10+6","speed":{"walk":"10 ft.","fly":"60 ft."},"strength":15,"dexterity":10,"constitution":15,"intelligence":6,"wisdom":12,"charisma":7,"proficiencies":[{"value":3,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":13},"languages":"understands Common but can''t speak","challenge_rating":1,"proficiency_bonus":2,"xp":200,"special_abilities":[{"name":"Keen Sight and Smell","desc":"The vulture has advantage on Wisdom (Perception) checks that rely on sight or smell."},{"name":"Pack Tactics","desc":"The vulture has advantage on an attack roll against a creature if at least one of the vulture''s allies is within 5 ft. of the creature and the ally isn''t incapacitated."}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The vulture makes two attacks: one with its beak and one with its talons.","actions":[{"action_name":"Beak","count":1,"type":"melee"},{"action_name":"Talons","count":1,"type":"melee"}]},{"name":"Beak","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 7 (2d4 + 2) piercing damage.","attack_bonus":4,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"2d4+2"}]},{"name":"Talons","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 9 (2d6 + 2) slashing damage.","attack_bonus":4,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"2d6+2"}]}],"image":"/api/images/monsters/giant-vulture.png","url":"/api/2014/monsters/giant-vulture"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Giant Wasp","desc":null}'::jsonb, '{"index":"giant-wasp","name":"Giant Wasp","size":"Medium","type":"beast","alignment":"unaligned","armor_class":[{"type":"dex","value":12}],"hit_points":13,"hit_dice":"3d8","hit_points_roll":"3d8","speed":{"walk":"10 ft.","fly":"50 ft.","swim":"50 ft."},"strength":10,"dexterity":14,"constitution":10,"intelligence":1,"wisdom":10,"charisma":3,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":10},"languages":"","challenge_rating":0.5,"proficiency_bonus":2,"xp":100,"actions":[{"name":"Sting","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 5 (1d6 + 2) piercing damage, and the target must make a DC 11 Constitution saving throw, taking 10 (3d6) poison damage on a failed save, or half as much damage on a successful one. If the poison damage reduces the target to 0 hit points, the target is stable but poisoned for 1 hour, even after regaining hit points, and is paralyzed while poisoned in this way.","attack_bonus":4,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d6+2"}]}],"image":"/api/images/monsters/giant-wasp.png","url":"/api/2014/monsters/giant-wasp"}'::jsonb),
