  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Giant Wolf Spider","desc":"Smaller than a giant spider, a giant wolf spider hunts prey across open ground or hides in a burrow or crevice, or in a hidden cavity beneath debris."}'::jsonb, '{"index":"giant-wolf-spider","name":"Giant Wolf Spider","desc":"Smaller than a giant spider, a giant wolf spider hunts prey across open ground or hides in a burrow or crevice, or in a hidden cavity beneath debris.","size":"Medium","type":"beast","alignment":"unaligned","armor_class":[{"type":"dex","value":13}],"hit_points":11,"hit_dice":"2d8","hit_points_roll":"2d8+2","speed":{"walk":"40 ft.","climb":"40 ft."},"strength":12,"dexterity":16,"constitution":13,"intelligence":3,"wisdom":12,"charisma":4,"proficiencies":[{"value":3,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"value":7,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"blindsight":"10 ft.","darkvision":"60 ft.","passive_perception":13},"languages":"","challenge_rating":0.25,"proficiency_bonus":2,"xp":50,"special_abilities":[{"name":"Spider Climb","desc":"The spider can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."},{"name":"Web Sense","desc":"While in contact with a web, the spider knows the exact location of any other creature in contact with the same web."},{"name":"Web Walker","desc":"The spider ignores movement restrictions caused by webbing."}],"actions":[{"name":"Bite","desc":"Melee Weapon Attack: +3 to hit, reach 5 ft., one creature. Hit: 4 (1d6 + 1) piercing damage, and the target must make a DC 11 Constitution saving throw, taking 7 (2d6) poison damage on a failed save, or half as much damage on a successful one. If the poison damage reduces the target to 0 hit points, the target is stable but poisoned for 1 hour, even after regaining hit points, and is paralyzed while poisoned in this way.","attack_bonus":3,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d6+1"}]}],"image":"/api/images/monsters/giant-wolf-spider.png","url":"/api/2014/monsters/giant-wolf-spider"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Gibbering Mouther","desc":null}'::jsonb, '{"index":"gibbering-mouther","name":"Gibbering Mouther","size":"Medium","type":"aberration","alignment":"neutral","armor_class":[{"type":"dex","value":9}],"hit_points":67,"hit_dice":"9d8","hit_points_roll":"9d8+27","speed":{"walk":"10 ft.","swim":"10 ft."},"strength":10,"dexterity":8,"constitution":16,"intelligence":3,"wisdom":10,"charisma":6,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[{"index":"prone","name":"Prone","url":"/api/2014/conditions/prone"}],"senses":{"darkvision":"60 ft.","passive_perception":10},"languages":"","challenge_rating":2,"proficiency_bonus":2,"xp":450,"special_abilities":[{"name":"Aberrant Ground","desc":"The ground in a 10-foot radius around the mouther is doughlike difficult terrain. Each creature that starts its turn in that area must succeed on a DC 10 Strength saving throw or have its speed reduced to 0 until the start of its next turn."},{"name":"Gibbering","desc":"The mouther babbles incoherently while it can see any creature and isn''t incapacitated. Each creature that starts its turn within 20 feet of the mouther and can hear the gibbering must succeed on a DC 10 Wisdom saving throw. On a failure, the creature can''t take reactions until the start of its next turn and rolls a d8 to determine what it does during its turn. On a 1 to 4, the creature does nothing. On a 5 or 6, the creature takes no action or bonus action and uses all its movement to move in a randomly determined direction. On a 7 or 8, the creature makes a melee attack against a randomly determined creature within its reach or does nothing if it can''t make such an attack.","dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_value":10,"success_type":"none"}}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The gibbering mouther makes one bite attack and, if it can, uses its Blinding Spittle.","actions":[{"action_name":"Bites","count":1,"type":"melee"},{"action_name":"Blinding Spittle","count":1,"type":"ranged"}]},{"name":"Bites","desc":"Melee Weapon Attack: +2 to hit, reach 5 ft., one creature. Hit: 17 (5d6) piercing damage. If the target is Medium or smaller, it must succeed on a DC 10 Strength saving throw or be knocked prone. If the target is killed by this damage, it is absorbed into the mouther.","attack_bonus":2,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"5d6"}]},{"name":"Blinding Spittle","desc":"The mouther spits a chemical glob at a point it can see within 15 feet of it. The glob explodes in a blinding flash of light on impact. Each creature within 5 feet of the flash must succeed on a DC 13 Dexterity saving throw or be blinded until the end of the mouther''s next turn.","usage":{"type":"recharge on roll","dice":"1d6","min_value":5},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_value":13,"success_type":"none"}}],"image":"/api/images/monsters/gibbering-mouther.png","url":"/api/2014/monsters/gibbering-mouther"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Glabrezu","desc":null}'::jsonb, '{"index":"glabrezu","name":"Glabrezu","size":"Large","type":"fiend","subtype":"demon","alignment":"chaotic evil","armor_class":[{"type":"natural","value":17}],"hit_points":157,"hit_dice":"15d10","hit_points_roll":"15d10+75","speed":{"walk":"40 ft."},"strength":20,"dexterity":15,"constitution":21,"intelligence":19,"wisdom":17,"charisma":16,"proficiencies":[{"value":9,"proficiency":{"index":"saving-throw-str","name":"Saving Throw: STR","url":"/api/2014/proficiencies/saving-throw-str"}},{"value":9,"proficiency":{"index":"saving-throw-con","name":"Saving Throw: CON","url":"/api/2014/proficiencies/saving-throw-con"}},{"value":7,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}},{"value":7,"proficiency":{"index":"saving-throw-cha","name":"Saving Throw: CHA","url":"/api/2014/proficiencies/saving-throw-cha"}}],"damage_vulnerabilities":[],"damage_resistances":["cold","fire","lightning","bludgeoning, piercing, and slashing from nonmagical weapons"],"damage_immunities":["poison"],"condition_immunities":[{"index":"poisoned","name":"Poisoned","url":"/api/2014/conditions/poisoned"}],"senses":{"truesight":"120 ft.","passive_perception":13},"languages":"Abyssal, telepathy 120 ft.","challenge_rating":9,"proficiency_bonus":4,"xp":5000,"special_abilities":[{"name":"Innate Spellcasting","desc":"The glabrezu''s spellcasting ability is Intelligence (spell save DC 16). The glabrezu can innately cast the following spells, requiring no material components:\nAt will: darkness, detect magic, dispel magic\n1/day each: confusion, fly, power word stun","spellcasting":{"ability":{"index":"int","name":"INT","url":"/api/2014/ability-scores/int"},"dc":16,"components_required":["V","S"],"spells":[{"name":"Darkness","level":2,"url":"/api/2014/spells/darkness","usage":{"type":"at will"}},{"name":"Detect Magic","level":1,"url":"/api/2014/s