  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Gladiator","desc":"Gladiators battle for the entertainment of raucous crowds. Some gladiators are brutal pit fighters who treat each match as a life-or-death struggle, while others are professional duelists who command huge fees but rarely fight to the death."}'::jsonb, '{"index":"gladiator","name":"Gladiator","desc":"Gladiators battle for the entertainment of raucous crowds. Some gladiators are brutal pit fighters who treat each match as a life-or-death struggle, while others are professional duelists who command huge fees but rarely fight to the death.","size":"Medium","type":"humanoid","subtype":"any race","alignment":"any alignment","armor_class":[{"type":"armor","value":16,"armor":[{"index":"studded-leather-armor","name":"Studded Leather Armor","url":"/api/2014/equipment/studded-leather-armor"},{"index":"shield","name":"Shield","url":"/api/2014/equipment/shield"}]}],"hit_points":112,"hit_dice":"15d8","hit_points_roll":"15d8+45","speed":{"walk":"30 ft."},"strength":18,"dexterity":15,"constitution":16,"intelligence":10,"wisdom":12,"charisma":15,"proficiencies":[{"value":7,"proficiency":{"index":"saving-throw-str","name":"Saving Throw: STR","url":"/api/2014/proficiencies/saving-throw-str"}},{"value":5,"proficiency":{"index":"saving-throw-dex","name":"Saving Throw: DEX","url":"/api/2014/proficiencies/saving-throw-dex"}},{"value":6,"proficiency":{"index":"saving-throw-con","name":"Saving Throw: CON","url":"/api/2014/proficiencies/saving-throw-con"}},{"value":10,"proficiency":{"index":"skill-athletics","name":"Skill: Athletics","url":"/api/2014/proficiencies/skill-athletics"}},{"value":5,"proficiency":{"index":"skill-intimidation","name":"Skill: Intimidation","url":"/api/2014/proficiencies/skill-intimidation"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":11},"languages":"any one language (usually Common)","challenge