  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Gold Dragon Wyrmling","desc":null}'::jsonb, '{"index":"gold-dragon-wyrmling","name":"Gold Dragon Wyrmling","size":"Medium","type":"dragon","alignment":"lawful good","armor_class":[{"type":"natural","value":17}],"hit_points":60,"hit_dice":"8d8","hit_points_roll":"8d8+24","speed":{"walk":"30 ft.","fly":"60 ft.","swim":"30 ft."},"strength":19,"dexterity":14,"constitution":17,"intelligence":14,"wisdom":11,"charisma":16,"proficiencies":[{"value":4,"proficiency":{"index":"saving-throw-dex","name":"Saving Throw: DEX","url":"/api/2014/proficiencies/saving-throw-dex"}},{"value":5,"proficiency":{"index":"saving-throw-con","name":"Saving Throw: CON","url":"/api/2014/proficiencies/saving-throw-con"}},{"value":2,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}},{"value":5,"proficiency":{"index":"saving-throw-cha","name":"Saving Throw: CHA","url":"/api/2014/proficiencies/saving-throw-cha"}},{"value":4,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"value":4,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":["fire"],"condition_immunities":[],"senses":{"blindsight":"10 ft.","darkvision":"60 ft.","passive_perception":14},"languages":"Draconic","challenge_rating":3,"proficiency_bonus":2,"xp":700,"special_abilities":[{"name":"Amphibious","desc":"The dragon can breathe air and water."}],"actions":[{"name":"Bite","desc":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 9 (1d10 + 4) piercing damage.","attack_bonus":6,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d10+4"}]},{"name":"Breath Weapons","desc":"The dragon uses one of the following breath weapons.\nFire Breath. The dragon exhales fire in a 15-foot cone. Each creature in that area must make a DC 13 Dexterity saving throw, taking 22 (4d10) fire damage on a failed save, or half as much damage on a successful one.\nWeakening Breath. The dragon exhales gas in a 15-foot cone. Each creature in that area must succeed on a DC 13 Strength saving throw or have disadvantage on Strength-based attack rolls, Strength checks, and Strength saving throws for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","usage":{"type":"recharge on roll","dice":"1d6","min_value":5},"options":{"choose":1,"type":"attack","from":{"option_set_type":"options_array","options":[{"option_type":"breath","name":"Fire Breath","dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_value":13,"success_type":"half"},"damage":[{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_dice":"4d10"}]},{"option_type":"breath","name":"Weakening Breath","dc":{"dc_type":{"index":"str","name":"STR","url":"/api/2014/ability-scores/str"},"dc_value":13,"success_type":"none"}}]}}}],"image":"/api/images/monsters/gold-dragon-wyrmling.png","url":"/api/2014/monsters/gold-dragon-wyrmling"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Gorgon","desc":null}'::jsonb, '{"index":"gorgon","name":"Gorgon","size":"Large","type":"monstrosity","alignment":"unaligned","armor_class":[{"type":"natural","value":19}],"hit_points":114,"hit_dice":"12d10","hit_points_roll":"12d10+48","speed":{"walk":"40 ft."},"strength":20,"dexterity":11,"constitution":18,"intelligence":2,"wisdom":12,"charisma":7,"proficiencies":[{"value":4,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[{"index":"petrified","name":"Petrified","url":"/api/2014/conditions/petrified"}],"senses":{"darkvision":"60 ft.","passive_perception":14},"languages":"","challenge_rating":5,"proficiency_bonus":3,"xp":1800,"special_abilities":[{"name":"Trampling Charge","desc":"If the gorgon moves at least 20 feet straight toward a creature and then hits it with a gore attack on the same turn, that target must succeed on a DC 16 Strength saving throw or be knocked prone. If the target is prone, the gorgon can make one attack with its hooves against it as a bonus action."}],"actions":[{"name":"Gore","desc":"Melee Weapon Attack: +8 to hit, reach 5 ft., one target. Hit: 18 (2d12 + 5) piercing damage.","attack_bonus":8,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"2d12+5"}]},{"name":"Hooves","desc":"Melee Weapon Attack: +8 to hit, reach 5 ft., one target. Hit: 16 (2d10 + 5) bludgeoning damage.","attack_bonus":8,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"2d10+5"}]},{"name":"Petrifying Breath","desc":"The gorgon exhales petrifying gas in a 30-foot cone. Each creature in that area must succeed on a DC 13 Constitution saving throw. On a failed save, a target begins to turn to stone and is restrained. The restrained target must repeat the saving throw at the end of its next turn. On a success, the effect ends on the target. On a failure, the target is petrified until freed by the greater restoration spell or other magic.","usage":{"type":"recharge on roll","dice":"1d6","min_value":5},"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_value":13,"success_type":"none"}}],"image":"/api/images/monsters/gorgon.png","url":"/api/2014/monsters/gorgon"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Gray Ooze","desc":null}'::jsonb, '{"index":"gray-ooze","name":"Gray Ooze","size":"Medium","type":"ooze","alignment":"unaligned","armor_class":[{"type":"dex","value":8}],"hit_points":22,"hit_dice":"3d8","hit_points_roll":"3d8+9","speed":{"walk":"10 ft.","climb":"10 ft."},"strength":12,"dexterity":6,"constitution":16,"intelligence":1,"wisdom":6,"charisma":2,"proficiencies":[{"value":2,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":["acid","cold","fire"],"damage_immunities":[],"condition_immunities":[{"index":"blinded","name":"Blinded","url":"/api/2014/conditions/blinded"},{"index":"charmed","name":"Charmed","url":"/api/2014/conditions/charmed"},{"index":"deafened","name":"Deafened","url":"/api/2014/conditions/deafened"},{"index":"exhaustion","name":"Exhaustion","url":"/api/2014/conditions/exhaustion"},{"index":"frightened","name":"Frightened","url":"/api/2014/conditions/frightened"},{"index":"prone","name":"Prone","url":"/api/2014/conditions/prone"}],"senses":{"blindsight":"60 ft. (blind beyond this radius)","passive_perception":8},"languages":"","challenge_rating":0.5,"proficiency_bonus":2,"xp":100,"special_abilities":[{"name":"Amorphous","desc":"The ooze can move through a space as narrow as 1 inch wide without squeezing."},{"name":"Corrode Metal","desc":"Any nonmagical weapon made of metal that hits the ooze corrodes. After dealing damage, the weapon takes a permanent and cumulative -1 penalty to damage rolls. If its penalty drops to -5, the weapon is destroyed. Nonmagical ammunition made of metal that hits the ooze is destroyed after dealing damage.\nThe ooze can eat through 2-inch-thick, nonmagical metal in 1 round."},{"name":"False Appearance","desc":"While the ooze remains motionless, it is indistinguishable from an oily pool or wet rock."}],"actions":[{"name":"Pseudopod","desc":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 4 (1d6 + 1) bludgeoning damage plus 7 (2d6) acid damage, and if the target is wearing nonmagical metal armor, its armor is partly corroded and takes a permanent and cumulative -1 penalty to the AC it offers. The armor is destroyed if the penalty reduces its AC to 10.","attack_bonus":3,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"1d6+1"},{"damage_type":{"index":"acid","name":"Acid","url":"/api/2014/damage-types/acid"},"damage_dice":"2d6"}]}],"image":"/api/images/monsters/gray-ooze.png","url":"/api/2014/monsters/gray-ooze"}'::jsonb),
