":"options_array","options":[{"option_type":"action","action_name":"Slam","count":2,"type":"melee"},{"option_type":"action","action_name":"Sword","count":2,"type":"melee"},{"option_type":"multiple","items":[{"option_type":"action","action_name":"Slam","count":1,"type":"melee"},{"option_type":"action","action_name":"Sword","count":1,"type":"melee"}]}]}}},{"name":"Slam","desc":"Melee Weapon Attack: +13 to hit, reach 5 ft., one target. Hit: 20 (3d8 + 7) bludgeoning damage.","attack_bonus":13,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"3d8+7"}]},{"name":"Sword","desc":"Melee Weapon Attack: +13 to hit, reach 10 ft., one target. Hit: 23 (3d10 + 7) slashing damage.","attack_bonus":13,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"3d10+7"}]},{"name":"Poison Breath","desc":"The golem exhales poisonous gas in a 15-foot cone. Each creature in that area must make a DC 19 Constitution saving throw, taking 45 (10d8) poison damage on a failed save, or half as much damage on a successful one.","usage":{"type":"recharge on roll","dice":"1d6","min_value":5},"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_value":19,"success_type":"half"},"damage":[{"damage_type":{"index":"poison","name":"Poison","url":"/api/2014/damage-types/poison"},"damage_dice":"10d8"}]}],"image":"/api/images/monsters/iron-golem.png","url":"/api/2014/monsters/iron-golem"}'::jsonb),
