  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Lemure","desc":null}'::jsonb, '{"index":"lemure","name":"Lemure","size":"Medium","type":"fiend","subtype":"devil","alignment":"lawful evil","armor_class":[{"type":"dex","value":7}],"hit_points":13,"hit_dice":"3d8","hit_points_roll":"3d8","speed":{"walk":"15 ft."},"strength":10,"dexterity":5,"constitution":11,"intelligence":1,"wisdom":11,"charisma":3,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":["cold"],"damage_immunities":["fire","poison"],"condition_immunities":[{"index":"charmed","name":"Charmed","url":"/api/2014/conditions/charmed"},{"index":"frightened","name":"Frightened","url":"/api/2014/conditions/frightened"},{"index":"poisoned","name":"Poisoned","url":"/api/2014/conditions/poisoned"}],"senses":{"darkvision":"120 ft.","passive_perception":10},"languages":"understands infernal but can''t speak","challenge_rating":0,"proficiency_bonus":2,"xp":10,"special_abilities":[{"name":"Devil''s Sight","desc":"Magical darkness doesn''t impede the lemure''s darkvision."},{"name":"Hellish Rejuvenation","desc":"A lemure that dies in the Nine Hells comes back to life with all its hit points in 1d10 days unless it is killed by a good-aligned creature with a bless spell cast on that creature or its remains are sprinkled with holy water."}],"actions":[{"name":"Fist","desc":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 2 (1d4) bludgeoning damage.","attack_bonus":3,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"1d4"}]}],"image":"/api/images/monsters/lemure.png","url":"/api/2014/monsters/lemure"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Lich","desc":null}'::jsonb, '{"index":"lich","name":"Lich","size":"Medium","type":"undead","alignment":"any evil alignment","armor_class":[{"type":"natural","value":17}],"hit_points":135,"hit_dice":"18d8","hit_points_roll":"18d8+54","speed":{"walk":"30 ft."},"strength":11,"dexterity":16,"constitution":16,"intelligence":20,"wisdom":14,"charisma":16,"proficiencies":[{"value":10,"proficiency":{"index":"saving-throw-con","name":"Saving Throw: CON","url":"/api/2014/proficiencies/saving-throw-con"}},{"value":12,"proficiency":{"index":"saving-throw-int","name":"Saving Throw: INT","url":"/api/2014/proficiencies/saving-throw-int"}},{"value":9,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}},{"value":18,"proficiency":{"index":"skill-arcana","name":"Skill: Arcana","url":"/api/2014/proficiencies/skill-arcana"}},{"value":12,"proficiency":{"index":"skill-history","name":"Skill: History","url":"/api/2014/proficiencies/skill-history"}},{"value":9,"proficiency":{"index":"skill-insight","name":"Skill: Insight","url":"/api/2014/proficiencies/skill-insight"}},{"value":9,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}}],"damage_vulnerabilities":[],"damage_resistances":["cold","lightning","necrotic"],"damage_immunities":["poison","bludgeoning, piercing, and slashing from nonmagical weapons"],"condition_immunities":[{"index":"charmed","name":"Charmed","url":"/api/2014/conditions/charmed"},{"index":"exhaustion","name":"Exhaustion","url":"/api/2014/conditions/exhaustion"},{"index":"frightened","name":"Frightened","url":"/api/2014/conditions/frightened"},{"index":"paralyzed","name":"Paralyzed","url":"/api/2014/conditions/paralyzed"},{"index":"poisoned","name":"Poisoned","url":"/api/2014/conditions/poisoned"}],"senses":{"truesight":"120 ft.","passive_perception":19},"languages":"Common plus up to five other languages","challenge_rating":21,"proficiency_bonus":7,"xp":33000,"special_abilities":[{"name":"Legendary Resistance","desc":"If the lich fails a saving throw, it can choose to succeed instead.","usage":{"type":"per day","times":3}},{"name":"Rejuvenation","desc":"If it has a phylactery, a destroyed lich gains a new body in 1d10 days, regaining all its hit points and becoming active again. The new body appears within 5 feet of the phylactery."},{"name":"Spellcasting","desc":"The lich is an 18th-level spellcaster. Its spellcasting ability is Intelligence (spell save DC 20, +12 to hit with spell attacks). The lich has the following wizard spells prepared:\n\n- Cantrips (at will): mage hand, prestidigitation, ray of frost\n- 1st level (4 slots): detect magic, magic missile, shield, thunderwave\n- 2nd level (3 slots): acid arrow, detect thoughts, invisibility, mirror image\n- 3rd level (3 slots): animate dead, counterspell, dispel magic, fireball\n- 4th level (3 slots): blight, dimension door\n- 5th level (3 slots): cloudkill, scrying\n- 6th level (1 slot): disintegrate, globe of invulnerability\n- 7th level (1 slot): finger of death, plane shift\n- 8th level (1 slot): dominate monster, power word stun\n- 9th level (1 slot): power word kill","spellcasting":{"level":18,"ability":{"index":"int","name":"INT","url":"/api/2014/ability-scores/int"},"dc":20,"modifier":12,"components_required":["V","S","M"],"school":"wizard","slots":{"1":4,"2":3,"3":3,"4":3,"5":3,"6":1,"7":1,"8":1,"9":1},"spells":[{"name":"Mage Hand","level":0,"url":"/api/2014/spells/mage-hand"},{"name":"Prestidigitation","level":0,"url":"/api/2014/spells/prestidigitation"},{"name":"Ray of Frost","level":0,"url":"/api/2014/spells/ray-of-frost"},{"name":"Detect Magic","level":1,"url":"/api/2014/spells/detect-magic"},{"name":"Magic Missile","level":1,"url":"/api/2014/spells/magic-missile"},{"name":"Shield","level":1,"url":"/api/2014/spells/shield"},{"name":"Thunderwave","level":1,"url":"/api/2014/spells/thunderwave"},{"name":"Acid Arrow","level":2,"url":"/api/2014/spells/acid-arrow"},{"name":"Detect Thoughts","level":2,"url":"/api/2014/spells/detect-thoughts"},{"name":"Invisibility","level":2,"url":"/api/2014/spells/invisibility"},{"name":"Mirror Image","level":2,"url":"/api/2014/spells/mirror-image"},{"name":"Animate Dead","level":3,"url":"/api/2014/spells/animate-dead"},{"name":"Counterspell","level":3,"url":"/api/2014/spells/counterspell"},{"name":"Dispel Magic","level":3,"url":"/api/2014/spells/dispel-magic"},{"name":"Fireball","level":3,"url":"/api/2014/spells/fireball"},{"name":"Blight","level":4,"url":"/api/2014/spells/blight"},{"name":"Dimension Door","level":4,"url":"/api/2014/spells/dimension-door"},{"name":"Cloudkill","level":5,"url":"/api/2014/spells/cloudkill"},{"name":"Scrying","level":5,"url":"/api/2014/spells/scrying"},{"name":"Disintegrate","level":6,"url":"/api/2014/spells/disintegrate"},{"name":"Globe of Invulnerability","level":6,"url":"/api/2014/spells/globe-of-invulnerability"},{"name":"Finger of Death","level":7,"url":"/api/2014/spells/finger-of-death"},{"name":"Plane Shift","level":7,"url":"/api/2014/spells/plane-shift"},{"name":"Dominate Monster","level":8,"url":"/api/2014/spells/dominate-monster"},{"name":"Power Word Stun","level":8,"url":"/api/2014/spells/power-word-stun"},{"name":"Power Word Kill","level":9,"url":"/api/2014/spells/power-word-kill"}]}},{"name":"Turn Resistance","desc":"The lich has advantage on saving throws against any effect that turns undead."}],"actions":[{"name":"Paralyzing Touch","desc":"Melee Spell Attack: +12 to hit, reach 5 ft., one creature. Hit: 10 (3d6) cold damage. The target must succeed on a DC 18 Constitution saving throw or be paralyzed for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","attack_bonus":12,"damage":[{"damage_type":{"index":"cold","name":"Cold","url":"/api/2014/damage-types/cold"},"damage_dice":"3d6"}]}],"legendary_actions":[{"name":"Cantrip","desc":"The lich casts a cantrip."},{"name":"Paralyzing Touch (Costs 2 Actions)","desc":"The lich uses its Paralyzing Touch."},{"name":"Frightening Gaze (Costs 2 Actions)","desc":"The lich fixes its gaze on one creature it can see within 10 feet of it. The target must succeed on a DC 18 Wisdom saving throw against this magic or become frightened for 1 minute. The frightened target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a target''s saving throw is successful or the effect ends for it, the target is immune to the lich''s gaze for the next 24 hours.","dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_value":18,"success_type":"none"}},{"name":"Disrupt Life (Costs 3 Actions)","desc":"Each living creature within 20 feet of the lich must make a DC 18 Constitution saving throw against this magic, taking 21 (6d6) necrotic damage on a failed save, or half as much damage on a successful one.","dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_value":18,"success_type":"none"},"damage":[{"damage_type":{"index":"necrotic","name":"Necrotic","url":"/api/2014/damage-types/necrotic"},"damage_dice":"6d6"}]}],"image":"/api/images/monsters/lich.png","url":"/api/2014/monsters/lich"}'::jsonb),
