  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Magma Mephit","desc":null}'::jsonb, '{"index":"magma-mephit","name":"Magma Mephit","size":"Small","type":"elemental","alignment":"neutral evil","armor_class":[{"type":"dex","value":11}],"hit_points":22,"hit_dice":"5d6","hit_points_roll":"5d6+5","speed":{"walk":"30 ft.","fly":"30 ft."},"strength":8,"dexterity":12,"constitution":12,"intelligence":7,"wisdom":10,"charisma":10,"proficiencies":[{"value":3,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":["cold"],"damage_resistances":[],"damage_immunities":["fire","poison"],"condition_immunities":[{"index":"poisoned","name":"Poisoned","url":"/api/2014/conditions/poisoned"}],"senses":{"darkvision":"60 ft.","passive_perception":10},"languages":"Ignan, Terran","challenge_rating":0.5,"proficiency_bonus":2,"xp":100,"special_abilities":[{"name":"Death Burst","desc":"When the mephit dies, it explodes in a burst of lava. Each creature within 5 ft. of it must make a DC 11 Dexterity saving throw, taking 7 (2d6) fire damage on a failed save, or half as much damage on a successful one.","dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_value":11,"success_type":"half"},"damage":[{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_dice":"2d6"}]},{"name":"False Appearance","desc":"While the mephit remains motionless, it is indistinguishable from an ordinary mound of magma."},{"name":"Innate Spellcasting","desc":"The mephit can innately cast heat metal (spell save DC 10), requiring no material components. Its innate spellcasting ability is Charisma.","spellcasting":{"ability":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"components_required":["V","S"],"dc":10,"spells":[{"name":"Heat Metal","level":2,"url":"/api/2014/spells/heat-metal","usage":{"type":"per day","times":1}}]}}],"actions":[{"name":"Claws","desc":"Melee Weapon Attack: +3 to hit, reach 5 ft., one creature. Hit: 3 (1d4 + 1) slashing damage plus 2 (1d4) fire damage.","attack_bonus":3,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"1d4+1"},{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_dice":"1d4"}]},{"name":"Fire Breath","desc":"The mephit exhales a 15-foot cone of fire. Each creature in that area must make a DC 11 Dexterity saving throw, taking 7 (2d6) fire damage on a failed save, or half as much damage on a successful one.","usage":{"type":"recharge on roll","dice":"1d6","min_value":6},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_value":11,"success_type":"half"},"damage":[{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_dice":"2d6"}]}],"image":"/api/images/monsters/magma-mephit.png","url":"/api/2014/monsters/magma-mephit"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Magmin","desc":null}'::jsonb, '{"index":"magmin","name":"Magmin","size":"Small","type":"elemental","alignment":"chaotic neutral","armor_class":[{"type":"natural","value":14}],"hit_points":9,"hit_dice":"2d6","hit_points_roll":"2d6+2","speed":{"walk":"30 ft."},"strength":7,"dexterity":15,"constitution":12,"intelligence":8,"wisdom":11,"charisma":10,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":["bludgeoning, piercing, and slashing from nonmagical weapons"],"damage_immunities":["fire"],"condition_immunities":[],"senses":{"darkvision":"60 ft.","passive_perception":10},"languages":"Ignan","challenge_rating":0.5,"proficiency_bonus":2,"xp":100,"special_abilities":[{"name":"Death Burst","desc":"When the magmin dies, it explodes in a burst of fire and magma. Each creature within 10 ft. of it must make a DC 11 Dexterity saving throw, taking 7 (2d6) fire damage on a failed save, or half as much damage on a successful one. Flammable objects that aren''t being worn or carried in that area are ignited.","dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_value":11,"success_type":"half"},"damage":[{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_dice":"2d6"}]},{"name":"Ignited Illumination","desc":"As a bonus action, the magmin can set itself ablaze or extinguish its flames. While ablaze, the magmin sheds bright light in a 10-foot radius and dim light for an additional 10 ft."}],"actions":[{"name":"Touch","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 7 (2d6) fire damage. If the target is a creature or a flammable object, it ignites. Until a target takes an action to douse the fire, the target takes 3 (1d6) fire damage at the end of each of its turns.","attack_bonus":4,"damage":[{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_dice":"2d6"}]}],"image":"/api/ima