  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Mammoth","desc":"A mammoth is an elephantine creature with thick fur and long tusks. Stockier and fiercer than normal elephants, mammoths inhabit a wide range of climes, from subarctic to subtropical."}'::jsonb, '{"index":"mammoth","name":"Mammoth","desc":"A mammoth is an elephantine creature with thick fur and long tusks. Stockier and fiercer than normal elephants, mammoths inhabit a wide range of climes, from subarctic to subtropical.","size":"Huge","type":"beast","alignment":"unaligned","armor_class":[{"type":"natural","value":13}],"hit_points":126,"hit_dice":"11d12","hit_points_roll":"11d12+55","speed":{"walk":"40 ft."},"strength":24,"dexterity":9,"constitution":21,"intelligence":3,"wisdom":11,"charisma":6,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":10},"languages":"","challenge_rating":6,"proficiency_bonus":3,"xp":2300,"special_abilities":[{"name":"Trampling Charge","desc":"If the mammoth moves at least 20 ft. straight toward a creature and then hits it with a gore attack on the same turn, that target must succeed on a DC 18 Strength saving throw or be knocked prone. If the target is prone, the mammoth can make one stomp attack against it as a bonus action."}],"actions":[{"name":"Gore","desc":"Melee Weapon Attack: +10 to hit, reach 10 ft., one target. Hit: 25 (4d8 + 7) piercing damage.","attack_bonus":10,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"4d8+7"}]},{"name":"Stomp","desc":"Melee Weapon Attack: +10 to hit, reach 5 ft., one prone creature. Hit: 29 (4d10 + 7) bludgeoning damage.","attack_bonus":10,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"4d10+7"}]}],"image":"/api/images/monsters/mammoth.png","url":"/api/2014/monsters/mammoth"}':