  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Manticore","desc":null}'::jsonb, '{"index":"manticore","name":"Manticore","size":"Large","type":"monstrosity","alignment":"lawful evil","armor_class":[{"type":"natural","value":14}],"hit_points":68,"hit_dice":"8d10","hit_points_roll":"8d10+24","speed":{"walk":"30 ft.","fly":"50 ft."},"strength":17,"dexterity":16,"constitution":17,"intelligence":7,"wisdom":12,"charisma":8,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"60 ft.","passive_perception":11},"languages":"","challenge_rating":3,"proficiency_bonus":2,"xp":700,"special_abilities":[{"name":"Tail Spike Regrowth","desc":"The manticore has twenty-four tail spikes. Used spikes regrow when the manticore finishes a long rest."}],"actions":[{"name":"Multiattack","multiattack_type":"action_options","desc":"The manticore makes three attacks: one with its bite and two with its claws or three with its tail spikes.","action_options":{"choose":1,"type":"action","from":{"option_set_type":"options_array","options":[{"option_type":"multiple","items":[{"option_type":"action","action_name":"Bite","count":1,"type":"melee"},{"option_type":"action","action_name":"Claw","count":2,"type":"melee"}]},{"option_type":"action","action_name":"Tail Spike","count":3,"type":"ranged"}]}}},{"name":"Bite","desc":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 7 (1d8 + 3) piercing damage.","attack_bonus":5,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d8+3"}]},{"name":"Claw","desc":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) slashing damage.","attack_bonus":5,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"1d6+3"}]},{"name":"Tail Spike","desc":"Ranged Weapon Attack: +5 to hit, range 100/200 ft., one t