  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Marilith","desc":null}'::jsonb, '{"index":"marilith","name":"Marilith","size":"Large","type":"fiend","subtype":"demon","alignment":"chaotic evil","armor_class":[{"type":"natural","value":18}],"hit_points":189,"hit_dice":"18d10","hit_points_roll":"18d10+90","speed":{"walk":"40 ft."},"strength":18,"dexterity":20,"constitution":20,"intelligence":18,"wisdom":16,"charisma":20,"proficiencies":[{"value":9,"proficiency":{"index":"saving-throw-str","name":"Saving Throw: STR","url":"/api/2014/proficiencies/saving-throw-str"}},{"value":10,"proficiency":{"index":"saving-throw-con","name":"Saving Throw: CON","url":"/api/2014/proficiencies/saving-throw-con"}},{"value":8,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}},{"value":10,"proficiency":{"index":"saving-throw-cha","name":"Saving Throw: CHA","url":"/api/2014/proficiencies/saving-throw-cha"}}],"damage_vulnerabilities":[],"damage_resistances":["cold","fire","lightning","bludgeoning, piercing, and slashing from nonmagical weapons"],"damage_immunities":["poison"],"condition_immunities":[{"index":"poisoned","name":"Poisoned","url":"/api/2014/conditions/poisoned"}],"senses":{"truesight":"120 ft.","passive_perception":13},"languages":"Abyssal, telepathy 120 ft.","challenge_rating":16,"proficiency_bonus":5,"xp":15000,"special_abilities":[{"name":"Magic Resistance","desc":"The marilith has advantage on saving throws against spells and other magical effects."},{"name":"Magic Weapons","desc":"The marilith''s weapon attacks are magical."},{"name":"Reactive","desc":"The marilith can take one reaction on every turn in combat."}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The marilith can make seven attacks: six with its longswords and one with its tail.","actions":[{"action_name":"Longsword","count":6,"type":"melee"},{"action_name":"Tail","count":1,"type":"melee"}]},{"name":"Longsword","desc":"Melee Weapon Attack: +9 to hit, reach 5 ft., one target. Hit: 13 (2d8 + 4) slashing damage.","attack_bonus":9,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"2d8+4"}]},{"name":"Tail","desc":"Melee Weapon Attack: +9 to hit, reach 10 ft., one creature. Hit: 15 (2d10 + 4) bludgeoning damage. If the target is Medium or smaller, it is grappled (escape DC 19). Until this grapple ends, the target is restrained, the marilith can automatically hit the target with its tail, and the marilith can''t make tail attacks against other targets.","attack_bonus":9,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"2d10+4"}]},{"name":"Teleport","desc":"The marilith magically teleports, along with any equipment it is wearing or carrying, up to 120 feet to an unoccupied space it can see."}],"reactions":[{"name":"Parry","desc":"The marilith adds 5 to its AC against one melee attack that would hit it. To do so, the marilith must see the attacker and be wielding a melee weapon."}],"image":"/api/images/monsters/marilith.png","url":"/api/2014/monsters/marilith"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Mastiff","desc":"Mastiffs are impressive hounds prized by humanoids for their loyalty and keen senses. Mastiffs can be trained as guard dogs, hunting dogs, and war dogs. Halflings and other Small humanoids ride them as mounts."}'::jsonb, '{"index":"mastiff","name":"Mastiff","desc":"Mastiffs are impressive hounds prized by humanoids for their loyalty and keen senses. Mastiffs can be trained as guard dogs, hunting dogs, and war dogs. Halflings and other Small humanoids ride them as mounts.","size":"Medium","type":"beast","alignment":"unaligned","armor_class":[{"type":"dex","value":12}],"hit_points":5,"hit_dice":"1d8","hit_points_roll":"1d8+1","speed":{"walk":"40 ft."},"strength":13,"dexterity":14,"constitution":12,"intelligence":3,"wisdom":12,"charisma":7,"proficiencies":[{"value":3,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":13},"languages":"","challenge_rating":0.125,"proficiency_bonus":2,"xp":25,"special_abilities":[{"name":"Keen Hearing and Smell","desc":"The mastiff has advantage on Wisdom (Perception) checks that rely on hearing or smell."}],"actions":[{"name":"Bite","desc":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 4 (1d6 + 1) piercing damage. If the target is a creature, it must succeed on a DC 11 Strength saving throw or be knocked prone.","attack_bonus":3,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d6+1"}]}],"image":"/api/images/monsters/mastiff.png","url":"/api/2014/monsters/mastiff"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Medusa","desc":null}'::jsonb, '{"index":"medusa","name":"Medusa","size":"Medium","type":"monstrosity","alignment":"lawful evil","armor_class":[{"type":"natural","value":15}],"hit_points":127,"hit_dice":"17d8","hit_points_roll":"17d8+51","speed":{"walk":"30 ft."},"strength":10,"dexterity":15,"constitution":16,"intelligence":12,"wisdom":13,"charisma":15,"proficiencies":[{"value":5,"proficiency":{"index":"skill-deception","name":"Skill: Deception","url":"/api/2014/proficiencies/skill-deception"}},{"value":4,"proficiency":{"index":"skill-insight","name":"Skill: Insight","url":"/api/2014/proficiencies/skill-insight"}},{"value":4,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"value":5,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"60 ft.","passive_perception":14},"languages":"Common","challenge_rating":6,"proficiency_bonus":3,"xp":2300,"special_abilities":[{"name":"Petrifying Gaze","desc":"When a creature that can see the medusa''s eyes starts its turn within 30 ft. of the medusa, the medusa can force it to make a DC 14 Constitution saving throw if the medusa isn''t incapacitated and can see the creature. If the saving throw fails by 5 or more, the creature is instantly petrified. Otherwise, a creature that fails the save begins to turn to stone and is restrained. The restrained creature must repeat the saving throw at the end of its next turn, becoming petrified on a failure or ending the effect on a success. The petrification lasts until the creature is freed by the greater restoration spell or other magic.\nUnless surprised, a creature can avert its eyes to avoid the saving throw at the start of its turn. If the creature does so, it can''t see the medusa until the start of its next turn, when it can avert its eyes again. If the creature looks at the medusa in the meantime, it must immediately make the save.\nIf the medusa sees itself reflected on a polished surface within 30 ft. of it and in an area of bright light, the medusa is, due to its curse, affected by its own gaze.","dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_value":14,"success_type":"none"}}],"actions":[{"name":"Multiattack","multiattack_type":"action_options","desc":"The medusa makes either three melee attacks--one with its snake hair and two with its shortsword--or two ranged attacks with its longbow.","action_options":{"choose":1,"type":"action","from":{"option_set_type":"options_array","options":[{"option_type":"multiple","items":[{"option_type":"action","action_name":"Snake Hair","count":1,"type":"melee"},{"option_type":"action","action_name":"Shortsword","count":2,"type":"melee"}]},{"option_type":"action","action_name":"Longbow","count":2,"type":"ranged"}]}}},{"name":"Snake Hair","desc":"Melee Weapon Attack: +5 to hit, reach 5 ft., one creature. Hit: 4 (1d4 + 2) piercing damage plus 14 (4d6) poison damage.","attack_bonus":5,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d4+2"},{"damage_type":{"index":"poison","name":"Poison","url":"/api/2014/damage-types/poison"},"damage_dice":"4d6"}]},{"name":"Shortsword","desc":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 5 (1d6 + 2) piercing damage.","attack_bonus":5,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d6+2"}]},{"name":"Longbow","desc":"Ranged Weapon Attack: +5 to hit, range 150/600 ft., one target. Hit: 6 (1d8 + 2) piercing damage plus 7 (2d6) poison damage.","attack_bonus":5,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d8+2"},{"damage_type":{"index":"poison","name":"Poison","url":"/api/2014/damage-types/poison"},"damage_dice":"2d6"}]}],"image":"/api/images/monsters/medusa.png","url":"/api/2014/monsters/medusa"}'::jsonb),
