  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Mummy","desc":null}'::jsonb, '{"index":"mummy","name":"Mummy","size":"Medium","type":"undead","alignment":"lawful evil","armor_class":[{"type":"natural","value":11}],"hit_points":58,"hit_dice":"9d8","hit_points_roll":"9d8+18","speed":{"walk":"20 ft."},"strength":16,"dexterity":8,"constitution":15,"intelligence":6,"wisdom":10,"charisma":12,"proficiencies":[{"value":2,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}}],"damage_vulnerabilities":["fire"],"damage_resistances":["bludgeoning, piercing, and slashing from nonmagical weapons"],"damage_immunities":["necrotic","poison"],"condition_immunities":[{"index":"charmed","name":"Charmed","url":"/api/2014/conditions/charmed"},{"index":"exhaustion","name":"Exhaustion","url":"/api/2014/conditions/exhaustion"},{"index":"frightened","name":"Frightened","url":"/api/2014/conditions/frightened"},{"index":"paralyzed","name":"Paralyzed","url":"/api/2014/conditions/paralyzed"},{"index":"poisoned","name":"Poisoned","url":"/api/2014/conditions/poisoned"}],"senses":{"darkvision":"60 ft.","passive_perception":10},"languages":"the languages it knew in life","challenge_rating":3,"proficiency_bonus":2,"xp":700,"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The mummy can use its Dreadful Glare and makes one attack with its rotting fist.","actions":[{"action_name":"Dreadful Glare","count":1,"type":"ability"},{"action_name":"Rotting Fist","count":1,"type":"melee"}]},{"name":"Rotting Fist","desc":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) bludgeoning damage plus 10 (3d6) necrotic damage. If the target is a creature, it must succeed on a DC 12 Constitution saving throw or be cursed with mummy rot. The cursed target can''t regain hit points, and its hit point maximum decreases by 10 (3d6) for every 24 hours that elapse. If the curse reduces the target''s hit point maximum to 0, the target dies, and its body turns to dust. The curse lasts until removed by the remove curse spell or other magic.","attack_bonus":5,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"2d6+3"},{"damage_type":{"index":"necrotic","name":"Necrotic","url":"/api/2014/damage-types/necrotic"},"damage_dice":"3d6"}]},{"name":"Dreadful Glare","desc":"The mummy targets one creature it can see within 60 ft. of it. If the target can see the mummy, it must succeed on a DC 11 Wisdom saving throw against this magic or become frightened until the end of the mummy''s next turn. If the target fails the saving throw by 5 or more, it is also paralyzed for the same duration. A target that succeeds on the saving throw is immune to the Dreadful Glare of all mummies (but not mummy lords) for the next 24 hours.","dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_value":11,"success_type":"none"}}],"image":"/api/images/monsters/mummy.png","url":"/api/2014/monsters/mummy"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Mummy Lord","desc":null}'::jsonb, '{"index":"mummy-lord","name":"Mummy Lord","size":"Medium","type":"undead","alignment":"lawful evil","armor_class":[{"type":"natural","value":17}],"hit_points":97,"hit_dice":"13d8","hit_points_roll":"13d8+39","speed":{"walk":"20 ft."},"strength":18,"dexterity":10,"constitution":17,"intelligence":11,"wisdom":18,"charisma":16,"proficiencies":[{"value":8,"proficiency":{"index":"saving-throw-con","name":"Saving Throw: CON","url":"/api/2014/proficiencies/saving-throw-con"}},{"value":5,"proficiency":{"index":"saving-throw-int","name":"Saving Throw: INT","url":"/api/2014/proficiencies/saving-throw-int"}},{"value":9,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}},{"value":8,"proficiency":{"index":"saving-throw-cha","name":"Saving Throw: CHA","url":"/api/2014/proficiencies/saving-throw-cha"}},{"value":5,"proficiency":{"index":"skill-history","name":"Skill: History","url":"/api/2014/proficiencies/skill-history"}},{"value":5,"proficiency":{"index":"skill-religion","name":"Skill: Religion","url":"/api/2014/proficiencies/skill-religion"}}],"damage_vulnerabilities":["fire"],"damage_resistances":[],"damage_immunities":["necrotic","poison","bludgeoning, piercing, and slashing from nonmagical weapons"],"condition_immunities":[{"index":"charmed","name":"Charmed","url":"/api/2014/conditions/charmed"},{"index":"exhaustion","name":"Exhaustion","url":"/api/2014/conditions/exhaustion"},{"index":"frightened","name":"Frightened","url":"/api/2014/conditions/frightened"},{"index":"paralyzed","name":"Paralyzed","url":"/api/2014/conditions/paralyzed"},{"index":"poisoned","name":"Poisoned","url":"/api/2014/conditions/poisoned"}],"senses":{"darkvision":"60 ft.","passive_perception":14},"languages":"the languages it knew in life","challenge_rating":15,"proficiency_bonus":5,"xp":13000,"special_abilities":[{"name":"Magic Resistance","desc":"The mummy lord has advantage on saving throws against spells and other magical effects."},{"name":"Rejuvenation","desc":"A destroyed mummy lord gains a new body in 24 hours if its heart is intact, regaining all its hit points and becoming active again. The new body appears within 5 feet of the mummy lord''s heart."},{"name":"Spellcasting","desc":"The mummy lord is a 10th-level spellcaster. Its spellcasting ability is Wisdom (spell save DC 17, +9 to hit with spell attacks). The mummy lord has the following cleric spells prepared:\n\n- Cantrips (at will): sacred flame, thaumaturgy\n- 1st level (4 slots): command, guiding bolt, shield of faith\n- 2nd level (3 slots): hold person, silence, spiritual weapon\n- 3rd level (3 slots): animate dead, dispel magic\n- 4th level (3 slots): divination, guardian of faith\n- 5th level (2 slots): contagion, insect plague\n- 6th level (1 slot): harm","spellcasting":{"level":10,"ability":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc":17,"modifier":9,"components_required":["V","S","M"],"school":"cleric","slots":{"1":4,"2":3,"3":3,"4":3,"5":2,"6":1},"spells":[{"name":"Sacred Flame","level":0,"url":"/api/2014/spells/sacred-flame"},{"name":"Thaumaturgy","level":0,"url":"/api/2014/spells/thaumaturgy"},{"name":"Command","level":1,"url":"/api/2014/spells/command"},{"name":"Guiding Bolt","level":1,"url":"/api/2014/spells/guiding-bolt"},{"name":"Shield of Faith","level":1,"url":"/api/2014/spells/shield-of-faith"},{"name":"Hold Person","level":2,"url":"/api/2014/spells/hold-person"},{"name":"Silence","level":2,"url":"/api/2014/spells/silence"},{"name":"Spiritual Weapon","level":2,"url":"/api/2014/spells/spiritual-weapon"},{"name":"Animate Dead","level":3,"url":"/api/2014/spells/animate-dead"},{"name":"Dispel Magic","level":3,"url":"/api/2014/spells/dispel-magic"},{"name":"Divination","level":4,"url":"/api/2014/spells/divination"},{"name":"Guardian of Faith","level":4,"url":"/api/2014/spells/guardian-of-faith"},{"name":"Contagion","level":5,"url":"/api/2014/spells/contagion"},{"name":"Insect Plague","level":5,"url":"/api/2014/spells/insect-plague"},{"name":"Harm","level":6,"url":"/api/2014/spells/harm"}]}}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The mummy can use its Dreadful Glare and makes one attack with its rotting fist.","actions":[{"action_name":"Dreadful Glare","count":1,"type":"ability"},{"action_name":"Rotting Fist","count":1,"type":"melee"}]},{"name":"Rotting Fist","desc":"Melee Weapon Attack: +9 to hit, reach 5 ft., one target. Hit: 14 (3d6 + 4) bludgeoning damage plus 21 (6d6) necrotic damage. If the target is a creature, it must succeed on a DC 16 Constitution saving throw or be cursed with mummy rot. The cursed target can''t regain hit points, and its hit point maximum decreases by 10 (3d6) for every 24 hours that elapse. If the curse reduces the target''s hit point maximum to 0, the target dies, and its body turns to dust. The curse lasts until removed by the remove curse spell or other magic.","attack_bonus":9,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"3d6+4"},{"damage_type":{"index":"necrotic","name":"Necrotic","url":"/api/2014/damage-types/necrotic"},"damage_dice":"6d6"}]},{"name":"Dreadful Glare","desc":"The mummy lord targets one creature it can see within 60 feet of it. If the target can see the mummy lord, it must succeed on a DC 16 Wisdom saving throw against this magic or become frightened until the end of the mummy''s next turn. If the target fails the saving throw by 5 or more, it is also paralyzed for the same duration. A target that succeeds on the saving throw is immune to the Dreadful Glare of all mummies and mummy lords for the next 24 hours.","dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_value":16,"success_type":"none"}}],"legendary_actions":[{"name":"Attack","desc":"The mummy lord makes one attack with its rotting fist or uses its Dreadful Glare."},{"name":"Blinding Dust","desc":"Blinding dust and sand swirls magically around the mummy lord. Each creature within 5 feet of the mummy lord must succeed on a DC 16 Constitution saving throw or be blinded until the end of the creature''s next turn.","dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_value":16,"success_type":"none"}},{"name":"Blasphemous Word (Costs 2 Actions)","desc":"The mummy lord utters a blasphemous word. Each non-undead creature within 10 feet of the mummy lord that can hear the magical utterance must succeed on a DC 16 Constitution saving throw or be stunned until the end of the mummy lord''s next turn.","dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_value":16,"success_type":"none"}},{"name":"Channel Negative Energy (Costs 2 Actions)","desc":"The mummy lord magically unleashes negative energy. Creatures within 60 feet of the mummy lord, including ones behind barriers and around corners, can''t regain hit points until the end of the mummy lord''s next turn."},{"name":"Whirlwind of Sand (Costs 2 Actions)","desc":"The mummy lord magically transforms into a whirlwind of sand, moves up to 60 feet, and reverts to its normal form. While in whirlwind form, the mummy lord is immune to all damage, and it can''t be grappled, petrified, knocked prone, restrained, or stunned. Equipment worn or carried by the mummy lord remain in its possession."}],"image":"/api/images/monsters/mummy-lord.png","url":"/api/2014/monsters/mummy-lord"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Nalfeshnee","desc":null}'::jsonb, '{"index":"nalfeshnee","name":"Nalfeshnee","size":"Large","type":"fiend","subtype":"demon","alignment":"chaotic evil","armor_class":[{"type":"natural","value":18}],"hit_points":184,"hit_dice":"16d10","hit_points_roll":"16d10+96","speed":{"walk":"20 ft.","fly":"30 ft."},"strength":21,"dexterity":10,"constitution":22,"intelligence":19,"wisdom":12,"charisma":15,"proficiencies":[{"value":11,"proficiency":{"index":"saving-throw-con","name":"Saving Throw: CON","url":"/api/2014/proficiencies/saving-throw-con"}},{"value":9,"proficiency":{"index":"saving-throw-int","name":"Saving Throw: INT","url":"/api/2014/proficiencies/saving-throw-int"}},{"value":6,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}},{"value":7,"proficiency":{"index":"saving-throw-cha","name":"Saving Throw: CHA","url":"/api/2014/proficiencies/saving-throw-cha"}}],"damage_vulnerabilities":[],"damage_resistances":["cold","fire","lightning","bludgeoning, piercing, and slashing from nonmagical weapons"],"damage_immunities":["poison"],"condition_immunities":[{"index":"poisoned","name":"Poisoned","url":"/api/2014/conditions/poisoned"}],"senses":{"truesight":"120 ft.","passive_perception":11},"languages":"Abyssal, telepathy 120 ft.","challenge_rating":13,"proficiency_bonus":5,"xp":10000,"special_abilities":[{"name":"Magic Resistance","desc":"The nalfeshnee has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The nalfeshnee uses Horror Nimbus if it can. It then makes three attacks: one with its bite and two with its claws.","actions":[{"action_name":"Horror Nimbus","count":1,"type":"ability"},{"action_name":"Bite","count":1,"type":"melee"},{"action_name":"Claw","count":2,"type":"melee"}]},{"name":"Bite","desc":"Melee Weapon Attack: +10 to hit, reach 5 ft., one target. Hit: 32 (5d10 + 5) piercing damage.","attack_bonus":10,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"5d10+5"}]},{"name":"Claw","desc":"Melee Weapon Attack: +10 to hit, reach 10 ft., one target. Hit: 15 (3d6 + 5) slashing damage.","attack_bonus":10,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"3d6+5"}]},{"name":"Horror Nimbus","desc":"The nalfeshnee magically emits scintillating, multicolored light. Each creature within 15 feet of the nalfeshnee that can see the light must succeed on a DC 15 Wisdom saving throw or be frightened for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the nalfeshnee''s Horror Nimbus for the next 24 hours.","usage":{"type":"recharge on roll","dice":"1d6","min_value":5},"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_value":15,"success_type":"none"}},{"name":"Teleport","desc":"The nalfeshnee magically teleports, along with any equipment it is wearing or carrying, up to 120 feet to an unoccupied space it can see."}],"image":"/api/images/monsters/nalfeshnee.png","url":"/api/2014/monsters/nalfeshnee"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Night Hag","desc":null}'::jsonb, '{"index":"night-hag","name":"Night Hag","size":"Medium","type":"fiend","alignment":"neutral evil","armor_class":[{"type":"natural","value":17}],"hit_points":112,"hit_dice":"15d8","hit_points_roll":"15d8+45","speed":{"walk":"30 ft."},"strength":18,"dexterity":15,"constitution":16,"intelligence":16,"wisdom":14,"charisma":16,"proficiencies":[{"value":7,"proficiency":{"index":"skill-deception","name":"Skill: Deception","url":"/api/2014/proficiencies/skill-deception"}},{"value":6,"proficiency":{"index":"skill-insight","name":"Skill: Insight","url":"/api/2014/proficiencies/skill-insight"}},{"value":6,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"value":6,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":["cold","fire","bludgeoning, piercing, and slashing from nonmagical weapons that aren''t silvered"],"damage_immunities":[],"condition_immunities":[{"index":"charmed","name":"Charmed","url":"/api/2014/conditions/charmed"}],"senses":{"darkvision":"120 ft.","passive_perception":16},"languages":"Abyssal, Common, Infernal, Primordial","challenge_rating":5,"proficiency_bonus":3,"xp":1800,"special_abilities":[{"name":"Innate Spellcasting","desc":"The hag''s innate spellcasting ability is Charisma (spell save DC 14, +6 to hit with spell attacks). She can innately cast the following spells, requiring no material components:\n\nAt will: detect magic, magic missile\n2/day each: plane shift (self only), ray of enfeeblement, sleep","spellcasting":{"ability":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"dc":14,"modifier":6,"components_required":["V","S"],"spells":[{"name":"Detect Magic","level":1,"url":"/api/2014/spells/detect-magic","usage":{"type":"at will"}},{"name":"Magic Missile","level":1,"url":"/api/2014/spells/magic-missile","usage":{"type":"at will"}},{"name":"Plane Shift","level":7,"notes":"Self Only","url":"/api/2014/spells/plane-shift","usage":{"type":"per day","times":2}},{"name":"Ray of Enfeeblement","level":2,"url":"/api/2014/spells/ray-of-enfeeblement","usage":{"type":"per day","times":2}},{"name":"Sleep","level":1,"url":"/api/2014/spells/sleep","usage":{"type":"per day","times":2}}]}},{"name":"Magic Resistance","desc":"The hag has advantage on saving throws against spells and other magical effects."},{"name":"Night Hag Items","desc":"A night hag carries two very rare magic items that she must craft for herself If either object is lost, the night hag will go to great lengths to retrieve it, as creating a new tool takes time and effort.\nHeartstone: This lustrous black gem allows a night hag to become ethereal while it is in her possession. The touch of a heartstone also cures any disease. Crafting a heartstone takes 30 days.\nSoul Bag: When an evil humanoid dies as a result of a night hag''s Nightmare Haunting, the hag catches the soul in this black sack made of stitched flesh. A soul bag can hold only one evil soul at a time, and only the night hag who crafted the bag can catch a soul with it. Crafting a soul bag takes 7 days and a humanoid sacrifice (whose flesh is used to make the bag)."}],"actions":[{"name":"Claws (Hag Form Only)","desc":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 13 (2d8 + 4) slashing damage.","attack_bonus":7,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"2d8+4"}]},{"name":"Change Shape","desc":"The hag magically polymorphs into a Small or Medium female humanoid, or back into her true form. Her statistics are the same in each form. Any equipment she is wearing or carrying isn''t transformed. She reverts to her true form if she dies."},{"name":"Etherealness","desc":"The hag magically enters the Ethereal Plane from the Material Plane, or vice versa. To do so, the hag must have a heartstone in her possession."},{"name":"Nightmare Haunting","desc":"While on the Ethereal Plane, the hag magically touches a sleeping humanoid on the Material Plane. A protection from evil and good spell cast on the target prevents this contact, as does a magic circle. As long as the contact persists, the target has dreadful visions. If these visions last for at least 1 hour, the target gains no benefit from its rest, and its hit point maximum is reduced by 5 (1d10). If this effect reduces the target''s hit point maximum to 0, the target dies, and if the target was evil, its soul is trapped in the hag''s soul bag. The reduction to the target''s hit point maximum lasts until removed by the greater restoration spell or similar magic.","usage":{"type":"per day","times":1}}],"image":"/api/images/monsters/night-hag.png","url":"/api/2014/monsters/night-hag"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Nightmare","desc":null}'::jsonb, '{"index":"nightmare","name":"Nightmare","size":"Large","type":"fiend","alignment":"neutral evil","armor_class":[{"type":"natural","value":13}],"hit_points":68,"hit_dice":"8d10","hit_points_roll":"8d10+24","speed":{"walk":"60 ft.","fly":"90 ft."},"strength":18,"dexterity":15,"constitution":16,"intelligence":10,"wisdom":13,"charisma":15,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":["fire"],"condition_immunities":[],"senses":{"passive_perception":11},"languages":"understands Abyssal, Common, and Infernal but can''t speak","challenge_rating":3,"proficiency_bonus":2,"xp":700,"special_abilities":[{"name":"Confer Fire Resistance","desc":"The nightmare can grant resistance to fire damage to anyone riding it."},{"name":"Illumination","desc":"The nightmare sheds bright light in a 10-foot radius and dim light for an additional 10 feet."}],"actions":[{"name":"Hooves","desc":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 13 (2d8 + 4) bludgeoning damage plus 7 (2d6) fire damage.","attack_bonus":6,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"2d8+4"},{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_dice":"2d6"}]},{"name":"Ethereal Stride","desc":"The nightmare and up to three willing creatures within 5 feet of it magically enter the Ethereal Plane from the Material Plane, or vice versa."}],"image":"/api/images/monsters/nightmare.png","url":"/api/2014/monsters/nightmare"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Noble","desc":"**Nobles** wield great authority and influence as members of the upper class, possessing wealth and connections that can make them as powerful as monarchs and generals. A noble often travels in the company of guards, as well as servants who are commoners.\n\nThe noble’s statistics can also be used to represent **courtiers** who aren’t of noble birth."}'::jsonb, '{"index":"noble","name":"Noble","desc":"**Nobles** wield great authority and influence as members of the upper class, possessing wealth and connections that can make them as powerful as monarchs and generals. A noble often travels in the company of guards, as well as servants who are commoners.\n\nThe noble’s statistics can also be used to represent **courtiers** who aren’t of noble birth.","size":"Medium","type":"humanoid","subtype":"any race","alignment":"any alignment","armor_class":[{"type":"armor","value":15,"armor":[{"index":"breastplate","name":"Breastplate","url":"/api/2014/equipment/breastplate"}]}],"hit_points":9,"hit_dice":"2d8","hit_points_roll":"2d8","speed":{"walk":"30 ft."},"strength":11,"dexterity":12,"constitution":11,"intelligence":12,"wisdom":14,"charisma":16,"proficiencies":[{"value":5,"proficiency":{"index":"skill-deception","name":"Skill: Deception","url":"/api/2014/proficiencies/skill-deception"}},{"value":4,"proficiency":{"index":"skill-insight","name":"Skill: Insight","url":"/api/2014/proficiencies/skill-insight"}},{"value":5,"proficiency":{"index":"skill-persuasion","name":"Skill: Persuasion","url":"/api/2014/proficiencies/skill-persuasion"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":12},"languages":"any two languages","challenge_rating":0.125,"proficiency_bonus":2,"xp":25,"actions":[{"name":"Rapier","desc":"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 5 (1d8 + 1) piercing damage.","attack_bonus":3,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d8+1"}]}],"reactions":[{"name":"Parry","desc":"The noble adds 2 to its AC against one melee attack that would hit it. To do so, the noble must see the attacker and be wielding a melee weapon."}],"image":"/api/images/monsters/noble.png","url":"/api/2014/monsters/noble"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Ochre Jelly","desc":null}'::jsonb, '{"index":"ochre-jelly","name":"Ochre Jelly","size":"Large","type":"ooze","alignment":"unaligned","armor_class":[{"type":"dex","value":8}],"hit_points":45,"hit_dice":"6d10","hit_points_roll":"6d10+12","speed":{"walk":"10 ft.","climb":"10 ft."},"strength":15,"dexterity":6,"constitution":14,"intelligence":2,"wisdom":6,"charisma":1,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":["acid"],"damage_immunities":["lightning","slashing"],"condition_immunities":[{"index":"blinded","name":"Blinded","url":"/api/2014/conditions/blinded"},{"index":"charmed","name":"Charmed","url":"/api/2014/conditions/charmed"},{"index":"blinded","name":"Blinded","url":"/api/2014/conditions/blinded"},{"index":"exhaustion","name":"Exhaustion","url":"/api/2014/conditions/exhaustion"},{"index":"frightened","name":"Frightened","url":"/api/2014/conditions/frightened"},{"index":"prone","name":"Prone","url":"/api/2014/conditions/prone"}],"senses":{"blindsight":"60 ft. (blind beyond this radius)","passive_perception":8},"languages":"","challenge_rating":2,"proficiency_bonus":2,"xp":450,"special_abilities":[{"name":"Amorphous","desc":"The jelly can move through a space as narrow as 1 inch wide without squeezing."},{"name":"Spider Climb","desc":"The jelly can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."}],"actions":[{"name":"Pseudopod","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 9 (2d6 + 2) bludgeoning damage plus 3 (1d6) acid damage.","attack_bonus":4,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"2d6+2"},{"damage_type":{"index":"acid","name":"Acid","url":"/api/2014/damage-types/acid"},"damage_dice":"1d6"}]}],"reactions":[{"name":"Split","desc":"When a jelly that is Medium or larger is subjected to lightning or slashing damage, it splits into two new jellies if it has at least 10 hit points. Each new jelly has hit points equal to half the original jelly''s, rounded down. New jellies are one size smaller than the original jelly."}],"image":"/api/images/monsters/ochre-jelly.png","url":"/api/2014/monsters/ochre-jelly"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Octopus","desc":null}'::jsonb, '{"index":"octopus","name":"Octopus","size":"Small","type":"beast","alignment":"unaligned","armor_class":[{"type":"dex","value":12}],"hit_points":3,"hit_dice":"1d6","hit_points_roll":"1d6","speed":{"walk":"5 ft.","swim":"30 ft."},"strength":4,"dexterity":15,"constitution":11,"intelligence":3,"wisdom":10,"charisma":4,"proficiencies":[{"value":2,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"value":4,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"30 ft.","passive_perception":12},"languages":"","challenge_rating":0,"proficiency_bonus":2,"xp":10,"special_abilities":[{"name":"Hold Breath","desc":"While out of water, the octopus can hold its breath for 30 minutes."},{"name":"Underwater Camouflage","desc":"The octopus has advantage on Dexterity (Stealth) checks made while underwater."},{"name":"Water Breathing","desc":"The octopus can breathe only underwater."}],"actions":[{"name":"Tentacles","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 1 bludgeoning damage, and the target is grappled (escape DC 10). Until this grapple ends, the octopus can''t use its tentacles on another target.","attack_bonus":4,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"1"}]},{"name":"Ink Cloud","desc":"A 5-foot-radius cloud of ink extends all around the octopus if it is underwater. The area is heavily obscured for 1 minute, although a significant current can disperse the ink. After releasing the ink, the octopus can use the Dash action as a bonus action.","usage":{"type":"recharge after rest","rest_types":["short","long"]},"attack_bonus":0}],"image":"/api/images/monsters/octopus.png","url":"/api/2014/monsters/octopus"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Ogre","desc":null}'::jsonb, '{"index":"ogre","name":"Ogre","size":"Large","type":"giant","alignment":"chaotic evil","armor_class":[{"type":"armor","value":11,"armor":[{"index":"hide-armor","name":"Hide Armor","url":"/api/2014/equipment/hide-armor"}]}],"hit_points":59,"hit_dice":"7d10","hit_points_roll":"7d10+21","speed":{"walk":"40 ft."},"strength":19,"dexterity":8,"constitution":16,"intelligence":5,"wisdom":7,"charisma":7,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"60 ft.","passive_perception":8},"languages":"Common, Giant","challenge_rating":2,"proficiency_bonus":2,"xp":450,"actions":[{"name":"Greatclub","desc":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 13 (2d8 + 4) bludgeoning damage.","attack_bonus":6,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"2d8+4"}]},{"name":"Javelin","desc":"Melee or Ranged Weapon Attack: +6 to hit, reach 5 ft. or range 30/120 ft., one target. Hit: 11 (2d6 + 4) piercing damage.","attack_bonus":6,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"2d6+4"}]}],"image":"/api/images/monsters/ogre.png","url":"/api/2014/monsters/ogre"}'::jsonb),
