  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Oni","desc":null}'::jsonb, '{"index":"oni","name":"Oni","size":"Large","type":"giant","alignment":"lawful evil","armor_class":[{"type":"armor","value":16,"armor":[{"index":"chain-mail","name":"Chain Mail","url":"/api/2014/equipment/chain-mail"}]}],"hit_points":110,"hit_dice":"13d10","hit_points_roll":"13d10+39","speed":{"walk":"30 ft.","fly":"30 ft."},"strength":19,"dexterity":11,"constitution":16,"intelligence":14,"wisdom":12,"charisma":15,"proficiencies":[{"value":3,"proficiency":{"index":"saving-throw-dex","name":"Saving Throw: DEX","url":"/api/2014/proficiencies/saving-throw-dex"}},{"value":6,"proficiency":{"index":"saving-throw-con","name":"Saving Throw: CON","url":"/api/2014/proficiencies/saving-throw-con"}},{"value":4,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}},{"value":5,"proficiency":{"index":"saving-throw-cha","name":"Saving Throw: CHA","url":"/api/2014/proficiencies/saving-throw-cha"}},{"value":5,"proficiency":{"index":"skill-arcana","name":"Skill: Arcana","url":"/api/2014/proficiencies/skill-arcana"}},{"value":8,"proficiency":{"index":"skill-deception","name":"Skill: Deception","url":"/api/2014/proficiencies/skill-deception"}},{"value":4,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"60 ft.","passive_perception":14},"languages":"Common, Giant","challenge_rating":7,"proficiency_bonus":3,"xp":2900,"special_abilities":[{"name":"Innate Spellcasting","desc":"The oni''s innate spellcasting ability is Charisma (spell save DC 13). The oni can innately cast the following spells, requiring no material components:\n\nAt will: darkness, invisibility\n1/day each: charm person, cone of cold, gaseous form, sleep","spellcasting":{"ability":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"dc":13,"components_required":["V","S"],"spells":[{"name":"Darkness","level":2,"url":"/api/2014/spells/darkness","usage":{"type":"at will"}},{"name":"Invisibility","level":2,"url":"/api/2014/spells/invisibility","usage":{"type":"at will"}},{"name":"Charm Person","level":1,"url":"/api/2014/spells/charm-person","usage":{"type":"per day","times":1}},{"name":"Cone of Cold","level":5,"url":"/api/2014/spells/cone-of-cold","usage":{"type":"per day","times":1}},{"name":"Gaseous Form","level":3,"url":"/api/2014/spells/gaseous-form","usage":{"type":"per day","times":1}},{"name":"Sleep","level":1,"url":"/api/2014/spells/sleep","usage":{"type":"per day","times":1}}]}},{"name":"Magic Weapons","desc":"The oni''s weapon attacks are magical."},{"name":"Regeneration","desc":"The oni regains 10 hit points at the start of its turn if it has at least 1 hit point."}],"actions":[{"name":"Multiattack","multiattack_type":"action_options","desc":"The oni makes two attacks, either with its claws or its glaive.","action_options":{"choose":1,"type":"action","from":{"option_set_type":"options_array","options":[{"option_type":"action","action_name":"Glaive","count":2,"type":"melee"},{"option_type":"action","action_name":"Claw","desc":"If in Oni form","count":2,"type":"melee"},{"desc":"If in Oni form","option_type":"multiple","items":[{"option_type":"action","action_name":"Glaive","count":1,"type":"melee"},{"option_type":"action","action_name":"Claw","count":1,"type":"melee"}]}]}}},{"name":"Claw (Oni Form Only)","desc":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 8 (1d8 + 4) slashing damage.","attack_bonus":7,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"1d8+4"}]},{"name":"Glaive","desc":"Melee Weapon Attack: +7 to hit, reach 10 ft., one target. Hit: 15 (2d10 + 4) slashing damage, or 9 (1d10 + 4) slashing damage in Small or Medium form.","attack_bonus":7,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"2d10+4"}]},{"name":"Change Shape","desc":"The oni magically polymorphs into a Small or Medium humanoid, into a Large giant, or back into its true form. Other than its size, its statistics are the same in each form. The only equipment that is transformed is its glaive, which shrinks so that it can be wielded in humanoid form. If the oni dies, it reverts to its true form, and its glaive reverts to its normal size."}],"image":"/api/images/monsters/oni.png","url":"/api/2014/monsters/oni"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Orc","desc":null}'::jsonb, '{"index":"orc","name":"Orc","size":"Medium","type":"humanoid","subtype":"orc","alignment":"chaotic evil","armor_class":[{"type":"armor","value":13,"armor":[{"index":"hide-armor","name":"Hide Armor","url":"/api/2014/equipment/hide-armor"}]}],"hit_points":15,"hit_dice":"2d8","hit_points_roll":"2d8+6","speed":{"walk":"30 ft."},"strength":16,"dexterity":12,"constitution":16,"intelligence":7,"wisdom":11,"charisma":10,"proficiencies":[{"value":2,"proficiency":{"index":"skill-intimidation","name":"Skill: Intimidation","url":"/api/2014/proficiencies/skill-intimidation"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"60 ft.","passive_perception":10},"languages":"Common, Orc","challenge_rating":0.5,"proficiency_bonus":2,"xp":100,"special_abilities":[{"name":"Aggressive","desc":"As a bonus action, the orc can move up to its speed toward a hostile creature that it can see."}],"actions":[{"name":"Greataxe","desc":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 9 (1d12 + 3) slashing damage.","attack_bonus":5,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"1d12+3"}]},{"name":"Javelin","desc":"Melee or Ranged Weapon Attack: +5 to hit, reach 5 ft. or range 30/120 ft., one target. Hit: 6 (1d6 + 3) piercing damage.","attack_bonus":5,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d6+3"}]}],"image":"/api/images/monsters/orc.png","url":"/api/2014/monsters/orc"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Otyugh","desc":null}'::jsonb, '{"index":"otyugh","name":"Otyugh","size":"Large","type":"aberration","alignment":"neutral","armor_class":[{"type":"natural","value":14}],"hit_points":114,"hit_dice":"12d10","hit_points_roll":"12d10+48","speed":{"walk":"30 ft."},"strength":16,"dexterity":11,"constitution":19,"intelligence":6,"wisdom":13,"charisma":6,"proficiencies":[{"value":7,"proficiency":{"index":"saving-throw-con","name":"Saving Throw: CON","url":"/api/2014/proficiencies/saving-throw-con"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"120 ft.","passive_perception":11},"languages":"Otyugh","challenge_rating":5,"proficiency_bonus":3,"xp":1800,"special_abilities":[{"name":"Limited Telepathy","desc":"The otyugh can magically transmit simple messages and images to any creature within 120 ft. of it that can understand a language. This form of telepathy doesn''t allow the receiving creature to telepathically respond."}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The otyugh makes three attacks: one with its bite and two with its tentacles.","actions":[{"action_name":"Bite","count":1,"type":"melee"},{"action_name":"Tentacle","count":2,"type":"melee"}]},{"name":"Bite","desc":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 12 (2d8 + 3) piercing damage. If the target is a creature, it must succeed on a DC 15 Constitution saving throw against disease or become poisoned until the disease is cured. Every 24 hours that elapse, the target must repeat the saving throw, reducing its hit point maximum by 5 (1d10) on a failure. The disease is cured on a success. The target dies if the disease reduces its hit point maximum to 0. This reduction to the target''s hit point maximum lasts until the disease is cured.","attack_bonus":6,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"2d8+3"}]},{"name":"Tentacle","desc":"Melee Weapon Attack: +6 to hit, reach 10 ft., one target. Hit: 7 (1d8 + 3) bludgeoning damage plus 4 (1d8) piercing damage. If the target is Medium or smaller, it is grappled (escape DC 13) and restrained until the grapple ends. The otyugh has two tentacles, each of which can grapple one target.","attack_bonus":6,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"1d8+3"},{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d8"}]},{"name":"Tentacle Slam","desc":"The otyugh slams creatures grappled by it into each other or a solid surface. Each creature must succeed on a DC 14 Constitution saving throw or take 10 (2d6 + 3) bludgeoning damage and be stunned until the end of the otyugh''s next turn. On a successful save, the target takes half the bludgeoning damage and isn''t stunned.","dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_value":14,"success_type":"half"}}],"image":"/api/images/monsters/otyugh.png","url":"/api/2014/monsters/otyugh"}'::jsonb),
