  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Pegasus","desc":null}'::jsonb, '{"index":"pegasus","name":"Pegasus","size":"Large","type":"celestial","alignment":"chaotic good","armor_class":[{"type":"dex","value":12}],"hit_points":59,"hit_dice":"7d10","hit_points_roll":"7d10+21","speed":{"walk":"60 ft.","fly":"90 ft."},"strength":18,"dexterity":15,"constitution":16,"intelligence":10,"wisdom":15,"charisma":13,"proficiencies":[{"value":4,"proficiency":{"index":"saving-throw-dex","name":"Saving Throw: DEX","url":"/api/2014/proficiencies/saving-throw-dex"}},{"value":4,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}},{"value":3,"proficiency":{"index":"saving-throw-cha","name":"Saving Throw: CHA","url":"/api/2014/proficiencies/saving-throw-cha"}},{"value":6,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":16},"languages":"understands Celestial, Common, Elvish, and Sylvan but can''t speak","challenge_rating":2,"proficiency_bonus":2,"xp":450,"actions":[{"name":"Hooves","desc":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) bludgeoning damage.","attack_bonus":6,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"2d6+4"}]}],"image":"/api/images/monsters/pegasus.png","url":"/api/2014/monsters/pegasus"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Phase Spider","desc":"A phase spider possesses the magical ability to phase in and out of the Ethereal Plane. It seems to appear out of nowhere and quickly vanishes after attacking. Its movement on the Ethereal Plane before coming back to the Material Plane makes it seem like it can teleport."}'::jsonb, '{"index":"phase-spider","name":"Phase Spider","desc":"A phase spider possesses the magical ability to phase in and out of the Ethereal Plane. It seems to appear out of nowhere and quickly vanishes after attacking. Its movement on the Ethereal Plane before coming back to the Material Plane makes it seem like it can teleport.","size":"Large","type":"monstrosity","alignment":"unaligned","armor_class":[{"type":"natural","value":13}],"hit_points":32,"hit_dice":"5d10","hit_points_roll":"5d10+5","speed":{"walk":"30 ft.","climb":"30 ft."},"strength":15,"dexterity":15,"constitution":12,"intelligence":6,"wisdom":10,"charisma":6,"proficiencies":[{"value":6,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"60 ft.","passive_perception":10},"languages":"","challenge_rating":3,"proficiency_bonus":2,"xp":700,"special_abilities":[{"name":"Ethereal Jaunt","desc":"As a bonus action, the spider can magically shift from the Material Plane to the Ethereal Plane, or vice versa."},{"name":"Spider Climb","desc":"The spider can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."},{"name":"Web Walker","desc":"The spider ignores movement restrictions caused by webbing."}],"actions":[{"name":"Bite","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 7 (1d10 + 2) piercing damage, and the target must make a DC 11 Constitution saving throw, taking 18 (4d8) poison damage on a failed save, or half as much damage on a successful one. If the poison damage reduces the target to 0 hit points, the target is stable but poisoned for 1 hour, even after regaining hit points, and is paralyzed while poisoned in this way.","attack_bonus":4,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d10+2"}]}],"image":"/api/images/monsters/phase-spider.png","url":"/api/2014/monsters/phase-spider"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Pit Fiend","desc":null}'::jsonb, '{"index":"pit-fiend","name":"Pit Fiend","size":"Large","type":"fiend","subtype":"devil","alignment":"lawful evil","armor_class":[{"type":"natural","value":19}],"hit_points":300,"hit_dice":"24d10","hit_points_roll":"24d10+168","speed":{"walk":"30 ft.","fly":"60 ft."},"strength":26,"dexterity":14,"constitution":24,"intelligence":22,"wisdom":18,"charisma":24,"proficiencies":[{"value":8,"proficiency":{"index":"saving-throw-dex","name":"Saving Throw: DEX","url":"/api/2014/proficiencies/saving-throw-dex"}},{"value":13,"proficiency":{"index":"saving-throw-con","name":"Saving Throw: CON","url":"/api/2014/proficiencies/saving-throw-con"}},{"value":10,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}}],"damage_vulnerabilities":[],"damage_resistances":["cold","bludgeoning, piercing, and slashing from nonmagical weapons that aren''t silvered"],"damage_immunities":["fire","poison"],"condition_immunities":[{"index":"poisoned","name":"Poisoned","url":"/api/2014/conditions/poisoned"}],"senses":{"truesight":"120 ft.","passive_perception":14},"languages":"Infernal, telepathy 120 ft.","challenge_rating":20,"proficiency_bonus":6,"xp":25000,"special_abilities":[{"name":"Fear Aura","desc":"Any creature hostile to the pit fiend that starts its turn within 20 feet of the pit fiend must make a DC 21 Wisdom saving throw, unless the pit fiend is incapacitated. On a failed save, the creature is frightened until the start of its next turn. If a creature''s saving throw is successful, the creature is immune to the pit fiend''s Fear Aura for the next 24 hours.","dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_value":21,"success_type":"none"}},{"name":"Magic Resistance","desc":"The pit fiend has advantage on saving throws against spells and other magical effects."},{"name":"Magic Weapons","desc":"The pit fiend''s weapon attacks are magical."},{"name":"Innate Spellcasting","desc":"The pit fiend''s spellcasting ability is Charisma (spell save DC 21). The pit fiend can innately cast the following spells, requiring no material components:\nAt will: detect magic, fireball\n3/day each: hold monster, wall of fire","spellcasting":{"ability":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"dc":21,"components_required":["V","S"],"spells":[{"name":"Detect Magic","level":1,"url":"/api/2014/spells/detect-magic","usage":{"type":"at will"}},{"name":"Fireball","level":3,"url":"/api/2014/spells/fireball","usage":{"type":"at will"}},{"name":"Hold Monster","level":5,"url":"/api/2014/spells/hold-monster","usage":{"type":"per day","times":3}},{"name":"Wall of Fire","level":4,"url":"/api/2014/spells/wall-of-fire","usage":{"type":"per day","times":3}}]}}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The pit fiend makes four attacks: one with its bite, one with its claw, one with its mace, and one with its tail.","actions":[{"action_name":"Bite","count":1,"type":"melee"},{"action_name":"Claw","count":1,"type":"melee"},{"action_name":"Mace","count":1,"type":"melee"},{"action_name":"Tail","count":1,"type":"melee"}]},{"name":"Bite","desc":"Melee Weapon Attack: +14 to hit, reach 5 ft., one target. Hit: 22 (4d6 + 8) piercing damage. The target must succeed on a DC 21 Constitution saving throw or become poisoned. While poisoned in this way, the target can''t regain hit points, and it takes 21 (6d6) poison damage at the start of each of its turns. The poisoned target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","attack_bonus":14,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"4d6+8"}]},{"name":"Claw","desc":"Melee Weapon Attack: +14 to hit, reach 10 ft., one target. Hit: 17 (2d8 + 8) slashing damage.","attack_bonus":14,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"2d8+8"}]},{"name":"Mace","desc":"Melee Weapon Attack: +14 to hit, reach 10 ft., one target. Hit: 15 (2d6 + 8) bludgeoning damage plus 21 (6d6) fire damage.","attack_bonus":14,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"2d6+8"}]},{"name":"Tail","desc":"Melee Weapon Attack: +14 to hit, reach 10 ft., one target. Hit: 24 (3d10 + 8) bludgeoning damage.","attack_bonus":14,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"3d10+8"}]}],"image":"/api/images/monsters/pit-fiend.png","url":"/api/2014/monsters/pit-fiend"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Planetar","desc":null}'::jsonb, '{"index":"planetar","name":"Planetar","size":"Large","type":"celestial","alignment":"lawful good","armor_class":[{"type":"natural","value":19}],"hit_points":200,"hit_dice":"16d10","hit_points_roll":"16d10+112","speed":{"walk":"40 ft.","fly":"120 ft."},"strength":24,"dexterity":20,"constitution":24,"intelligence":19,"wisdom":22,"charisma":25,"proficiencies":[{"value":12,"proficiency":{"index":"saving-throw-con","name":"Saving Throw: CON","url":"/api/2014/proficiencies/saving-throw-con"}},{"value":11,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}},{"value":12,"proficiency":{"index":"saving-throw-cha","name":"Saving Throw: CHA","url":"/api/2014/proficiencies/saving-throw-cha"}},{"value":11,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}}],"damage_vulnerabilities":[],"damage_resistances":["radiant","bludgeoning, piercing, and slashing from nonmagical weapons"],"damage_immunities":[],"condition_immunities":[{"index":"charmed","name":"Charmed","url":"/api/2014/conditions/charmed"},{"index":"exhaustion","name":"Exhaustion","url":"/api/2014/conditions/exhaustion"},{"index":"frightened","name":"Frightened","url":"/api/2014/conditions/frightened"}],"senses":{"truesight":"120 ft.","passive_perception":21},"languages":"all, telepathy 120 ft.","challenge_rating":16,"proficiency_bonus":5,"xp":15000,"special_abilities":[{"name":"Angelic Weapons","desc":"The planetar''s weapon attacks are magical. When the planetar hits with any weapon, the weapon deals an extra 5d8 radiant damage (included in the attack)."},{"name":"Divine Awareness","desc":"The planetar knows if it hears a lie."},{"name":"Innate Spellcasting","desc":"The planetar''s spellcasting ability is Charisma (spell save DC 20). The planetar can innately cast the following spells, requir