  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Priest","desc":"Priests bring the teachings of their gods to the common folk. They are the spiritual leaders of temples and shrines and often hold positions of influence in their communities. Evil priests might work openly under a tyrant, or they might be the leaders of religious sects hidden in the shadows of good society, overseeing depraved rites.\n\nA priest typically has one or more acolytes to help with religious ceremonies and other sacred duties."}'::jsonb, '{"index":"priest","name":"Priest","desc":"Priests bring the teachings of their gods to the common folk. They are the spiritual leaders of temples and shrines and often hold positions of influence in their communities. Evil priests might work openly under a tyrant, or they might be the leaders of religious sects hidden in the shadows of good society, overseeing depraved rites.\n\nA priest typically has one or more acolytes to help with religious ceremonies and other sacred duties.","size":"Medium","type":"humanoid","subtype":"any race","alignment":"any alignment","armor_class":[{"type":"armor","value":13,"armor":[{"index":"chain-shirt","name":"Chain Shirt","url":"/api/2014/equipment/chain-shirt"}]}],"hit_points":27,"hit_dice":"5d8","hit_points_roll":"5d8+5","speed":{"walk":"25 ft."},"strength":10,"dexterity":10,"constitution":12,"intelligence":13,"wisdom":16,"charisma":13,"proficiencies":[{"value":7,"proficiency":{"index":"skill-medicine","name":"Skill: Medicine","url":"/api/2014/proficiencies/skill-medicine"}},{"value":3,"proficiency":{"index":"skill-persuasion","name":"Skill: Persuasion","url":"/api/2014/proficiencies/skill-persuasion"}},{"value":4,"proficiency":{"index":"skill-religion","name":"Skill: Religion","url":"/api/2014/proficiencies/skill-religion"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":13},"languages":"any two languages","challenge_rating":2,"proficiency_bonus":2,"xp":450,"special_abilities":[{"name":"Divine Eminence","desc":"As a bonus action, the priest can expend a spell slot to cause its melee weapon attacks to magically deal an extra 10 (3d6) radiant damage to a target on a hit. This benefit lasts until the end of the turn. If the priest expends a spell slot of 2nd level or higher, the extra damage increases by 1d6 for each level above 1st."},{"name":"Spellcasting","desc":"The priest is a 5th-level spellcaster. Its spellcasting ability is Wisdom (spell save DC 13, +5 to hit with spell attacks). The priest has the following cleric spells prepared:\n\n- Cantrips (at will): light, sacred flame, thaumaturgy\n- 1st level (4 slots): cure wounds, guiding bolt, sanctuary\n- 2nd level (3 slots): lesser restoration, spiritual weapon\n- 3rd level (2 slots): dispel magic, spirit guardians","spellcasting":{"level":5,"ability":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc":13,"modifier":5,"components_required":["V","S","M"],"school":"cleric","slots":{"1":4,"2":3,"3":2},"spells":[{"name":"Light","level":0,"url":"/api/2014/spells/light"},{"name":"Sacred Flame","level":0,"url":"/api/2014/spells/sacred-flame"},{"name":"Thaumaturgy","level":0,"url":"/api/2014/spells/thaumaturgy"},{"name":"Cure Wounds","level":1,"url":"/api/2014/spells/cure-wounds"},{"name":"Guiding Bolt","level":1,"url":"/api/2014/spells/guiding-bolt"},{"name":"Sanctuary","level":1,"url":"/api/2014/spells/sanctuary"},{"name":"Lesser Restoration","level":2,"url":"/api/2014/spells/lesser-restoration"},{"name":"Spiritual Weapon","level":2,"url":"/api/2014/spells/spiritual-weapon"},{"name":"Dispel Magic","level":3,"url":"/api/2014/spells/dispel-magic"},{"name":"Spirit Guardians","level":3,"url":"/api/2014/spells/spirit-guardians"}]}}],"actions":[{"name":"Mace","desc":"Melee Weapon Attack: +2 to hit, reach 5 ft., one target. Hit: 3 (1d6) bludgeoning damage.","attack_bonus":2,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"1d6"}]}],"image":"/api/images/monsters/priest.png","url":"/api/2014/monsters/priest"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Pseudodragon","desc":null}'::jsonb, '{"index":"pseudodragon","name":"Pseudodragon","size":"Tiny","type":"dragon","alignment":"neutral good","armor_class":[{"type":"natural","value":13}],"hit_points":7,"hit_dice":"2d4","hit_points_roll":"2d4+2","speed":{"walk":"15 ft.","fly":"60 ft."},"strength":6,"dexterity":15,"constitution":13,"intelligence":10,"wisdom":12,"charisma":10,"proficiencies":[{"value":3,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"value":4,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"blindsight":"10 ft.","darkvision":"60 ft.","passive_perception":13},"languages":"understands Common and Draconic but can''t speak","challenge_rating":0.25,"proficiency_bonus":2,"xp":50,"special_abilities":[{"name":"Keen Senses","desc":"The pseudodragon has advantage on Wisdom (Perception) checks that rely on sight, hearing, or smell."},{"name":"Magic Resistance","desc":"The pseudodragon has advantage on saving throws against spells and other magical effects."},{"name":"Limited Telepathy","desc":"The pseudodragon can magically communicate simple ideas, emotions, and images telepathically with any creature within 100 ft. of it that can understand a language."}],"actions":[{"name":"Bite","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 4 (1d4 + 2) piercing damage.","attack_bonus":4,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d4+2"}]},{"name":"Sting","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 4 (1d4 + 2) piercing damage, and the target must succeed on a DC 11 Constitution saving throw or become poisoned for 1 hour. If the saving throw fails by 5 or more, the target falls unconscious for the same duration, or until it takes damage or another creature uses an action to shake it awake.","attack_bonus":4,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d4+2"}]}],"image":"/api/images/monsters/pseudodragon.png","url":"/api/2014/monsters/pseudodragon"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Purple Worm","desc":null}'::jsonb, '{"index":"purple-worm","name":"Purple Worm","size":"Gargantuan","type":"monstrosity","alignment":"unaligned","armor_class":[{"type":"natural","value":18}],"hit_points":247,"hit_dice":"15d20","hit_points_roll":"15d20+90","speed":{"walk":"50 ft.","burrow":"30 ft."},"strength":28,"dexterity":7,"constitution":22,"intelligence":1,"wisdom":8,"charisma":4,"proficiencies":[{"value":11,"proficiency":{"index":"saving-throw-con","name":"Saving Throw: CON","url":"/api/2014/proficiencies/saving-throw-con"}},{"value":4,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"blindsight":"30 ft.","tremorsense":"60 ft.","passive_perception":9},"languages":"","challenge_rating":15,"proficiency_bonus":5,"xp":13000,"special_abilities":[{"name":"Tunneler","desc":"The worm can burrow through solid rock at half its burrow speed and leaves a 10-foot-diameter tunnel in its wake."}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The worm makes two attacks: one with its bite and one with its stinger.","actions":[{"action_name":"Bite","count":1,"type":"melee"},{"action_name":"Tail Stinger","count":1,"type":"melee"}]},{"name":"Bite","desc":"Melee Weapon Attack: +9 to hit, reach 10 ft., one target. Hit: 22 (3d8 + 9) piercing damage. If the target is a Large or smaller creature, it must succeed on a DC 19 Dexterity saving throw or be swallowed by the worm. A swallowed creature is blinded and restrained, it has total cover against attacks and other effects outside the worm, and it takes 21 (6d6) acid damage at the start of each of the worm''s turns.\nIf the worm takes 30 damage or more on a single turn from a creature inside it, the worm must succeed on a DC 21 Constitution saving throw at the end of that turn or regurgitate all swallowed creatures, which fall prone in a space within 10 feet of the worm. If the worm dies, a swallowed creature is no longer restrained by it and can escape from the corpse by using 20 feet of movement, exiting prone.","attack_bonus":9,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"3d8+9"}]},{"name":"Tail Stinger","desc":"Melee Weapon Attack: +9 to hit, reach 10 ft., one creature. Hit: 19 (3d6 + 9) piercing damage, and the target must make a DC 19 Constitution saving throw, taking 42 (12d6) poison damage on a failed save, or half as much damage on a successful one.","attack_bonus":9,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"3d6+9"}]}],"image":"/api/images/monsters/purple-worm.png","url":"/api/2014/monsters/purple-worm"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Quasit","desc":null}'::jsonb, '{"index":"quasit","name":"Quasit","size":"Tiny","type":"fiend","subtype":"demon","alignment":"chaotic evil","armor_class":[{"type":"dex","value":13}],"hit_points":7,"hit_dice":"3d4","hit_points_roll":"3d4","speed":{"walk":"40 ft."},"strength":5,"dexterity":17,"constitution":10,"intelligence":7,"wisdom":10,"charisma":10,"proficiencies":[{"value":5,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":["cold","fire","lightning","bludgeoning, piercing, and slashing from nonmagical weapons"],"damage_immunities":["poison"],"condition_immunities":[{"index":"poisoned","name":"Poisoned","url":"/api/2014/conditions/poisoned"}],"senses":{"darkvision":"120 ft.","passive_perception":10},"languages":"Abyssal, Common","challenge_rating":1,"proficiency_bonus":2,"xp":200,"special_abilities":[{"name":"Shapechanger","desc":"The quasit can use its action to polymorph into a beast form that resembles a bat (speed 10 ft. fly 40 ft.), a centipede (40 ft., climb 40 ft.), or a toad (40 ft., swim 40 ft.), or back into its true form . Its statistics are the same in each form, except for the speed changes noted. Any equipment it is wearing or carrying isn''t transformed . It reverts to its true form if it dies."},{"name":"Magic Resistance","desc":"The quasit has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Claw (Bite in Beast Form)","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 5 (1d4 + 3) piercing damage, and the target must succeed on a DC 10 Constitution saving throw or take 5 (2d4) poison damage and become poisoned for 1 minute. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","attack_bonus":4,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d4+3"}]},{"name":"Scare","desc":"One creature of the quasit''s choice within 20 ft. of it must succeed on a DC 10 Wisdom saving throw or be frightened for 1 minute. The target can repeat the saving throw at the end of each of its turns, with disadvantage if the quasit is within line of sight, ending the effect on itself on a success.","usage":{"type":"per day","times":1},"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_value":10,"success_type":"none"}},{"name":"Invisibility","desc":"The quasit magically turns invisible until it attacks or uses Scare, or until its concentration ends (as if concentrating on a spell). Any equipment the quasit wears or carries is invisible with it."}],"image":"/api/images/monsters/quasit.png","url":"/api/2014/monsters/quasit"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Quipper","desc":"A quipper is a carnivorous fish with sharp teeth. Quippers can adapt to any aquatic environment, including cold subterranean lakes. They frequently gather in swarms; the statistics for a swarm of quippers appear later in this appendix."}'::jsonb, '{"index":"quipper","name":"Quipper","desc":"A quipper is a carnivorous fish with sharp teeth. Quippers can adapt to any aquatic environment, including cold subterranean lakes. They frequently gather in swarms; the statistics for a swarm of quippers appear later in this appendix.","size":"Tiny","type":"beast","alignment":"unaligned","armor_class":[{"type":"dex","value":13}],"hit_points":1,"hit_dice":"1d4","hit_points_roll":"1d4-1","speed":{"swim":"40 ft."},"strength":2,"dexterity":16,"constitution":9,"intelligence":1,"wisdom":7,"charisma":2,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"60 ft.","passive_perception":8},"languages":"","challenge_rating":0,"proficiency_bonus":2,"xp":10,"special_abilities":[{"name":"Blood Frenzy","desc":"The quipper has advantage on melee attack rolls against any creature that doesn''t have all its hit points."},{"name":"Water Breathing","desc":"The quipper can breathe only underwater."}],"actions":[{"name":"Bite","desc":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 1 piercing damage.","attack_bonus":5,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1"}]}],"image":"/api/images/monsters/quipper.png","url":"/api/2014/monsters/quipper"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Rakshasa","desc":null}'::jsonb, '{"index":"rakshasa","name":"Rakshasa","size":"Medium","type":"fiend","alignment":"lawful evil","armor_class":[{"type":"natural","value":16}],"hit_dice":"13d8","hit_points":110,"hit_points_roll":"13d8+52","speed":{"walk":"40 ft."},"strength":14,"dexterity":17,"constitution":18,"intelligence":13,"wisdom":16,"charisma":20,"proficiencies":[{"value":10,"proficiency":{"index":"skill-deception","name":"Skill: Deception","url":"/api/2014/proficiencies/skill-deception"}},{"value":8,"proficiency":{"index":"skill-insight","name":"Skill: Insight","url":"/api/2014/proficiencies/skill-insight"}}],"damage_vulnerabilities":["piercing from magic weapons wielded by good creatures"],"damage_resistances":[],"damage_immunities":["bludgeoning, piercing, and slashing from nonmagical weapons"],"condition_immunities":[],"senses":{"darkvision":"60 ft.","passive_perception":13},"languages":"Common, Infernal","challenge_rating":13,"proficiency_bonus":5,"xp":10000,"special_abilities":[{"name":"Limited Magic Immunity","desc":"The rakshasa can''t be affected or detected by spells of 6th level or lower unless it wishes to be. It has advantage on saving throws against all other spells and magical effects."},{"name":"Innate Spellcasting","desc":"The rakshasa''s innate spellcasting ability is Charisma (spell save DC 18, +10 to hit with spell attacks). The rakshasa can innately cast the following spells, requiring no material components:\n\nAt will: detect thoughts, disguise self, mage hand, minor illusion\n3/day each: charm person, detect magic, invisibility, major image, suggestion\n1/day each: dominate person, fly, plane shift, true seeing","spellcasting":{"ability":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"dc":18,"modifier":10,"components_required":["V","S"],"spells":[{"name":"Detect Thoughts","level":2,"url":"/api/2014/spells/detect-thoughts","usage":{"type":"at will"}},{"nam