  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Red Dragon Wyrmling","desc":null}'::jsonb, '{"index":"red-dragon-wyrmling","name":"Red Dragon Wyrmling","size":"Medium","type":"dragon","alignment":"chaotic evil","armor_class":[{"type":"natural","value":17}],"hit_points":75,"hit_dice":"10d8","hit_points_roll":"10d8+30","speed":{"walk":"30 ft.","climb":"30 ft.","fly":"60 ft."},"strength":19,"dexterity":10,"constitution":17,"intelligence":12,"wisdom":11,"charisma":15,"proficiencies":[{"value":2,"proficiency":{"index":"saving-throw-dex","name":"Saving Throw: DEX","url":"/api/2014/proficiencies/saving-throw-dex"}},{"value":5,"proficiency":{"index":"saving-throw-con","name":"Saving Throw: CON","url":"/api/2014/proficiencies/saving-throw-con"}},{"value":2,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}},{"value":4,"proficiency":{"index":"saving-throw-cha","name":"Saving Throw: CHA","url":"/api/2014/proficiencies/saving-throw-cha"}},{"value":4,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"value":2,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":["fire"],"condition_immunities":[],"senses":{"blindsight":"10 ft.","darkvision":"60 ft.","passive_perception":14},"languages":"Draconic","challenge_rating":4,"proficiency_bonus":2,"xp":1100,"actions":[{"name":"Bite","desc":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 9 (1d10 + 4) piercing damage plus 3 (1d6) fire damage.","attack_bonus":6,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d10+4"},{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_dice":"1d6"}]},{"name":"Fire Breath","desc":"The dragon exhales fire in a 15-foot cone. Each creature in that area must make a DC 13 Dexterity saving throw, taking 24 (7d6) fire damage on a failed save, or half as much damage on a successful one.","usage":{"type":"recharge on roll","dice":"1d6","min_value":5},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_value":13,"success_type":"half"},"damage":[{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_dice":"7d6"}]}],"image":"/api/images/monsters/red-dragon-wyrmling.png","url":"/api/2014/monsters/red-dragon-wyrmling"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Reef Shark","desc":"Smaller than giant sharks and hunter sharks, reef sharks inhabit shallow waters and coral reefs, gathering in small packs to hunt. A full-grown specimen measures 6 to 10 feet long."}'::jsonb, '{"index":"reef-shark","name":"Reef Shark","desc":"Smaller than giant sharks and hunter sharks, reef sharks inhabit shallow waters and coral reefs, gathering in small packs to hunt. A full-grown specimen measures 6 to 10 feet long.","size":"Medium","type":"beast","alignment":"unaligned","armor_class":[{"type":"natural","value":12}],"hit_points":22,"hit_dice":"4d8","hit_points_roll":"4d8+4","speed":{"swim":"40 ft."},"strength":14,"dexterity":13,"constitution":13,"intelligence":1,"wisdom":10,"charisma":4,"proficiencies":[{"value":2,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"blindsight":"30 ft.","passive_perception":12},"languages":"","challenge_rating":0.5,"proficiency_bonus":2,"xp":100,"special_abilities":[{"name":"Pack Tactics","desc":"The shark has advantage on an attack roll against a creature if at least one of the shark''s allies is within 5 ft. of the creature and the ally isn''t incapacitated."},{"name":"Water Breathing","desc":"The shark can breathe only underwater."}],"actions":[{"name":"Bite","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 6 (1d8 + 2) piercing damage.","attack_bonus":4,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d8+2"}]}],"image":"/api/images/monsters/reef-shark.png","url":"/api/2014/monsters/reef-shark"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Remorhaz","desc":null}'::jsonb, '{"index":"remorhaz","name":"Remorhaz","size":"Huge","type":"monstrosity","alignment":"unaligned","armor_class":[{"type":"natural","value":17}],"hit_points":195,"hit_dice":"17d12","hit_points_roll":"17d12+85","speed":{"walk":"30 ft.","burrow":"20 ft."},"strength":24,"dexterity":13,"constitution":21,"intelligence":4,"wisdom":10,"charisma":5,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":["cold","fire"],"condition_immunities":[],"senses":{"darkvision":"60 ft.","tremorsense":"60 ft.","passive_perception":10},"languages":"","challenge_rating":11,"proficiency_bonus":4,"xp":7200,"special_abilities":[{"name":"Heated Body","desc":"A creature that touches the remorhaz or hits it with a melee attack while within 5 feet of it takes 10 (3d6) fire damage.","damage":[{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_dice":"3d6"}]}],"actions":[{"name":"Bite","desc":"Melee Weapon Attack: +11 to hit, reach 10 ft., one target. Hit: 40 (6d10 + 7) piercing damage plus 10 (3d6) fire damage. If the target is a creature, it is grappled (escape DC 17). Until this grapple ends, the target is restrained, and the remorhaz can''t bite another target.","attack_bonus":11,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"6d10+7"},{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_dice":"3d6"}]},{"name":"Swallow","desc":"The remorhaz makes one bite attack against a Medium or smaller creature it is grappling. If the attack hits, that creature takes the bite''s damage and is swallowed, and the grapple ends. While swallowed, the creature is blinded and restrained, it has total cover against attacks and other effects outside the remorhaz, and it takes 21 (6d6) acid damage at the start of each of the remorhaz''s turns.\nIf the remorhaz takes 30 damage or more on a single turn from a creature inside it, the remorhaz must succeed on a DC 15 Constitution saving throw at the end of that turn or regurgitate all swallowed creatures, which fall prone in a space within 10 feet of the remorhaz. If the remorhaz dies, a swallowed creature is no longer restrained by it and can escape from the corpse using 15 feet of movement, exiting prone."}],"image":"/api/images/monsters/remorhaz.png","url":"/api/2014/monsters/remorhaz"}'::jsonb),
