  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Shadow","desc":null}'::jsonb, '{"index":"shadow","name":"Shadow","size":"Medium","type":"undead","alignment":"chaotic evil","armor_class":[{"type":"dex","value":12}],"hit_points":16,"hit_dice":"3d8","hit_points_roll":"3d8+3","speed":{"walk":"40 ft."},"strength":6,"dexterity":14,"constitution":13,"intelligence":6,"wisdom":10,"charisma":8,"proficiencies":[{"value":4,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":["radiant"],"damage_resistances":["acid","cold","fire","lightning","thunder","bludgeoning, piercing, and slashing from nonmagical weapons"],"damage_immunities":["necrotic","poison"],"condition_immunities":[{"index":"exhaustion","name":"Exhaustion","url":"/api/2014/conditions/exhaustion"},{"index":"frightened","name":"Frightened","url":"/api/2014/conditions/frightened"},{"index":"grappled","name":"Grappled","url":"/api/2014/conditions/grappled"},{"index":"paralyzed","name":"Paralyzed","url":"/api/2014/conditions/paralyzed"},{"index":"petrified","name":"Petrified","url":"/api/2014/conditions/petrified"},{"index":"poisoned","name":"Poisoned","url":"/api/2014/conditions/poisoned"},{"index":"prone","name":"Prone","url":"/api/2014/conditions/prone"},{"index":"restrained","name":"Restrained","url":"/api/2014/conditions/restrained"}],"senses":{"darkvision":"60 ft.","passive_perception":10},"languages":"","challenge_rating":0.5,"proficiency_bonus":2,"xp":100,"special_abilities":[{"name":"Amorphous","desc":"The shadow can move through a space as narrow as 1 inch wide without squeezing."},{"name":"Shadow Stealth","desc":"While in dim light or darkness, the shadow can take the Hide action as a bonus action. Its stealth bonus is also improved to +6."},{"name":"Sunlight Weakness","desc":"While in sunlight, the shadow has disadvantage on attack rolls, ability checks, and saving throws."}],"actions":[{"name":"Strength Drain","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 9 (2d6 + 2) necrotic damage, and the target''s Strength score is reduced by 1d4. The target dies if this reduces its Strength to 0. Otherwise, the reduction lasts until the target finishes a short or long rest.\nIf a non-evil humanoid dies from this attack, a new shadow rises from the corpse 1d4 hours later.","attack_bonus":4,"damage":[{"damage_type":{"index":"necrotic","name":"Necrotic","url":"/api/2014/damage-types/necrotic"},"damage_dice":"2d6+2"}]}],"image":"/api/images/monsters/shadow.png","url":"/api/2014/monsters/shadow"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Shambling Mound","desc":null}'::jsonb, '{"index":"shambling-mound","name":"Shambling Mound","size":"Large","type":"plant","alignment":"unaligned","armor_class":[{"type":"natural","value":15}],"hit_points":136,"hit_dice":"16d10","hit_points_roll":"16d10+48","speed":{"walk":"20 ft.","swim":"20 ft."},"strength":18,"dexterity":8,"constitution":16,"intelligence":5,"wisdom":10,"charisma":5,"proficiencies":[{"value":2,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":["cold","fire"],"damage_immunities":["lightning"],"condition_immunities":[{"index":"blinded","name":"Blinded","url":"/api/2014/conditions/blinded"},{"index":"blinded","name":"Blinded","url":"/api/2014/conditions/blinded"},{"index":"exhaustion","name":"Exhaustion","url":"/api/2014/conditions/exhaustion"}],"senses":{"blindsight":"60 ft. (blind beyond this radius)","passive_perception":10},"languages":"","challenge_rating":5,"proficiency_bonus":3,"xp":1800,"special_abilities":[{"name":"Lightning Absorption","desc":"Whenever the shambling mound is subjected to lightning damage, it takes no damage and regains a number of hit points equal to the lightning damage dealt."}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The shambling mound makes two slam attacks. If both attacks hit a Medium or smaller target, the target is grappled (escape DC 14), and the shambling mound uses its Engulf on it.","actions":[{"action_name":"Slam","count":2,"type":"melee"},{"action_name":"Engulf","count":1,"type":"melee"}]},{"name":"Slam","desc":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 13 (2d8 + 4) bludgeoning damage.","attack_bonus":7,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"2d8+4"}]},{"name":"Engulf","desc":"The shambling mound engulfs a Medium or smaller creature grappled by it. The engulfed target is blinded, restrained, and unable to breathe, and it must succeed on a DC 14 Constitution saving throw at the start of each of the mound''s turns or take 13 (2d8 + 4) bludgeoning damage. If the mound moves, the engulfed target moves with it. The mound can have only one creature engulfed at a time."}],"image":"/api/images/monsters/shambling-mound.png","url":"/api/2014/monsters/shambling-mound"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Shield Guardian","desc":null}'::jsonb, '{"index":"shield-guardian","name":"Shield Guardian","size":"Large","type":"construct","alignment":"unaligned","armor_class":[{"type":"natural","value":17}],"hit_points":142,"hit_dice":"15d10","hit_points_roll":"15d10+60","speed":{"walk":"30 ft."},"strength":18,"dexterity":8,"constitution":18,"intelligence":7,"wisdom":10,"charisma":3,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":["poison"],"condition_immunities":[{"index":"charmed","name":"Charmed","url":"/api/2014/conditions/charmed"},{"index":"exhaustion","name":"Exhaustion","url":"/api/2014/conditions/exhaustion"},{"index":"frightened","name":"Frightened","url":"/api/2014/conditions/frightened"},{"index":"paralyzed","name":"Paralyzed","url":"/api/2014/conditions/paralyzed"},{"index":"poisoned","name":"Poisoned","url":"/api/2014/conditions/poisoned"}],"senses":{"blindsight":"10 ft.","darkvision":"60 ft.","passive_perception":10},"languages":"understands commands given in any language but can''t speak","challenge_rating":7,"proficiency_bonus":3,"xp":2900,"special_abilities":[{"name":"Bound","desc":"The shield guardian is magically bound to an amulet. As long as the guardian and its amulet are on the same plane of existence, the amulet''s wearer can telepathically call the guardian to travel to it, and the guardian knows the distance and direction to the amulet. If the guardian is within 60 feet of the amulet''s wearer, half of any damage the wearer takes (rounded up) is transferred to the guardian."},{"name":"Regeneration","desc":"The shield guardian regains 10 hit points at the start of its turn if it has at least 1 hit. point."},{"name":"Spell Storing","desc":"A spellcaster who wears the shield guardian''s amulet can cause the guardian to store one spell of 4th level or lower. To do so, the wearer must cast the spell on the guardian. The spell has no effect but is stored within the guardian. When commanded to do so by the wearer or when a situation arises that was predefined by the spellcaster, the guardian casts the stored spell with any parameters set by the original caster, requiring no components. When the spell is cast or a new spell is stored, any previously stored spell is lost."}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The guardian makes two fist attacks.","actions":[{"action_name":"Fist","count":2,"type":"melee"}]},{"name":"Fist","desc":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) bludgeoning damage.","attack_bonus":7,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"2d6+4"}]}],"reactions":[{"name":"Shield","desc":"When a creature makes an attack against the wearer of the guardian''s amulet, the guardian grants a +2 bonus to the wearer''s AC if the guardian is within 5 feet of the wearer."}],"image":"/api/images/monsters/shield-guardian.png","url":"/api/2014/monsters/shield-guardian"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Shrieker","desc":null}'::jsonb, '{"index":"shrieker","name":"Shrieker","size":"Medium","type":"plant","alignment":"unaligned","armor_class":[{"type":"dex","value":5}],"hit_points":13,"hit_dice":"3d8","hit_points_roll":"3d8","speed":{"walk":"0 ft."},"strength":1,"dexterity":1,"constitution":10,"intelligence":1,"wisdom":3,"charisma":1,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[{"index":"blinded","name":"Blinded","url":"/api/2014/conditions/blinded"},{"index":"blinded","name":"Blinded","url":"/api/2014/conditions/blinded"},{"index":"frightened","name":"Frightened","url":"/api/2014/conditions/frightened"}],"senses":{"blindsight":"30 ft. (blind beyond this radius)","passive_perception":6},"languages":"","challenge_rating":0,"proficiency_bonus":2,"xp":10,"special_abilities":[{"name":"False Appearance","desc":"While the shrieker remains motionless, it is indistinguishable from an ordinary fungus."}],"reactions":[{"name":"Shriek","desc":"When bright light or a creature is within 30 feet of the shrieker, it emits a shriek audible within 300 feet of it. The shrieker continues to shriek until the disturbance moves out of range and for 1d4 of the shrieker''s turns afterward"}],"image":"/api/images/monsters/shrieker.png","url":"/api/2014/monsters/shrieker"}'::jsonb),
