  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Steam Mephit","desc":null}'::jsonb, '{"index":"steam-mephit","name":"Steam Mephit","size":"Small","type":"elemental","alignment":"neutral evil","armor_class":[{"type":"dex","value":10}],"hit_points":21,"hit_dice":"6d6","hit_points_roll":"6d6","speed":{"walk":"30 ft.","fly":"30 ft."},"strength":5,"dexterity":11,"constitution":10,"intelligence":11,"wisdom":10,"charisma":12,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":["fire","poison"],"condition_immunities":[{"index":"poisoned","name":"Poisoned","url":"/api/2014/conditions/poisoned"}],"senses":{"darkvision":"60 ft.","passive_perception":10},"languages":"Aquan, Ignan","challenge_rating":0.25,"proficiency_bonus":2,"xp":50,"special_abilities":[{"name":"Death Burst","desc":"When the mephit dies, it explodes in a cloud of steam. Each creature within 5 ft. of the mephit must succeed on a DC 10 Dexterity saving throw or take 4 (1d8) fire damage.","dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_value":10,"success_type":"none"},"damage":[{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_dice":"1d8"}]},{"name":"Innate Spellcasting","desc":"The mephit can innately cast blur, requiring no material components. Its innate spellcasting ability is Charisma.","spellcasting":{"ability":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"dc":11,"components_required":["V","S"],"spells":[{"name":"Blur","level":2,"url":"/api/2014/spells/blur","usage":{"type":"per day","times":1}}]}}],"actions":[{"name":"Claws","desc":"Melee Weapon Attack: +2 to hit, reach 5 ft., one creature. Hit: 2 (1d4) slashing damage plus 2 (1d4) fire damage.","attack_bonus":2,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"1d4"},{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_dice":"1d4"}]},{"name":"Steam Breath","desc":"The mephit exhales a 15-foot cone of scalding steam. Each creature in that area must succeed on a DC 10 Dexterity saving throw, taking 4 (1d8) fire damage on a failed save, or half as much damage on a successful one.","usage":{"type":"recharge on roll","dice":"1d6","min_value":6},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2014/ability-scores/dex"},"dc_value":10,"success_type":"half"},"damage":[{"damage_type":{"index":"fire","name":"Fire","url":"/api/2014/damage-types/fire"},"damage_dice":"1d8"}]}],"image":"/api/images/monsters/steam-mephit.png","url":"/api/2014/monsters/steam-mephit"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Stirge","desc":null}'::jsonb, '{"index":"stirge","name":"Stirge","size":"Tiny","type":"beast","alignment":"unaligned","armor_class":[{"type":"natural","value":14}],"hit_points":2,"hit_dice":"1d4","hit_points_roll":"1d4","speed":{"walk":"10 ft.","fly":"40 ft."},"strength":4,"dexterity":16,"constitution":11,"intelligence":2,"wisdom":8,"charisma":6,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"60 ft.","passive_perception":9},"languages":"","challenge_rating":0.125,"proficiency_bonus":2,"xp":25,"actions":[{"name":"Blood Drain","desc":"Melee Weapon Attack: +5 to hit, reach 5 ft., one creature. Hit: 5 (1d4 + 3) piercing damage, and the stirge attaches to the target. While attached, the stirge doesn''t attack. Instead, at the start of each of the stirge''s turns, the target loses 5 (1d4 + 3) hit points due to blood loss.\nThe stirge can detach itself by spending 5 feet of its movement. It does so after it drains 10 hit points of blood from the target or the target dies. A creature, including the target, can use its action to detach the stirge.","attack_bonus":5,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d4+3"}]}],"image":"/api/images/monsters/stirge.png","url":"/api/2014/monsters/stirge"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Stone Giant","desc":null}'::jsonb, '{"index":"stone-giant","name":"Stone Giant","size":"Huge","type":"giant","alignment":"neutral","armor_class":[{"type":"natural","value":17}],"hit_points":126,"hit_dice":"11d12","hit_points_roll":"11d12+55","speed":{"walk":"40 ft."},"strength":23,"dexterity":15,"constitution":20,"intelligence":10,"wisdom":12,"charisma":9,"proficiencies":[{"value":5,"proficiency":{"index":"saving-throw-dex","name":"Saving Throw: DEX","url":"/api/2014/proficiencies/saving-throw-dex"}},{"value":8,"proficiency":{"index":"saving-throw-con","name":"Saving Throw: CON","url":"/api/2014/proficiencies/saving-throw-con"}},{"value":4,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}},{"value":12,"proficiency":{"index":"skill-athletics","name":"Skill: Athletics","url":"/api/2014/proficiencies/skill-athletics"}},{"value":4,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"60 ft.","passive_perception":14},"languages":"Giant","challenge_rating":7,"proficiency_bonus":3,"xp":2900,"special_abilities":[{"name":"Stone Camouflage","desc":"The giant has advantage on Dexterity (Stealth) checks made to hide in rocky terrain."}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The giant makes two greatclub attacks.","actions":[{"action_name":"Greatclub","count":2,"type":"melee"}]},{"name":"Greatclub","desc":"Melee Weapon Attack: +9 to hit, reach 15 ft., one target. Hit: 19 (3d8 + 6) bludgeoning damage.","attack_bonus":9,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"3d8+6"}]},{"name":"Rock","desc":"Ranged Weapon Attack: +9 to hit, range 60/240 ft., one target. Hit: 28 (4d10 + 6) bludgeoning damage. If the target is a creature, it must succeed on a DC 17 Strength saving throw or be knocked prone.","attack_bonus":9,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"4d10+6"}]}],"reactions":[{"name":"Rock Catching","desc":"If a rock or similar object is hurled at the giant, the giant can, with a successful DC 10 Dexterity saving throw, catch the missile and take no bludgeoning damage from it."}],"image":"/api/images/monsters/stone-giant.png","url":"/api/2014/monsters/stone-giant"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Stone Golem","desc":null}'::jsonb, '{"index":"stone-golem","name":"Stone Golem","size":"Large","type":"construct","alignment":"unaligned","armor_class":[{"type":"natural","value":17}],"hit_points":178,"hit_dice":"17d10","hit_points_roll":"17d10+85","speed":{"walk":"30 ft."},"strength":22,"dexterity":9,"constitution":20,"intelligence":3,"wisdom":11,"charisma":1,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":["poison","psychic","bludgeoning, piercing, and slashing from nonmagical weapons that aren''t adamantine"],"condition_immunities":[{"index":"charmed","name":"Charmed","url":"/api/2014/conditions/charmed"},{"index":"exhaustion","name":"Exhaustion","url":"/api/2014/conditions/exhaustion"},{"index":"frightened","name":"Frightened","url":"/api/2014/conditions/frightened"},{"index":"paralyzed","name":"Paralyzed","url":"/api/2014/conditions/paralyzed"},{"index":"petrified","name":"Petrified","url":"/api/2014/conditions/petrified"},{"index":"poisoned","name":"Poisoned","url":"/api/2014/conditions/poisoned"}],"senses":{"darkvision":"120 ft.","passive_perception":10},"languages":"understands the languages of its creator but can''t speak","challenge_rating":10,"proficiency_bonus":4,"xp":5900,"special_abilities":[{"name":"Immutable Form","desc":"The golem is immune to any spell or effect that would alter its form."},{"name":"Magic Resistance","desc":"The golem has advantage on saving throws against spells and other magical effects."},{"name":"Magic Weapons","desc":"The golem''s weapon attacks are magical."}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The golem makes two slam attacks.","actions":[{"action_name":"Slam","count":2,"type":"melee"}]},{"name":"Slam","desc":"Melee Weapon Attack: +10 to hit, reach 5 ft., one target. Hit: 19 (3d8 + 6) bludgeoning damage.","attack_bonus":10,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"3d8+6"}]},{"name":"Slow","desc":"The golem targets one or more creatures it can see within 10 ft. of it. Each target must make a DC 17 Wisdom saving throw against this magic. On a failed save, a target can''t use reactions, its speed is halved, and it can''t make more than one attack on its turn. In addition, the target can take either an action or a bonus action on its turn, not both. These effects last for 1 minute. A target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.","usage":{"type":"recharge on roll","dice":"1d6","min_value":5},"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_value":17,"success_type":"none"}}],"image":"/api/images/monsters/stone-golem.png","url":"/api/2014/monsters/stone-golem"}'::jsonb),
