  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Tarrasque","desc":null}'::jsonb, '{"index":"tarrasque","name":"Tarrasque","size":"Gargantuan","type":"monstrosity","subtype":"titan","alignment":"unaligned","armor_class":[{"type":"natural","value":25}],"hit_points":676,"hit_dice":"33d20","hit_points_roll":"33d20+330","speed":{"walk":"40 ft."},"strength":30,"dexterity":11,"constitution":30,"intelligence":3,"wisdom":11,"charisma":11,"proficiencies":[{"value":5,"proficiency":{"index":"saving-throw-int","name":"Saving Throw: INT","url":"/api/2014/proficiencies/saving-throw-int"}},{"value":9,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}},{"value":9,"proficiency":{"index":"saving-throw-cha","name":"Saving Throw: CHA","url":"/api/2014/proficiencies/saving-throw-cha"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":["fire","poison","bludgeoning, piercing, and slashing from nonmagical weapons"],"condition_immunities":[{"index":"charmed","name":"Charmed","url":"/api/2014/conditions/charmed"},{"index":"frightened","name":"Frightened","url":"/api/2014/conditions/frightened"},{"index":"paralyzed","name":"Paralyzed","url":"/api/2014/conditions/paralyzed"},{"index":"poisoned","name":"Poisoned","url":"/api/2014/conditions/poisoned"}],"senses":{"blindsight":"120 ft.","passive_perception":10},"languages":"","challenge_rating":30,"proficiency_bonus":9,"xp":155000,"special_abilities":[{"name":"Legendary Resistance","desc":"If the tarrasque fails a saving throw, it can choose to succeed instead.","usage":{"type":"per day","times":3}},{"name":"Magic Resistance","desc":"The tarrasque has advantage on saving throws against spells and other magical effects."},{"name":"Reflective Carapace","desc":"Any time the tarrasque is targeted by a magic missile spell, a line spell, or a spell that requires a ranged attack roll, roll a d6. On a 1 to 5, the tarrasque is unaffected. On a 6, the tarrasque is unaffected, and the effect is reflected back at the caster as though it originated from the tarrasque, turning the caster into the target."},{"name":"Siege Monster","desc":"The tarrasque deals double damage to objects and structures."}],"actions":[{"name":"Multiattack","multiattack_type":"action_options","desc":"The tarrasque can use its Frightful Presence. It then makes five attacks: one with its bite, two with its claws, one with its horns, and one with its tail. It can use its Swallow instead of its bite.","action_options":{"choose":1,"type":"action","from":{"option_set_type":"options_array","options":[{"option_type":"multiple","items":[{"option_type":"action","action_name":"Frightful Presence","count":1,"type":"ability"},{"option_type":"action","action_name":"Bite","count":1,"type":"melee"},{"option_type":"action","action_name":"Claw","count":2,"type":"melee"},{"option_type":"action","action_name":"Horns","count":1,"type":"melee"},{"option_type":"action","action_name":"Tail","count":1,"type":"melee"}]},{"option_type":"multiple","items":[{"option_type":"action","action_name":"Frightful Presence","count":1,"type":"ability"},{"option_type":"action","action_name":"Swallow","desc":"If the target is grappled","count":1,"type":"ability"},{"option_type":"action","action_name":"Claw","count":2,"type":"melee"},{"option_type":"action","action_name":"Horns","count":1,"type":"melee"},{"option_type":"action","action_name":"Tail","count":1,"type":"melee"}]}]}}},{"name":"Bite","desc":"Melee Weapon Attack: +19 to hit, reach 10 ft., one target. Hit: 36 (4d12 + 10) piercing damage. If the target is a creature, it is grappled (escape DC 20). Until this grapple ends, the target is restrained, and the tarrasque can''t bite another target.","attack_bonus":19,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"4d12+10"}]},{"name":"Claw","desc":"Melee Weapon Attack: +19 to hit, reach 15 ft., one target. Hit: 28 (4d8 + 10) slashing damage.","attack_bonus":19,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"4d8+10"}]},{"name":"Horns","desc":"Melee Weapon Attack: +19 to hit, reach 10 ft., one target. Hit: 32 (4d10 + 10) piercing damage.","attack_bonus":19,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"4d10+10"}]},{"name":"Tail","desc":"Melee Weapon Attack: +19 to hit, reach 20 ft., one target. Hit: 24 (4d6 + 10) bludgeoning damage. If the target is a creature, it must succeed on a DC 20 Strength saving throw or be knocked prone.","attack_bonus":19,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"4d6+10"}]},{"name":"Frightful Presence","desc":"Each creature of the tarrasque''s choice within 120 feet of it and aware of it must succeed on a DC 17 Wisdom saving throw or become frightened for 1 minute. A creature can repeat the saving throw at the end of each of its turns, with disadvantage if the tarrasque is within line of sight, ending the effect on itself on a success. If a creature''s saving throw is successful or the effect ends for it, the creature is immune to the tarrasque''s Frightful Presence for the next 24 hours.","dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_value":17,"success_type":"none"}},{"name":"Swallow","desc":"The tarrasque makes one bite attack against a Large or smaller creature it is grappling. If the attack hits, the target takes the bite''s damage, the target is swallowed, and the grapple ends. While swallowed, the creature is blinded and restrained, it has total cover against attacks and other effects outside the tarrasque, and it takes 56 (16d6) acid damage at the start of each of the tarrasque''s turns.\nIf the tarrasque takes 60 damage or more on a single turn from a creature inside it, the tarrasque must succeed on a DC 20 Constitution saving throw at the end of that turn or regurgitate all swallowed creatures, which fall prone in a space within 10 feet of the tarrasque. If the tarrasque dies, a swallowed creature is no longer restrained by it and can escape from the corpse by using 30 feet of movement, exiting prone."}],"legendary_actions":[{"name":"Attack","desc":"The tarrasque makes one claw attack or tail attack."},{"name":"Move","desc":"The tarrasque moves up to half its speed."},{"name":"Chomp (Costs 2 Actions)","desc":"The tarrasque makes one bite attack or uses its Swallow."}],"image":"/api/images/monsters/tarrasque.png","url":"/api/2014/monsters/tarrasque"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Thug","desc":"Thugs are ruthless enforcers skilled at intimidation and violence. They work for money and have few scruples."}'::jsonb, '{"index":"thug","name":"Thug","desc":"Thugs are ruthless enforcers skilled at intimidation and violence. They work for money and have few scruples.","size":"Medium","type":"humanoid","subtype":"any race","alignment":"any non-good alignment","armor_class":[{"type":"armor","value":11,"armor":[{"index":"leather-armor","name":"Leather Armor","url":"/api/2014/equipment/leather-armor"}]}],"hit_points":32,"hit_dice":"5d8","hit_points_roll":"5d8+10","speed":{"walk":"30 ft."},"strength":15,"dexterity":11,"constitution":14,"intelligence":10,"wisdom":10,"charisma":11,"proficiencies":[{"value":2,"proficiency":{"index":"skill-intimidation","name":"Skill: Intimidation","url":"/api/2014/proficiencies/skill-intimidation"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":10},"languages":"any one language (usually Common)","challenge_rating":0.5,"proficiency_bonus":2,"xp":100,"special_abilities":[{"name":"Pack Tactics","desc":"The thug has advantage on an attack roll against a creature if at least one of the thug''s allies is within 5 ft. of the creature and the ally isn''t incapacitated."}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The thug makes two melee attacks.","actions":[{"action_name":"Mace","count":2,"type":"melee"}]},{"name":"Mace","desc":"Melee Weapon Attack: +4 to hit, reach 5 ft., one creature. Hit: 5 (1d6 + 2) bludgeoning damage.","attack_bonus":4,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"1d6+2"}]},{"name":"Heavy Crossbow","desc":"Ranged Weapon Attack: +2 to hit, range 100/400 ft., one target. Hit: 5 (1d10) piercing damage.","attack_bonus":2,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d10"}]}],"image":"/api/images/monsters/thug.png","url":"/api/2014/monsters/thug"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Tiger","desc":null}'::jsonb, '{"index":"tiger","name":"Tiger","size":"Large","type":"beast","alignment":"unaligned","armor_class":[{"type":"dex","value":12}],"hit_points":37,"hit_dice":"5d10","hit_points_roll":"5d10+10","speed":{"walk":"40 ft."},"strength":17,"dexterity":15,"constitution":14,"intelligence":3,"wisdom":12,"charisma":8,"proficiencies":[{"value":3,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"value":6,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"60 ft.","passive_perception":13},"languages":"","challenge_rating":1,"proficiency_bonus":2,"xp":200,"special_abilities":[{"name":"Keen Smell","desc":"The tiger has advantage on Wisdom (Perception) checks that rely on smell."},{"name":"Pounce","desc":"If the tiger moves at least 20 ft. straight toward a creature and then hits it with a claw attack on the same turn, that target must succeed on a DC 13 Strength saving throw or be knocked prone. If the target is prone, the tiger can make one bite attack against it as a bonus action.","dc":{"dc_type":{"index":"str","name":"STR","url":"/api/2014/ability-scores/str"},"dc_value":13,"success_type":"none"}}],"actions":[{"name":"Bite","desc":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 8 (1d10 + 3) piercing damage.","attack_bonus":5,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d10+3"}]},{"name":"Claw","desc":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 7 (1d8 + 3) slashing damage.","attack_bonus":5,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"1d8+3"}]}],"image":"/a