  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Treant","desc":null}'::jsonb, '{"index":"treant","name":"Treant","size":"Huge","type":"plant","alignment":"chaotic good","armor_class":[{"type":"natural","value":16}],"hit_points":138,"hit_dice":"12d12","hit_points_roll":"12d12+60","speed":{"walk":"30 ft."},"strength":23,"dexterity":8,"constitution":21,"intelligence":12,"wisdom":16,"charisma":12,"proficiencies":[],"damage_vulnerabilities":["fire"],"damage_resistances":["bludgeoning","piercing"],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":13},"languages":"Common, Druidic, Elvish, Sylvan","challenge_rating":9,"proficiency_bonus":4,"xp":5000,"special_abilities":[{"name":"False Appearance","desc":"While the treant remains motionless, it is indistinguishable from a normal tree."},{"name":"Siege Monster","desc":"The treant deals double damage to objects and structures."}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The treant makes two slam attacks.","actions":[{"action_name":"Slam","count":2,"type":"melee"}]},{"name":"Slam","desc":"Melee Weapon Attack: +10 to hit, reach 5 ft., one target. Hit: 16 (3d6 + 6) bludgeoning damage.","attack_bonus":10,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"3d6+6"}]},{"name":"Rock","desc":"Ranged Weapon Attack: +10 to hit, range 60/180 ft., one target. Hit: 28 (4d10 + 6) bludgeoning damage.","attack_bonus":10,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"4d10+6"}]},{"name":"Animate Trees","desc":"The treant magically animates one or two trees it can see within 60 feet of it. These trees have the same statistics as a treant, except they have Intelligence and Charisma scores of 1, they can''t speak, and they have only the Slam action option. An animated tree acts as an ally of the treant. The tree remains animate for 1 day or until it dies; until the treant dies or is more than 120 feet from the tree; or until the treant takes a bonus action to turn it back into an inanimate tree. The tree then takes root if possible.","usage":{"type":"per day","times":1}}],"image":"/api/images/monsters/treant.png","url":"/api/2014/monsters/treant"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Tribal Warrior","desc":"Tribal warriors live beyond civilization, most often subsisting on fishing and hunting. Each tribe acts in accordance with the wishes of its chief, who is the greatest or oldest warrior of the tribe or a tribe member blessed by the gods."}'::jsonb, '{"index":"tribal-warrior","name":"Tribal Warrior","desc":"Tribal warriors live beyond civilization, most often subsisting on fishing and hunting. Each tribe acts in accordance with the wishes of its chief, who is the greatest or oldest warrior of the tribe or a tribe member blessed by the gods.","size":"Medium","type":"humanoid","subtype":"any race","alignment":"any alignment","armor_class":[{"type":"armor","value":12,"armor":[{"index":"hide-armor","name":"Hide Armor","url":"/api/2014/equipment/hide-armor"}]}],"hit_points":11,"hit_dice":"2d8","hit_points_roll":"2d8+2","speed":{"walk":"30 ft."},"strength":13,"dexterity":11,"constitution":12,"intelligence":8,"wisdom":11,"charisma":8,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":10},"languages":"any one language","challenge_rating":0.125,"proficiency_bonus":2,"xp":25,"special_abilities":[{"name":"Pack Tactics","desc":"The warrior has advantage on an attack roll against a creature if at least one of the warrior''s allies is within 5 ft. of the creature and the ally isn''t incapacitated."}],"actions":[{"name":"Spear","desc":"Melee or Ranged Weapon Attack: +3 to hit, reach 5 ft. or range 20/60 ft., one target. Hit: 4 (1d6 + 1) piercing damage, or 5 (1d8 + 1) piercing damage if used with two hands to make a melee attack.","attack_bonus":3,"damage":[{"choose":1,"type":"damage","from":{"option_set_type":"options_array","options":[{"option_type":"damage","notes":"One handed","damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d6+1"},{