  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Triceratops","desc":null}'::jsonb, '{"index":"triceratops","name":"Triceratops","size":"Huge","type":"beast","alignment":"unaligned","armor_class":[{"type":"natural","value":13}],"hit_points":95,"hit_dice":"10d12","hit_points_roll":"10d12+30","speed":{"walk":"50 ft."},"strength":22,"dexterity":9,"constitution":17,"intelligence":2,"wisdom":11,"charisma":5,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":10},"languages":"","challenge_rating":5,"proficiency_bonus":3,"xp":1800,"special_abilities":[{"name":"Trampling Charge","desc":"If the triceratops moves at least 20 ft. straight toward a creature and then hits it with a gore attack on the same turn, that target must succeed on a DC 13 Strength saving throw or be knocked prone. If the target is prone, the triceratops can make one stomp attack against it as a bonus action."}],"actions":[{"name":"Gore","desc":"Melee Weapon Attack: +9 to hit, reach 5 ft., one target. Hit: 24 (4d8 + 6) piercing damage.","attack_bonus":9,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"4d8+6"}]},{"name":"Stomp","desc":"Melee Weapon Attack: +9 to hit, reach 5 ft., one prone creature. Hit: 22 (3d10 + 6) bludgeoning damage","attack_bonus":9,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"3d10+6"}]}],"image":"/api/images/monsters/triceratops.png","url":"/api/2014/monsters/triceratops"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Troll","desc":null}'::jsonb, '{"index":"troll","name":"Troll","size":"Large","type":"giant","alignment":"chaotic evil","armor_class":[{"type":"natural","value":15}],"hit_points":84,"hit_dice":"8d10","hit_points_roll":"8d10+40","speed":{"walk":"30 ft."},"strength":18,"dexterity":13,"constitution":20,"intelligence":7,"wisdom":9,"charisma":7,"proficiencies":[{"value":2,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"60 ft.","passive_perception":12},"languages":"Giant","challenge_rating":5,"proficiency_bonus":3,"xp":1800,"special_abilities":[{"name":"Keen Smell","desc":"The troll has advantage on Wisdom (Perception) checks that rely on smell."},{"name":"Regeneration","desc":"The troll regains 10 hit points at the start of its turn. If the troll takes acid or fire damage, this trait doesn''t function at the start of the troll''s next turn. The troll dies only if it starts its turn with 0 hit points and doesn''t regenerate."}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The troll makes three attacks: one with its bite and two with its claws.","actions":[{"action_name":"Bite","count":1,"type":"melee"},{"action_name":"Claw","count":2,"type":"melee"}]},{"name":"Bite","desc":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 7 (1d6 + 4) piercing damage.","attack_bonus":7,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d6+4"}]},{"name":"Claw","desc":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) slashing damage.","attack_bonus":7,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"2d6+4"}]}],"image":"/api/images/monsters/troll.png","url":"/api/2014/monsters/troll"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Tyrannosaurus Rex","desc":null}'::jsonb, '{"index":"tyrannosaurus-rex","name":"Tyrannosaurus Rex","size":"Huge","type":"beast","alignment":"unaligned","armor_class":[{"type":"natural","value":13}],"hit_points":136,"hit_dice":"13d12","hit_points_roll":"13d12+52","speed":{"walk":"50 ft."},"strength":25,"dexterity":10,"constitution":19,"intelligence":2,"wisdom":12,"charisma":9,"proficiencies":[{"value":4,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"passive_perception":14},"languages":"","challenge_rating":8,"proficiency_bonus":3,"xp":3900,"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The tyrannosaurus makes two attacks: one with its bite and one with its tail. It can''t make both attacks against the same target.","actions":[{"action_name":"Bite","count":1,"type":"melee"},{"action_name":"Tail","count":1,"type":"melee"}]},{"name":"Bite","desc":"Melee Weapon Attack: +10 to hit, reach 10 ft., one target. Hit: 33 (4d12 + 7) piercing damage. If the target is a Medium or smaller creature, it is grappled (escape DC 17). Until this grapple ends, the target is restrained, and the tyrannosaurus can''t bite another target.","attack_bonus":10,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"4d12+7"}]},{"name":"Tail","desc":"Melee Weapon Attack: +10 to hit, reach 10 ft., one target. Hit: 20 (3d8 + 7) bludgeoning damage.","attack_bonus":10,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"3d8+7"}]}],"image":"/api/images/monsters/tyrannosaurus-rex.png","url":"/api/2014/monsters/tyrannosaurus-rex"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Unicorn","desc":null}'::jsonb, '{"index":"unicorn","name":"Unicorn","size":"Large","type":"celestial","alignment":"lawful good","armor_class":[{"type":"dex","value":12}],"hit_points":67,"hit_dice":"9d10","hit_points_roll":"9d10+18","speed":{"walk":"50 ft."},"strength":18,"dexterity":14,"constitution":15,"intelligence":11,"wisdom":17,"charisma":16,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":["poison"],"condition_immunities":[{"index":"charmed","name":"Charmed","url":"/api/2014/conditions/charmed"},{"index":"paralyzed","name":"Paralyzed","url":"/api/2014/conditions/paralyzed"},{"index":"poisoned","name":"Poisoned","url":"/api/2014/conditions/poisoned"}],"senses":{"darkvision":"60 ft.","passive_perception":13},"languages":"Celestial, Elvish, Sylvan, telepathy 60 ft.","challenge_rating":5,"proficiency_bonus":3,"xp":1800,"special_abilities":[{"name":"Charge","desc":"If the unicorn moves at least 20 ft. straight toward a target and then hits it with a horn attack on the same turn, the target takes an extra 9 (2d8) piercing damage. If the target is a creature, it must succeed on a DC 15 Strength saving throw or be knocked prone."},{"name":"Innate Spellcasting","desc":"The unicorn''s innate spellcasting ability is Charisma (spell save DC 14). The unicorn can innately cast the following spells, requiring no components:\n\nAt will: detect evil and good, druidcraft, pass without trace\n1/day each: calm emotions, dispel evil and good, entangle","spellcasting":{"ability":{"index":"cha","name":"CHA","url":"/api/2014/ability-scores/cha"},"dc":14,"components_required":[],"spells":[{"name":"Detect Evil and Good","level":1,"url":"/api/2014/spells/detect-evil-and-good","usage":{"type":"at will"}},{"name":"Druidcraft","level":0,"url":"/api/2014/spells/druidcraft","usage":{"type":"at will"}},{"name":"Pass Without Trace","level":2,"url":"/api/2014/spells/pass-without-trace","usage":{"type":"at will"}},{"name":"Calm Emotions","level":2,"url":"/api/2014/spells/calm-emotions","usage":{"type":"per day","times":1}},{"name":"Dispel Evil and Good","level":5,"url":"/api/2014/spells/dispel-evil-and-good","usage":{"type":"per day","times":1}},{"name":"Entangle","level":1,"url":"/api/2014/spells/entangle","usage":{"type":"per day","times":1}}]}},{"name":"Magic Resistance","desc":"The unicorn has advantage on saving throws against spells and other magical effects."},{"name":"Magic Weapons","desc":"The unicorn''s weapon attacks are magical."}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The unicorn makes two attacks: one with its hooves and one with its horn.","actions":[{"action_name":"Hooves","count":1,"type":"melee"},{"action_name":"Horn","count":1,"type":"melee"}]},{"name":"Hooves","desc":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) bludgeoning damage.","attack_bonus":7,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"2d6+4"}]},{"name":"Horn","desc":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 8 (1d8 + 4) piercing damage.","attack_bonus":7,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d8+4"}]},{"name":"Healing Touch","desc":"The unicorn touches another creature with its horn. The target magically regains 11 (2d8 + 2) hit points. In addition, the touch removes all diseases and neutralizes all poisons afflicting the target.","usage":{"type":"per day","times":3}},{"name":"Teleport","desc":"The unicorn magically teleports itself and up to three willing creatures it can see within 5 ft. of it, along with any equipment they are wearing or carrying, to a location the unicorn is familiar with, up to 1 mile away.","usage":{"type":"per day","times":1}}],"legendary_actions":[{"name":"Hooves","desc":"The unicorn makes one attack with its hooves."},{"name":"Shimmering Shield (Costs 2 Actions)","desc":"The unicorn creates a shimmering, magical field around itself or another creature it can see within 60 ft. of it. The target gains a +2 bonus to AC until the end of the unicorn''s next turn."},{"name":"Heal Self (Costs 3 Actions)","desc":"The unicorn magically regains 11 (2d8 + 2) hit points."}],"image":"/api/images/monsters/unicorn.png","url":"/api/2014/monsters/unicorn"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Vampire, Vampire Form","desc":null}'::jsonb, '{"index":"vampire-vampire","name":"Vampire, Vampire Form","size":"Medium","type":"undead","subtype":"shapechanger","alignment":"lawful evil","armor_class":[{"type":"natural","value":16}],"hit_points":144,"hit_dice":"17d8","hit_points_roll":"17d8+68","speed":{"walk":"30 ft."},"forms":[{"index":"vampire-bat","name":"Vampire, Bat Form","url":"/api/2014/monsters/vampire-bat"},{"index":"vampire-mist","name":"Vampire, Mist Form","url":"/api/2014/monsters/vampire-mist"}],"strength":18,"dexterity":18,"constitution":18,"intelligence":17,"wisdom":15,"charisma":18,"proficiencies":[{"value":9,"proficiency":{"index":"saving-throw-dex","name":"Saving Throw: DEX","url":"/api/2014/proficiencies/saving-throw-dex"}},{"value":7,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}},{"value":9,"proficiency":{"index":"saving-throw-cha","name":"Saving Throw: CHA","url":"/api/2014/proficiencies/saving-throw-cha"}},{"value":7,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}},{"value":9,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2014/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":["necrotic","bludgeoning, piercing, and slashing from nonmagical weapons"],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"120 ft.","passive_perception":17},"languages":"the languages it knew in life","challenge_rating":13,"proficiency_bonus":5,"xp":10000,"special_abilities":[{"name":"Shapechanger","desc":"If the vampire isn''t in sun light or running water, it can use its action to polymorph into a Tiny bat or a Medium cloud of mist, or back into its true form.\nWhile in bat form, the vampire can''t speak, its walking speed is 5 feet, and it has a flying speed of 30 feet. Its statistics, other than its size and speed, are unchanged. Anything it is wearing transforms with it, but nothing it is carrying does. It reverts to its true form if it dies.\nWhile in mist form, the vampire can''t take any actions, speak, or manipulate objects. It is weightless, has a flying speed of 20 feet, can hover, and can enter a hostile creature''s space and stop there. In addition, if air can pass through a space, the mist can do so without squeezing, and it can''t pass through water. It has advantage on Strength, Dexterity, and Constitution saving throws, and it is immune to all nonmagical damage, except the damage it takes from sunlight."},{"name":"Legendary Resistance","desc":"If the vampire fails a saving throw, it can choose to succeed instead.","usage":{"type":"per day","times":3}},{"name":"Misty Escape","desc":"When it drops to 0 hit points outside its resting place, the vampire transforms into a cloud of mist (as in the Shapechanger trait) instead of falling unconscious, provided that it isn''t in sunlight or running water. If it can''t transform, it is destroyed.\nWhile it has 0 hit points in mist form, it can''t revert to its vampire form, and it must reach its resting place within 2 hours or be destroyed. Once in its resting place, it reverts to its vampire form. It is then paralyzed until it regains at least 1 hit point. After spending 1 hour in its resting place with 0 hit points, it regains 1 hit point."},{"name":"Regeneration","desc":"The vampire regains 20 hit points at the start of its turn if it has at least 1 hit point and isn''t in sunlight or running water. If the vampire takes radiant damage or damage from holy water, this trait doesn''t function at the start of the vampire''s next turn."},{"name":"Spider Climb","desc":"The vampire can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."},{"name":"Vampire Weaknesses","desc":"The vampire has the following flaws:\nForbiddance. The vampire can''t enter a residence without an invitation from one of the occupants.\nHarmed by Running Water. The vampire takes 20 acid damage if it ends its turn in running water.\nStake to the Heart. If a piercing weapon made of wood is driven into the vampire''s heart while the vampire is incapacitated in its resting place, the vampire is paralyzed until the stake is removed.\nSunlight Hypersensitivity. The vampire takes 20 radiant damage when it starts its turn in sunlight. While in sunlight, it has disadvantage on attack rolls and ability checks."}],"actions":[{"name":"Multiattack","multiattack_type":"action_options","desc":"The vampire makes two attacks, only one of which can be a bite attack.","action_options":{"choose":1,"type":"action","from":{"option_set_type":"options_array","options":[{"option_type":"multiple","items":[{"option_type":"action","action_name":"Unarmed Strike (Vampire Form Only)","count":1,"type":"melee"},{"option_type":"action","action_name":"Bite (Bat or Vampire Form Only)","count":1,"type":"melee"}]},{"option_type":"action","action_name":"Unarmed Strike (Vampire Form Only)","count":2,"type":"melee"}]}}},{"name":"Unarmed Strike","desc":"Melee Weapon Attack: +9 to hit, reach 5 ft., one creature. Hit: 8 (1d8 + 4) bludgeoning damage. Instead of dealing damage, the vampire can grapple the target (escape DC 18).","attack_bonus":9,"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2014/damage-types/bludgeoning"},"damage_dice":"1d8+4"}]},{"name":"Bite","desc":"Melee Weapon Attack: +9 to hit, reach 5 ft., one willing creature, or a creature that is grappled by the vampire, incapacitated, or restrained. Hit: 7 (1d6 + 4) piercing damage plus 10 (3d6) necrotic damage. The target''s hit point maximum is reduced by an amount equal to the necrotic damage taken, and the vampire regains hit points equal to that amount. The reduction lasts until the target finishes a long rest. The target dies if this effect reduces its hit point maximum to 0. A humanoid slain in this way and then buried in the ground rises the following night as a vampire spawn under the vampire''s control.","attack_bonus":9,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"1d6+4"},{"damage_type":{"index":"necrotic","name":"Necrotic","url":"/api/2014/damage-types/necrotic"},"damage_dice":"3d6"}]},{"name":"Charm","desc":"The vampire targets one humanoid it can see within 30 ft. of it. If the target can see the vampire, the target must succeed on a DC 17 Wisdom saving throw against this magic or be charmed by the vampire. The charmed target regards the vampire as a trusted friend to be heeded and protected. Although the target isn''t under the vampire''s control, it takes the vampire''s requests or actions in the most favorable way it can, and it is a willing target for the vampire''s bit attack.\nEach time the vampire or the vampire''s companions do anything harmful to the target, it can repeat the saving throw, ending the effect on itself on a success. Otherwise, the effect lasts 24 hours or until the vampire is destroyed, is on a different plane of existence than the target, or takes a bonus action to end the effect.","dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2014/ability-scores/wis"},"dc_value":17,"success_type":"none"}},{"name":"Children of the Night","desc":"The vampire magically calls 2d4 swarms of bats or rats, provided that the sun isn''t up. While outdoors, the vampire can call 3d6 wolves instead. The called creatures arrive in 1d4 rounds, acting as allies of the vampire and obeying its spoken commands. The beasts remain for 1 hour, until the vampire dies, or until the vampire dismisses them as a bonus action.","usage":{"type":"per day","times":1}}],"legendary_actions":[{"name":"Move","desc":"The vampire moves up to its speed without provoking opportunity attacks.","attack_bonus":0},{"name":"Unarmed Strike","desc":"The vampire makes one unarmed strike.","attack_bonus":0},{"name":"Bite (Costs 2 Actions)","desc":"The vampire makes one bite attack.","attack_bonus":0}],"image":"/api/images/monsters/vampire-vampire.png","url":"/api/2014/monsters/vampire-vampire"}'::jsonb),
