  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Vrock","desc":null}'::jsonb, '{"index":"vrock","name":"Vrock","size":"Large","type":"fiend","subtype":"demon","alignment":"chaotic evil","armor_class":[{"type":"natural","value":15}],"hit_points":104,"hit_dice":"11d10","hit_points_roll":"11d10+44","speed":{"walk":"40 ft.","fly":"60 ft."},"strength":17,"dexterity":15,"constitution":18,"intelligence":8,"wisdom":13,"charisma":8,"proficiencies":[{"value":5,"proficiency":{"index":"saving-throw-dex","name":"Saving Throw: DEX","url":"/api/2014/proficiencies/saving-throw-dex"}},{"value":4,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2014/proficiencies/saving-throw-wis"}},{"value":2,"proficiency":{"index":"saving-throw-cha","name":"Saving Throw: CHA","url":"/api/2014/proficiencies/saving-throw-cha"}}],"damage_vulnerabilities":[],"damage_resistances":["cold","fire","lightning","bludgeoning, piercing, and slashing from nonmagical weapons"],"damage_immunities":["poison"],"condition_immunities":[{"index":"poisoned","name":"Poisoned","url":"/api/2014/conditions/poisoned"}],"senses":{"darkvision":"120 ft.","passive_perception":11},"languages":"Abyssal, telepathy 120 ft.","challenge_rating":6,"proficiency_bonus":3,"xp":2300,"special_abilities":[{"name":"Magic Resistance","desc":"The vrock has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The vrock makes two attacks: one with its beak and one with its talons.","actions":[{"action_name":"Beak","count":1,"type":"melee"},{"action_name":"Talons","count":1,"type":"melee"}]},{"name":"Beak","desc":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) piercing damage.","attack_bonus":6,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"2d6+3"}]},{"name":"Talons","desc":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 14 (2d10 + 3) slashing damage.","attack_bonus":6,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2014/damage-types/slashing"},"damage_dice":"2d10+3"}]},{"name":"Spores","desc":"A 15-foot-radius cloud of toxic spores extends out from the vrock. The spores spread around corners. Each creature in that area must succeed on a DC 14 Constitution saving throw or become poisoned. While poisoned in this way, a target takes 5 (1d10) poison damage at the start of each of its turns. A target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. Emptying a vial of holy water on the target also ends the effect on it.","usage":{"type":"recharge on roll","dice":"1d6","min_value":6},"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_value":14,"success_type":"none"}},{"name":"Stunning Screech","desc":"The vrock emits a horrific screech. Each creature within 20 feet of it that can hear it and that isn''t a demon must succeed on a DC 14 Constitution saving throw or be stunned until the end of the vrock''s next turn .","usage":{"type":"per day","times":1},"dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2014/ability-scores/con"},"dc_value":14,"success_type":"none"}}],"image":"/api/images/monsters/vrock.png","url":"/api/2014/monsters/vrock"}'::jsonb),
