  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Water Elemental","desc":null}'::jsonb, '{"index":"water-elemental","name":"Water Elemental","size":"Large","type":"elemental","alignment":"neutral","armor_class":[{"type":"natural","value":14}],"hit_points":114,"hit_dice":"12d10","hit_points_roll":"12d10+48","speed":{"walk":"30 ft.","swim":"90 ft."},"strength":18,"dexterity":14,"constitution":18,"intelligence":5,"wisdom":10,"charisma":8,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":["acid","bludgeoning, piercing, and slashing from nonmagical weapons"],"damage_immunities":["poison"],"condition_immunities":[{"index":"exhaustion","name":"Exhaustion","url":"/api/2014/conditions/exhaustion"},{"index":"grappled","name":"Grappled","url":"/api/2014/conditions/grappled"},{"index":"paralyzed","name":"Paralyzed","url":"/api/2014/conditions/paralyzed"},{"index":"petrified","name":"Petrified","url":"/api/2014/conditions/petrified"},{"index":"poisoned","name":"Poisoned","url":"/api/2014/conditions/poisoned"},{"index":"prone","name":"Prone","url":"/api/2014/conditions/prone"},{"index":"restrained","name":"Restrained","url":"/api/2014/conditions/restrained"},{"index":"unconscious","name":"Unconscious","url":"/api/2014/conditions/unconscious"}],"senses":{"darkvision":"60 ft.","passive_perception":10},"languages":"Aquan","challenge_rating":5,"proficiency_bonus":3,"xp":1800,"special_abilities":[{"name":"Water Form","desc":"The elemental can enter a hostile creature''s space and stop there. It can move through a space as narrow as 1 inch wide without squeezing."},{"name":"Freeze","desc":"If the elemental takes cold damage, it partially freezes; its speed is reduced by 20 ft. until the end of its next turn."}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The elemental makes two slam attacks.","actions":[{"action_name":"Slam","count":2,"type":"melee"}]},{"name":"Slam","desc":"Melee Weapon Attack: +7 to hit, reach 5 ft., one tar