  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Worg","desc":"A worg is an evil predator that delights in hunting and devouring creatures weaker than itself. Cunning and malevolent, worgs roam across the remote wilderness or are raised by goblins and hobgoblins. Those creatures use worgs as mounts, but a worg will turn on its rider if it feels mistreated or malnourished. Worgs speak in their own language and Goblin, and a few learn to speak Common as well."}'::jsonb, '{"index":"worg","name":"Worg","desc":"A worg is an evil predator that delights in hunting and devouring creatures weaker than itself. Cunning and malevolent, worgs roam across the remote wilderness or are raised by goblins and hobgoblins. Those creatures use worgs as mounts, but a worg will turn on its rider if it feels mistreated or malnourished. Worgs speak in their own language and Goblin, and a few learn to speak Common as well.","size":"Large","type":"monstrosity","alignment":"neutral evil","armor_class":[{"type":"natural","value":13}],"hit_points":26,"hit_dice":"4d10","hit_points_roll":"4d10+4","speed":{"walk":"50 ft."},"strength":16,"dexterity":13,"constitution":13,"intelligence":7,"wisdom":11,"charisma":8,"proficiencies":[{"value":4,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2014/proficiencies/skill-perception"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"60 ft.","passive_perception":14},"languages":"Goblin, Worg","challenge_rating":0.5,"proficiency_bonus":2,"xp":100,"special_abilities":[{"name":"Keen Hearing and Smell","desc":"The worg has advantage on Wisdom (Perception) checks that rely on hearing or smell."}],"actions":[{"name":"Bite","desc":"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 10 (2d6 + 3) piercing damage. If the target is a creature, it must succeed on a DC 13 Strength saving throw or be knocked prone.","attack_bonus":5,"damage":[{"damage_type":{"index":"piercing","name":"Piercing","url":"/api/2014/damage-types/piercing"},"damage_dice":"2d6+3"}]}],"image":"/api/images/monsters/worg.png","url":"/api/2014/monsters/worg"}'::jsonb),
  ('8c788102-6d8c-42ab-bd56-31a7cfe3e272', 'monsters', '{"name":"Wraith","desc":null}'::jsonb, '{"index":"wraith","name":"Wraith","size":"Medium","type":"undead","alignment":"neutral evil","armor_class":[{"type":"dex","value":13}],"hit_points":67,"hit_dice":"9d8","hit_points_roll":"9d8+27","speed":{"walk":"0 ft.","fly":"60 ft.","hover":true},"strength":6,"dexterity":16,"constitution":16,"intelligence":12,"wisdom":14,"charisma":15,"proficiencies":[],"damage_vulnerabilities":[],"damage_resistances":["acid","cold","fire","lightning","thunder","bludgeoning, piercing, and slashing from nonmagical weapons that aren''t silvered"],"damage_immunities":["necrotic","poison"],"condition_immunities":[{"index":"charmed","name":"Charmed","url":"/api/2014/conditions/charmed"},{"index":"exhaustion","name":"Exhaustion","url":"/api/2014/conditions/exhaustion"},{"index":"grappled","name":"Grappled","url":"/api/2014/conditions/grappled"},{"index":"paralyzed","name":"Paralyzed","url":"/api/2014/conditions/paralyzed"},{"index":"petrified","name":"Petrified","url":"/api/2014/conditions/petrified"},{"index":"poisoned","name":"Poisoned","url":"/api/2014/conditions/poisoned"},{"index":"prone","name":"Prone","url":"/api/2014/conditions/prone"},{"index":"restrained","name":"Restrained","url":"/api/2014/conditions/restrained"}],"senses":{"darkvision":"60 ft.","passive_perception":12},"languages":"the languages it knew in life","challenge_rating":5,"proficiency_bonus":3,"xp":1800,"special_abilities":[{"name":"Incorporeal Movement","desc":"The wraith can move through other creatures and objects as if they were difficult terrain. It takes 5 (1d10) force damage if it ends its turn inside an object."},{"name":"Sunlight Sensitivity","desc":"While in sunlight, the wraith has disadvantage on attack rolls, as well as on Wisdom (Perception) checks that rely on sight."}],"actions":[{"name":"Life Drain","desc":"Melee Weapon Attack: +6 to hit, reach 5 ft., one creature. Hit: 21 (4d8 + 3) necrotic damage. The target must succeed on a DC 14 Constitution saving throw or its hit point maximum is reduced by an amount equal to the damage taken. This reduction lasts until the target finishes a long rest. The target dies if this effect reduces its hit point maximum to 0.","attack_bonus":6,"damage":[{"damage_type":{"index":"necrotic","name":"Necrotic","url":"/api/2014/damage-types/necrotic"},"damage_dice":"4d8+3"}]},{"name":"Create Specter","desc":"The wraith targets a humanoid within 10 feet of it that has been dead for no longer than 1 minute and died violently. The target''s spirit rises as a specter in the space of its corpse or in the nearest unoccupied space. The specter is under the wraith''s control. The wraith can have no more than seven specters under its control at one time."}],"image":"/api/images/monsters/wraith.png","url":"/api/2014/monsters/wraith"}'::jsonb),
