  ('336a0121-bb51-47b7-8125-a40673d53a77', 'equipment', '{"name":"Potion of Healing","desc":"This potion is a magic item. As a Bonus Action, you can drink it or administer it to another creature within 5 feet of yourself. The creature that drinks the magical red fluid in this vial regains 2d4 + 2 Hit Points."}'::jsonb, '{"index":"potion-of-healing","name":"Potion of Healing","equipment_categories":[{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2024/equipment-categories/adventuring-gear"}],"cost":{"quantity":50,"unit":"gp"},"description":"This potion is a magic item. As a Bonus Action, you can drink it or administer it to another creature within 5 feet of yourself. The creature that drinks the magical red fluid in this vial regains 2d4 + 2 Hit Points.","weight":0.5,"url":"/api/2024/equipment/potion-of-healing"}'::jsonb),
