  ('336a0121-bb51-47b7-8125-a40673d53a77', 'equipment', '{"name":"Waterskin","desc":"A Waterskin holds up to 4 pints. If you don''t drink sufficient water, you risk dehydration (see “Rules Glossary”)."}'::jsonb, '{"index":"waterskin","name":"Waterskin","equipment_categories":[{"index":"adventuring-gear","name":"Adventuring Gear","url":"/api/2024/equipment-categories/adventuring-gear"}],"cost":{"quantity":2,"unit":"sp"},"description":"A Waterskin holds up to 4 pints. If you don''t drink sufficient water, you risk dehydration (see “Rules Glossary”).","weight":5,"url":"/api/2024/equipment/waterskin"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'equipment', '{"name":"Weaver''s Tools","desc":null}'::jsonb, '{"index":"weavers-tools","name":"Weaver''s Tools","equipment_categories":[{"index":"artisans-tools","name":"Artisan''s Tools","url":"/api/2024/equipment-categories/artisans-tools"},{"index":"tools","name":"Tools","url":"/api/2024/equipment-categories/tools"}],"ability":{"index":"dex","name":"DEX","url":"/api/2024/ability-scores/dex"},"cost":{"quantity":1,"unit":"gp"},"craft":[{"index":"padded-armor","name":"Padded Armor","url":"/api/2024/equipment/padded-armor"},{"index":"basket","name":"Basket","url":"/api/2024/equipment/basket"},{"index":"bedroll","name":"Bedroll","url":"/api/2024/equipment/bedroll"},{"index":"blanket","name":"Blanket","url":"/api/2024/equipment/blanket"},{"index":"clothes-fine","name":"Clothes, Fine","url":"/api/2024/equipment/clothes-fine"},{"index":"net","name":"Net","url":"/api/2024/equipment/net"},{"index":"robe","name":"Robe","url":"/api/2024/equipment/robe"},{"index":"rope","name":"Rope","url":"/api/2024/equipment/rope"},{"index":"sack","name":"Sack","url":"/api/2024/equipment/sack"},{"index":"string","name":"String","url":"/api/2024/equipment/string"},{"index":"tent","name":"Tent","url":"/api/2024/equipment/tent"},{"index":"clothes-travelers","name":"Clothes, Traveler''s","url":"/api/2024/equipment/clothes-travelers"}],"utilize":[{"name":"Mend a tear in clothing","dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2024/ability-scores/dex"},"dc_value":10,"success_type":"none"}},{"name":"sew a Tiny design","dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2024/ability-scores/dex"},"dc_value":10,"success_type":"none"}}],"weight":5,"url":"/api/2024/equipment/weavers-tools"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'equipment', '{"name":"Whip","desc":null}'::jsonb, '{"index":"whip","name":"Whip","equipment_categories":[{"index":"martial-melee-weapons","name":"Martial Melee Weapons","url":"/api/2024/equipment-categories/martial-melee-weapons"},{"index":"martial-weapons","name":"Martial Weapons","url":"/api/2024/equipment-categories/martial-weapons"},{"index":"melee-weapons","name":"Melee Weapons","url":"/api/2024/equipment-categories/melee-weapons"},{"index":"weapons","name":"Weapons","url":"/api/2024/equipment-categories/weapons"}],"cost":{"quantity":2,"unit":"gp"},"damage":{"damage_dice":"1d4","damage_type":{"index":"slashing","name":"Slashing","url":"/api/2024/damage-types/slashing"}},"range":{"normal":5},"weight":3,"properties":[{"index":"finesse","name":"Finesse","url":"/api/2024/weapon-properties/finesse"},{"index":"reach","name":"Reach","url":"/api/2024/weapon-properties/reach"}],"mastery":{"index":"slow","name":"Slow","url":"/api/2024/weapon-mastery-properties/slow"},"url":"/api/2024/equipment/whip"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'equipment', '{"name":"Woodcarver''s Tools","desc":null}'::jsonb, '{"index":"woodcarvers-tools","name":"Woodcarver''s Tools","equipment_categories":[{"index":"artisans-tools","name":"Artisan''s Tools","url":"/api/2024/equipment-categories/artisans-tools"},{"index":"tools","name":"Tools","url":"/api/2024/equipment-categories/tools"}],"ability":{"index":"dex","name":"DEX","url":"/api/2024/ability-scores/dex"},"cost":{"quantity":1,"unit":"gp"},"craft":[{"index":"club","name":"Club","url":"/api/2024/equipment/club"},{"index":"greatclub","name":"Greatclub","url":"/api/2024/equipment/greatclub"},{"index":"quarterstaff","name":"Quarterstaff","url":"/api/2024/equipment/quarterstaff"},{"index":"blowgun","name":"Blowgun","url":"/api/2024/equipment/blowgun"},{"index":"dart","name":"Dart","url":"/api/2024/equipment/dart"},{"index":"hand-crossbow","name":"Hand Crossbow","url":"/api/2024/equipment/hand-crossbow"},{"index":"heavy-crossbow","name":"Heavy Crossbow","url":"/api/2024/equipment/heavy-crossbow"},{"index":"light-crossbow","name":"Light Crossbow","url":"/api/2024/equipment/light-crossbow"},{"index":"longbow","name":"Longbow","url":"/api/2024/equipment/longbow"},{"index":"shortbow","name":"Shortbow","url":"/api/2024/equipment/shortbow"},{"index":"crystal","name":"Crystal","url":"/api/2024/equipment/crystal"},{"index":"orb","name":"Orb","url":"/api/2024/equipment/orb"},{"index":"quarterstaff","name":"Quarterstaff","url":"/api/2024/equipment/quarterstaff"},{"index":"rod","name":"Rod","url":"/api/2024/equipment/rod"},{"index":"staff","name":"Staff","url":"/api/2024/equipment/staff"},{"index":"wand","name":"Wand","url":"/api/2024/equipment/wand"},{"index":"arrows","name":"Arrows","url":"/api/2024/equipment/arrows"},{"index":"bolts","name":"Bolts","url":"/api/2024/equipment/bolts"},{"index":"sprig-of-mistletoe","name":"Sprig of Mistletoe","url":"/api/2024/equipment/sprig-of-mistletoe"},{"index":"staff","name":"Staff","url":"/api/2024/e