insert into ruleset_entries (ruleset_id, entry_type, human_readable, structured_data)
values
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'feats', '{"name":"Alert","desc":"You gain the following benefits.\n**Initiative Proficiency.** When you roll Initiative, you can add your Proficiency Bonus to the roll.\n**Initiative Swap.** Immediately after you roll Initiative, you can swap your Initiative with the Initiative of one willing ally in the same combat. You can''t make this swap if you or the ally has the Incapacitated condition."}'::jsonb, '{"index":"alert","name":"Alert","description":"You gain the following benefits.\n**Initiative Proficiency.** When you roll Initiative, you can add your Proficiency Bonus to the roll.\n**Initiative Swap.** Immediately after you roll Initiative, you can swap your Initiative with the Initiative of one willing ally in the same combat. You can''t make this swap if you or the ally has the Incapacitated condition.","type":"origin","url":"/api/2024/feats/alert"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'feats', '{"name":"Magic Initiate","desc":"You gain the following benefits.\n**Two Cantrips.** You learn two cantrips of your choice from the Cleric, Druid, or Wizard spell list. Intelligence, Wisdom, or Charisma is your spellcasting ability for this feat''s spells (choose when you select this feat).\n**Level 1 Spell.** Choose a level 1 spell from the same list you selected for this feat''s cantrips. You always have that spell prepared. You can cast it once without a spell slot, and you regain the ability to cast it in that way when you finish a Long Rest. You can also cast the spell using any spell slots you have.\n**Spell Change.** Whenever you gain a new level, you can replace one of the spells you chose for this feat with a different spell of the same level from the chosen spell list."}'::jsonb, '{"index":"magic-initiate","name":"Magic Initiate","description":"You gain the following benefits.\n**Two Cantrips.** You learn two cantrips of your choice from the Cleric, Druid, or Wizard spell list. Intelligence, Wisdom, or Charisma is your spellcasting ability for this feat''s spells (choose when you select this feat).\n**Level 1 Spell.** Choose a level 1 spell from the same list you selected for this feat''s cantrips. You always have that spell prepared. You can cast it once without a spell slot, and you regain the ability to cast it in that way when you finish a Long Rest. You can also cast the spell using any spell slots you have.\n**Spell Change.** Whenever you gain a new level, you can replace one of the spells you chose for this feat with a different spell of the same level from the chosen spell list.","repeatable":"You can take this feat more than once, but you must choose a different spell list each time.","type":"origin","url":"/api/2024/feats/magic-initiate"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'feats', '{"name":"Savage Attacker","desc":"You''ve trained to deal particularly damaging strikes. Once per turn when you hit a target with a weapon, you can roll the weapon''s damage dice twice and use either roll against the target."}'::jsonb, '{"index":"savage-attacker","name":"Savage Attacker","description":"You''ve trained to deal particularly damaging strikes. Once per turn when you hit a target with a weapon, you can roll the weapon''s damage dice twice and use either roll against the target.","type":"origin","url":"/api/2024/feats/savage-attacker"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'feats', '{"name":"Skilled","desc":"You gain proficiency in any combination of three skills or tools of your choice."}'::jsonb, '{"index":"skilled","name":"Skilled","description":"You gain proficiency in any combination of three skills or tools of your choice.","repeatable":"You can take this feat more than once.","type":"origin","url":"/api/2024/feats/skilled"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'feats', '{"name":"Ability Score Improvement","desc":"Increase one ability score of your choice by 2, or increase two ability scores of your choice by 1. This feat can''t increase an ability score above 20."}'::jsonb, '{"index":"ability-score-improvement","name":"Ability Score Improvement","type":"general","prerequisites":{"minimum_level":4},"description":"Increase one ability score of your choice by 2, or increase two ability scores of your choice by 1. This feat can''t increase an ability score above 20.","repeatable":"You can take this feat more than once.","url":"/api/2024/feats/ability-score-improvement"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'feats', '{"name":"Grappler","desc":"You gain the following benefits.\n**Ability Score Increase.** Increase your Strength or Dexterity score by 1, to a maximum of 20.\n**Punch and Grab.** When you hit a creature with an Unarmed Strike as part of the Attack action on your turn, you can use both the Damage and the Grapple option. You can use this benefit only once per turn.\n**Attack Advantage.** You have Advantage on attack rolls against a creature Grappled by you.\n**Fast Wrestler.** You don''t have to spend extra movement to move a creature Grappled by you if the creature is your size or smaller."}'::jsonb, '{"index":"grappler","name":"Grappler","type":"general","prerequisites":{"minimum_level":4},"prerequisite_options":{"desc":"Strength or Dexterity 13+","type":"ability-scores","choose":1,"from":{"option_set_type":"options_array","options":[{"option_type":"score_prerequisite","ability_score":{"index":"str","name":"STR","url":"/api/2024/ability-scores/str"},"minimum_score":13},{"option_type":"score_prerequisite","ability_score":{"index":"dex","name":"DEX","url":"/api/2024/ability-scores/dex"},"minimum_score":13}]}},"description":"You gain the following benefits.\n**Ability Score Increase.** Increase your Strength or Dexterity score by 1, to a maximum of 20.\n**Punch and Grab.** When you hit a creature with an Unarmed Strike as part of the Attack action on your turn, you can use both the Damage and the Grapple option. You can use this benefit only once per turn.\n**Attack Advantage.** You have Advantage on attack rolls against a creature Grappled by you.\n**Fast Wrestler.** You don''t have to spend extra movement to move a creature Grappled by you if the creature is your size or smaller.","url":"/api/2024/feats/grappler"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'feats', '{"name":"Archery","desc":"You gain a +2 bonus to attack rolls you make with Ranged weapons."}'::jsonb, '{"index":"archery","name":"Archery","type":"fighting-style","prerequisites":{"feature_named":"Fighting Style"},"description":"You gain a +2 bonus to attack rolls you make with Ranged weapons.","url":"/api/2024/feats/archery"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'feats', '{"name":"Defense","desc":"While you''re wearing Light, Medium, or Heavy armor, you gain a +1 bonus to Armor Class."}'::jsonb, '{"index":"defense","name":"Defense","type":"fighting-style","prerequisites":{"feature_named":"Fighting Style"},"description":"While you''re wearing Light, Medium, or Heavy armor, you gain a +1 bonus to Armor Class.","url":"/api/2024/feats/defense"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'feats', '{"name":"Great Weapon Fighting","desc":"When you roll damage for an attack you make with a Melee weapon that you are holding with two hands, you can treat any 1 or 2 on a damage die as a 3. The weapon must have the Two-Handed or Versatile property to gain this benefit."}'::jsonb, '{"index":"great-weapon-fighting","name":"Great Weapon Fighting","type":"fighting-style","prerequisites":{"feature_named":"Fighting Style"},"description":"When you roll damage for an attack you make with a Melee weapon that you are holding with two hands, you can treat any 1 or 2 on a damage die as a 3. The weapon must have the Two-Handed or Versatile property to gain this benefit.","url":"/api/2024/feats/great-weapon-fighting"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'feats', '{"name":"Two Weapon Fighting","desc":"When you make an extra attack as a result of using a weapon that has the Light property, you can add your ability modifier to the damage of that attack if you aren''t already adding it to the damage."}'::jsonb, '{"index":"two-weapon-fighting","name":"Two Weapon Fighting","type":"fighting-style","prerequisites":{"feature_named":"Fighting Style"},"description":"When you make an extra attack as a result of using a weapon that has the Light property, you can add your ability modifier to the damage of that attack if you aren''t already adding it to the damage.","url":"/api/2024/feats/two-weapon-fighting"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'feats', '{"name":"Boon of Combat Prowess","desc":"You gain the following benefits.\n**Ability Score Increase.** Increase one ability score of your choice by 1, to a maximum of 30.\n**Peerless Aim.** When you miss with an attack roll, you can hit instead. Once you use this benefit, you can''t use it again until the start of your next turn."}'::jsonb, '{"index":"boon-of-combat-prowess","name":"Boon of Combat Prowess","type":"epic-boon","prerequisites":{"minimum_level":19},"description":"You gain the following benefits.\n**Ability Score Increase.** Increase one ability score of your choice by 1, to a maximum of 30.\n**Peerless Aim.** When you miss with an attack roll, you can hit instead. Once you use this benefit, you can''t use it again until the start of your next turn.","url":"/api/2024/feats/boon-of-combat-prowess"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'feats', '{"name":"Boon of Dimensional Travel","desc":"You gain the following benefits.\n**Ability Score Increase.** Increase one ability score of your choice by 1, to a maximum of 30.\n**Blink Steps.** Immediately after you take the Attack action or the Magic action, you can teleport up to 30 feet to an unoccupied space you can see."}'::jsonb, '{"index":"boon-of-dimensional-travel","name":"Boon of Dimensional Travel","type":"epic-boon","prerequisites":{"minimum_level":19},"description":"You gain the following benefits.\n**Ability Score Increase.** Increase one ability score of your choice by 1, to a maximum of 30.\n**Blink Steps.** Immediately after you take the Attack action or the Magic action, you can teleport up to 30 feet to an unoccupied space you can see.","url":"/api/2024/feats/boon-of-dimensional-travel"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'feats', '{"name":"Boon of Fate","desc":"You gain the following benefits.\n**Ability Score Increase.** Increase one ability score of your choice by 1, to a maximum of 30.\n**Improve Fate.** When you or another creature within 60 feet of you succeeds on or fails a D20 Test, you can roll 2d4 and apply the total rolled as a bonus or penalty to the d20 roll. Once you use this benefit, you can''t use it again until you roll Initiative or finish a Short or Long Rest."}'::jsonb, '{"index":"boon-of-fate","name":"Boon of Fate","type":"epic-boon","prerequisites":{"minimum_level":19},"description":"You gain the following benefits.\n**Ability Score Increase.** Increase one ability score of your choice by 1, to a maximum of 30.\n**Improve Fate.** When you or another creature within 60 feet of you succeeds on or fails a D20 Test, you can roll 2d4 and apply the total rolled as a bonus or penalty to the d20 roll. Once you use this benefit, you can''t use it again until you roll Initiative or finish a Short or Long Rest.","url":"/api/2024/feats/boon-of-fate"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'feats', '{"name":"Boon of Irresistible Offense","desc":"You gain the following benefits.\n**Ability Score Increase.** Increase one ability score of your choice by 1, to a maximum of 30.\n**Overcome Defenses.** The Bludgeoning, Piercing, and Slashing damage you deal always ignores Resistance.\n**Overwhelming Strike.** When you roll a 20 on the d20 for an attack roll, you can deal extra damage to the target equal to the ability score increased by this feat. The extra damage''s type is the same as the attack''s type."}'::jsonb, '{"index":"boon-of-irresistible-offense","name":"Boon of Irresistible Offense","type":"epic-boon","prerequisites":{"minimum_level":19},"description":"You gain the following benefits.\n**Ability Score Increase.** Increase one ability score of your choice by 1, to a maximum of 30.\n**Overcome Defenses.** The Bludgeoning, Piercing, and Slashing damage you deal always ignores Resistance.\n**Overwhelming Strike.** When you roll a 20 on the d20 for an attack roll, you can deal extra damage to the target equal to the ability score increased by this feat. The extra damage''s type is the same as the attack''s type.","url":"/api/2024/feats/boon-of-irresistible-offense"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'feats', '{"name":"Boon of Spell Recall","desc":"You gain the following benefits.\n**Ability Score Increase.** Increase one ability score of your choice by 1, to a maximum of 30.\n**Free Casting.** Whenever you cast a spell with a level 1–4 spell slot, roll 1d4. If the number you roll is the same as the slot''s level, the slot isn''t expended."}'::jsonb, '{"index":"boon-of-spell-recall","name":"Boon of Spell Recall","type":"epic-boon","prerequisites":{"minimum_level":19,"feature_named":"Spellcasting"},"description":"You gain the following benefits.\n**Ability Score Increase.** Increase one ability score of your choice by 1, to a maximum of 30.\n**Free Casting.** Whenever you cast a spell with a level 1–4 spell slot, roll 1d4. If the number you roll is the same as the slot''s level, the slot isn''t expended.","url":"/api/2024/feats/boon-of-spell-recall"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'feats', '{"name":"Boon of the Night Spirit","desc":"You gain the following benefits.\n**Ability Score Increase.** Increase one ability score of your choice by 1, to a maximum of 30.\n**Merge with Shadows.** While within Dim Light or Darkness, you can give yourself the Invisible condition as a Bonus Action. The condition ends on you immediately after you take an action, a Bonus Action, or a Reaction.\n**Shadowy form.** While within Dim Light or Darkness, you have Resistance to all damage except Psychic and Radiant."}'::jsonb, '{"index":"boon-of-the-night-spirit","name":"Boon of the Night Spirit","type":"epic-boon","prerequisites":{"minimum_level":19},"description":"You gain the following benefits.\n**Ability Score Increase.** Increase one ability score of your choice by 1, to a maximum of 30.\n**Merge with Shadows.** While within Dim Light or Darkness, you can give yourself the Invisible condition as a Bonus Action. The condition ends on you immediately after you take an action, a Bonus Action, or a Reaction.\n**Shadowy form.** While within Dim Light or Darkness, you have Resistance to all damage except Psychic and Radiant.","url":"/api/2024/feats/boon-of-the-night-spirit"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'feats', '{"name":"Boon of Truesight","desc":"You gain the following benefits.\n**Ability Score Increase.** Increase one ability score of your choice by 1, to a maximum of 30.\n**Truesight.** You have Truesight with a range of 60 feet."}'::jsonb, '{"index":"boon-of-truesight","name":"Boon of Truesight","type":"epic-boon","prerequisites":{"minimum_level":19},"description":"You gain the following benefits.\n**Ability Score Increase.** Increase one ability score of your choice by 1, to a maximum of 30.\n**Truesight.** You have Truesight with a range of 60 feet.","url":"/api/2024/feats/boon-of-truesight"}'::jsonb);
insert into ruleset_entries (ruleset_id, entry_type, human_readable, structured_data)
values
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Rage","desc":"You can imbue yourself with a primal power called Rage, a force that grants you extraordinary might and resilience. You can enter it as a Bonus Action if you aren''t wearing Heavy armor.\n  You can enter your Rage the number of times shown for your Barbarian level in the Rages column of the Barbarian Features table. You regain one ex- pended use when you finish a Short Rest, and you regain all expended uses when you finish a Long Rest.\n  While active, your Rage follows the rules below.\n  **Damage Resistance.** You have Resistance to Blud- geoning, Piercing, and Slashing damage.\n  **Rage Damage.** When you make an attack using Strength-with either a weapon or an Unarmed Strike-and deal damage to the target, you gain a bonus to the damage that increases as you gain levels as a Barbarian, as shown in the Rage Damage column of the Barbarian Features table.\n  **Strength Advantage.** You have Advantage on Strength checks and Strength saving throws.\n  **No Concentration or Spells.** You can''t maintain Concentration, and you can''t cast spells.\n  **Duration.** The Rage lasts until the end of your next turn, and it ends early if you don Heavy armor or have the Incapacitated condition. If your Rage is still active on your next turn, you can extend the Rage for another round by doing one of the following:\n- Make an attack roll against an enemy.\n- Force an enemy to make a saving throw.\n- Take a Bonus Action to extend your Rage.\nEach time the Rage is extended, it lasts until the end of your next turn. You can maintain a Rage for up to 10 minutes."}'::jsonb, '{"index":"barbarian-rage","url":"/api/2024/features/barbarian-rage","name":"Rage","class":{"index":"barbarian","name":"Barbarian","url":"/api/2024/classes/barbarian"},"level":{"index":"barbarian-1","name":"Barbarian 1","url":"/api/2024/classes/barbarian/levels/1"},"description":"You can imbue yourself with a primal power called Rage, a force that grants you extraordinary might and resilience. You can enter it as a Bonus Action if you aren''t wearing Heavy armor.\n  You can enter your Rage the number of times shown for your Barbarian level in the Rages column of the Barbarian Features table. You regain one ex- pended use when you finish a Short Rest, and you regain all expended uses when you finish a Long Rest.\n  While active, your Rage follows the rules below.\n  **Damage Resistance.** You have Resistance to Blud- geoning, Piercing, and Slashing damage.\n  **Rage Damage.** When you make an attack using Strength-with either a weapon or an Unarmed Strike-and deal damage to the target, you gain a bonus to the damage that increases as you gain levels as a Barbarian, as shown in the Rage Damage column of the Barbarian Features table.\n  **Strength Advantage.** You have Advantage on Strength checks and Strength saving throws.\n  **No Concentration or Spells.** You can''t maintain Concentration, and you can''t cast spells.\n  **Duration.** The Rage lasts until the end of your next turn, and it ends early if you don Heavy armor or have the Incapacitated condition. If your Rage is still active on your next turn, you can extend the Rage for another round by doing one of the following:\n- Make an attack roll against an enemy.\n- Force an enemy to make a saving throw.\n- Take a Bonus Action to extend your Rage.\nEach time the Rage is extended, it lasts until the end of your next turn. You can maintain a Rage for up to 10 minutes."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Unarmored Defense","desc":"While you aren''t wearing any armor, your base Ar- mor Class equals 10 plus your Dexterity and Consti- tution modifiers. You can use a Shield and still gain this benefit."}'::jsonb, '{"index":"barbarian-unarmored-defense","url":"/api/2024/features/barbarian-unarmored-defense","name":"Unarmored Defense","class":{"index":"barbarian","name":"Barbarian","url":"/api/2024/classes/barbarian"},"level":{"index":"barbarian-1","name":"Barbarian 1","url":"/api/2024/classes/barbarian/levels/1"},"description":"While you aren''t wearing any armor, your base Ar- mor Class equals 10 plus your Dexterity and Consti- tution modifiers. You can use a Shield and still gain this benefit."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Weapon Mastery","desc":"Your training with weapons allows you to use the mastery properties of two kinds of Simple or Mar- tial Melee weapons of your choice, such as Great- axes and Handaxes. Whenever you finish a Long Rest, you can practice weapon drills and change one of those weapon choices.\n  When you reach certain Barbarian levels, you gain the ability to use the mastery properties of more kinds of weapons, as shown in the Weapon Mastery column of the Barbarian Features table."}'::jsonb, '{"index":"barbarian-weapon-mastery","url":"/api/2024/features/barbarian-weapon-mastery","name":"Weapon Mastery","class":{"index":"barbarian","name":"Barbarian","url":"/api/2024/classes/barbarian"},"level":{"index":"barbarian-1","name":"Barbarian 1","url":"/api/2024/classes/barbarian/levels/1"},"description":"Your training with weapons allows you to use the mastery properties of two kinds of Simple or Mar- tial Melee weapons of your choice, such as Great- axes and Handaxes. Whenever you finish a Long Rest, you can practice weapon drills and change one of those weapon choices.\n  When you reach certain Barbarian levels, you gain the ability to use the mastery properties of more kinds of weapons, as shown in the Weapon Mastery column of the Barbarian Features table."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Danger Sense","desc":"You gain an uncanny sense of when things aren''t as they should be, giving you an edge when you dodge perils. You have Advantage on Dexterity saving throws unless you have the Incapacitated condition."}'::jsonb, '{"index":"barbarian-danger-sense","url":"/api/2024/features/barbarian-danger-sense","name":"Danger Sense","class":{"index":"barbarian","name":"Barbarian","url":"/api/2024/classes/barbarian"},"level":{"index":"barbarian-2","name":"Barbarian 2","url":"/api/2024/classes/barbarian/levels/2"},"description":"You gain an uncanny sense of when things aren''t as they should be, giving you an edge when you dodge perils. You have Advantage on Dexterity saving throws unless you have the Incapacitated condition."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Reckless Attack","desc":"You can throw aside all concern for defense to at- tack with increased ferocity. When you make your first attack roll on your turn, you can decide to at- tack recklessly. Doing so gives you Advantage on at- tack rolls using Strength until the start of your next\nturn, but attack rolls against you have Advantage during that time."}'::jsonb, '{"index":"barbarian-reckless-attack","url":"/api/2024/features/barbarian-reckless-attack","name":"Reckless Attack","class":{"index":"barbarian","name":"Barbarian","url":"/api/2024/classes/barbarian"},"level":{"index":"barbarian-2","name":"Barbarian 2","url":"/api/2024/classes/barbarian/levels/2"},"description":"You can throw aside all concern for defense to at- tack with increased ferocity. When you make your first attack roll on your turn, you can decide to at- tack recklessly. Doing so gives you Advantage on at- tack rolls using Strength until the start of your next\nturn, but attack rolls against you have Advantage during that time."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Barbarian Subclass","desc":"You gain a Barbarian subclass of your choice. A subclass is a specialization that grants you features at certain Barbarian levels. For the rest of your career, you gain each of your subclass''s features that are of your Barbarian level or lower."}'::jsonb, '{"index":"barbarian-subclass","url":"/api/2024/features/barbarian-subclass","name":"Barbarian Subclass","class":{"index":"barbarian","name":"Barbarian","url":"/api/2024/classes/barbarian"},"level":{"index":"barbarian-3","name":"Barbarian 3","url":"/api/2024/classes/barbarian/levels/3"},"description":"You gain a Barbarian subclass of your choice. A subclass is a specialization that grants you features at certain Barbarian levels. For the rest of your career, you gain each of your subclass''s features that are of your Barbarian level or lower."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Primal Knowledge","desc":"You gain proficiency in another skill of your choice from the skill list available to Barbarians at level 1.\n  In addition, while your Rage is active, you can channel primal power when you attempt certain tasks; whenever you make an ability check using one of the following skills, you can make it as a Strength check even if it normally uses a differ- ent ability: Acrobatics, Intimidation, Perception,\nStealth, or Survival. When you use this ability, your Strength represents primal power coursing through you, honing your agility, bearing, and senses."}'::jsonb, '{"index":"barbarian-primal-knowledge","url":"/api/2024/features/barbarian-primal-knowledge","name":"Primal Knowledge","class":{"index":"barbarian","name":"Barbarian","url":"/api/2024/classes/barbarian"},"level":{"index":"barbarian-3","name":"Barbarian 3","url":"/api/2024/classes/barbarian/levels/3"},"description":"You gain proficiency in another skill of your choice from the skill list available to Barbarians at level 1.\n  In addition, while your Rage is active, you can channel primal power when you attempt certain tasks; whenever you make an ability check using one of the following skills, you can make it as a Strength check even if it normally uses a differ- ent ability: Acrobatics, Intimidation, Perception,\nStealth, or Survival. When you use this ability, your Strength represents primal power coursing through you, honing your agility, bearing, and senses."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Ability Score Improvement","desc":"You gain the Ability Score Improvement feat (see \"Feats\") or another feat of your choice for which you qualify. You gain this feature again at Barbarian lev- els 8, 12, and 16."}'::jsonb, '{"index":"barbarian-ability-score-improvement","url":"/api/2024/features/barbarian-ability-score-improvement","name":"Ability Score Improvement","class":{"index":"barbarian","name":"Barbarian","url":"/api/2024/classes/barbarian"},"level":{"index":"barbarian-4","name":"Barbarian 4","url":"/api/2024/classes/barbarian/levels/4"},"description":"You gain the Ability Score Improvement feat (see \"Feats\") or another feat of your choice for which you qualify. You gain this feature again at Barbarian lev- els 8, 12, and 16."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Extra Attack","desc":"You can attack twice instead of once whenever you take the Attack action on your turn."}'::jsonb, '{"index":"barbarian-extra-attack","url":"/api/2024/features/barbarian-extra-attack","name":"Extra Attack","class":{"index":"barbarian","name":"Barbarian","url":"/api/2024/classes/barbarian"},"level":{"index":"barbarian-5","name":"Barbarian 5","url":"/api/2024/classes/barbarian/levels/5"},"description":"You can attack twice instead of once whenever you take the Attack action on your turn."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Fast Movement","desc":"Your speed increases by 10 feet while you aren''t wearing Heavy armor."}'::jsonb, '{"index":"barbarian-fast-movement","url":"/api/2024/features/barbarian-fast-movement","name":"Fast Movement","class":{"index":"barbarian","name":"Barbarian","url":"/api/2024/classes/barbarian"},"level":{"index":"barbarian-5","name":"Barbarian 5","url":"/api/2024/classes/barbarian/levels/5"},"description":"Your speed increases by 10 feet while you aren''t wearing Heavy armor."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Feral Instinct","desc":"Your instincts are so honed that you have Advan- tage on Initiative rolls."}'::jsonb, '{"index":"barbarian-feral-instinct","url":"/api/2024/features/barbarian-feral-instinct","name":"Feral Instinct","class":{"index":"barbarian","name":"Barbarian","url":"/api/2024/classes/barbarian"},"level":{"index":"barbarian-7","name":"Barbarian 7","url":"/api/2024/classes/barbarian/levels/7"},"description":"Your instincts are so honed that you have Advan- tage on Initiative rolls."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Instinctive Pounce","desc":"As part of the Bonus Action you take to enter your Rage, you can move up to half your Speed."}'::jsonb, '{"index":"barbarian-instinctive-pounce","url":"/api/2024/features/barbarian-instinctive-pounce","name":"Instinctive Pounce","class":{"index":"barbarian","name":"Barbarian","url":"/api/2024/classes/barbarian"},"level":{"index":"barbarian-7","name":"Barbarian 7","url":"/api/2024/classes/barbarian/levels/7"},"description":"As part of the Bonus Action you take to enter your Rage, you can move up to half your Speed."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Brutal Strike","desc":"If you use Reckless Attack, you can forgo any Ad- vantage on one Strength-based attack roll of your choice on your turn. The chosen attack roll mustn''t have Disadvantage. If the chosen attack roll hits, the target takes an extra 1d10 damage of the same type dealt by the weapon or Unarmed Strike, and you can cause one Brutal Strike effect of your choice. You have the following effect options.\n  Forceful Blow. The target is pushed 15 feet straight away from you. You can then move up to half your Speed straight toward the target without provoking Opportunity Attacks.\n  Hamstring Blow. The target''s Speed is reduced by 15 feet until the start of your next turn. A target can be affected by only one Hamstring Blow at a time- the most recent one."}'::jsonb, '{"index":"barbarian-brutal-strike","url":"/api/2024/features/barbarian-brutal-strike","name":"Brutal Strike","class":{"index":"barbarian","name":"Barbarian","url":"/api/2024/classes/barbarian"},"level":{"index":"barbarian-9","name":"Barbarian 9","url":"/api/2024/classes/barbarian/levels/9"},"description":"If you use Reckless Attack, you can forgo any Ad- vantage on one Strength-based attack roll of your choice on your turn. The chosen attack roll mustn''t have Disadvantage. If the chosen attack roll hits, the target takes an extra 1d10 damage of the same type dealt by the weapon or Unarmed Strike, and you can cause one Brutal Strike effect of your choice. You have the following effect options.\n  Forceful Blow. The target is pushed 15 feet straight away from you. You can then move up to half your Speed straight toward the target without provoking Opportunity Attacks.\n  Hamstring Blow. The target''s Speed is reduced by 15 feet until the start of your next turn. A target can be affected by only one Hamstring Blow at a time- the most recent one."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Relentless Rage","desc":"Your Rage can keep you fighting despite grievous wounds. If you drop to 0 Hit Points while your Rage is active and don''t die outright, you can make a DC 10 Constitution saving throw. If you succeed, your Hit Points instead change to a number equal to twice your Barbarian level.\n  Each time you use this feature after the first, the DC increases by 5. When you finish a Short or Long Rest, the DC resets to 10."}'::jsonb, '{"index":"barbarian-relentless-rage","url":"/api/2024/features/barbarian-relentless-rage","name":"Relentless Rage","class":{"index":"barbarian","name":"Barbarian","url":"/api/2024/classes/barbarian"},"level":{"index":"barbarian-11","name":"Barbarian 11","url":"/api/2024/classes/barbarian/levels/11"},"description":"Your Rage can keep you fighting despite grievous wounds. If you drop to 0 Hit Points while your Rage is active and don''t die outright, you can make a DC 10 Constitution saving throw. If you succeed, your Hit Points instead change to a number equal to twice your Barbarian level.\n  Each time you use this feature after the first, the DC increases by 5. When you finish a Short or Long Rest, the DC resets to 10."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Improved Brutal Strike","desc":"You have honed new ways to attack furiously. The following effects are now among your Brutal Strike options.\n  Staggering Blow. The target has Disadvantage on the next saving throw it makes, and it can''t make Opportunity Attacks until the start of your next turn.\n  Sundering Blow. Before the start of your next turn, the next attack roll made by another creature against the target gains a +5 bonus to the roll. An attack roll can gain only one Sundering Blow bonus."}'::jsonb, '{"index":"barbarian-improved-brutal-strike-1","url":"/api/2024/features/barbarian-improved-brutal-strike-1","name":"Improved Brutal Strike","class":{"index":"barbarian","name":"Barbarian","url":"/api/2024/classes/barbarian"},"level":{"index":"barbarian-13","name":"Barbarian 13","url":"/api/2024/classes/barbarian/levels/13"},"description":"You have honed new ways to attack furiously. The following effects are now among your Brutal Strike options.\n  Staggering Blow. The target has Disadvantage on the next saving throw it makes, and it can''t make Opportunity Attacks until the start of your next turn.\n  Sundering Blow. Before the start of your next turn, the next attack roll made by another creature against the target gains a +5 bonus to the roll. An attack roll can gain only one Sundering Blow bonus."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Persistent Rage","desc":"When you roll Initiative, you can regain all ex- pended uses of Rage. After you regain uses of Rage in this way, you can''t do so again until you finish a Long Rest.\n  In addition, your Rage is so fierce that it now lasts for 10 minutes without you needing to do anything to extend it from round to round. Your Rage ends early if you have the Unconscious condition (not just the Incapacitated condition) or don Heavy armor."}'::jsonb, '{"index":"barbarian-persistent-rage","url":"/api/2024/features/barbarian-persistent-rage","name":"Persistent Rage","class":{"index":"barbarian","name":"Barbarian","url":"/api/2024/classes/barbarian"},"level":{"index":"barbarian-15","name":"Barbarian 15","url":"/api/2024/classes/barbarian/levels/15"},"description":"When you roll Initiative, you can regain all ex- pended uses of Rage. After you regain uses of Rage in this way, you can''t do so again until you finish a Long Rest.\n  In addition, your Rage is so fierce that it now lasts for 10 minutes without you needing to do anything to extend it from round to round. Your Rage ends early if you have the Unconscious condition (not just the Incapacitated condition) or don Heavy armor."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Improved Brutal Strike","desc":"The extra damage of your Brutal Strike increases to 2d10. In addition, you can use two different Brutal Strike effects whenever you use your Brutal Strike feature."}'::jsonb, '{"index":"barbarian-improved-brutal-strike-2","url":"/api/2024/features/barbarian-improved-brutal-strike-2","name":"Improved Brutal Strike","class":{"index":"barbarian","name":"Barbarian","url":"/api/2024/classes/barbarian"},"level":{"index":"barbarian-17","name":"Barbarian 17","url":"/api/2024/classes/barbarian/levels/17"},"description":"The extra damage of your Brutal Strike increases to 2d10. In addition, you can use two different Brutal Strike effects whenever you use your Brutal Strike feature."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Indomitable Might","desc":"If your total for a Strength check or Strength saving throw is less than your Strength score, you can use that score in place of the total."}'::jsonb, '{"index":"barbarian-indomitable-might","url":"/api/2024/features/barbarian-indomitable-might","name":"Indomitable Might","class":{"index":"barbarian","name":"Barbarian","url":"/api/2024/classes/barbarian"},"level":{"index":"barbarian-18","name":"Barbarian 18","url":"/api/2024/classes/barbarian/levels/18"},"description":"If your total for a Strength check or Strength saving throw is less than your Strength score, you can use that score in place of the total."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Epic Boon","desc":"You gain an Epic Boon feat (see \"Feats\") or another feat of your choice for which you qualify. Boon of Irresistible Offense is recommended."}'::jsonb, '{"index":"barbarian-epic-boon","url":"/api/2024/features/barbarian-epic-boon","name":"Epic Boon","class":{"index":"barbarian","name":"Barbarian","url":"/api/2024/classes/barbarian"},"level":{"index":"barbarian-19","name":"Barbarian 19","url":"/api/2024/classes/barbarian/levels/19"},"description":"You gain an Epic Boon feat (see \"Feats\") or another feat of your choice for which you qualify. Boon of Irresistible Offense is recommended."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Primal Champion","desc":"You embody primal power. Your Strength and Con- stitution scores increase by 4, to a maximum of 25."}'::jsonb, '{"index":"barbarian-primal-champion","url":"/api/2024/features/barbarian-primal-champion","name":"Primal Champion","class":{"index":"barbarian","name":"Barbarian","url":"/api/2024/classes/barbarian"},"level":{"index":"barbarian-20","name":"Barbarian 20","url":"/api/2024/classes/barbarian/levels/20"},"description":"You embody primal power. Your Strength and Con- stitution scores increase by 4, to a maximum of 25."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Frenzy","desc":"If you use Reckless Attack while your Rage is active, you deal extra damage to the first target you hit on your turn with a Strength-based attack. To determine the extra damage, roll a number of d6s equal to your Rage Damage bonus, and add them together. The damage has the same type as the weapon or Unarmed Strike used for the attack."}'::jsonb, '{"index":"berserker-frenzy","name":"Frenzy","url":"/api/2024/features/berserker-frenzy","class":{"index":"barbarian","name":"Barbarian","url":"/api/2024/classes/barbarian"},"subclass":{"index":"path-of-the-berserker","name":"Path of the Berserker","url":"/api/2024/subclasses/path-of-the-berserker"},"level":{"index":"barbarian-3","name":"Barbarian 3","url":"/api/2024/classes/barbarian/levels/3"},"description":"If you use Reckless Attack while your Rage is active, you deal extra damage to the first target you hit on your turn with a Strength-based attack. To determine the extra damage, roll a number of d6s equal to your Rage Damage bonus, and add them together. The damage has the same type as the weapon or Unarmed Strike used for the attack."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Mindless Rage","desc":"You have Immunity to the Charmed and Frightened conditions while your Rage is active. If you''re Charmed or Frightened when you enter your Rage, the condition ends on you."}'::jsonb, '{"index":"berserker-mindless-rage","name":"Mindless Rage","url":"/api/2024/features/berserker-mindless-rage","class":{"index":"barbarian","name":"Barbarian","url":"/api/2024/classes/barbarian"},"subclass":{"index":"path-of-the-berserker","name":"Path of the Berserker","url":"/api/2024/subclasses/path-of-the-berserker"},"level":{"index":"barbarian-6","name":"Barbarian 6","url":"/api/2024/classes/barbarian/levels/6"},"description":"You have Immunity to the Charmed and Frightened conditions while your Rage is active. If you''re Charmed or Frightened when you enter your Rage, the condition ends on you."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Retaliation","desc":"When you take damage from a creature that is within 5 feet of you, you can take a Reaction to make one melee attack against that creature, using a weapon or an Unarmed Strike."}'::jsonb, '{"index":"berserker-retaliation","name":"Retaliation","url":"/api/2024/features/berserker-retaliation","class":{"index":"barbarian","name":"Barbarian","url":"/api/2024/classes/barbarian"},"subclass":{"index":"path-of-the-berserker","name":"Path of the Berserker","url":"/api/2024/subclasses/path-of-the-berserker"},"level":{"index":"barbarian-10","name":"Barbarian 10","url":"/api/2024/classes/barbarian/levels/10"},"description":"When you take damage from a creature that is within 5 feet of you, you can take a Reaction to make one melee attack against that creature, using a weapon or an Unarmed Strike."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Intimidating Presence","desc":"As a Bonus Action, you can strike terror into others with your menacing presence and primal power.\nWhen you do so, each creature of your choice in a 30-foot Emanation originating from you must make a Wisdom saving throw (DC 8 plus your Strength modifier and Proficiency Bonus). On a failed save,\na creature has the Frightened condition for 1 minute. At the end of each of the Frightened creature''s turns, the creature repeats the save, ending the effect on itself on a success.\n  Once you use this feature, you can''t use it again until you finish a Long Rest unless you expend a use of your Rage (no action required) to restore your use of it."}'::jsonb, '{"index":"berserker-intimidating-presence","name":"Intimidating Presence","url":"/api/2024/features/berserker-intimidating-presence","class":{"index":"barbarian","name":"Barbarian","url":"/api/2024/classes/barbarian"},"subclass":{"index":"path-of-the-berserker","name":"Path of the Berserker","url":"/api/2024/subclasses/path-of-the-berserker"},"level":{"index":"barbarian-14","name":"Barbarian 14","url":"/api/2024/classes/barbarian/levels/14"},"description":"As a Bonus Action, you can strike terror into others with your menacing presence and primal power.\nWhen you do so, each creature of your choice in a 30-foot Emanation originating from you must make a Wisdom saving throw (DC 8 plus your Strength modifier and Proficiency Bonus). On a failed save,\na creature has the Frightened condition for 1 minute. At the end of each of the Frightened creature''s turns, the creature repeats the save, ending the effect on itself on a success.\n  Once you use this feature, you can''t use it again until you finish a Long Rest unless you expend a use of your Rage (no action required) to restore your use of it."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Bardic Inspiration","desc":"You can supernaturally inspire others through words, music, or dance. This inspiration is repre- sented by your Bardic Inspiration die, which is a d6.\n  Using Bardic Inspiration. As a Bonus Action, you can inspire another creature within 60 feet of your- self who can see or hear you. That creature gains\none of your Bardic Inspiration dice. A creature can have only one Bardic Inspiration die at a time.\n  Once within the next hour when the creature fails a D20 Test, the creature can roll the Bardic Inspira- tion die and add the number rolled to the d20, po- tentially turning the failure into a success. A Bardic Inspiration die is expended when it''s rolled.\n  Number of Uses. You can confer a Bardic Inspira- tion die a number of times equal to your Charisma modifier (minimum of once), and you regain all ex- pended uses when you finish a Long Rest.\n  At Higher Levels. Your Bardic Inspiration die changes when you reach certain Bard levels, as shown in the Bardic Die column of the Bard Fea- tures table. The die becomes a d8 at level 5, a d10 at level 10, and a d12 at level 15."}'::jsonb, '{"index":"bard-bardic-inspiration","url":"/api/2024/features/bard-bardic-inspiration","name":"Bardic Inspiration","level":{"index":"bard-1","name":"Bard 1","url":"/api/2024/classes/bard/levels/1"},"class":{"index":"bard","name":"Bard","url":"/api/2024/classes/bard"},"description":"You can supernaturally inspire others through words, music, or dance. This inspiration is repre- sented by your Bardic Inspiration die, which is a d6.\n  Using Bardic Inspiration. As a Bonus Action, you can inspire another creature within 60 feet of your- self who can see or hear you. That creature gains\none of your Bardic Inspiration dice. A creature can have only one Bardic Inspiration die at a time.\n  Once within the next hour when the creature fails a D20 Test, the creature can roll the Bardic Inspira- tion die and add the number rolled to the d20, po- tentially turning the failure into a success. A Bardic Inspiration die is expended when it''s rolled.\n  Number of Uses. You can confer a Bardic Inspira- tion die a number of times equal to your Charisma modifier (minimum of once), and you regain all ex- pended uses when you finish a Long Rest.\n  At Higher Levels. Your Bardic Inspiration die changes when you reach certain Bard levels, as shown in the Bardic Die column of the Bard Fea- tures table. The die becomes a d8 at level 5, a d10 at level 10, and a d12 at level 15."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Spellcasting","desc":"You have learned to cast spells through your bardic arts. See \"Spells\" for the rules on spellcasting. The information below details how you use those rules with Bard spells, which appear in the Bard spell list later in the class''s description.\n  Cantrips. You know two cantrips of your choice from the Bard spell list. Dancing Lights and Vicious Mockery are recommended.\n  Whenever you gain a Bard level, you can replace one of your cantrips with another cantrip of your choice from the Bard spell list.\n  When you reach Bard levels 4 and 10, you learn another cantrip of your choice from the Bard spell list, as shown in the Cantrips column of the Bard Features table.\n  Spell Slots. The Bard Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you fin- ish a Long Rest.\n  Prepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose four level 1 spells from the Bard spell list. Charm Person, Color Spray, Dissonant Whispers, and Healing Word are recommended.\n  The number of spells on your list increases as you gain Bard levels, as shown in the Prepared Spells column of the Bard Features table. Whenever that number increases, choose additional spells from the Bard spell list until the number of spells on your list matches the number on the table. The chosen spells must be of a level for which you have spell slots.\nFor example, if you''re a level 3 Bard, your list of\nprepared spells can include six spells of levels 1 and 2 in any combination.\n  If another Bard feature gives you spells that you always have prepared, those spells don''t count against the number of spells you can prepare with this feature, but those spells otherwise count as Bard spells for you.\n  Changing Your Prepared Spells. Whenever you gain a Bard level, you can replace one spell on your list with another Bard spell for which you have spell slots.\n  Spellcasting Ability. Charisma is your spellcast- ing ability for your Bard spells.\n  Spellcasting Focus. You can use a Musical Instru- ment as a Spellcasting Focus for your Bard spells."}'::jsonb, '{"index":"bard-spellcasting","url":"/api/2024/features/bard-spellcasting","name":"Spellcasting","level":{"index":"bard-1","name":"Bard 1","url":"/api/2024/classes/bard/levels/1"},"class":{"index":"bard","name":"Bard","url":"/api/2024/classes/bard"},"description":"You have learned to cast spells through your bardic arts. See \"Spells\" for the rules on spellcasting. The information below details how you use those rules with Bard spells, which appear in the Bard spell list later in the class''s description.\n  Cantrips. You know two cantrips of your choice from the Bard spell list. Dancing Lights and Vicious Mockery are recommended.\n  Whenever you gain a Bard level, you can replace one of your cantrips with another cantrip of your choice from the Bard spell list.\n  When you reach Bard levels 4 and 10, you learn another cantrip of your choice from the Bard spell list, as shown in the Cantrips column of the Bard Features table.\n  Spell Slots. The Bard Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you fin- ish a Long Rest.\n  Prepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose four level 1 spells from the Bard spell list. Charm Person, Color Spray, Dissonant Whispers, and Healing Word are recommended.\n  The number of spells on your list increases as you gain Bard levels, as shown in the Prepared Spells column of the Bard Features table. Whenever that number increases, choose additional spells from the Bard spell list until the number of spells on your list matches the number on the table. The chosen spells must be of a level for which you have spell slots.\nFor example, if you''re a level 3 Bard, your list of\nprepared spells can include six spells of levels 1 and 2 in any combination.\n  If another Bard feature gives you spells that you always have prepared, those spells don''t count against the number of spells you can prepare with this feature, but those spells otherwise count as Bard spells for you.\n  Changing Your Prepared Spells. Whenever you gain a Bard level, you can replace one spell on your list with another Bard spell for which you have spell slots.\n  Spellcasting Ability. Charisma is your spellcast- ing ability for your Bard spells.\n  Spellcasting Focus. You can use a Musical Instru- ment as a Spellcasting Focus for your Bard spells."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Expertise","desc":"You gain Expertise (see \"Rules Glossary\") in two of your skill proficiencies of your choice. Performance and Persuasion are recommended if you have profi- ciency in them.\n  At Bard level 9, you gain Expertise in two more of your skill proficiencies of your choice."}'::jsonb, '{"index":"bard-expertise","url":"/api/2024/features/bard-expertise","name":"Expertise","level":{"index":"bard-2","name":"Bard 2","url":"/api/2024/classes/bard/levels/2"},"class":{"index":"bard","name":"Bard","url":"/api/2024/classes/bard"},"description":"You gain Expertise (see \"Rules Glossary\") in two of your skill proficiencies of your choice. Performance and Persuasion are recommended if you have profi- ciency in them.\n  At Bard level 9, you gain Expertise in two more of your skill proficiencies of your choice."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Jack of All Trades","desc":"You can add half your Proficiency Bonus (round down) to any ability check you make that uses a skill proficiency you lack and that doesn''t otherwise use your Proficiency Bonus.\n  For example, if you make a Strength (Athletics) check and lack Athletics proficiency, you can add half your Proficiency Bonus to the check."}'::jsonb, '{"index":"bard-jack-of-all-trades","url":"/api/2024/features/bard-jack-of-all-trades","name":"Jack of All Trades","level":{"index":"bard-2","name":"Bard 2","url":"/api/2024/classes/bard/levels/2"},"class":{"index":"bard","name":"Bard","url":"/api/2024/classes/bard"},"description":"You can add half your Proficiency Bonus (round down) to any ability check you make that uses a skill proficiency you lack and that doesn''t otherwise use your Proficiency Bonus.\n  For example, if you make a Strength (Athletics) check and lack Athletics proficiency, you can add half your Proficiency Bonus to the check."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Bard Subclass","desc":"You gain a Bard subclass of your choice. A subclass is a specialization that grants you features at certain Bard levels. For the rest of your career, you gain each of your subclass''s features that are of your Bard level or lower."}'::jsonb, '{"index":"bard-subclass","url":"/api/2024/features/bard-subclass","name":"Bard Subclass","level":{"index":"bard-3","name":"Bard 3","url":"/api/2024/classes/bard/levels/3"},"class":{"index":"bard","name":"Bard","url":"/api/2024/classes/bard"},"description":"You gain a Bard subclass of your choice. A subclass is a specialization that grants you features at certain Bard levels. For the rest of your career, you gain each of your subclass''s features that are of your Bard level or lower."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Ability Score Improvement","desc":"You gain the Ability Score Improvement feat (see \"Feats\") or another feat of your choice for which you qualify. You gain this feature again at Bard levels 8, 12, and 16."}'::jsonb, '{"index":"bard-ability-score-improvement","url":"/api/2024/features/bard-ability-score-improvement","name":"Ability Score Improvement","level":{"index":"bard-4","name":"Bard 4","url":"/api/2024/classes/bard/levels/4"},"class":{"index":"bard","name":"Bard","url":"/api/2024/classes/bard"},"description":"You gain the Ability Score Improvement feat (see \"Feats\") or another feat of your choice for which you qualify. You gain this feature again at Bard levels 8, 12, and 16."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Font of Inspiration","desc":"You now regain all your expended uses of Bardic In- spiration when you finish a Short or Long Rest.\n  In addition, you can expend a spell slot (no action required) to regain one expended use of Bardic Inspiration."}'::jsonb, '{"index":"bard-font-of-inspiration","url":"/api/2024/features/bard-font-of-inspiration","name":"Font of Inspiration","level":{"index":"bard-5","name":"Bard 5","url":"/api/2024/classes/bard/levels/5"},"class":{"index":"bard","name":"Bard","url":"/api/2024/classes/bard"},"description":"You now regain all your expended uses of Bardic In- spiration when you finish a Short or Long Rest.\n  In addition, you can expend a spell slot (no action required) to regain one expended use of Bardic Inspiration."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Countercharm","desc":"You can use musical notes or words of power to dis- rupt mind-influencing effects. If you or a creature within 30 feet of you fails a saving throw against an effect that applies the Charmed or Frightened con- dition, you can take a Reaction to cause the save to be rerolled, and the new roll has Advantage."}'::jsonb, '{"index":"bard-countercharm","url":"/api/2024/features/bard-countercharm","name":"Countercharm","level":{"index":"bard-7","name":"Bard 7","url":"/api/2024/classes/bard/levels/7"},"class":{"index":"bard","name":"Bard","url":"/api/2024/classes/bard"},"description":"You can use musical notes or words of power to dis- rupt mind-influencing effects. If you or a creature within 30 feet of you fails a saving throw against an effect that applies the Charmed or Frightened con- dition, you can take a Reaction to cause the save to be rerolled, and the new roll has Advantage."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Magical Secrets","desc":"You''ve learned secrets from various magical tradi- tions. Whenever you reach a Bard level (including this level) and the Prepared Spells number in the Bard Features table increases, you can choose any of your new prepared spells from the Bard, Cleric, Druid, and Wizard spell lists, and the chosen spells count as Bard spells for you (see a class''s section for its spell list). In addition, whenever you replace a spell prepared for this class, you can replace it with a spell from those lists."}'::jsonb, '{"index":"bard-magical-secrets","url":"/api/2024/features/bard-magical-secrets","name":"Magical Secrets","level":{"index":"bard-10","name":"Bard 10","url":"/api/2024/classes/bard/levels/10"},"class":{"index":"bard","name":"Bard","url":"/api/2024/classes/bard"},"description":"You''ve learned secrets from various magical tradi- tions. Whenever you reach a Bard level (including this level) and the Prepared Spells number in the Bard Features table increases, you can choose any of your new prepared spells from the Bard, Cleric, Druid, and Wizard spell lists, and the chosen spells count as Bard spells for you (see a class''s section for its spell list). In addition, whenever you replace a spell prepared for this class, you can replace it with a spell from those lists."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Superior Inspiration","desc":"When you roll Initiative, you regain expended uses of Bardic Inspiration until you have two if you have fewer than that."}'::jsonb, '{"index":"bard-superior-inspiration","url":"/api/2024/features/bard-superior-inspiration","name":"Superior Inspiration","level":{"index":"bard-18","name":"Bard 18","url":"/api/2024/classes/bard/levels/18"},"class":{"index":"bard","name":"Bard","url":"/api/2024/classes/bard"},"description":"When you roll Initiative, you regain expended uses of Bardic Inspiration until you have two if you have fewer than that."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Epic Boon","desc":"You gain an Epic Boon feat (see \"Feats\") or another feat of your choice for which you qualify. Boon of Spell Recall is recommended."}'::jsonb, '{"index":"bard-epic-boon","url":"/api/2024/features/bard-epic-boon","name":"Epic Boon","level":{"index":"bard-19","name":"Bard 19","url":"/api/2024/classes/bard/levels/19"},"class":{"index":"bard","name":"Bard","url":"/api/2024/classes/bard"},"description":"You gain an Epic Boon feat (see \"Feats\") or another feat of your choice for which you qualify. Boon of Spell Recall is recommended."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Words of Creation","desc":"You have mastered two of the Words of Creation: the words of life and death. You therefore always have the Power Word Heal and Power Word Kill spells prepared. When you cast either spell, you can target a second creature with it if that creature is within 10 feet of the first target."}'::jsonb, '{"index":"bard-words-of-creation","url":"/api/2024/features/bard-words-of-creation","name":"Words of Creation","level":{"index":"bard-20","name":"Bard 20","url":"/api/2024/classes/bard/levels/20"},"class":{"index":"bard","name":"Bard","url":"/api/2024/classes/bard"},"description":"You have mastered two of the Words of Creation: the words of life and death. You therefore always have the Power Word Heal and Power Word Kill spells prepared. When you cast either spell, you can target a second creature with it if that creature is within 10 feet of the first target."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Bonus Proficiencies","desc":"You gain proficiency with three skills of your choice."}'::jsonb, '{"index":"lore-bonus-proficiencies","url":"/api/2024/features/lore-bonus-proficiencies","name":"Bonus Proficiencies","level":{"index":"bard-3","name":"Bard 3","url":"/api/2024/classes/bard/levels/3"},"class":{"index":"bard","name":"Bard","url":"/api/2024/classes/bard"},"subclass":{"index":"college-of-lore","name":"College of Lore","url":"/api/2024/subclasses/college-of-lore"},"description":"You gain proficiency with three skills of your choice."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Cutting Words","desc":"You learn to use your wit to supernaturally distract, confuse, and otherwise sap the confidence and com- petence of others. When a creature that you can see within 60 feet of yourself makes a damage roll or succeeds on an ability check or attack roll, you can take a Reaction to expend one use of your Bardic Inspiration; roll your Bardic Inspiration die, and subtract the number rolled from the creature''s roll, reducing the damage or potentially turning the suc- cess into a failure."}'::jsonb, '{"index":"lore-cutting-words","url":"/api/2024/features/lore-cutting-words","name":"Cutting Words","level":{"index":"bard-3","name":"Bard 3","url":"/api/2024/classes/bard/levels/3"},"class":{"index":"bard","name":"Bard","url":"/api/2024/classes/bard"},"subclass":{"index":"college-of-lore","name":"College of Lore","url":"/api/2024/subclasses/college-of-lore"},"description":"You learn to use your wit to supernaturally distract, confuse, and otherwise sap the confidence and com- petence of others. When a creature that you can see within 60 feet of yourself makes a damage roll or succeeds on an ability check or attack roll, you can take a Reaction to expend one use of your Bardic Inspiration; roll your Bardic Inspiration die, and subtract the number rolled from the creature''s roll, reducing the damage or potentially turning the suc- cess into a failure."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Magical Discoveries","desc":"You learn two spells of your choice. These spells can come from the Cleric, Druid, or Wizard spell list or any combination thereof (see a class''s section for its spell list). A spell you choose must be a cantrip or a spell for which you have spell slots, as shown in the Bard Features table.\n  You always have the chosen spells prepared, and whenever you gain a Bard level, you can replace one of the spells with another spell that meets these requirements."}'::jsonb, '{"index":"lore-magical-discoveries","url":"/api/2024/features/lore-magical-discoveries","name":"Magical Discoveries","level":{"index":"bard-6","name":"Bard 6","url":"/api/2024/classes/bard/levels/6"},"class":{"index":"bard","name":"Bard","url":"/api/2024/classes/bard"},"subclass":{"index":"college-of-lore","name":"College of Lore","url":"/api/2024/subclasses/college-of-lore"},"description":"You learn two spells of your choice. These spells can come from the Cleric, Druid, or Wizard spell list or any combination thereof (see a class''s section for its spell list). A spell you choose must be a cantrip or a spell for which you have spell slots, as shown in the Bard Features table.\n  You always have the chosen spells prepared, and whenever you gain a Bard level, you can replace one of the spells with another spell that meets these requirements."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Peerless Skill","desc":"When you make an ability check or attack roll and fail, you can expend one use of Bardic Inspiration; roll the Bardic Inspiration die, and add the number rolled to the d20, potentially turning a failure into a success. On a failure, the Bardic Inspiration isn''t expended."}'::jsonb, '{"index":"lore-peerless-skill","url":"/api/2024/features/lore-peerless-skill","name":"Peerless Skill","level":{"index":"bard-14","name":"Bard 14","url":"/api/2024/classes/bard/levels/14"},"class":{"index":"bard","name":"Bard","url":"/api/2024/classes/bard"},"subclass":{"index":"college-of-lore","name":"College of Lore","url":"/api/2024/subclasses/college-of-lore"},"description":"When you make an ability check or attack roll and fail, you can expend one use of Bardic Inspiration; roll the Bardic Inspiration die, and add the number rolled to the d20, potentially turning a failure into a success. On a failure, the Bardic Inspiration isn''t expended."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Spellcasting","desc":"You have learned to cast spells through prayer and meditation. See \"Spells\" for the rules on spellcasting. The information below details how you use those rules with Cleric spells, which appear on the Cleric spell list later in the class''s description.\n  Cantrips. You know three cantrips of your choice from the Cleric spell list. Guidance, Sacred Flame, and Thaumaturgy are recommended.\n  Whenever you gain a Cleric level, you can replace one of your cantrips with another cantrip of your choice from the Cleric spell list.\n  When you reach Cleric levels 4 and 10, you learn another cantrip of your choice from the Cleric spell list, as shown in the Cantrips column of the Cleric Features table.\n  Spell Slots. The Cleric Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest.\n  Prepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose four level 1 spells from the Cleric spell list. Bless, Cure Wounds, Guiding Bolt, and Shield of Faith are recommended.\n  The number of spells on your list increases as you gain Cleric levels, as shown in the Prepared Spells column of the Cleric Features table. Whenever that number increases, choose additional spells from the Cleric spell list until the number of spells on your list matches the number on the table. The chosen spells must be of a level for which you have spell slots. For example, if you''re a level 3 Cleric, your list of prepared spells can include six spells of levels 1 and 2 in any combination.\n  If another Cleric feature gives you spells that you always have prepared, those spells don''t count against the number of spells you can prepare with this feature, but those spells otherwise count as Cleric spells for you.\n  Changing Your Prepared Spells. Whenever you finish a Long Rest, you can change your list of prepared spells, replacing any of the spells there with other Cleric spells for which you have spell slots.\n  Spellcasting Ability. Wisdom is your spellcasting ability for your Cleric spells.\n  Spellcasting Focus. You can use a Holy Symbol as a Spellcasting Focus for your Cleric spells."}'::jsonb, '{"index":"cleric-spellcasting","url":"/api/2024/features/cleric-spellcasting","name":"Spellcasting","level":{"index":"cleric-1","name":"Cleric 1","url":"/api/2024/classes/cleric/levels/1"},"class":{"index":"cleric","name":"Cleric","url":"/api/2024/classes/cleric"},"description":"You have learned to cast spells through prayer and meditation. See \"Spells\" for the rules on spellcasting. The information below details how you use those rules with Cleric spells, which appear on the Cleric spell list later in the class''s description.\n  Cantrips. You know three cantrips of your choice from the Cleric spell list. Guidance, Sacred Flame, and Thaumaturgy are recommended.\n  Whenever you gain a Cleric level, you can replace one of your cantrips with another cantrip of your choice from the Cleric spell list.\n  When you reach Cleric levels 4 and 10, you learn another cantrip of your choice from the Cleric spell list, as shown in the Cantrips column of the Cleric Features table.\n  Spell Slots. The Cleric Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest.\n  Prepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose four level 1 spells from the Cleric spell list. Bless, Cure Wounds, Guiding Bolt, and Shield of Faith are recommended.\n  The number of spells on your list increases as you gain Cleric levels, as shown in the Prepared Spells column of the Cleric Features table. Whenever that number increases, choose additional spells from the Cleric spell list until the number of spells on your list matches the number on the table. The chosen spells must be of a level for which you have spell slots. For example, if you''re a level 3 Cleric, your list of prepared spells can include six spells of levels 1 and 2 in any combination.\n  If another Cleric feature gives you spells that you always have prepared, those spells don''t count against the number of spells you can prepare with this feature, but those spells otherwise count as Cleric spells for you.\n  Changing Your Prepared Spells. Whenever you finish a Long Rest, you can change your list of prepared spells, replacing any of the spells there with other Cleric spells for which you have spell slots.\n  Spellcasting Ability. Wisdom is your spellcasting ability for your Cleric spells.\n  Spellcasting Focus. You can use a Holy Symbol as a Spellcasting Focus for your Cleric spells."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Divine Order","desc":"You have dedicated yourself to one of the following sacred roles of your choice.\n  Protector. Trained for battle, you gain proficiency with Martial weapons and training with Heavy armor.\n  Thaumaturge. You know one extra cantrip from the Cleric spell list. In addition, your mystical connection to the divine gives you a bonus to your Intelligence (Arcana or Religion) checks. The bonus equals your Wisdom modifier (minimum of +1).\n"}'::jsonb, '{"index":"cleric-divine-order","url":"/api/2024/features/cleric-divine-order","name":"Divine Order","level":{"index":"cleric-1","name":"Cleric 1","url":"/api/2024/classes/cleric/levels/1"},"class":{"index":"cleric","name":"Cleric","url":"/api/2024/classes/cleric"},"description":"You have dedicated yourself to one of the following sacred roles of your choice.\n  Protector. Trained for battle, you gain proficiency with Martial weapons and training with Heavy armor.\n  Thaumaturge. You know one extra cantrip from the Cleric spell list. In addition, your mystical connection to the divine gives you a bonus to your Intelligence (Arcana or Religion) checks. The bonus equals your Wisdom modifier (minimum of +1).\n"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Channel Divinity","desc":"You can channel divine energy directly from the Outer Planes to fuel magical effects. You start with two such effects: Divine Spark and Turn Undead, each of which is described below. Each time you use this class''s Channel Divinity, choose which Channel Divinity effect from this class to create. You gain additional effect options at higher Cleric levels.\nYou can use this class''s Channel Divinity twice. You regain one of its expended uses when you finish a Short Rest, and you regain all expended uses when you finish a Long Rest. You gain additional uses when you reach certain Cleric levels, as shown in the Channel Divinity column of the Cleric Features table.\n  If a Channel Divinity effect requires a saving throw, the DC equals the spell save DC from this class''s Spellcasting feature.\n  Divine Spark. As a Magic action, you point your Holy Symbol at another creature you can see within 30 feet of yourself and focus divine energy at it.\nRoll 1d8 and add your Wisdom modifier. You either restore Hit Points to the creature equal to that total or force the creature to make a Constitution saving throw. On a failed save, the creature takes Necrotic or Radiant damage (your choice) equal to that total. On a successful save, the creature takes half as much damage (round down).\n  You roll an additional d8 when you reach Cleric levels 7 (2d8), 13 (3d8), and 18 (4d8).\n  Turn Undead. As a Magic action, you present your Holy Symbol and censure Undead creatures. Each Undead of your choice within 30 feet of you must make a Wisdom saving throw. If the creature fails its save, it has the Frightened and Incapacitated conditions for 1 minute. For that duration, it tries\nto move as far from you as it can on its turns. This effect ends early on the creature if it takes any damage, if you have the Incapacitated condition, or if you die.\n"}'::jsonb, '{"index":"cleric-channel-divinity","url":"/api/2024/features/cleric-channel-divinity","name":"Channel Divinity","level":{"index":"cleric-2","name":"Cleric 2","url":"/api/2024/classes/cleric/levels/2"},"class":{"index":"cleric","name":"Cleric","url":"/api/2024/classes/cleric"},"description":"You can channel divine energy directly from the Outer Planes to fuel magical effects. You start with two such effects: Divine Spark and Turn Undead, each of which is described below. Each time you use this class''s Channel Divinity, choose which Channel Divinity effect from this class to create. You gain additional effect options at higher Cleric levels.\nYou can use this class''s Channel Divinity twice. You regain one of its expended uses when you finish a Short Rest, and you regain all expended uses when you finish a Long Rest. You gain additional uses when you reach certain Cleric levels, as shown in the Channel Divinity column of the Cleric Features table.\n  If a Channel Divinity effect requires a saving throw, the DC equals the spell save DC from this class''s Spellcasting feature.\n  Divine Spark. As a Magic action, you point your Holy Symbol at another creature you can see within 30 feet of yourself and focus divine energy at it.\nRoll 1d8 and add your Wisdom modifier. You either restore Hit Points to the creature equal to that total or force the creature to make a Constitution saving throw. On a failed save, the creature takes Necrotic or Radiant damage (your choice) equal to that total. On a successful save, the creature takes half as much damage (round down).\n  You roll an additional d8 when you reach Cleric levels 7 (2d8), 13 (3d8), and 18 (4d8).\n  Turn Undead. As a Magic action, you present your Holy Symbol and censure Undead creatures. Each Undead of your choice within 30 feet of you must make a Wisdom saving throw. If the creature fails its save, it has the Frightened and Incapacitated conditions for 1 minute. For that duration, it tries\nto move as far from you as it can on its turns. This effect ends early on the creature if it takes any damage, if you have the Incapacitated condition, or if you die.\n"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Cleric Subclass","desc":"You gain a Cleric subclass of your choice. A subclass is a specialization that grants you features at certain Cleric levels. For the rest of your career, you gain each of your subclass''s features that are of your Cleric level or lower.\n"}'::jsonb, '{"index":"cleric-subclass","url":"/api/2024/features/cleric-subclass","name":"Cleric Subclass","level":{"index":"cleric-3","name":"Cleric 3","url":"/api/2024/classes/cleric/levels/3"},"class":{"index":"cleric","name":"Cleric","url":"/api/2024/classes/cleric"},"description":"You gain a Cleric subclass of your choice. A subclass is a specialization that grants you features at certain Cleric levels. For the rest of your career, you gain each of your subclass''s features that are of your Cleric level or lower.\n"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Ability Score Improvement","desc":"You gain the Ability Score Improvement feat (see \"Feats\") or another feat of your choice for which you qualify. You gain this feature again at Cleric levels 8, 12, and 16.\n"}'::jsonb, '{"index":"cleric-ability-score-improvement","url":"/api/2024/features/cleric-ability-score-improvement","name":"Ability Score Improvement","level":{"index":"cleric-4","name":"Cleric 4","url":"/api/2024/classes/cleric/levels/4"},"class":{"index":"cleric","name":"Cleric","url":"/api/2024/classes/cleric"},"description":"You gain the Ability Score Improvement feat (see \"Feats\") or another feat of your choice for which you qualify. You gain this feature again at Cleric levels 8, 12, and 16.\n"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Sear Undead","desc":"Whenever you use Turn Undead, you can roll a number of d8s equal to your Wisdom modifier (minimum of 1d8) and add the rolls together. Each Undead that fails its saving throw against that use of Turn Undead takes Radiant damage equal to the roll''s total. This damage doesn''t end the turn effect.\n"}'::jsonb, '{"index":"cleric-sear-undead","url":"/api/2024/features/cleric-sear-undead","name":"Sear Undead","level":{"index":"cleric-5","name":"Cleric 5","url":"/api/2024/classes/cleric/levels/5"},"class":{"index":"cleric","name":"Cleric","url":"/api/2024/classes/cleric"},"description":"Whenever you use Turn Undead, you can roll a number of d8s equal to your Wisdom modifier (minimum of 1d8) and add the rolls together. Each Undead that fails its saving throw against that use of Turn Undead takes Radiant damage equal to the roll''s total. This damage doesn''t end the turn effect.\n"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Blessed Strikes","desc":"Divine power infuses you in battle. You gain one of the following options of your choice (if you get either option from a Cleric subclass in an older book, use only the option you choose for this feature).\n  Divine Strike. Once on each of your turns when you hit a creature with an attack roll using a weapon, you can cause the target to take an extra 1d8 Necrotic or Radiant damage (your choice).\n  Potent Spellcasting. Add your Wisdom modifier to the damage you deal with any Cleric cantrip.\n"}'::jsonb, '{"index":"cleric-blessed-strikes","url":"/api/2024/features/cleric-blessed-strikes","name":"Blessed Strikes","level":{"index":"cleric-7","name":"Cleric 7","url":"/api/2024/classes/cleric/levels/7"},"class":{"index":"cleric","name":"Cleric","url":"/api/2024/classes/cleric"},"description":"Divine power infuses you in battle. You gain one of the following options of your choice (if you get either option from a Cleric subclass in an older book, use only the option you choose for this feature).\n  Divine Strike. Once on each of your turns when you hit a creature with an attack roll using a weapon, you can cause the target to take an extra 1d8 Necrotic or Radiant damage (your choice).\n  Potent Spellcasting. Add your Wisdom modifier to the damage you deal with any Cleric cantrip.\n"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Divine Intervention","desc":"You can call on your deity or pantheon to intervene on your behalf. As a Magic action, choose any Cleric spell of level 5 or lower that doesn''t require a\nReaction to cast. As part of the same action, you cast that spell without expending a spell slot or needing Material components. You can''t use this feature again until you finish a Long Rest.\n"}'::jsonb, '{"index":"cleric-divine-intervention","url":"/api/2024/features/cleric-divine-intervention","name":"Divine Intervention","level":{"index":"cleric-10","name":"Cleric 10","url":"/api/2024/classes/cleric/levels/10"},"class":{"index":"cleric","name":"Cleric","url":"/api/2024/classes/cleric"},"description":"You can call on your deity or pantheon to intervene on your behalf. As a Magic action, choose any Cleric spell of level 5 or lower that doesn''t require a\nReaction to cast. As part of the same action, you cast that spell without expending a spell slot or needing Material components. You can''t use this feature again until you finish a Long Rest.\n"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Improved Blessed Strikes","desc":"The option you chose for Blessed Strikes grows more powerful.\n  Divine Strike. The extra damage of your Divine Strike increases to 2d8.\n  Potent Spellcasting. When you cast a Cleric cantrip and deal damage to a creature with it, you can give vitality to yourself or another creature within 60 feet of yourself, granting a number of Temporary Hit Points equal to twice your Wisdom modifier.\n"}'::jsonb, '{"index":"cleric-improved-blessed-strikes","url":"/api/2024/features/cleric-improved-blessed-strikes","name":"Improved Blessed Strikes","level":{"index":"cleric-14","name":"Cleric 14","url":"/api/2024/classes/cleric/levels/14"},"class":{"index":"cleric","name":"Cleric","url":"/api/2024/classes/cleric"},"description":"The option you chose for Blessed Strikes grows more powerful.\n  Divine Strike. The extra damage of your Divine Strike increases to 2d8.\n  Potent Spellcasting. When you cast a Cleric cantrip and deal damage to a creature with it, you can give vitality to yourself or another creature within 60 feet of yourself, granting a number of Temporary Hit Points equal to twice your Wisdom modifier.\n"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Epic Boon","desc":"You gain an Epic Boon feat (see \"Feats\") or another feat of your choice for which you qualify. Boon of Fate is recommended.\n"}'::jsonb, '{"index":"cleric-epic-boon","url":"/api/2024/features/cleric-epic-boon","name":"Epic Boon","level":{"index":"cleric-19","name":"Cleric 19","url":"/api/2024/classes/cleric/levels/19"},"class":{"index":"cleric","name":"Cleric","url":"/api/2024/classes/cleric"},"description":"You gain an Epic Boon feat (see \"Feats\") or another feat of your choice for which you qualify. Boon of Fate is recommended.\n"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Greater Divine Intervention","desc":"You can call on even more powerful divine intervention. When you use your Divine Intervention feature, you can choose Wish when you select a spell.\nIf you do so, you can''t use Divine Intervention again until you finish 2d4 Long Rests.\n"}'::jsonb, '{"index":"cleric-greater-divine-intervention","url":"/api/2024/features/cleric-greater-divine-intervention","name":"Greater Divine Intervention","level":{"index":"cleric-20","name":"Cleric 20","url":"/api/2024/classes/cleric/levels/20"},"class":{"index":"cleric","name":"Cleric","url":"/api/2024/classes/cleric"},"description":"You can call on even more powerful divine intervention. When you use your Divine Intervention feature, you can choose Wish when you select a spell.\nIf you do so, you can''t use Divine Intervention again until you finish 2d4 Long Rests.\n"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Disciple of Life","desc":"When a spell you cast with a spell slot restores Hit Points to a creature, that creature regains additional Hit Points on the turn you cast the spell. The additional Hit Points equal 2 plus the spell slot''s level.\n"}'::jsonb, '{"index":"life-disciple-of-life","url":"/api/2024/features/life-disciple-of-life","name":"Disciple of Life","level":{"index":"cleric-3","name":"Cleric 3","url":"/api/2024/classes/cleric/levels/3"},"class":{"index":"cleric","name":"Cleric","url":"/api/2024/classes/cleric"},"subclass":{"index":"life-domain","name":"Life Domain","url":"/api/2024/subclasses/life-domain"},"description":"When a spell you cast with a spell slot restores Hit Points to a creature, that creature regains additional Hit Points on the turn you cast the spell. The additional Hit Points equal 2 plus the spell slot''s level.\n"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Life Domain Spells","desc":"Your connection to this divine domain ensures you always have certain spells ready. When you reach a Cleric level specified in the Life Domain Spells table, you thereafter always have the listed spells prepared.\nLife Domain Spells\nCleric Level | Prepared Spells\n3 | Aid, Bless, Cure Wounds, Lesser Restoration\n5 | Mass Healing Word, Revivify\n7 | Aura of Life, Death Ward\n9 | Greater Restoration, Mass Cure Wounds\n"}'::jsonb, '{"index":"life-domain-spells","url":"/api/2024/features/life-domain-spells","name":"Life Domain Spells","level":{"index":"cleric-3","name":"Cleric 3","url":"/api/2024/classes/cleric/levels/3"},"class":{"index":"cleric","name":"Cleric","url":"/api/2024/classes/cleric"},"subclass":{"index":"life-domain","name":"Life Domain","url":"/api/2024/subclasses/life-domain"},"description":"Your connection to this divine domain ensures you always have certain spells ready. When you reach a Cleric level specified in the Life Domain Spells table, you thereafter always have the listed spells prepared.\nLife Domain Spells\nCleric Level | Prepared Spells\n3 | Aid, Bless, Cure Wounds, Lesser Restoration\n5 | Mass Healing Word, Revivify\n7 | Aura of Life, Death Ward\n9 | Greater Restoration, Mass Cure Wounds\n"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Preserve Life","desc":"As a Magic action, you present your Holy Symbol and expend a use of your Channel Divinity to evoke healing energy that can restore a number of Hit Points equal to five times your Cleric level. Choose Bloodied creatures within 30 feet of yourself (which can include you), and divide those Hit Points among them. This feature can restore a creature to no more than half its Hit Point maximum.\n"}'::jsonb, '{"index":"life-preserve-life","url":"/api/2024/features/life-preserve-life","name":"Preserve Life","level":{"index":"cleric-3","name":"Cleric 3","url":"/api/2024/classes/cleric/levels/3"},"class":{"index":"cleric","name":"Cleric","url":"/api/2024/classes/cleric"},"subclass":{"index":"life-domain","name":"Life Domain","url":"/api/2024/subclasses/life-domain"},"description":"As a Magic action, you present your Holy Symbol and expend a use of your Channel Divinity to evoke healing energy that can restore a number of Hit Points equal to five times your Cleric level. Choose Bloodied creatures within 30 feet of yourself (which can include you), and divide those Hit Points among them. This feature can restore a creature to no more than half its Hit Point maximum.\n"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Blessed Healer","desc":"The healing spells you cast on others heal you as well. Immediately after you cast a spell with a spell slot that restores Hit Points to one or more creatures other than yourself, you regain Hit Points equal to 2 plus the spell slot''s level.\n"}'::jsonb, '{"index":"life-blessed-healer","url":"/api/2024/features/life-blessed-healer","name":"Blessed Healer","level":{"index":"cleric-6","name":"Cleric 6","url":"/api/2024/classes/cleric/levels/6"},"class":{"index":"cleric","name":"Cleric","url":"/api/2024/classes/cleric"},"subclass":{"index":"life-domain","name":"Life Domain","url":"/api/2024/subclasses/life-domain"},"description":"The healing spells you cast on others heal you as well. Immediately after you cast a spell with a spell slot that restores Hit Points to one or more creatures other than yourself, you regain Hit Points equal to 2 plus the spell slot''s level.\n"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Supreme Healing","desc":"When you would normally roll one or more dice to restore Hit Points to a creature with a spell or Channel Divinity, don''t roll those dice for the healing; instead use the highest number possible for each die. For example, instead of restoring 2d6 Hit Points to a creature with a spell, you restore 12.\n"}'::jsonb, '{"index":"life-supreme-healing","url":"/api/2024/features/life-supreme-healing","name":"Supreme Healing","level":{"index":"cleric-17","name":"Cleric 17","url":"/api/2024/classes/cleric/levels/17"},"class":{"index":"cleric","name":"Cleric","url":"/api/2024/classes/cleric"},"subclass":{"index":"life-domain","name":"Life Domain","url":"/api/2024/subclasses/life-domain"},"description":"When you would normally roll one or more dice to restore Hit Points to a creature with a spell or Channel Divinity, don''t roll those dice for the healing; instead use the highest number possible for each die. For example, instead of restoring 2d6 Hit Points to a creature with a spell, you restore 12.\n"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Spellcasting","desc":"You have learned to cast spells through studying the mystical forces of nature. See \"Spells\" for the rules on spellcasting. The information below details how you use those rules with Druid spells, which appear on the Druid spell list later in the class''s description.\n  Cantrips. You know two cantrips of your choice from the Druid spell list. Druidcraft and Produce Flame are recommended.\n  Whenever you gain a Druid level, you can replace one of your cantrips with another cantrip of your choice from the Druid spell list.\n  When you reach Druid levels 4 and 10, you learn another cantrip of your choice from the Druid spell list, as shown in the Cantrips column of the Druid Features table.\n  Spell Slots. The Druid Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest.\n  Prepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose four level 1 spells from the Druid spell list. Animal Friendship, Cure Wounds, Faerie Fire, and Thunderwave are recommended.\n  The number of spells on your list increases as you gain Druid levels, as shown in the Prepared Spells column of the Druid Features table. Whenever that number increases, choose additional spells from the Druid spell list until the number of spells on your list matches the number on the table. The chosen spells must be of a level for which you have spell slots. For example, if you''re a level 3 Druid, your list of prepared spells can include six spells of levels 1 and 2 in any combination.\n  If another Druid feature gives you spells that you always have prepared, those spells don''t count against the number of spells you can prepare with this feature, but those spells otherwise count as Druid spells for you.\n  Changing Your Prepared Spells. Whenever you finish a Long Rest, you can change your list of prepared spells, replacing any of the spells with other Druid spells for which you have spell slots.\n  Spellcasting Ability. Wisdom is your spellcasting ability for your Druid spells.\n  Spellcasting Focus. You can use a Druidic Focus as a Spellcasting Focus for your Druid spells."}'::jsonb, '{"index":"druid-spellcasting","url":"/api/2024/features/druid-spellcasting","name":"Spellcasting","level":{"index":"druid-1","url":"/api/2024/classes/druid/levels/1","name":"Druid 1"},"class":{"index":"druid","name":"Druid","url":"/api/2024/classes/druid"},"description":"You have learned to cast spells through studying the mystical forces of nature. See \"Spells\" for the rules on spellcasting. The information below details how you use those rules with Druid spells, which appear on the Druid spell list later in the class''s description.\n  Cantrips. You know two cantrips of your choice from the Druid spell list. Druidcraft and Produce Flame are recommended.\n  Whenever you gain a Druid level, you can replace one of your cantrips with another cantrip of your choice from the Druid spell list.\n  When you reach Druid levels 4 and 10, you learn another cantrip of your choice from the Druid spell list, as shown in the Cantrips column of the Druid Features table.\n  Spell Slots. The Druid Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest.\n  Prepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose four level 1 spells from the Druid spell list. Animal Friendship, Cure Wounds, Faerie Fire, and Thunderwave are recommended.\n  The number of spells on your list increases as you gain Druid levels, as shown in the Prepared Spells column of the Druid Features table. Whenever that number increases, choose additional spells from the Druid spell list until the number of spells on your list matches the number on the table. The chosen spells must be of a level for which you have spell slots. For example, if you''re a level 3 Druid, your list of prepared spells can include six spells of levels 1 and 2 in any combination.\n  If another Druid feature gives you spells that you always have prepared, those spells don''t count against the number of spells you can prepare with this feature, but those spells otherwise count as Druid spells for you.\n  Changing Your Prepared Spells. Whenever you finish a Long Rest, you can change your list of prepared spells, replacing any of the spells with other Druid spells for which you have spell slots.\n  Spellcasting Ability. Wisdom is your spellcasting ability for your Druid spells.\n  Spellcasting Focus. You can use a Druidic Focus as a Spellcasting Focus for your Druid spells."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Druidic","desc":"You know Druidic, the secret language of Druids. While learning this ancient tongue, you also unlocked the magic of communicating with animals; you always have the Speak with Animals spell prepared.\n  You can use Druidic to leave hidden messages. You and others who know Druidic automatically spot such a message. Others spot the message''s presence with a successful DC 15 Intelligence (Investigation) check but can''t decipher it without magic."}'::jsonb, '{"index":"druid-druidic","url":"/api/2024/features/druid-druidic","name":"Druidic","level":{"index":"druid-1","url":"/api/2024/classes/druid/levels/1","name":"Druid 1"},"class":{"index":"druid","name":"Druid","url":"/api/2024/classes/druid"},"description":"You know Druidic, the secret language of Druids. While learning this ancient tongue, you also unlocked the magic of communicating with animals; you always have the Speak with Animals spell prepared.\n  You can use Druidic to leave hidden messages. You and others who know Druidic automatically spot such a message. Others spot the message''s presence with a successful DC 15 Intelligence (Investigation) check but can''t decipher it without magic."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Primal Order","desc":"You have dedicated yourself to one of the following sacred roles of your choice.\n  Magician. You know one extra cantrip from the Druid spell list. In addition, your mystical connection to nature gives you a bonus to your Intelligence (Arcana or Nature) checks. The bonus equals your Wisdom modifier (minimum bonus of +1).\n  Warden. Trained for battle, you gain proficiency with Martial weapons and training with Medium armor."}'::jsonb, '{"index":"druid-primal-order","url":"/api/2024/features/druid-primal-order","name":"Primal Order","level":{"index":"druid-1","url":"/api/2024/classes/druid/levels/1","name":"Druid 1"},"class":{"index":"druid","name":"Druid","url":"/api/2024/classes/druid"},"description":"You have dedicated yourself to one of the following sacred roles of your choice.\n  Magician. You know one extra cantrip from the Druid spell list. In addition, your mystical connection to nature gives you a bonus to your Intelligence (Arcana or Nature) checks. The bonus equals your Wisdom modifier (minimum bonus of +1).\n  Warden. Trained for battle, you gain proficiency with Martial weapons and training with Medium armor."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Wild Shape","desc":"The power of nature allows you to assume the form of an animal. As a Bonus Action, you shape-shift into a Beast form that you have learned for this feature (see \"Known Forms\" below). You stay in that form for a number of hours equal to half your Druid level or until you use Wild Shape again, have the Incapacitated condition, or die. You can also leave the form early as a Bonus Action.\n  Number of Uses. You can use Wild Shape twice. You regain one expended use when you finish a Short Rest, and you regain all expended uses when you finish a Long Rest.\n  You gain additional uses when you reach certain Druid levels, as shown in the Wild Shape column of the Druid Features table.\n  Known Forms. You know four Beast forms for this feature, chosen from among Beast stat blocks that have a maximum Challenge Rating of 1/4 and that lack a Fly Speed (see \"Animals\" in \"Monsters\" for stat block options). The Rat, Riding Horse, Spider, and Wolf are recommended. Whenever you finish a Long Rest, you can replace one of your known forms with another eligible form.\n  When you reach certain Druid levels, your number of known forms and the maximum Challenge Rating for those forms increases, as shown in the Beast Shapes table. In addition, starting at level 8, you can adopt a form that has a Fly Speed.\n  When choosing known forms, you may look in other sources for eligible Beasts if the Game Master permits you to do so.\n\nBeast Shapes\nDruid Level / Known Forms / Max CR / Fly Speed\n2 / 4 / 1/4 / No\n4 / 6 / 1/2 / No\n8 / 8 / 1 / Yes\n\n  Rules While Shape-Shifted. While in a form, you retain your personality, memories, and ability to speak, and the following rules apply:\nTemporary Hit Points. When you assume a Wild Shape form, you gain a number of Temporary Hit Points equal to your Druid level.\nGame Statistics. Your game statistics are replaced by the Beast''s stat block, but you retain your creature type; Hit Points; Hit Point Dice; Intelligence, Wisdom, and Charisma scores; class features; languages; and feats. You also retain your skill and saving throw proficiencies and use your Proficiency Bonus for them, in addition to gaining the proficiencies of the creature. If a skill or saving throw modifier in the Beast''s stat block is higher than yours, use the one in the stat block.\nNo Spellcasting. You can''t cast spells, but shapeshifting doesn''t break your Concentration or otherwise interfere with a spell you''ve already cast.\nObjects. Your ability to handle objects is determined by the form''s limbs rather than your own. In addition, you choose whether your equipment falls in your space, merges into your new form, or is worn by it. Worn equipment functions as normal, but the GM decides whether it''s practical for the new form to wear a piece of equipment based on the creature''s size and shape. Your equipment doesn''t change size or shape to match the new form, and any equipment that the new form can''t wear must either fall to the ground or merge with the form. Equipment that merges with the form has no effect while you''re in that form."}'::jsonb, '{"index":"druid-wild-shape","url":"/api/2024/features/druid-wild-shape","name":"Wild Shape","level":{"index":"druid-2","url":"/api/2024/classes/druid/levels/2","name":"Druid 2"},"class":{"index":"druid","name":"Druid","url":"/api/2024/classes/druid"},"description":"The power of nature allows you to assume the form of an animal. As a Bonus Action, you shape-shift into a Beast form that you have learned for this feature (see \"Known Forms\" below). You stay in that form for a number of hours equal to half your Druid level or until you use Wild Shape again, have the Incapacitated condition, or die. You can also leave the form early as a Bonus Action.\n  Number of Uses. You can use Wild Shape twice. You regain one expended use when you finish a Short Rest, and you regain all expended uses when you finish a Long Rest.\n  You gain additional uses when you reach certain Druid levels, as shown in the Wild Shape column of the Druid Features table.\n  Known Forms. You know four Beast forms for this feature, chosen from among Beast stat blocks that have a maximum Challenge Rating of 1/4 and that lack a Fly Speed (see \"Animals\" in \"Monsters\" for stat block options). The Rat, Riding Horse, Spider, and Wolf are recommended. Whenever you finish a Long Rest, you can replace one of your known forms with another eligible form.\n  When you reach certain Druid levels, your number of known forms and the maximum Challenge Rating for those forms increases, as shown in the Beast Shapes table. In addition, starting at level 8, you can adopt a form that has a Fly Speed.\n  When choosing known forms, you may look in other sources for eligible Beasts if the Game Master permits you to do so.\n\nBeast Shapes\nDruid Level / Known Forms / Max CR / Fly Speed\n2 / 4 / 1/4 / No\n4 / 6 / 1/2 / No\n8 / 8 / 1 / Yes\n\n  Rules While Shape-Shifted. While in a form, you retain your personality, memories, and ability to speak, and the following rules apply:\nTemporary Hit Points. When you assume a Wild Shape form, you gain a number of Temporary Hit Points equal to your Druid level.\nGame Statistics. Your game statistics are replaced by the Beast''s stat block, but you retain your creature type; Hit Points; Hit Point Dice; Intelligence, Wisdom, and Charisma scores; class features; languages; and feats. You also retain your skill and saving throw proficiencies and use your Proficiency Bonus for them, in addition to gaining the proficiencies of the creature. If a skill or saving throw modifier in the Beast''s stat block is higher than yours, use the one in the stat block.\nNo Spellcasting. You can''t cast spells, but shapeshifting doesn''t break your Concentration or otherwise interfere with a spell you''ve already cast.\nObjects. Your ability to handle objects is determined by the form''s limbs rather than your own. In addition, you choose whether your equipment falls in your space, merges into your new form, or is worn by it. Worn equipment functions as normal, but the GM decides whether it''s practical for the new form to wear a piece of equipment based on the creature''s size and shape. Your equipment doesn''t change size or shape to match the new form, and any equipment that the new form can''t wear must either fall to the ground or merge with the form. Equipment that merges with the form has no effect while you''re in that form."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Wild Companion","desc":"You can summon a nature spirit that assumes an animal form to aid you. As a Magic action, you can expend a spell slot or a use of Wild Shape to cast the Find Familiar spell without Material components.\n  When you cast the spell in this way, the familiar is Fey and disappears when you finish a Long Rest."}'::jsonb, '{"index":"druid-wild-companion","url":"/api/2024/features/druid-wild-companion","name":"Wild Companion","level":{"index":"druid-2","url":"/api/2024/classes/druid/levels/2","name":"Druid 2"},"class":{"index":"druid","name":"Druid","url":"/api/2024/classes/druid"},"description":"You can summon a nature spirit that assumes an animal form to aid you. As a Magic action, you can expend a spell slot or a use of Wild Shape to cast the Find Familiar spell without Material components.\n  When you cast the spell in this way, the familiar is Fey and disappears when you finish a Long Rest."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Druid Subclass","desc":"You gain a Druid subclass of your choice. A subclass is a specialization that grants you features at certain Druid levels. For the rest of your career, you gain each of your subclass''s features that are of your Druid level or lower."}'::jsonb, '{"index":"druid-subclass","url":"/api/2024/features/druid-subclass","name":"Druid Subclass","level":{"index":"druid-3","url":"/api/2024/classes/druid/levels/3","name":"Druid 3"},"class":{"index":"druid","name":"Druid","url":"/api/2024/classes/druid"},"description":"You gain a Druid subclass of your choice. A subclass is a specialization that grants you features at certain Druid levels. For the rest of your career, you gain each of your subclass''s features that are of your Druid level or lower."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Ability Score Improvement","desc":"You gain the Ability Score Improvement feat (see \"Feats\") or another feat of your choice for which you qualify. You gain this feature again at Druid levels 8, 12, and 16."}'::jsonb, '{"index":"druid-ability-score-improvement","url":"/api/2024/features/druid-ability-score-improvement","name":"Ability Score Improvement","level":{"index":"druid-4","url":"/api/2024/classes/druid/levels/4","name":"Druid 4"},"class":{"index":"druid","name":"Druid","url":"/api/2024/classes/druid"},"description":"You gain the Ability Score Improvement feat (see \"Feats\") or another feat of your choice for which you qualify. You gain this feature again at Druid levels 8, 12, and 16."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Wild Resurgence","desc":"Once on each of your turns, if you have no uses of Wild Shape left, you can give yourself one use by expending a spell slot (no action required).\n  In addition, you can expend one use of Wild Shape (no action required) to give yourself a level 1 spell slot, but you can''t do so again until you finish a Long Rest."}'::jsonb, '{"index":"druid-wild-resurgence","url":"/api/2024/features/druid-wild-resurgence","name":"Wild Resurgence","level":{"index":"druid-5","url":"/api/2024/classes/druid/levels/5","name":"Druid 5"},"class":{"index":"druid","name":"Druid","url":"/api/2024/classes/druid"},"description":"Once on each of your turns, if you have no uses of Wild Shape left, you can give yourself one use by expending a spell slot (no action required).\n  In addition, you can expend one use of Wild Shape (no action required) to give yourself a level 1 spell slot, but you can''t do so again until you finish a Long Rest."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Elemental Fury","desc":"The might of the elements flows through you. You gain one of the following options of your choice.\n  Potent Spellcasting. Add your Wisdom modifier to the damage you deal with any Druid cantrip.\n  Primal Strike. Once on each of your turns when you hit a creature with an attack roll using a weapon or a Beast form''s attack in Wild Shape, you can cause the target to take an extra 1d8 Cold, Fire, Lightning, or Thunder damage (choose when you hit)."}'::jsonb, '{"index":"druid-elemental-fury","url":"/api/2024/features/druid-elemental-fury","name":"Elemental Fury","level":{"index":"druid-7","url":"/api/2024/classes/druid/levels/7","name":"Druid 7"},"class":{"index":"druid","name":"Druid","url":"/api/2024/classes/druid"},"description":"The might of the elements flows through you. You gain one of the following options of your choice.\n  Potent Spellcasting. Add your Wisdom modifier to the damage you deal with any Druid cantrip.\n  Primal Strike. Once on each of your turns when you hit a creature with an attack roll using a weapon or a Beast form''s attack in Wild Shape, you can cause the target to take an extra 1d8 Cold, Fire, Lightning, or Thunder damage (choose when you hit)."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Improved Elemental Fury","desc":"The option you chose for Elemental Fury grows more powerful, as detailed below.\n  Potent Spellcasting. When you cast a Druid cantrip with a range of 10 feet or greater, the spell''s range increases by 300 feet.\n  Primal Strike. The extra damage of your Primal Strike increases to 2d8."}'::jsonb, '{"index":"druid-improved-elemental-fury","url":"/api/2024/features/druid-improved-elemental-fury","name":"Improved Elemental Fury","level":{"index":"druid-15","url":"/api/2024/classes/druid/levels/15","name":"Druid 15"},"class":{"index":"druid","name":"Druid","url":"/api/2024/classes/druid"},"description":"The option you chose for Elemental Fury grows more powerful, as detailed below.\n  Potent Spellcasting. When you cast a Druid cantrip with a range of 10 feet or greater, the spell''s range increases by 300 feet.\n  Primal Strike. The extra damage of your Primal Strike increases to 2d8."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Beast Spells","desc":"While using Wild Shape, you can cast spells in Beast form, except for any spell that has a Material component with a cost specified or that consumes its Material component."}'::jsonb, '{"index":"druid-beast-spells","url":"/api/2024/features/druid-beast-spells","name":"Beast Spells","level":{"index":"druid-18","url":"/api/2024/classes/druid/levels/18","name":"Druid 18"},"class":{"index":"druid","name":"Druid","url":"/api/2024/classes/druid"},"description":"While using Wild Shape, you can cast spells in Beast form, except for any spell that has a Material component with a cost specified or that consumes its Material component."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Epic Boon","desc":"You gain an Epic Boon feat (see \"Feats\") or another feat of your choice for which you qualify. Boon of Dimensional Travel is recommended."}'::jsonb, '{"index":"druid-epic-boon","url":"/api/2024/features/druid-epic-boon","name":"Epic Boon","level":{"index":"druid-19","url":"/api/2024/classes/druid/levels/19","name":"Druid 19"},"class":{"index":"druid","name":"Druid","url":"/api/2024/classes/druid"},"description":"You gain an Epic Boon feat (see \"Feats\") or another feat of your choice for which you qualify. Boon of Dimensional Travel is recommended."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Archdruid","desc":"The vitality of nature constantly blooms within you, granting you the following benefits.\n  Evergreen Wild Shape. Whenever you roll Initiative and have no uses of Wild Shape left, you regain one expended use of it.\n  Nature Magician. You can convert uses of Wild Shape into a spell slot (no action required). Choose a number of your unexpended uses of Wild Shape and convert them into a single spell slot, with each use contributing 2 spell levels. For example, if you convert two uses of Wild Shape, you produce a level 4 spell slot. Once you use this benefit, you can''t do so again until you finish a Long Rest.\n  Longevity. The primal magic that you wield causes you to age more slowly. For every ten years that pass, your body ages only one year."}'::jsonb, '{"index":"druid-archdruid","url":"/api/2024/features/druid-archdruid","name":"Archdruid","level":{"index":"druid-20","url":"/api/2024/classes/druid/levels/20","name":"Druid 20"},"class":{"index":"druid","name":"Druid","url":"/api/2024/classes/druid"},"description":"The vitality of nature constantly blooms within you, granting you the following benefits.\n  Evergreen Wild Shape. Whenever you roll Initiative and have no uses of Wild Shape left, you regain one expended use of it.\n  Nature Magician. You can convert uses of Wild Shape into a spell slot (no action required). Choose a number of your unexpended uses of Wild Shape and convert them into a single spell slot, with each use contributing 2 spell levels. For example, if you convert two uses of Wild Shape, you produce a level 4 spell slot. Once you use this benefit, you can''t do so again until you finish a Long Rest.\n  Longevity. The primal magic that you wield causes you to age more slowly. For every ten years that pass, your body ages only one year."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Circle of the Land Spells","desc":"Whenever you finish a Long Rest, choose one type of land: arid, polar, temperate, or tropical. Consult the table below that corresponds to the chosen type; you have the spells listed for your Druid level and lower prepared.\nArid Land\nDruid Level / Circle Spells\n3 / Blur, Burning Hands, Fire Bolt\n5 / Fireball\n7 / Blight\n9 / Wall of Stone\n\nPolar Land\nDruid Level / Circle Spells\n3 / Fog Cloud, Hold Person\n5 / Sleet Storm\n7 / Ice Storm\n9 / Cone of Cold\n\nTemperate Land\nDruid Level / Circle Spells\n3 / Misty Step\n5 / Lightning Bolt\n7 / Freedom of Movement\n9 / Tree Stride\n\nTropical Land\nDruid Level / Circle Spells\n3 / Acid Splash, Ray of Sickness, Web\n5 / Stinking Cloud\n7 / Polymorph\n9 / Insect Plague"}'::jsonb, '{"index":"land-circle-of-the-land-spells","url":"/api/2024/features/land-circle-of-the-land-spells","name":"Circle of the Land Spells","level":{"index":"druid-3","url":"/api/2024/classes/druid/levels/3","name":"Druid 3"},"class":{"index":"druid","name":"Druid","url":"/api/2024/classes/druid"},"subclass":{"index":"circle-of-the-land","name":"Circle of the Land","url":"/api/2024/subclasses/circle-of-the-land"},"description":"Whenever you finish a Long Rest, choose one type of land: arid, polar, temperate, or tropical. Consult the table below that corresponds to the chosen type; you have the spells listed for your Druid level and lower prepared.\nArid Land\nDruid Level / Circle Spells\n3 / Blur, Burning Hands, Fire Bolt\n5 / Fireball\n7 / Blight\n9 / Wall of Stone\n\nPolar Land\nDruid Level / Circle Spells\n3 / Fog Cloud, Hold Person\n5 / Sleet Storm\n7 / Ice Storm\n9 / Cone of Cold\n\nTemperate Land\nDruid Level / Circle Spells\n3 / Misty Step\n5 / Lightning Bolt\n7 / Freedom of Movement\n9 / Tree Stride\n\nTropical Land\nDruid Level / Circle Spells\n3 / Acid Splash, Ray of Sickness, Web\n5 / Stinking Cloud\n7 / Polymorph\n9 / Insect Plague"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Land''s Aid","desc":"As a Magic action, you can expend a use of your Wild Shape and choose a point within 60 feet of yourself. Vitality-giving flowers and life-draining thorns appear for a moment in a 10-foot-radius Sphere centered on that point. Each creature of your choice in the Sphere must make a Constitution saving throw against your spell save DC, taking 2d6 Necrotic damage on a failed save or half as much damage on a successful one. One creature of your choice in that area regains 2d6 Hit Points.\n  The damage and healing increase by 1d6 when you reach Druid levels 10 (3d6) and 14 (4d6)."}'::jsonb, '{"index":"land-lands-aid","url":"/api/2024/features/land-lands-aid","name":"Land''s Aid","level":{"index":"druid-3","url":"/api/2024/classes/druid/levels/3","name":"Druid 3"},"class":{"index":"druid","name":"Druid","url":"/api/2024/classes/druid"},"subclass":{"index":"circle-of-the-land","name":"Circle of the Land","url":"/api/2024/subclasses/circle-of-the-land"},"description":"As a Magic action, you can expend a use of your Wild Shape and choose a point within 60 feet of yourself. Vitality-giving flowers and life-draining thorns appear for a moment in a 10-foot-radius Sphere centered on that point. Each creature of your choice in the Sphere must make a Constitution saving throw against your spell save DC, taking 2d6 Necrotic damage on a failed save or half as much damage on a successful one. One creature of your choice in that area regains 2d6 Hit Points.\n  The damage and healing increase by 1d6 when you reach Druid levels 10 (3d6) and 14 (4d6)."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Natural Recovery","desc":"You can cast one of the level 1+ spells that you have prepared from your Circle Spells feature without expending a spell slot, and you must finish a Long Rest before you do so again.\n  In addition, when you finish a Short Rest, you can choose expended spell slots to recover. The spell slots can have a combined level that is equal to or less than half your Druid level (round up), and none of them can be level 6+. For example, if you''re a level 6 Druid, you can recover up to three levels'' worth of spell slots. You can recover a level 3 spell slot, a level 2 and a level 1 spell slot, or three level 1 spell slots. Once you recover spell slots with this feature, you can''t do so again until you finish a Long Rest."}'::jsonb, '{"index":"land-natural-recovery","url":"/api/2024/features/land-natural-recovery","name":"Natural Recovery","level":{"index":"druid-6","url":"/api/2024/classes/druid/levels/6","name":"Druid 6"},"class":{"index":"druid","name":"Druid","url":"/api/2024/classes/druid"},"subclass":{"index":"circle-of-the-land","name":"Circle of the Land","url":"/api/2024/subclasses/circle-of-the-land"},"description":"You can cast one of the level 1+ spells that you have prepared from your Circle Spells feature without expending a spell slot, and you must finish a Long Rest before you do so again.\n  In addition, when you finish a Short Rest, you can choose expended spell slots to recover. The spell slots can have a combined level that is equal to or less than half your Druid level (round up), and none of them can be level 6+. For example, if you''re a level 6 Druid, you can recover up to three levels'' worth of spell slots. You can recover a level 3 spell slot, a level 2 and a level 1 spell slot, or three level 1 spell slots. Once you recover spell slots with this feature, you can''t do so again until you finish a Long Rest."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Nature''s Ward","desc":"You are immune to the Poisoned condition, and you have Resistance to a damage type associated with your current land choice in the Circle Spells feature, as shown in the Nature''s Ward table.\n\nNature''s Ward\nLand Type / Resistance\nArid / Fire\nPolar / Cold\nTemperate / Lightning\nTropical / Poison"}'::jsonb, '{"index":"land-natures-ward","url":"/api/2024/features/land-natures-ward","name":"Nature''s Ward","level":{"index":"druid-10","url":"/api/2024/classes/druid/levels/10","name":"Druid 10"},"class":{"index":"druid","name":"Druid","url":"/api/2024/classes/druid"},"subclass":{"index":"circle-of-the-land","name":"Circle of the Land","url":"/api/2024/subclasses/circle-of-the-land"},"description":"You are immune to the Poisoned condition, and you have Resistance to a damage type associated with your current land choice in the Circle Spells feature, as shown in the Nature''s Ward table.\n\nNature''s Ward\nLand Type / Resistance\nArid / Fire\nPolar / Cold\nTemperate / Lightning\nTropical / Poison"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Nature''s Sanctuary","desc":"As a Magic action, you can expend a use of your Wild Shape and cause spectral trees and vines to appear in a 15-foot Cube on the ground within 120 feet of yourself. They last there for 1 minute or until you have the Incapacitated condition or die. You and your allies have Half Cover while in that area, and your allies gain the current Resistance of your Nature''s Ward while there.\n  As a Bonus Action, you can move the Cube up to 60 feet to ground within 120 feet of yourself."}'::jsonb, '{"index":"land-natures-sanctuary","url":"/api/2024/features/land-natures-sanctuary","name":"Nature''s Sanctuary","level":{"index":"druid-14","url":"/api/2024/classes/druid/levels/14","name":"Druid 14"},"class":{"index":"druid","name":"Druid","url":"/api/2024/classes/druid"},"subclass":{"index":"circle-of-the-land","name":"Circle of the Land","url":"/api/2024/subclasses/circle-of-the-land"},"description":"As a Magic action, you can expend a use of your Wild Shape and cause spectral trees and vines to appear in a 15-foot Cube on the ground within 120 feet of yourself. They last there for 1 minute or until you have the Incapacitated condition or die. You and your allies have Half Cover while in that area, and your allies gain the current Resistance of your Nature''s Ward while there.\n  As a Bonus Action, you can move the Cube up to 60 feet to ground within 120 feet of yourself."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Fighting Style","desc":"You have honed your martial prowess and gain a Fighting Style feat of your choice (see \"Feats\"). Defense is recommended.\n  Whenever you gain a Fighter level, you can replace the feat you chose with a different Fighting Style feat."}'::jsonb, '{"index":"fighter-fighting-style","url":"/api/2024/features/fighter-fighting-style","name":"Fighting Style","level":{"index":"fighter-1","url":"/api/2024/classes/fighter/levels/1","name":"Fighter 1"},"class":{"index":"fighter","url":"/api/2024/classes/fighter","name":"Fighter"},"description":"You have honed your martial prowess and gain a Fighting Style feat of your choice (see \"Feats\"). Defense is recommended.\n  Whenever you gain a Fighter level, you can replace the feat you chose with a different Fighting Style feat."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Second Wind","desc":"You have a limited well of physical and mental stamina that you can draw on. As a Bonus Action, you can use it to regain Hit Points equal to 1d10 plus your Fighter level.\n  You can use this feature twice. You regain one expended use when you finish a Short Rest, and you regain all expended uses when you finish a Long Rest.\n  When you reach certain Fighter levels, you gain more uses of this feature, as shown in the Second Wind column of the Fighter Features table."}'::jsonb, '{"index":"fighter-second-wind","url":"/api/2024/features/fighter-second-wind","name":"Second Wind","level":{"index":"fighter-1","url":"/api/2024/classes/fighter/levels/1","name":"Fighter 1"},"class":{"index":"fighter","url":"/api/2024/classes/fighter","name":"Fighter"},"description":"You have a limited well of physical and mental stamina that you can draw on. As a Bonus Action, you can use it to regain Hit Points equal to 1d10 plus your Fighter level.\n  You can use this feature twice. You regain one expended use when you finish a Short Rest, and you regain all expended uses when you finish a Long Rest.\n  When you reach certain Fighter levels, you gain more uses of this feature, as shown in the Second Wind column of the Fighter Features table."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Weapon Mastery","desc":"Your training with weapons allows you to use the mastery properties of three kinds of Simple or Martial weapons of your choice. Whenever you finish\na Long Rest, you can practice weapon drills and change one of those weapon choices.\n  When you reach certain Fighter levels, you gain the ability to use the mastery properties of more kinds of weapons, as shown in the Weapon Mastery column of the Fighter Features table."}'::jsonb, '{"index":"fighter-weapon-mastery","url":"/api/2024/features/fighter-weapon-mastery","name":"Weapon Mastery","level":{"index":"fighter-1","url":"/api/2024/classes/fighter/levels/1","name":"Fighter 1"},"class":{"index":"fighter","url":"/api/2024/classes/fighter","name":"Fighter"},"description":"Your training with weapons allows you to use the mastery properties of three kinds of Simple or Martial weapons of your choice. Whenever you finish\na Long Rest, you can practice weapon drills and change one of those weapon choices.\n  When you reach certain Fighter levels, you gain the ability to use the mastery properties of more kinds of weapons, as shown in the Weapon Mastery column of the Fighter Features table."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Action Surge","desc":"You can push yourself beyond your normal limits for a moment. On your turn, you can take one additional action, except the Magic action.\n  Once you use this feature, you can''t do so again until you finish a Short or Long Rest. Starting at level 17, you can use it twice before a rest but only once on a turn."}'::jsonb, '{"index":"fighter-action-surge","url":"/api/2024/features/fighter-action-surge","name":"Action Surge","level":{"index":"fighter-2","url":"/api/2024/classes/fighter/levels/2","name":"Fighter 2"},"class":{"index":"fighter","url":"/api/2024/classes/fighter","name":"Fighter"},"description":"You can push yourself beyond your normal limits for a moment. On your turn, you can take one additional action, except the Magic action.\n  Once you use this feature, you can''t do so again until you finish a Short or Long Rest. Starting at level 17, you can use it twice before a rest but only once on a turn."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Tactical Mind","desc":"You have a mind for tactics on and off the battlefield. When you fail an ability check, you can expend a use of your Second Wind to push yourself toward success. Rather than regaining Hit Points, you roll 1d10 and add the number rolled to the ability check, potentially turning it into a success. If the check still fails, this use of Second Wind isn''t expended."}'::jsonb, '{"index":"fighter-tactical-mind","url":"/api/2024/features/fighter-tactical-mind","name":"Tactical Mind","level":{"index":"fighter-2","url":"/api/2024/classes/fighter/levels/2","name":"Fighter 2"},"class":{"index":"fighter","url":"/api/2024/classes/fighter","name":"Fighter"},"description":"You have a mind for tactics on and off the battlefield. When you fail an ability check, you can expend a use of your Second Wind to push yourself toward success. Rather than regaining Hit Points, you roll 1d10 and add the number rolled to the ability check, potentially turning it into a success. If the check still fails, this use of Second Wind isn''t expended."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Fighter Subclass","desc":"You gain a Fighter subclass of your choice. A subclass is a specialization that grants you features at certain Fighter levels. For the rest of your career, you gain each of your subclass''s features that are of your Fighter level or lower."}'::jsonb, '{"index":"fighter-subclass","url":"/api/2024/features/fighter-subclass","name":"Fighter Subclass","level":{"index":"fighter-3","url":"/api/2024/classes/fighter/levels/3","name":"Fighter 3"},"class":{"index":"fighter","url":"/api/2024/classes/fighter","name":"Fighter"},"description":"You gain a Fighter subclass of your choice. A subclass is a specialization that grants you features at certain Fighter levels. For the rest of your career, you gain each of your subclass''s features that are of your Fighter level or lower."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Ability Score Improvement","desc":"You gain the Ability Score Improvement feat (see \"Feats\") or another feat of your choice for which you qualify. You gain this feature again at Fighter levels 6, 8, 12, 14, and 16."}'::jsonb, '{"index":"fighter-ability-score-improvement","url":"/api/2024/features/fighter-ability-score-improvement","name":"Ability Score Improvement","level":{"index":"fighter-4","url":"/api/2024/classes/fighter/levels/4","name":"Fighter 4"},"class":{"index":"fighter","url":"/api/2024/classes/fighter","name":"Fighter"},"description":"You gain the Ability Score Improvement feat (see \"Feats\") or another feat of your choice for which you qualify. You gain this feature again at Fighter levels 6, 8, 12, 14, and 16."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Extra Attack","desc":"You can attack twice instead of once whenever you take the Attack action on your turn."}'::jsonb, '{"index":"fighter-extra-attack","url":"/api/2024/features/fighter-extra-attack","name":"Extra Attack","level":{"index":"fighter-5","url":"/api/2024/classes/fighter/levels/5","name":"Fighter 5"},"class":{"index":"fighter","url":"/api/2024/classes/fighter","name":"Fighter"},"description":"You can attack twice instead of once whenever you take the Attack action on your turn."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Tactical Shift","desc":"Whenever you activate your Second Wind with a Bonus Action, you can move up to half your Speed without provoking Opportunity Attacks."}'::jsonb, '{"index":"fighter-tactical-shift","url":"/api/2024/features/fighter-tactical-shift","name":"Tactical Shift","level":{"index":"fighter-5","url":"/api/2024/classes/fighter/levels/5","name":"Fighter 5"},"class":{"index":"fighter","url":"/api/2024/classes/fighter","name":"Fighter"},"description":"Whenever you activate your Second Wind with a Bonus Action, you can move up to half your Speed without provoking Opportunity Attacks."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Indomitable","desc":"If you fail a saving throw, you can reroll it with a bonus equal to your Fighter level. You must use the new roll, and you can''t use this feature again until you finish a Long Rest.\n  You can use this feature twice before a Long Rest starting at level 13 and three times before a Long Rest starting at level 17."}'::jsonb, '{"index":"fighter-indomitable","url":"/api/2024/features/fighter-indomitable","name":"Indomitable","level":{"index":"fighter-9","url":"/api/2024/classes/fighter/levels/9","name":"Fighter 9"},"class":{"index":"fighter","url":"/api/2024/classes/fighter","name":"Fighter"},"description":"If you fail a saving throw, you can reroll it with a bonus equal to your Fighter level. You must use the new roll, and you can''t use this feature again until you finish a Long Rest.\n  You can use this feature twice before a Long Rest starting at level 13 and three times before a Long Rest starting at level 17."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Tactical Master","desc":"When you attack with a weapon whose mastery property you can use, you can replace that property with the Push, Sap, or Slow property for that attack."}'::jsonb, '{"index":"fighter-tactical-master","url":"/api/2024/features/fighter-tactical-master","name":"Tactical Master","level":{"index":"fighter-9","url":"/api/2024/classes/fighter/levels/9","name":"Fighter 9"},"class":{"index":"fighter","url":"/api/2024/classes/fighter","name":"Fighter"},"description":"When you attack with a weapon whose mastery property you can use, you can replace that property with the Push, Sap, or Slow property for that attack."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Two Extra Attacks","desc":"You can attack three times instead of once whenever you take the Attack action on your turn."}'::jsonb, '{"index":"fighter-two-extra-attacks","url":"/api/2024/features/fighter-two-extra-attacks","name":"Two Extra Attacks","level":{"index":"fighter-11","url":"/api/2024/classes/fighter/levels/11","name":"Fighter 11"},"class":{"index":"fighter","url":"/api/2024/classes/fighter","name":"Fighter"},"description":"You can attack three times instead of once whenever you take the Attack action on your turn."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Studied Attacks","desc":"You study your opponents and learn from each attack you make. If you make an attack roll against a creature and miss, you have Advantage on your next attack roll against that creature before the end of your next turn."}'::jsonb, '{"index":"fighter-studied-attacks","url":"/api/2024/features/fighter-studied-attacks","name":"Studied Attacks","level":{"index":"fighter-13","url":"/api/2024/classes/fighter/levels/13","name":"Fighter 13"},"class":{"index":"fighter","url":"/api/2024/classes/fighter","name":"Fighter"},"description":"You study your opponents and learn from each attack you make. If you make an attack roll against a creature and miss, you have Advantage on your next attack roll against that creature before the end of your next turn."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Epic Boon","desc":"You gain an Epic Boon feat (see \"Feats\") or another feat of your choice for which you qualify. Boon of Combat Prowess is recommended."}'::jsonb, '{"index":"fighter-epic-boon","url":"/api/2024/features/fighter-epic-boon","name":"Epic Boon","level":{"index":"fighter-19","url":"/api/2024/classes/fighter/levels/19","name":"Fighter 19"},"class":{"index":"fighter","url":"/api/2024/classes/fighter","name":"Fighter"},"description":"You gain an Epic Boon feat (see \"Feats\") or another feat of your choice for which you qualify. Boon of Combat Prowess is recommended."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Three Extra Attacks","desc":"You can attack four times instead of once whenever you take the Attack action on your turn."}'::jsonb, '{"index":"fighter-three-extra-attacks","url":"/api/2024/features/fighter-three-extra-attacks","name":"Three Extra Attacks","level":{"index":"fighter-20","url":"/api/2024/classes/fighter/levels/20","name":"Fighter 20"},"class":{"index":"fighter","url":"/api/2024/classes/fighter","name":"Fighter"},"description":"You can attack four times instead of once whenever you take the Attack action on your turn."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Improved Critical","desc":"Your attack rolls with weapons and Unarmed Strikes can score a Critical Hit on a roll of 19 or 20 on the d20."}'::jsonb, '{"index":"champion-improved-critical","url":"/api/2024/features/champion-improved-critical","name":"Improved Critical","level":{"index":"fighter-3","url":"/api/2024/classes/fighter/levels/3","name":"Fighter 3"},"class":{"index":"fighter","url":"/api/2024/classes/fighter","name":"Fighter"},"subclass":{"index":"champion","name":"Champion","url":"/api/2024/subclasses/champion"},"description":"Your attack rolls with weapons and Unarmed Strikes can score a Critical Hit on a roll of 19 or 20 on the d20."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Remarkable Athlete","desc":"Thanks to your athleticism, you have Advantage on Initiative rolls and Strength (Athletics) checks.\n  In addition, immediately after you score a Critical Hit, you can move up to half your Speed without provoking Opportunity Attacks."}'::jsonb, '{"index":"champion-remarkable-athlete","url":"/api/2024/features/champion-remarkable-athlete","name":"Remarkable Athlete","level":{"index":"fighter-3","url":"/api/2024/classes/fighter/levels/3","name":"Fighter 3"},"class":{"index":"fighter","url":"/api/2024/classes/fighter","name":"Fighter"},"subclass":{"index":"champion","name":"Champion","url":"/api/2024/subclasses/champion"},"description":"Thanks to your athleticism, you have Advantage on Initiative rolls and Strength (Athletics) checks.\n  In addition, immediately after you score a Critical Hit, you can move up to half your Speed without provoking Opportunity Attacks."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Additional Fighting Style","desc":"You gain another Fighting Style feat of your choice."}'::jsonb, '{"index":"champion-additional-fighting-style","url":"/api/2024/features/champion-additional-fighting-style","name":"Additional Fighting Style","level":{"index":"fighter-7","url":"/api/2024/classes/fighter/levels/7","name":"Fighter 7"},"class":{"index":"fighter","url":"/api/2024/classes/fighter","name":"Fighter"},"subclass":{"index":"champion","name":"Champion","url":"/api/2024/subclasses/champion"},"description":"You gain another Fighting Style feat of your choice."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Heroic Warrior","desc":"The thrill of battle drives you toward victory. During combat, you can give yourself Heroic Inspiration whenever you start your turn without it."}'::jsonb, '{"index":"champion-heroic-warrior","url":"/api/2024/features/champion-heroic-warrior","name":"Heroic Warrior","level":{"index":"fighter-10","url":"/api/2024/classes/fighter/levels/10","name":"Fighter 10"},"class":{"index":"fighter","url":"/api/2024/classes/fighter","name":"Fighter"},"subclass":{"index":"champion","name":"Champion","url":"/api/2024/subclasses/champion"},"description":"The thrill of battle drives you toward victory. During combat, you can give yourself Heroic Inspiration whenever you start your turn without it."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Superior Critical","desc":"Your attack rolls with weapons and Unarmed Strikes can now score a Critical Hit on a roll of 18-20 on the d20."}'::jsonb, '{"index":"champion-superior-critical","url":"/api/2024/features/champion-superior-critical","name":"Superior Critical","level":{"index":"fighter-15","url":"/api/2024/classes/fighter/levels/15","name":"Fighter 15"},"class":{"index":"fighter","url":"/api/2024/classes/fighter","name":"Fighter"},"subclass":{"index":"champion","name":"Champion","url":"/api/2024/subclasses/champion"},"description":"Your attack rolls with weapons and Unarmed Strikes can now score a Critical Hit on a roll of 18-20 on the d20."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Survivor","desc":"You attain the pinnacle of resilience in battle, giving you these benefits.\n  Defy Death. You have Advantage on Death Saving Throws. Moreover, when you roll 18-20 on a Death Saving Throw, you gain the benefit of rolling a 20 on it.\n  Heroic Rally. At the start of each of your turns, you regain Hit Points equal to 5 plus your Constitution modifier if you are Bloodied and have at least 1 Hit Point."}'::jsonb, '{"index":"champion-survivor","url":"/api/2024/features/champion-survivor","name":"Survivor","level":{"index":"fighter-18","url":"/api/2024/classes/fighter/levels/18","name":"Fighter 18"},"class":{"index":"fighter","url":"/api/2024/classes/fighter","name":"Fighter"},"subclass":{"index":"champion","name":"Champion","url":"/api/2024/subclasses/champion"},"description":"You attain the pinnacle of resilience in battle, giving you these benefits.\n  Defy Death. You have Advantage on Death Saving Throws. Moreover, when you roll 18-20 on a Death Saving Throw, you gain the benefit of rolling a 20 on it.\n  Heroic Rally. At the start of each of your turns, you regain Hit Points equal to 5 plus your Constitution modifier if you are Bloodied and have at least 1 Hit Point."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Martial Arts","desc":"Your practice of martial arts gives you mastery of combat styles that use your Unarmed Strike and Monk weapons, which are the following:\n• Simple Melee weapons\n• Martial Melee weapons that have the Light property\nYou gain the following benefits while you are unarmed or wielding only Monk weapons and you aren''t wearing armor or wielding a Shield.\n  Bonus Unarmed Strike. You can make an Unarmed Strike as a Bonus Action.\n  Martial Arts Die. You can roll 1d6 in place of the normal damage of your Unarmed Strike or Monk weapons. This die changes as you gain Monk levels, as shown in the Martial Arts column of the Monk Features table.\n  Dexterous Attacks. You can use your Dexterity modifier instead of your Strength modifier for the attack and damage rolls of your Unarmed Strikes and Monk weapons. In addition, when you use the Grapple or Shove option of your Unarmed Strike, you can use your Dexterity modifier instead of your Strength modifier to determine the save DC.\n"}'::jsonb, '{"index":"monk-martial-arts","url":"/api/2024/features/monk-martial-arts","name":"Martial Arts","level":{"index":"monk-1","url":"/api/2024/classes/monk/levels/1","name":"Monk 1"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"description":"Your practice of martial arts gives you mastery of combat styles that use your Unarmed Strike and Monk weapons, which are the following:\n• Simple Melee weapons\n• Martial Melee weapons that have the Light property\nYou gain the following benefits while you are unarmed or wielding only Monk weapons and you aren''t wearing armor or wielding a Shield.\n  Bonus Unarmed Strike. You can make an Unarmed Strike as a Bonus Action.\n  Martial Arts Die. You can roll 1d6 in place of the normal damage of your Unarmed Strike or Monk weapons. This die changes as you gain Monk levels, as shown in the Martial Arts column of the Monk Features table.\n  Dexterous Attacks. You can use your Dexterity modifier instead of your Strength modifier for the attack and damage rolls of your Unarmed Strikes and Monk weapons. In addition, when you use the Grapple or Shove option of your Unarmed Strike, you can use your Dexterity modifier instead of your Strength modifier to determine the save DC.\n"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Unarmored Defense","desc":"While you aren''t wearing armor or wielding a Shield, your base Armor Class equals 10 plus your Dexterity and Wisdom modifiers."}'::jsonb, '{"index":"monk-unarmored-defense","url":"/api/2024/features/monk-unarmored-defense","name":"Unarmored Defense","level":{"index":"monk-1","url":"/api/2024/classes/monk/levels/1","name":"Monk 1"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"description":"While you aren''t wearing armor or wielding a Shield, your base Armor Class equals 10 plus your Dexterity and Wisdom modifiers."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Monk''s Focus","desc":"Your focus and martial training allow you to harness a well of extraordinary energy within yourself. This energy is represented by Focus Points. Your Monk level determines the number of points you have, as shown in the Focus Points column of the Monk Features table.\n  You can expend these points to enhance or fuel certain Monk features. You start knowing three such features: Flurry of Blows, Patient Defense, and Step of the Wind, each of which is detailed below.\n  When you expend a Focus Point, it is unavailable until you finish a Short or Long Rest, at the end of which you regain all your expended points.\n Some features that use Focus Points require your target to make a saving throw. The save DC equals 8 plus your Wisdom modifier and Proficiency Bonus.\n  Flurry of Blows. You can expend 1 Focus Point to make two Unarmed Strikes as a Bonus Action.\n  Patient Defense. You can take the Disengage action as a Bonus Action. Alternatively, you can expend 1 Focus Point to take both the Disengage and the Dodge actions as a Bonus Action.\n  Step of the Wind. You can take the Dash action as a Bonus Action. Alternatively, you can expend 1 Focus Point to take both the Disengage and Dash\nactions as a Bonus Action, and your jump distance is doubled for the turn."}'::jsonb, '{"index":"monk-monks-focus","url":"/api/2024/features/monk-monks-focus","name":"Monk''s Focus","level":{"index":"monk-2","url":"/api/2024/classes/monk/levels/2","name":"Monk 2"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"description":"Your focus and martial training allow you to harness a well of extraordinary energy within yourself. This energy is represented by Focus Points. Your Monk level determines the number of points you have, as shown in the Focus Points column of the Monk Features table.\n  You can expend these points to enhance or fuel certain Monk features. You start knowing three such features: Flurry of Blows, Patient Defense, and Step of the Wind, each of which is detailed below.\n  When you expend a Focus Point, it is unavailable until you finish a Short or Long Rest, at the end of which you regain all your expended points.\n Some features that use Focus Points require your target to make a saving throw. The save DC equals 8 plus your Wisdom modifier and Proficiency Bonus.\n  Flurry of Blows. You can expend 1 Focus Point to make two Unarmed Strikes as a Bonus Action.\n  Patient Defense. You can take the Disengage action as a Bonus Action. Alternatively, you can expend 1 Focus Point to take both the Disengage and the Dodge actions as a Bonus Action.\n  Step of the Wind. You can take the Dash action as a Bonus Action. Alternatively, you can expend 1 Focus Point to take both the Disengage and Dash\nactions as a Bonus Action, and your jump distance is doubled for the turn."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Unarmored Movement","desc":"Your speed increases by 10 feet while you aren''t wearing armor or wielding a Shield. This bonus increases when you reach certain Monk levels, as shown on the Monk Features table."}'::jsonb, '{"index":"monk-unarmored-movement","url":"/api/2024/features/monk-unarmored-movement","name":"Unarmored Movement","level":{"index":"monk-2","url":"/api/2024/classes/monk/levels/2","name":"Monk 2"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"description":"Your speed increases by 10 feet while you aren''t wearing armor or wielding a Shield. This bonus increases when you reach certain Monk levels, as shown on the Monk Features table."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Uncanny Metabolism","desc":"When you roll Initiative, you can regain all expended Focus Points. When you do so, roll your Martial Arts die, and regain a number of Hit Points equal to your Monk level plus the number rolled.\n  Once you use this feature, you can''t use it again until you finish a Long Rest."}'::jsonb, '{"index":"monk-uncanny-metabolism","url":"/api/2024/features/monk-uncanny-metabolism","name":"Uncanny Metabolism","level":{"index":"monk-2","url":"/api/2024/classes/monk/levels/2","name":"Monk 2"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"description":"When you roll Initiative, you can regain all expended Focus Points. When you do so, roll your Martial Arts die, and regain a number of Hit Points equal to your Monk level plus the number rolled.\n  Once you use this feature, you can''t use it again until you finish a Long Rest."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Deflect Attacks","desc":"When an attack roll hits you and its damage includes Bludgeoning, Piercing, or Slashing damage, you can take a Reaction to reduce the attack''s total damage against you. The reduction equals 1d10 plus your Dexterity modifier and Monk level.\n  If you reduce the damage to 0, you can expend 1 Focus Point to redirect some of the attack''s force. If you do so, choose a creature you can see within 5 feet of yourself if the attack was a melee attack or a creature you can see within 60 feet of yourself that isn''t behind Total Cover if the attack was a ranged attack. That creature must succeed on a Dexterity saving throw or take damage equal to two rolls of your Martial Arts die plus your Dexterity modifier. The damage is the same type dealt by the attack."}'::jsonb, '{"index":"monk-deflect-attacks","url":"/api/2024/features/monk-deflect-attacks","name":"Deflect Attacks","level":{"index":"monk-3","url":"/api/2024/classes/monk/levels/3","name":"Monk 3"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"description":"When an attack roll hits you and its damage includes Bludgeoning, Piercing, or Slashing damage, you can take a Reaction to reduce the attack''s total damage against you. The reduction equals 1d10 plus your Dexterity modifier and Monk level.\n  If you reduce the damage to 0, you can expend 1 Focus Point to redirect some of the attack''s force. If you do so, choose a creature you can see within 5 feet of yourself if the attack was a melee attack or a creature you can see within 60 feet of yourself that isn''t behind Total Cover if the attack was a ranged attack. That creature must succeed on a Dexterity saving throw or take damage equal to two rolls of your Martial Arts die plus your Dexterity modifier. The damage is the same type dealt by the attack."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Monk Subclass","desc":"You gain a Monk subclass of your choice. A subclass is a specialization that grants you features at certain Monk levels. For the rest of your career, you gain each of your subclass''s features that are of your Monk level or lower."}'::jsonb, '{"index":"monk-subclass","url":"/api/2024/features/monk-subclass","name":"Monk Subclass","level":{"index":"monk-3","url":"/api/2024/classes/monk/levels/3","name":"Monk 3"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"description":"You gain a Monk subclass of your choice. A subclass is a specialization that grants you features at certain Monk levels. For the rest of your career, you gain each of your subclass''s features that are of your Monk level or lower."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Ability Score Improvement","desc":"You gain the Ability Score Improvement feat (see \"Feats\") or another feat of your choice for which you qualify. You gain this feature again at Monk levels 8, 12, and 16."}'::jsonb, '{"index":"monk-ability-score-improvement","url":"/api/2024/features/monk-ability-score-improvement","name":"Ability Score Improvement","level":{"index":"monk-4","url":"/api/2024/classes/monk/levels/4","name":"Monk 4"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"description":"You gain the Ability Score Improvement feat (see \"Feats\") or another feat of your choice for which you qualify. You gain this feature again at Monk levels 8, 12, and 16."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Slow Fall","desc":"You can take a Reaction when you fall to reduce any damage you take from the fall by an amount equal to five times your Monk level."}'::jsonb, '{"index":"monk-slow-fall","url":"/api/2024/features/monk-slow-fall","name":"Slow Fall","level":{"index":"monk-4","url":"/api/2024/classes/monk/levels/4","name":"Monk 4"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"description":"You can take a Reaction when you fall to reduce any damage you take from the fall by an amount equal to five times your Monk level."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Extra Attack","desc":"You can attack twice instead of once whenever you take the Attack action on your turn."}'::jsonb, '{"index":"monk-extra-attack","url":"/api/2024/features/monk-extra-attack","name":"Extra Attack","level":{"index":"monk-5","url":"/api/2024/classes/monk/levels/5","name":"Monk 5"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"description":"You can attack twice instead of once whenever you take the Attack action on your turn."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Stunning Strike","desc":"Once per turn when you hit a creature with a Monk weapon or an Unarmed Strike, you can expend 1 Focus Point to attempt a stunning strike. The target must make a Constitution saving throw. On a failed save, the target has the Stunned condition until the start of your next turn. On a successful save, the target''s Speed is halved until the start of your next turn, and the next attack roll made against the target before then has Advantage."}'::jsonb, '{"index":"monk-stunning-strike","url":"/api/2024/features/monk-stunning-strike","name":"Stunning Strike","level":{"index":"monk-5","url":"/api/2024/classes/monk/levels/5","name":"Monk 5"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"description":"Once per turn when you hit a creature with a Monk weapon or an Unarmed Strike, you can expend 1 Focus Point to attempt a stunning strike. The target must make a Constitution saving throw. On a failed save, the target has the Stunned condition until the start of your next turn. On a successful save, the target''s Speed is halved until the start of your next turn, and the next attack roll made against the target before then has Advantage."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Empowered Strikes","desc":"Whenever you deal damage with your Unarmed Strike, it can deal your choice of Force damage or its normal damage type."}'::jsonb, '{"index":"monk-empowered-strikes","url":"/api/2024/features/monk-empowered-strikes","name":"Empowered Strikes","level":{"index":"monk-6","url":"/api/2024/classes/monk/levels/6","name":"Monk 6"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"description":"Whenever you deal damage with your Unarmed Strike, it can deal your choice of Force damage or its normal damage type."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Evasion","desc":"When you''re subjected to an effect that allows you to make a Dexterity saving throw to take only half damage, you instead take no damage if you succeed on the saving throw and only half damage if you fail.\n  You don''t benefit from this feature if you have the Incapacitated condition."}'::jsonb, '{"index":"monk-evasion","url":"/api/2024/features/monk-evasion","name":"Evasion","level":{"index":"monk-7","url":"/api/2024/classes/monk/levels/7","name":"Monk 7"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"description":"When you''re subjected to an effect that allows you to make a Dexterity saving throw to take only half damage, you instead take no damage if you succeed on the saving throw and only half damage if you fail.\n  You don''t benefit from this feature if you have the Incapacitated condition."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Acrobatic Movement","desc":"While you aren''t wearing armor or wielding a Shield, you gain the ability to move along vertical surfaces and across liquids on your turn without falling during the movement."}'::jsonb, '{"index":"monk-acrobatic-movement","url":"/api/2024/features/monk-acrobatic-movement","name":"Acrobatic Movement","level":{"index":"monk-9","url":"/api/2024/classes/monk/levels/9","name":"Monk 9"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"description":"While you aren''t wearing armor or wielding a Shield, you gain the ability to move along vertical surfaces and across liquids on your turn without falling during the movement."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Heightened Focus","desc":"Your Flurry of Blows, Patient Defense, and Step of the Wind gain the following benefits.\n  Flurry of Blows. You can expend 1 Focus Point to use Flurry of Blows and make three Unarmed Strikes with it instead of two.\n  Patient Defense. When you expend a Focus Point to use Patient Defense, you gain a number of Temporary Hit Points equal to two rolls of your Martial Arts die.\n  Step of the Wind. When you expend a Focus Point to use Step of the Wind, you can choose a willing creature within 5 feet of yourself that is Large or smaller. You move the creature with you until the end of your turn. The creature''s movement doesn''t provoke Opportunity Attacks."}'::jsonb, '{"index":"monk-heightened-focus","url":"/api/2024/features/monk-heightened-focus","name":"Heightened Focus","level":{"index":"monk-10","url":"/api/2024/classes/monk/levels/10","name":"Monk 10"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"description":"Your Flurry of Blows, Patient Defense, and Step of the Wind gain the following benefits.\n  Flurry of Blows. You can expend 1 Focus Point to use Flurry of Blows and make three Unarmed Strikes with it instead of two.\n  Patient Defense. When you expend a Focus Point to use Patient Defense, you gain a number of Temporary Hit Points equal to two rolls of your Martial Arts die.\n  Step of the Wind. When you expend a Focus Point to use Step of the Wind, you can choose a willing creature within 5 feet of yourself that is Large or smaller. You move the creature with you until the end of your turn. The creature''s movement doesn''t provoke Opportunity Attacks."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Self-Restoration","desc":"Through sheer force of will, you can remove one of the following conditions from yourself at the\nend of each of your turns: Charmed, Frightened, or Poisoned.\n  In addition, forgoing food and drink doesn''t give you levels of Exhaustion."}'::jsonb, '{"index":"monk-self-restoration","url":"/api/2024/features/monk-self-restoration","name":"Self-Restoration","level":{"index":"monk-10","url":"/api/2024/classes/monk/levels/10","name":"Monk 10"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"description":"Through sheer force of will, you can remove one of the following conditions from yourself at the\nend of each of your turns: Charmed, Frightened, or Poisoned.\n  In addition, forgoing food and drink doesn''t give you levels of Exhaustion."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Deflect Energy","desc":"You can now use your Deflect Attacks feature against attacks that deal any damage type, not just Bludgeoning, Piercing, or Slashing."}'::jsonb, '{"index":"monk-deflect-energy","url":"/api/2024/features/monk-deflect-energy","name":"Deflect Energy","level":{"index":"monk-13","url":"/api/2024/classes/monk/levels/13","name":"Monk 13"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"description":"You can now use your Deflect Attacks feature against attacks that deal any damage type, not just Bludgeoning, Piercing, or Slashing."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Disciplined Survivor","desc":"Your physical and mental discipline grant you proficiency in all saving throws.\n  Additionally, whenever you make a saving throw and fail, you can expend 1 Focus Point to reroll it, and you must use the new roll."}'::jsonb, '{"index":"monk-disciplined-survivor","url":"/api/2024/features/monk-disciplined-survivor","name":"Disciplined Survivor","level":{"index":"monk-14","url":"/api/2024/classes/monk/levels/14","name":"Monk 14"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"description":"Your physical and mental discipline grant you proficiency in all saving throws.\n  Additionally, whenever you make a saving throw and fail, you can expend 1 Focus Point to reroll it, and you must use the new roll."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Perfect Focus","desc":"When you roll Initiative and don''t use Uncanny Metabolism, you regain expended Focus Points until you have 4 if you have 3 or fewer."}'::jsonb, '{"index":"monk-perfect-focus","url":"/api/2024/features/monk-perfect-focus","name":"Perfect Focus","level":{"index":"monk-15","url":"/api/2024/classes/monk/levels/15","name":"Monk 15"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"description":"When you roll Initiative and don''t use Uncanny Metabolism, you regain expended Focus Points until you have 4 if you have 3 or fewer."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Superior Defense","desc":"At the start of your turn, you can expend 3 Focus Points to bolster yourself against harm for 1 minute or until you have the Incapacitated condition. During that time, you have Resistance to all damage except Force damage."}'::jsonb, '{"index":"monk-superior-defense","url":"/api/2024/features/monk-superior-defense","name":"Superior Defense","level":{"index":"monk-18","url":"/api/2024/classes/monk/levels/18","name":"Monk 18"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"description":"At the start of your turn, you can expend 3 Focus Points to bolster yourself against harm for 1 minute or until you have the Incapacitated condition. During that time, you have Resistance to all damage except Force damage."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Epic Boon","desc":"You gain an Epic Boon feat (see \"Feats\") or another feat of your choice for which you qualify. Boon of Irresistible Offense is recommended."}'::jsonb, '{"index":"monk-epic-boon","url":"/api/2024/features/monk-epic-boon","name":"Epic Boon","level":{"index":"monk-19","url":"/api/2024/classes/monk/levels/19","name":"Monk 19"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"description":"You gain an Epic Boon feat (see \"Feats\") or another feat of your choice for which you qualify. Boon of Irresistible Offense is recommended."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Body and Mind","desc":"You have developed your body and mind to new heights. Your Dexterity and Wisdom scores increase by 4, to a maximum of 25."}'::jsonb, '{"index":"monk-body-and-mind","url":"/api/2024/features/monk-body-and-mind","name":"Body and Mind","level":{"index":"monk-20","url":"/api/2024/classes/monk/levels/20","name":"Monk 20"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"description":"You have developed your body and mind to new heights. Your Dexterity and Wisdom scores increase by 4, to a maximum of 25."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Open Hand Technique","desc":"Whenever you hit a creature with an attack granted by your Flurry of Blows, you can impose one of the following effects on that target.\n  Addle. The target can''t make Opportunity Attacks until the start of its next turn.\n  Push. The target must succeed on a Strength saving throw or be pushed up to 15 feet away from you.\n  Topple. The target must succeed on a Dexterity saving throw or have the Prone condition."}'::jsonb, '{"index":"open-hand-technique","url":"/api/2024/features/open-hand-technique","name":"Open Hand Technique","level":{"index":"monk-3","url":"/api/2024/classes/monk/levels/3","name":"Monk 3"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"subclass":{"index":"warrior-of-the-open-hand","name":"Warrior of the Open Hand","url":"/api/2024/subclasses/warrior-of-the-open-hand"},"description":"Whenever you hit a creature with an attack granted by your Flurry of Blows, you can impose one of the following effects on that target.\n  Addle. The target can''t make Opportunity Attacks until the start of its next turn.\n  Push. The target must succeed on a Strength saving throw or be pushed up to 15 feet away from you.\n  Topple. The target must succeed on a Dexterity saving throw or have the Prone condition."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Wholeness of Body","desc":"You gain the ability to heal yourself. As a Bonus Action, you can roll your Martial Arts die. You regain a number of Hit Points equal to the number rolled plus your Wisdom modifier (minimum of 1 Hit Point regained).\n  You can use this feature a number of times equal to your Wisdom modifier (minimum of once), and you regain all expended uses when you finish a Long Rest."}'::jsonb, '{"index":"open-hand-wholeness-of-body","url":"/api/2024/features/open-hand-wholeness-of-body","name":"Wholeness of Body","level":{"index":"monk-6","url":"/api/2024/classes/monk/levels/6","name":"Monk 6"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"subclass":{"index":"warrior-of-the-open-hand","name":"Warrior of the Open Hand","url":"/api/2024/subclasses/warrior-of-the-open-hand"},"description":"You gain the ability to heal yourself. As a Bonus Action, you can roll your Martial Arts die. You regain a number of Hit Points equal to the number rolled plus your Wisdom modifier (minimum of 1 Hit Point regained).\n  You can use this feature a number of times equal to your Wisdom modifier (minimum of once), and you regain all expended uses when you finish a Long Rest."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Fleet Step","desc":"When you take a Bonus Action other than Step of the Wind, you can also use Step of the Wind immediately after that Bonus Action."}'::jsonb, '{"index":"open-hand-fleet-step","url":"/api/2024/features/open-hand-fleet-step","name":"Fleet Step","level":{"index":"monk-11","url":"/api/2024/classes/monk/levels/11","name":"Monk 11"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"subclass":{"index":"warrior-of-the-open-hand","name":"Warrior of the Open Hand","url":"/api/2024/subclasses/warrior-of-the-open-hand"},"description":"When you take a Bonus Action other than Step of the Wind, you can also use Step of the Wind immediately after that Bonus Action."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Quivering Palm","desc":"You gain the ability to set up lethal vibrations in someone''s body. When you hit a creature with an Unarmed Strike, you can expend 4 Focus Points to start these imperceptible vibrations, which last for a number of days equal to your Monk level. The vibrations are harmless unless you take an action to end them. Alternatively, when you take the Attack action on your turn, you can forgo one of the attacks to end the vibrations. To end them, you and the target must be on the same plane of existence. When you end them, the target must make a Constitution saving throw, taking 10d12 Force damage on a failed save or half as much damage on a successful one.\n  You can have only one creature under the effect of this feature at a time. You can end the vibrations harmlessly (no action required)."}'::jsonb, '{"index":"open-hand-quivering-palm","url":"/api/2024/features/open-hand-quivering-palm","name":"Quivering Palm","level":{"index":"monk-17","url":"/api/2024/classes/monk/levels/17","name":"Monk 17"},"class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"subclass":{"index":"warrior-of-the-open-hand","name":"Warrior of the Open Hand","url":"/api/2024/subclasses/warrior-of-the-open-hand"},"description":"You gain the ability to set up lethal vibrations in someone''s body. When you hit a creature with an Unarmed Strike, you can expend 4 Focus Points to start these imperceptible vibrations, which last for a number of days equal to your Monk level. The vibrations are harmless unless you take an action to end them. Alternatively, when you take the Attack action on your turn, you can forgo one of the attacks to end the vibrations. To end them, you and the target must be on the same plane of existence. When you end them, the target must make a Constitution saving throw, taking 10d12 Force damage on a failed save or half as much damage on a successful one.\n  You can have only one creature under the effect of this feature at a time. You can end the vibrations harmlessly (no action required)."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Lay On Hands","desc":"Your blessed touch can heal wounds. You have a pool of healing power that replenishes when you finish a Long Rest. With that pool, you can restore a total number of Hit Points equal to five times your Paladin level.\n  As a Bonus Action, you can touch a creature (which could be yourself) and draw power from the pool of healing to restore a number of Hit Points to that creature, up to the maximum amount remaining in the pool.\n  You can also expend 5 Hit Points from the pool of healing power to remove the Poisoned condition from the creature; those points don''t also restore Hit Points to the creature."}'::jsonb, '{"index":"paladin-lay-on-hands","url":"/api/2024/features/paladin-lay-on-hands","name":"Lay On Hands","level":{"index":"paladin-1","url":"/api/2024/classes/paladin/levels/1","name":"Paladin 1"},"class":{"index":"paladin","url":"/api/2024/classes/paladin","name":"Paladin"},"description":"Your blessed touch can heal wounds. You have a pool of healing power that replenishes when you finish a Long Rest. With that pool, you can restore a total number of Hit Points equal to five times your Paladin level.\n  As a Bonus Action, you can touch a creature (which could be yourself) and draw power from the pool of healing to restore a number of Hit Points to that creature, up to the maximum amount remaining in the pool.\n  You can also expend 5 Hit Points from the pool of healing power to remove the Poisoned condition from the creature; those points don''t also restore Hit Points to the creature."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Spellcasting","desc":"You have learned to cast spells through prayer and meditation. See \"Spells\" for the rules on spellcasting. The information below details how you use those rules with Paladin spells, which appear in the Paladin spell list later in the class''s description.\n  Spell Slots. The Paladin Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest.\n  Prepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose two level 1 Paladin spells. Heroism and Searing Smite are recommended.\n  The number of spells on your list increases as you gain Paladin levels, as shown in the Prepared Spells column of the Paladin Features table. Whenever that number increases, choose additional Paladin spells until the number of spells on your list matches the number in the Paladin Features table. The chosen spells must be of a level for which you have spell slots. For example, if you''re a level 5 Paladin, your list of prepared spells can include six Paladin spells of level 1 or 2 in any combination.\n  If another Paladin feature gives you spells that you always have prepared, those spells don''t count against the number of spells you can prepare with this feature, but those spells otherwise count as Paladin spells for you.\n  Changing Your Prepared Spells. Whenever you finish a Long Rest, you can replace one spell on your list with another Paladin spell for which you have spell slots.\n  Spellcasting Ability. Charisma is your spellcasting ability for your Paladin spells.\n  Spellcasting Focus. You can use a Holy Symbol as a Spellcasting Focus for your Paladin spells."}'::jsonb, '{"index":"paladin-spellcasting","url":"/api/2024/features/paladin-spellcasting","name":"Spellcasting","level":{"index":"paladin-1","url":"/api/2024/classes/paladin/levels/1","name":"Paladin 1"},"class":{"index":"paladin","url":"/api/2024/classes/paladin","name":"Paladin"},"description":"You have learned to cast spells through prayer and meditation. See \"Spells\" for the rules on spellcasting. The information below details how you use those rules with Paladin spells, which appear in the Paladin spell list later in the class''s description.\n  Spell Slots. The Paladin Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest.\n  Prepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose two level 1 Paladin spells. Heroism and Searing Smite are recommended.\n  The number of spells on your list increases as you gain Paladin levels, as shown in the Prepared Spells column of the Paladin Features table. Whenever that number increases, choose additional Paladin spells until the number of spells on your list matches the number in the Paladin Features table. The chosen spells must be of a level for which you have spell slots. For example, if you''re a level 5 Paladin, your list of prepared spells can include six Paladin spells of level 1 or 2 in any combination.\n  If another Paladin feature gives you spells that you always have prepared, those spells don''t count against the number of spells you can prepare with this feature, but those spells otherwise count as Paladin spells for you.\n  Changing Your Prepared Spells. Whenever you finish a Long Rest, you can replace one spell on your list with another Paladin spell for which you have spell slots.\n  Spellcasting Ability. Charisma is your spellcasting ability for your Paladin spells.\n  Spellcasting Focus. You can use a Holy Symbol as a Spellcasting Focus for your Paladin spells."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Weapon Mastery","desc":"Your training with weapons allows you to use the mastery properties of two kinds of weapons of your choice with which you have proficiency, such as Longswords and Javelins.\nWhenever you finish a Long Rest, you can change the kinds of weapons you chose. For example, you could switch to using the mastery properties of Halberds and Flails."}'::jsonb, '{"index":"paladin-weapon-mastery","url":"/api/2024/features/paladin-weapon-mastery","name":"Weapon Mastery","level":{"index":"paladin-1","url":"/api/2024/classes/paladin/levels/1","name":"Paladin 1"},"class":{"index":"paladin","url":"/api/2024/classes/paladin","name":"Paladin"},"description":"Your training with weapons allows you to use the mastery properties of two kinds of weapons of your choice with which you have proficiency, such as Longswords and Javelins.\nWhenever you finish a Long Rest, you can change the kinds of weapons you chose. For example, you could switch to using the mastery properties of Halberds and Flails."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Fighting Style","desc":"You gain a Fighting Style feat of your choice (see \"Feats\" for feats). Instead of choosing one of those feats, you can choose the option below.\n  Blessed Warrior. You learn two Cleric cantrips of your choice (see the Cleric class''s section for a list of Cleric spells). Guidance and Sacred Flame are recommended. The chosen cantrips count as Paladin spells for you, and Charisma is your spellcasting ability for them. Whenever you gain a Paladin level, you can replace one of these cantrips with another Cleric cantrip."}'::jsonb, '{"index":"paladin-fighting-style","url":"/api/2024/features/paladin-fighting-style","name":"Fighting Style","level":{"index":"paladin-2","url":"/api/2024/classes/paladin/levels/2","name":"Paladin 2"},"class":{"index":"paladin","url":"/api/2024/classes/paladin","name":"Paladin"},"description":"You gain a Fighting Style feat of your choice (see \"Feats\" for feats). Instead of choosing one of those feats, you can choose the option below.\n  Blessed Warrior. You learn two Cleric cantrips of your choice (see the Cleric class''s section for a list of Cleric spells). Guidance and Sacred Flame are recommended. The chosen cantrips count as Paladin spells for you, and Charisma is your spellcasting ability for them. Whenever you gain a Paladin level, you can replace one of these cantrips with another Cleric cantrip."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Paladin''s Smite","desc":"You always have the Divine Smite spell prepared. In addition, you can cast it without expending a spell slot, but you must finish a Long Rest before you can cast it in this way again."}'::jsonb, '{"index":"paladin-paladins-smite","url":"/api/2024/features/paladin-paladins-smite","name":"Paladin''s Smite","level":{"index":"paladin-2","url":"/api/2024/classes/paladin/levels/2","name":"Paladin 2"},"class":{"index":"paladin","url":"/api/2024/classes/paladin","name":"Paladin"},"description":"You always have the Divine Smite spell prepared. In addition, you can cast it without expending a spell slot, but you must finish a Long Rest before you can cast it in this way again."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Channel Divinity","desc":"You can channel divine energy directly from the Outer Planes, using it to fuel magical effects. You start with one such effect: Divine Sense, which is described below. Other Paladin features give additional Channel Divinity effect options. Each time you use this class''s Channel Divinity, you choose which effect from this class to create.\n  You can use this class''s Channel Divinity twice. You regain one of its expended uses when you finish a Short Rest, and you regain all expended uses when you finish a Long Rest. You gain an additional use when you reach Paladin level 11.\n  If a Channel Divinity effect requires a saving throw, the DC equals the spell save DC from this class''s Spellcasting feature.\n  Divine Sense. As a Bonus Action, you can open your awareness to detect Celestials, Fiends, and Undead. For the next 10 minutes or until you have the Incapacitated condition, you know the location of any creature of those types within 60 feet of yourself, and you know its creature type. Within the same radius, you also detect the presence of any place or object that has been consecrated or desecrated, as with the Hallow spell."}'::jsonb, '{"index":"paladin-channel-divinity","url":"/api/2024/features/paladin-channel-divinity","name":"Channel Divinity","level":{"index":"paladin-3","url":"/api/2024/classes/paladin/levels/3","name":"Paladin 3"},"class":{"index":"paladin","url":"/api/2024/classes/paladin","name":"Paladin"},"description":"You can channel divine energy directly from the Outer Planes, using it to fuel magical effects. You start with one such effect: Divine Sense, which is described below. Other Paladin features give additional Channel Divinity effect options. Each time you use this class''s Channel Divinity, you choose which effect from this class to create.\n  You can use this class''s Channel Divinity twice. You regain one of its expended uses when you finish a Short Rest, and you regain all expended uses when you finish a Long Rest. You gain an additional use when you reach Paladin level 11.\n  If a Channel Divinity effect requires a saving throw, the DC equals the spell save DC from this class''s Spellcasting feature.\n  Divine Sense. As a Bonus Action, you can open your awareness to detect Celestials, Fiends, and Undead. For the next 10 minutes or until you have the Incapacitated condition, you know the location of any creature of those types within 60 feet of yourself, and you know its creature type. Within the same radius, you also detect the presence of any place or object that has been consecrated or desecrated, as with the Hallow spell."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Paladin Subclass","desc":"You gain a Paladin subclass of your choice. A subclass is a specialization that grants you features at certain Paladin levels. For the rest of your career, you gain each of your subclass''s features that are of your Paladin level or lower."}'::jsonb, '{"index":"paladin-subclass","url":"/api/2024/features/paladin-subclass","name":"Paladin Subclass","level":{"index":"paladin-3","url":"/api/2024/classes/paladin/levels/3","name":"Paladin 3"},"class":{"index":"paladin","url":"/api/2024/classes/paladin","name":"Paladin"},"description":"You gain a Paladin subclass of your choice. A subclass is a specialization that grants you features at certain Paladin levels. For the rest of your career, you gain each of your subclass''s features that are of your Paladin level or lower."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Ability Score Improvement","desc":"You gain the Ability Score Improvement feat (see \"Feats\") or another feat of your choice for which you qualify. You gain this feature again at Paladin levels 8, 12, and 16."}'::jsonb, '{"index":"paladin-ability-score-improvement","url":"/api/2024/features/paladin-ability-score-improvement","name":"Ability Score Improvement","level":{"index":"paladin-4","url":"/api/2024/classes/paladin/levels/4","name":"Paladin 4"},"class":{"index":"paladin","url":"/api/2024/classes/paladin","name":"Paladin"},"description":"You gain the Ability Score Improvement feat (see \"Feats\") or another feat of your choice for which you qualify. You gain this feature again at Paladin levels 8, 12, and 16."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Extra Attack","desc":"You can attack twice instead of once whenever you take the Attack action on your turn."}'::jsonb, '{"index":"paladin-extra-attack","url":"/api/2024/features/paladin-extra-attack","name":"Extra Attack","level":{"index":"paladin-5","url":"/api/2024/classes/paladin/levels/5","name":"Paladin 5"},"class":{"index":"paladin","url":"/api/2024/classes/paladin","name":"Paladin"},"description":"You can attack twice instead of once whenever you take the Attack action on your turn."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Faithful Steed","desc":"You can call on the aid of an otherworldly steed. You always have the Find Steed spell prepared.\n  You can also cast the spell once without expending a spell slot, and you regain the ability to do so when you finish a Long Rest."}'::jsonb, '{"index":"paladin-faithful-steed","url":"/api/2024/features/paladin-faithful-steed","name":"Faithful Steed","level":{"index":"paladin-5","url":"/api/2024/classes/paladin/levels/5","name":"Paladin 5"},"class":{"index":"paladin","url":"/api/2024/classes/paladin","name":"Paladin"},"description":"You can call on the aid of an otherworldly steed. You always have the Find Steed spell prepared.\n  You can also cast the spell once without expending a spell slot, and you regain the ability to do so when you finish a Long Rest."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Aura of Protection","desc":"You radiate a protective, unseeable aura in a 10-foot Emanation that originates from you. The aura is inactive while you have the Incapacitated condition.\n  You and your allies in the aura gain a bonus to saving throws equal to your Charisma modifier (minimum bonus of +1).\n  If another Paladin is present, a creature can benefit from only one Aura of Protection at a time; the creature chooses which aura while in them."}'::jsonb, '{"index":"paladin-aura-of-protection","url":"/api/2024/features/paladin-aura-of-protection","name":"Aura of Protection","level":{"index":"paladin-6","url":"/api/2024/classes/paladin/levels/6","name":"Paladin 6"},"class":{"index":"paladin","url":"/api/2024/classes/paladin","name":"Paladin"},"description":"You radiate a protective, unseeable aura in a 10-foot Emanation that originates from you. The aura is inactive while you have the Incapacitated condition.\n  You and your allies in the aura gain a bonus to saving throws equal to your Charisma modifier (minimum bonus of +1).\n  If another Paladin is present, a creature can benefit from only one Aura of Protection at a time; the creature chooses which aura while in them."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Abjure Foes","desc":"As a Magic action, you can expend one use of this class''s Channel Divinity to overwhelm foes with awe. As you present your Holy Symbol or weapon, you can target a number of creatures equal to your Charisma modifier (minimum of one creature) that you can see within 60 feet of yourself. Each target must succeed on a Wisdom saving throw or have the Frightened condition for 1 minute or until it takes any damage. While Frightened in this way, a target can do only one of the following on its turns: move, take an action, or take a Bonus Action."}'::jsonb, '{"index":"paladin-abjure-foes","url":"/api/2024/features/paladin-abjure-foes","name":"Abjure Foes","level":{"index":"paladin-9","url":"/api/2024/classes/paladin/levels/9","name":"Paladin 9"},"class":{"index":"paladin","url":"/api/2024/classes/paladin","name":"Paladin"},"description":"As a Magic action, you can expend one use of this class''s Channel Divinity to overwhelm foes with awe. As you present your Holy Symbol or weapon, you can target a number of creatures equal to your Charisma modifier (minimum of one creature) that you can see within 60 feet of yourself. Each target must succeed on a Wisdom saving throw or have the Frightened condition for 1 minute or until it takes any damage. While Frightened in this way, a target can do only one of the following on its turns: move, take an action, or take a Bonus Action."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Aura of Courage","desc":"You and your allies have Immunity to the Frightened condition while in your Aura of Protection. If a Frightened ally enters the aura, that condition has no effect on that ally while there."}'::jsonb, '{"index":"paladin-aura-of-courage","url":"/api/2024/features/paladin-aura-of-courage","name":"Aura of Courage","level":{"index":"paladin-10","url":"/api/2024/classes/paladin/levels/10","name":"Paladin 10"},"class":{"index":"paladin","url":"/api/2024/classes/paladin","name":"Paladin"},"description":"You and your allies have Immunity to the Frightened condition while in your Aura of Protection. If a Frightened ally enters the aura, that condition has no effect on that ally while there."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Radiant Strikes","desc":"Your strikes now carry supernatural power. When you hit a target with an attack roll using a Melee weapon or an Unarmed Strike, the target takes an extra 1d8 Radiant damage."}'::jsonb, '{"index":"paladin-radiant-strikes","url":"/api/2024/features/paladin-radiant-strikes","name":"Radiant Strikes","level":{"index":"paladin-11","url":"/api/2024/classes/paladin/levels/11","name":"Paladin 11"},"class":{"index":"paladin","url":"/api/2024/classes/paladin","name":"Paladin"},"description":"Your strikes now carry supernatural power. When you hit a target with an attack roll using a Melee weapon or an Unarmed Strike, the target takes an extra 1d8 Radiant damage."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Restoring Touch","desc":"When you use Lay On Hands on a creature, you can also remove one or more of the following conditions from the creature: Blinded, Charmed, Deafened, Frightened, Paralyzed, or Stunned. You must expend 5 Hit Points from the healing pool of Lay On Hands for each of these conditions you remove; those points don''t also restore Hit Points to the creature."}'::jsonb, '{"index":"paladin-restoring-touch","url":"/api/2024/features/paladin-restoring-touch","name":"Restoring Touch","level":{"index":"paladin-14","url":"/api/2024/classes/paladin/levels/14","name":"Paladin 14"},"class":{"index":"paladin","url":"/api/2024/classes/paladin","name":"Paladin"},"description":"When you use Lay On Hands on a creature, you can also remove one or more of the following conditions from the creature: Blinded, Charmed, Deafened, Frightened, Paralyzed, or Stunned. You must expend 5 Hit Points from the healing pool of Lay On Hands for each of these conditions you remove; those points don''t also restore Hit Points to the creature."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Aura Expansion","desc":"Your Aura of Protection is now a 30-foot Emanation."}'::jsonb, '{"index":"paladin-aura-expansion","url":"/api/2024/features/paladin-aura-expansion","name":"Aura Expansion","level":{"index":"paladin-18","url":"/api/2024/classes/paladin/levels/18","name":"Paladin 18"},"class":{"index":"paladin","url":"/api/2024/classes/paladin","name":"Paladin"},"description":"Your Aura of Protection is now a 30-foot Emanation."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Epic Boon","desc":"You gain an Epic Boon feat (see \"Feats\") or another feat of your choice for which you qualify. Boon of Truesight is recommended."}'::jsonb, '{"index":"paladin-epic-boon","url":"/api/2024/features/paladin-epic-boon","name":"Epic Boon","level":{"index":"paladin-19","url":"/api/2024/classes/paladin/levels/19","name":"Paladin 19"},"class":{"index":"paladin","url":"/api/2024/classes/paladin","name":"Paladin"},"description":"You gain an Epic Boon feat (see \"Feats\") or another feat of your choice for which you qualify. Boon of Truesight is recommended."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Oath of Devotion Spells","desc":"The magic of your oath ensures you always have certain spells ready; when you reach a Paladin level specified in the Oath of Devotion Spells table, you thereafter always have the listed spells prepared.\n\nOath of Devotion Spells\nPaladin Level / Spells\n3 / Protection from Evil and Good, Shielf of Faith\n5 / Aid, Zone of Truth\n9 / Beacon of Hope, Dispel Magic\n13 / Freedom of Movement, Guardian of Faith\n17 / Commune, Flame Strike"}'::jsonb, '{"index":"devotion-oath-of-devotion-spells","url":"/api/2024/features/devotion-oath-of-devotion-spells","name":"Oath of Devotion Spells","level":{"index":"paladin-3","url":"/api/2024/classes/paladin/levels/3","name":"Paladin 3"},"class":{"index":"paladin","url":"/api/2024/classes/paladin","name":"Paladin"},"subclass":{"index":"oath-of-devotion","name":"Oath of Devotion","url":"/api/2024/subclasses/oath-of-devotion"},"description":"The magic of your oath ensures you always have certain spells ready; when you reach a Paladin level specified in the Oath of Devotion Spells table, you thereafter always have the listed spells prepared.\n\nOath of Devotion Spells\nPaladin Level / Spells\n3 / Protection from Evil and Good, Shielf of Faith\n5 / Aid, Zone of Truth\n9 / Beacon of Hope, Dispel Magic\n13 / Freedom of Movement, Guardian of Faith\n17 / Commune, Flame Strike"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Sacred Weapon","desc":"When you take the Attack action, you can expend one use of your Channel Divinity to imbue one Melee weapon that you are holding with positive energy. For 10 minutes or until you use this feature again, you add your Charisma modifier to attack rolls you make with that weapon (minimum bonus of +1), and each time you hit with it, you cause it to deal its normal damage type or Radiant damage.\n  The weapon also emits Bright Light in a 20-foot radius and Dim Light 20 feet beyond that.\n  You can end this effect early (no action required). This effect also ends if you aren''t carrying the weapon."}'::jsonb, '{"index":"devotion-sacred-weapon","url":"/api/2024/features/devotion-sacred-weapon","name":"Sacred Weapon","level":{"index":"paladin-3","url":"/api/2024/classes/paladin/levels/3","name":"Paladin 3"},"class":{"index":"paladin","url":"/api/2024/classes/paladin","name":"Paladin"},"subclass":{"index":"oath-of-devotion","name":"Oath of Devotion","url":"/api/2024/subclasses/oath-of-devotion"},"description":"When you take the Attack action, you can expend one use of your Channel Divinity to imbue one Melee weapon that you are holding with positive energy. For 10 minutes or until you use this feature again, you add your Charisma modifier to attack rolls you make with that weapon (minimum bonus of +1), and each time you hit with it, you cause it to deal its normal damage type or Radiant damage.\n  The weapon also emits Bright Light in a 20-foot radius and Dim Light 20 feet beyond that.\n  You can end this effect early (no action required). This effect also ends if you aren''t carrying the weapon."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Aura of Devotion","desc":"You and your allies have Immunity to the Charmed condition while in your Aura of Protection. If a Charmed ally enters the aura, that condition has no effect on that ally while there."}'::jsonb, '{"index":"devotion-aura-of-devotion","url":"/api/2024/features/devotion-aura-of-devotion","name":"Aura of Devotion","level":{"index":"paladin-7","url":"/api/2024/classes/paladin/levels/7","name":"Paladin 7"},"class":{"index":"paladin","url":"/api/2024/classes/paladin","name":"Paladin"},"subclass":{"index":"oath-of-devotion","name":"Oath of Devotion","url":"/api/2024/subclasses/oath-of-devotion"},"description":"You and your allies have Immunity to the Charmed condition while in your Aura of Protection. If a Charmed ally enters the aura, that condition has no effect on that ally while there."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Smite of Protection","desc":"Your magical smite now radiates protective energy. Whenever you cast Divine Smite, you and your allies have Half Cover while in your Aura of Protection.\nThe aura has this benefit until the start of your next turn."}'::jsonb, '{"index":"devotion-smite-of-protection","url":"/api/2024/features/devotion-smite-of-protection","name":"Smite of Protection","level":{"index":"paladin-15","url":"/api/2024/classes/paladin/levels/15","name":"Paladin 15"},"class":{"index":"paladin","url":"/api/2024/classes/paladin","name":"Paladin"},"subclass":{"index":"oath-of-devotion","name":"Oath of Devotion","url":"/api/2024/subclasses/oath-of-devotion"},"description":"Your magical smite now radiates protective energy. Whenever you cast Divine Smite, you and your allies have Half Cover while in your Aura of Protection.\nThe aura has this benefit until the start of your next turn."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Holy Nimbus","desc":"As a Bonus Action, you can imbue your Aura of Protection with holy power, granting the benefits below for 10 minutes or until you end them (no action required). Once you use this feature, you can''t use it again until you finish a Long Rest. You can also restore your use of it by expending a level 5 spell slot (no action required).\n  Holy Ward. You have Advantage on any saving throw you are forced to make by a Fiend or an Undead.\n  Radiant Damage. Whenever an enemy starts its turn in the aura, that creature takes Radiant damage equal to your Charisma modifier plus your Proficiency Bonus.\n  Sunlight. The aura is filled with Bright Light that is sunlight."}'::jsonb, '{"index":"devotion-holy-nimbus","url":"/api/2024/features/devotion-holy-nimbus","name":"Holy Nimbus","level":{"index":"paladin-20","url":"/api/2024/classes/paladin/levels/20","name":"Paladin 20"},"class":{"index":"paladin","url":"/api/2024/classes/paladin","name":"Paladin"},"subclass":{"index":"oath-of-devotion","name":"Oath of Devotion","url":"/api/2024/subclasses/oath-of-devotion"},"description":"As a Bonus Action, you can imbue your Aura of Protection with holy power, granting the benefits below for 10 minutes or until you end them (no action required). Once you use this feature, you can''t use it again until you finish a Long Rest. You can also restore your use of it by expending a level 5 spell slot (no action required).\n  Holy Ward. You have Advantage on any saving throw you are forced to make by a Fiend or an Undead.\n  Radiant Damage. Whenever an enemy starts its turn in the aura, that creature takes Radiant damage equal to your Charisma modifier plus your Proficiency Bonus.\n  Sunlight. The aura is filled with Bright Light that is sunlight."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Spellcasting","desc":"You have learned to channel the magical essence of nature to cast spells. See \"Spells\" for the rules on spellcasting. The information below details how you use those rules with Ranger spells, which appear in the Ranger spell list later in the class''s description.\n  Spell Slots. The Ranger Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest.\n  Prepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose two level 1\nRanger spells. Cure Wounds and Ensnaring Strike are recommended.\n  The number of spells on your list increases as you gain Ranger levels, as shown in the Prepared Spells column of the Ranger Features table. Whenever that number increases, choose additional Ranger spells until the number of spells on your list matches the number in the Ranger Features table. The chosen spells must be of a level for which you have spell slots. For example, if you''re a level 5 Ranger, your list of prepared spells can include six Ranger spells of level 1 or 2 in any combination.\n  If another Ranger feature gives you spells that you always have prepared, those spells don''t count against the number of spells you can prepare with this feature, but those spells otherwise count as Ranger spells for you.\nChanging Your Prepared Spells. Whenever you finish a Long Rest, you can replace one spell on your list with another Ranger spell for which you have spell slots.\n  Spellcasting Ability. Wisdom is your spellcasting ability for your Ranger spells.\n  Spellcasting Focus. You can use a Druidic Focus as a Spellcasting Focus for your Ranger spells."}'::jsonb, '{"index":"ranger-spellcasting","url":"/api/2024/features/ranger-spellcasting","name":"Spellcasting","level":{"index":"ranger-1","url":"/api/2024/classes/ranger/levels/1","name":"Ranger 1"},"class":{"index":"ranger","url":"/api/2024/classes/ranger","name":"Ranger"},"description":"You have learned to channel the magical essence of nature to cast spells. See \"Spells\" for the rules on spellcasting. The information below details how you use those rules with Ranger spells, which appear in the Ranger spell list later in the class''s description.\n  Spell Slots. The Ranger Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest.\n  Prepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose two level 1\nRanger spells. Cure Wounds and Ensnaring Strike are recommended.\n  The number of spells on your list increases as you gain Ranger levels, as shown in the Prepared Spells column of the Ranger Features table. Whenever that number increases, choose additional Ranger spells until the number of spells on your list matches the number in the Ranger Features table. The chosen spells must be of a level for which you have spell slots. For example, if you''re a level 5 Ranger, your list of prepared spells can include six Ranger spells of level 1 or 2 in any combination.\n  If another Ranger feature gives you spells that you always have prepared, those spells don''t count against the number of spells you can prepare with this feature, but those spells otherwise count as Ranger spells for you.\nChanging Your Prepared Spells. Whenever you finish a Long Rest, you can replace one spell on your list with another Ranger spell for which you have spell slots.\n  Spellcasting Ability. Wisdom is your spellcasting ability for your Ranger spells.\n  Spellcasting Focus. You can use a Druidic Focus as a Spellcasting Focus for your Ranger spells."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Favored Enemy","desc":"You always have the Hunter''s Mark spell prepared. You can cast it twice without expending a spell slot, and you regain all expended uses of this ability when you finish a Long Rest.\n  The number of times you can cast the spell without a spell slot increases when you reach certain Ranger levels, as shown in the Favored Enemy column of the Ranger Features table."}'::jsonb, '{"index":"ranger-favored-enemy","url":"/api/2024/features/ranger-favored-enemy","name":"Favored Enemy","level":{"index":"ranger-1","url":"/api/2024/classes/ranger/levels/1","name":"Ranger 1"},"class":{"index":"ranger","url":"/api/2024/classes/ranger","name":"Ranger"},"description":"You always have the Hunter''s Mark spell prepared. You can cast it twice without expending a spell slot, and you regain all expended uses of this ability when you finish a Long Rest.\n  The number of times you can cast the spell without a spell slot increases when you reach certain Ranger levels, as shown in the Favored Enemy column of the Ranger Features table."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Weapon Mastery","desc":"Your training with weapons allows you to use the mastery properties of two kinds of weapons of your choice with which you have proficiency, such as Longbows and Shortswords.\n  Whenever you finish a Long Rest, you can change the kinds of weapons you chose. For example, you could switch to using the mastery properties of Scimitars and Longswords."}'::jsonb, '{"index":"ranger-weapon-mastery","url":"/api/2024/features/ranger-weapon-mastery","name":"Weapon Mastery","level":{"index":"ranger-1","url":"/api/2024/classes/ranger/levels/1","name":"Ranger 1"},"class":{"index":"ranger","url":"/api/2024/classes/ranger","name":"Ranger"},"description":"Your training with weapons allows you to use the mastery properties of two kinds of weapons of your choice with which you have proficiency, such as Longbows and Shortswords.\n  Whenever you finish a Long Rest, you can change the kinds of weapons you chose. For example, you could switch to using the mastery properties of Scimitars and Longswords."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Deft Explorer","desc":"Thanks to your travels, you gain the following benefits.\n  Expertise. Choose one of your skill proficiencies with which you lack Expertise. You gain Expertise in that skill.\n  Languages. You know two languages of your choice from the language tables in \"Character Creation.\""}'::jsonb, '{"index":"ranger-deft-explorer","url":"/api/2024/features/ranger-deft-explorer","name":"Deft Explorer","level":{"index":"ranger-2","url":"/api/2024/classes/ranger/levels/2","name":"Ranger 2"},"class":{"index":"ranger","url":"/api/2024/classes/ranger","name":"Ranger"},"description":"Thanks to your travels, you gain the following benefits.\n  Expertise. Choose one of your skill proficiencies with which you lack Expertise. You gain Expertise in that skill.\n  Languages. You know two languages of your choice from the language tables in \"Character Creation.\""}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Fighting Style","desc":"You gain a Fighting Style feat of your choice (see \"Feats\"). Instead of choosing one of those feats, you can choose the option below.\n  Druidic Warrior. You learn two Druid cantrips of your choice (see the Druid class''s section for a list of Druid spells). Guidance and Starry Wisp are recommended. The chosen cantrips count as Ranger spells for you, and Wisdom is your spellcasting ability for them. Whenever you gain a Ranger level, you can replace one of these cantrips with another Druid cantrip."}'::jsonb, '{"index":"ranger-fighting-style","url":"/api/2024/features/ranger-fighting-style","name":"Fighting Style","level":{"index":"ranger-2","url":"/api/2024/classes/ranger/levels/2","name":"Ranger 2"},"class":{"index":"ranger","url":"/api/2024/classes/ranger","name":"Ranger"},"description":"You gain a Fighting Style feat of your choice (see \"Feats\"). Instead of choosing one of those feats, you can choose the option below.\n  Druidic Warrior. You learn two Druid cantrips of your choice (see the Druid class''s section for a list of Druid spells). Guidance and Starry Wisp are recommended. The chosen cantrips count as Ranger spells for you, and Wisdom is your spellcasting ability for them. Whenever you gain a Ranger level, you can replace one of these cantrips with another Druid cantrip."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Ranger Subclass","desc":"You gain a Ranger subclass of your choice. A subclass is a specialization that grants you features at certain Ranger levels. For the rest of your career, you gain each of your subclass''s features that are of your Ranger level or lower."}'::jsonb, '{"index":"ranger-subclass","url":"/api/2024/features/ranger-subclass","name":"Ranger Subclass","level":{"index":"ranger-3","url":"/api/2024/classes/ranger/levels/3","name":"Ranger 3"},"class":{"index":"ranger","url":"/api/2024/classes/ranger","name":"Ranger"},"description":"You gain a Ranger subclass of your choice. A subclass is a specialization that grants you features at certain Ranger levels. For the rest of your career, you gain each of your subclass''s features that are of your Ranger level or lower."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Ability Score Improvement","desc":"You gain the Ability Score Improvement feat (see \"Feats\") or another feat of your choice for which you qualify. You gain this feature again at Ranger levels 8, 12, and 16."}'::jsonb, '{"index":"ranger-ability-score-improvement","url":"/api/2024/features/ranger-ability-score-improvement","name":"Ability Score Improvement","level":{"index":"ranger-4","url":"/api/2024/classes/ranger/levels/4","name":"Ranger 4"},"class":{"index":"ranger","url":"/api/2024/classes/ranger","name":"Ranger"},"description":"You gain the Ability Score Improvement feat (see \"Feats\") or another feat of your choice for which you qualify. You gain this feature again at Ranger levels 8, 12, and 16."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Extra Attack","desc":"You can attack twice instead of once whenever you take the Attack action on your turn."}'::jsonb, '{"index":"ranger-extra-attack","url":"/api/2024/features/ranger-extra-attack","name":"Extra Attack","level":{"index":"ranger-5","url":"/api/2024/classes/ranger/levels/5","name":"Ranger 5"},"class":{"index":"ranger","url":"/api/2024/classes/ranger","name":"Ranger"},"description":"You can attack twice instead of once whenever you take the Attack action on your turn."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Roving","desc":"Your Speed increases by 10 feet while you aren''t wearing Heavy armor. You also have a Climb Speed and a Swim Speed equal to your Speed."}'::jsonb, '{"index":"ranger-roving","url":"/api/2024/features/ranger-roving","name":"Roving","level":{"index":"ranger-6","url":"/api/2024/classes/ranger/levels/6","name":"Ranger 6"},"class":{"index":"ranger","url":"/api/2024/classes/ranger","name":"Ranger"},"description":"Your Speed increases by 10 feet while you aren''t wearing Heavy armor. You also have a Climb Speed and a Swim Speed equal to your Speed."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Expertise","desc":"Choose two of your skill proficiencies with which you lack Expertise. You gain Expertise in those skills."}'::jsonb, '{"index":"ranger-expertise","url":"/api/2024/features/ranger-expertise","name":"Expertise","level":{"index":"ranger-9","url":"/api/2024/classes/ranger/levels/9","name":"Ranger 9"},"class":{"index":"ranger","url":"/api/2024/classes/ranger","name":"Ranger"},"description":"Choose two of your skill proficiencies with which you lack Expertise. You gain Expertise in those skills."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Tireless","desc":"Primal forces now help fuel you on your journeys, granting you the following benefits.\n  Temporary Hit Points. As a Magic action, you can give yourself a number of Temporary Hit Points equal to 1d8 plus your Wisdom modifier (minimum of 1). You can use this action a number of times equal to your Wisdom modifier (minimum of once), and you regain all expended uses when you finish a Long Rest.\n  Decrease Exhaustion. Whenever you finish a Short Rest, your Exhaustion level, if any, decreases by 1."}'::jsonb, '{"index":"ranger-tireless","url":"/api/2024/features/ranger-tireless","name":"Tireless","level":{"index":"ranger-10","url":"/api/2024/classes/ranger/levels/10","name":"Ranger 10"},"class":{"index":"ranger","url":"/api/2024/classes/ranger","name":"Ranger"},"description":"Primal forces now help fuel you on your journeys, granting you the following benefits.\n  Temporary Hit Points. As a Magic action, you can give yourself a number of Temporary Hit Points equal to 1d8 plus your Wisdom modifier (minimum of 1). You can use this action a number of times equal to your Wisdom modifier (minimum of once), and you regain all expended uses when you finish a Long Rest.\n  Decrease Exhaustion. Whenever you finish a Short Rest, your Exhaustion level, if any, decreases by 1."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Relentless Hunter","desc":"Taking damage can''t break your Concentration on Hunter''s Mark."}'::jsonb, '{"index":"ranger-relentless-hunter","url":"/api/2024/features/ranger-relentless-hunter","name":"Relentless Hunter","level":{"index":"ranger-13","url":"/api/2024/classes/ranger/levels/13","name":"Ranger 13"},"class":{"index":"ranger","url":"/api/2024/classes/ranger","name":"Ranger"},"description":"Taking damage can''t break your Concentration on Hunter''s Mark."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Nature''s Veil","desc":"You invoke spirits of nature to magically hide yourself. As a Bonus Action, you can give yourself the Invisible condition until the end of your next turn.\n  You can use this feature a number of times equal to your Wisdom modifier (minimum of once), and you regain all expended uses when you finish a Long Rest."}'::jsonb, '{"index":"ranger-natures-veil","url":"/api/2024/features/ranger-natures-veil","name":"Nature''s Veil","level":{"index":"ranger-14","url":"/api/2024/classes/ranger/levels/14","name":"Ranger 14"},"class":{"index":"ranger","url":"/api/2024/classes/ranger","name":"Ranger"},"description":"You invoke spirits of nature to magically hide yourself. As a Bonus Action, you can give yourself the Invisible condition until the end of your next turn.\n  You can use this feature a number of times equal to your Wisdom modifier (minimum of once), and you regain all expended uses when you finish a Long Rest."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Precise Hunter","desc":"You have Advantage on attack rolls against the creature currently marked by your Hunter''s Mark."}'::jsonb, '{"index":"ranger-precise-hunter","url":"/api/2024/features/ranger-precise-hunter","name":"Precise Hunter","level":{"index":"ranger-17","url":"/api/2024/classes/ranger/levels/17","name":"Ranger 17"},"class":{"index":"ranger","url":"/api/2024/classes/ranger","name":"Ranger"},"description":"You have Advantage on attack rolls against the creature currently marked by your Hunter''s Mark."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Feral Senses","desc":"Your connection to the forces of nature grants you Blindsight with a range of 30 feet."}'::jsonb, '{"index":"ranger-feral-senses","url":"/api/2024/features/ranger-feral-senses","name":"Feral Senses","level":{"index":"ranger-18","url":"/api/2024/classes/ranger/levels/18","name":"Ranger 18"},"class":{"index":"ranger","url":"/api/2024/classes/ranger","name":"Ranger"},"description":"Your connection to the forces of nature grants you Blindsight with a range of 30 feet."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Epic Boon","desc":"You gain an Epic Boon feat (see \"Feats\") or another feat of your choice for which you qualify. Boon of Dimensional Travel is recommended."}'::jsonb, '{"index":"ranger-epic-boon","url":"/api/2024/features/ranger-epic-boon","name":"Epic Boon","level":{"index":"ranger-19","url":"/api/2024/classes/ranger/levels/19","name":"Ranger 19"},"class":{"index":"ranger","url":"/api/2024/classes/ranger","name":"Ranger"},"description":"You gain an Epic Boon feat (see \"Feats\") or another feat of your choice for which you qualify. Boon of Dimensional Travel is recommended."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Foe Slayer","desc":"The damage die of your Hunter''s Mark is a d10 rather than a d6."}'::jsonb, '{"index":"ranger-foe-slayer","url":"/api/2024/features/ranger-foe-slayer","name":"Foe Slayer","level":{"index":"ranger-20","url":"/api/2024/classes/ranger/levels/20","name":"Ranger 20"},"class":{"index":"ranger","url":"/api/2024/classes/ranger","name":"Ranger"},"description":"The damage die of your Hunter''s Mark is a d10 rather than a d6."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Hunter''s Lore","desc":"You can call on the forces of nature to reveal certain strengths and weaknesses of your prey. While a creature is marked by your Hunter''s Mark, you know whether that creature has any Immunities, Resistances, or Vulnerabilities, and if the creature has any, you know what they are."}'::jsonb, '{"index":"hunter-hunters-lore","url":"/api/2024/features/hunter-hunters-lore","name":"Hunter''s Lore","level":{"index":"ranger-3","url":"/api/2024/classes/ranger/levels/3","name":"Ranger 3"},"class":{"index":"ranger","url":"/api/2024/classes/ranger","name":"Ranger"},"subclass":{"index":"hunter","url":"/api/2024/subclasses/hunter","name":"Hunter"},"description":"You can call on the forces of nature to reveal certain strengths and weaknesses of your prey. While a creature is marked by your Hunter''s Mark, you know whether that creature has any Immunities, Resistances, or Vulnerabilities, and if the creature has any, you know what they are."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Hunter''s Prey","desc":"You gain one of the following feature options of your choice. Whenever you finish a Short or Long Rest, you can replace the chosen option with the other one.\n  Colossus Slayer. Your tenacity can wear down even the most resilient foes. When you hit a creature with a weapon, the weapon deals an extra 1d8 damage to the target if it''s missing any of its Hit Points. You can deal this extra damage only once per turn.\n  Horde Breaker. Once on each of your turns when you make an attack with a weapon, you can make another attack with the same weapon against a different creature that is within 5 feet of the original target, that is within the weapon''s range, and that you haven''t attacked this turn."}'::jsonb, '{"index":"hunter-hunters-prey","url":"/api/2024/features/hunter-hunters-prey","name":"Hunter''s Prey","level":{"index":"ranger-3","url":"/api/2024/classes/ranger/levels/3","name":"Ranger 3"},"class":{"index":"ranger","url":"/api/2024/classes/ranger","name":"Ranger"},"subclass":{"index":"hunter","url":"/api/2024/subclasses/hunter","name":"Hunter"},"description":"You gain one of the following feature options of your choice. Whenever you finish a Short or Long Rest, you can replace the chosen option with the other one.\n  Colossus Slayer. Your tenacity can wear down even the most resilient foes. When you hit a creature with a weapon, the weapon deals an extra 1d8 damage to the target if it''s missing any of its Hit Points. You can deal this extra damage only once per turn.\n  Horde Breaker. Once on each of your turns when you make an attack with a weapon, you can make another attack with the same weapon against a different creature that is within 5 feet of the original target, that is within the weapon''s range, and that you haven''t attacked this turn."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Defensive Tactics","desc":"You gain one of the following feature options of your choice. Whenever you finish a Short or Long Rest, you can replace the chosen option with the other one.\n  Escape the Horde. Opportunity Attacks have Disadvantage against you.\n  Multiattack Defense. When a creature hits you with an attack roll, that creature has Disadvantage on all other attack rolls against you this turn."}'::jsonb, '{"index":"hunter-defensive-tactics","url":"/api/2024/features/hunter-defensive-tactics","name":"Defensive Tactics","level":{"index":"ranger-7","url":"/api/2024/classes/ranger/levels/7","name":"Ranger 7"},"class":{"index":"ranger","url":"/api/2024/classes/ranger","name":"Ranger"},"subclass":{"index":"hunter","url":"/api/2024/subclasses/hunter","name":"Hunter"},"description":"You gain one of the following feature options of your choice. Whenever you finish a Short or Long Rest, you can replace the chosen option with the other one.\n  Escape the Horde. Opportunity Attacks have Disadvantage against you.\n  Multiattack Defense. When a creature hits you with an attack roll, that creature has Disadvantage on all other attack rolls against you this turn."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Superior Hunter''s Prey","desc":"Once per turn when you deal damage to a creature marked by your Hunter''s Mark, you can also deal that spell''s extra damage to a different creature that you can see within 30 feet of the first creature."}'::jsonb, '{"index":"hunter-superior-hunters-prey","url":"/api/2024/features/hunter-superior-hunters-prey","name":"Superior Hunter''s Prey","level":{"index":"ranger-11","url":"/api/2024/classes/ranger/levels/11","name":"Ranger 11"},"class":{"index":"ranger","url":"/api/2024/classes/ranger","name":"Ranger"},"subclass":{"index":"hunter","url":"/api/2024/subclasses/hunter","name":"Hunter"},"description":"Once per turn when you deal damage to a creature marked by your Hunter''s Mark, you can also deal that spell''s extra damage to a different creature that you can see within 30 feet of the first creature."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Superior Hunter''s Defense","desc":"When you take damage, you can take a Reaction to give yourself Resistance to that damage and any other damage of the same type until the end of the current turn."}'::jsonb, '{"index":"hunter-superior-hunters-defense","url":"/api/2024/features/hunter-superior-hunters-defense","name":"Superior Hunter''s Defense","level":{"index":"ranger-15","url":"/api/2024/classes/ranger/levels/15","name":"Ranger 15"},"class":{"index":"ranger","url":"/api/2024/classes/ranger","name":"Ranger"},"subclass":{"index":"hunter","url":"/api/2024/subclasses/hunter","name":"Hunter"},"description":"When you take damage, you can take a Reaction to give yourself Resistance to that damage and any other damage of the same type until the end of the current turn."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Expertise","desc":"You gain Expertise in two of your skill proficiencies of your choice. Sleight of Hand and Stealth are recommended if you have proficiency in them.\n At Rogue level 6, you gain Expertise in two more of your skill proficiencies of your choice."}'::jsonb, '{"index":"rogue-expertise","url":"/api/2024/features/rogue-expertise","name":"Expertise","level":{"index":"rogue-1","url":"/api/2024/classes/rogue/levels/1","name":"Rogue 1"},"class":{"index":"rogue","url":"/api/2024/classes/rogue","name":"Rogue"},"description":"You gain Expertise in two of your skill proficiencies of your choice. Sleight of Hand and Stealth are recommended if you have proficiency in them.\n At Rogue level 6, you gain Expertise in two more of your skill proficiencies of your choice."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Sneak Attack","desc":"You know how to strike subtly and exploit a foe''s distraction. Once per turn, you can deal an extra 1d6 damage to one creature you hit with an attack roll if you have Advantage on the roll and the attack uses a Finesse or a Ranged weapon. The extra damage''s type is the same as the weapon''s type.\n You don''t need Advantage on the attack roll if at least one of your allies is within 5 feet of the target, the ally doesn''t have the Incapacitated condition, and you don''t have Disadvantage on the attack roll.\n The extra damage increases as you gain Rogue levels, as shown in the Sneak Attack column of the Rogue Features table."}'::jsonb, '{"index":"rogue-sneak-attack","url":"/api/2024/features/rogue-sneak-attack","name":"Sneak Attack","level":{"index":"rogue-1","url":"/api/2024/classes/rogue/levels/1","name":"Rogue 1"},"class":{"index":"rogue","url":"/api/2024/classes/rogue","name":"Rogue"},"description":"You know how to strike subtly and exploit a foe''s distraction. Once per turn, you can deal an extra 1d6 damage to one creature you hit with an attack roll if you have Advantage on the roll and the attack uses a Finesse or a Ranged weapon. The extra damage''s type is the same as the weapon''s type.\n You don''t need Advantage on the attack roll if at least one of your allies is within 5 feet of the target, the ally doesn''t have the Incapacitated condition, and you don''t have Disadvantage on the attack roll.\n The extra damage increases as you gain Rogue levels, as shown in the Sneak Attack column of the Rogue Features table."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Thieves'' Cant","desc":"You picked up various languages in the communities where you plied your roguish talents. You know Thieves'' Cant and one other language of your choice, which you choose from the language tables in \"Character Creation.\""}'::jsonb, '{"index":"rogue-thieves-cant","url":"/api/2024/features/rogue-thieves-cant","name":"Thieves'' Cant","level":{"index":"rogue-1","url":"/api/2024/classes/rogue/levels/1","name":"Rogue 1"},"class":{"index":"rogue","url":"/api/2024/classes/rogue","name":"Rogue"},"description":"You picked up various languages in the communities where you plied your roguish talents. You know Thieves'' Cant and one other language of your choice, which you choose from the language tables in \"Character Creation.\""}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Weapon Mastery","desc":"Your training with weapons allows you to use the mastery properties of two kinds of weapons of your choice with which you have proficiency, such as Daggers and Shortbows.\n Whenever you finish a Long Rest, you can change the kinds of weapons you chose. For example, you could switch to using the mastery properties of Scimitars and Shortswords."}'::jsonb, '{"index":"rogue-weapon-mastery","url":"/api/2024/features/rogue-weapon-mastery","name":"Weapon Mastery","level":{"index":"rogue-1","url":"/api/2024/classes/rogue/levels/1","name":"Rogue 1"},"class":{"index":"rogue","url":"/api/2024/classes/rogue","name":"Rogue"},"description":"Your training with weapons allows you to use the mastery properties of two kinds of weapons of your choice with which you have proficiency, such as Daggers and Shortbows.\n Whenever you finish a Long Rest, you can change the kinds of weapons you chose. For example, you could switch to using the mastery properties of Scimitars and Shortswords."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Cunning Action","desc":"Your quick thinking and agility allow you to move and act quickly. On your turn, you can take one of the following actions as a Bonus Action: Dash, Disengage, or Hide."}'::jsonb, '{"index":"rogue-cunning-action","url":"/api/2024/features/rogue-cunning-action","name":"Cunning Action","level":{"index":"rogue-2","url":"/api/2024/classes/rogue/levels/2","name":"Rogue 2"},"class":{"index":"rogue","url":"/api/2024/classes/rogue","name":"Rogue"},"description":"Your quick thinking and agility allow you to move and act quickly. On your turn, you can take one of the following actions as a Bonus Action: Dash, Disengage, or Hide."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Rogue Subclass","desc":"You gain a Rogue subclass of your choice. A subclass is a specialization that grants you features at certain Rogue levels. For the rest of your career, you gain each of your subclass''s features that are of your Rogue level or lower."}'::jsonb, '{"index":"rogue-subclass","url":"/api/2024/features/rogue-subclass","name":"Rogue Subclass","level":{"index":"rogue-3","url":"/api/2024/classes/rogue/levels/3","name":"Rogue 3"},"class":{"index":"rogue","url":"/api/2024/classes/rogue","name":"Rogue"},"description":"You gain a Rogue subclass of your choice. A subclass is a specialization that grants you features at certain Rogue levels. For the rest of your career, you gain each of your subclass''s features that are of your Rogue level or lower."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Steady Aim","desc":"As a Bonus Action, you give yourself Advantage on your next attack roll on the current turn. You can use this feature only if you haven''t moved during this turn, and after you use it, your Speed is 0 until the end of the current turn."}'::jsonb, '{"index":"rogue-steady-aim","url":"/api/2024/features/rogue-steady-aim","name":"Steady Aim","level":{"index":"rogue-3","url":"/api/2024/classes/rogue/levels/3","name":"Rogue 3"},"class":{"index":"rogue","url":"/api/2024/classes/rogue","name":"Rogue"},"description":"As a Bonus Action, you give yourself Advantage on your next attack roll on the current turn. You can use this feature only if you haven''t moved during this turn, and after you use it, your Speed is 0 until the end of the current turn."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Ability Score Improvement","desc":"You gain the Ability Score Improvement feat (see \"Feats\") or another feat of your choice for which you qualify. You gain this feature again at Rogue levels 8, 10, 12, and 16."}'::jsonb, '{"index":"rogue-ability-score-improvement","url":"/api/2024/features/rogue-ability-score-improvement","name":"Ability Score Improvement","level":{"index":"rogue-4","url":"/api/2024/classes/rogue/levels/4","name":"Rogue 4"},"class":{"index":"rogue","url":"/api/2024/classes/rogue","name":"Rogue"},"description":"You gain the Ability Score Improvement feat (see \"Feats\") or another feat of your choice for which you qualify. You gain this feature again at Rogue levels 8, 10, 12, and 16."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Cunning Strike","desc":"You''ve developed cunning ways to use your Sneak Attack. When you deal Sneak Attack damage, you can add one of the following Cunning Strike effects.\n Each effect has a die cost, which is the number of Sneak Attack damage dice you must forgo to add the effect. You remove the die before rolling, and the effect occurs immediately after the attack''s damage is dealt. For example, if you add the Poison effect, remove 1d6 from the Sneak Attack''s damage before rolling.\n If a Cunning Strike effect requires a saving throw, the DC equals 8 plus your Dexterity modifier and Proficiency Bonus.\n Poison (Cost: 1d6). You add a toxin to your strike, forcing the target to make a Constitution saving throw. On a failed save, the target has the Poisoned condition for 1 minute. At the end of each of its turns, the Poisoned target repeats the save, ending the effect on itself on a success.\n To use this effect, you must have a Poisoner''s Kit on your person.\n Trip (Cost: 1d6). If the target is Large or smaller, it must succeed on a Dexterity saving throw or have the Prone condition.\n Withdraw (Cost: 1d6). Immediately after the attack, you move up to half your Speed without provoking Opportunity Attacks."}'::jsonb, '{"index":"rogue-cunning-strike","url":"/api/2024/features/rogue-cunning-strike","name":"Cunning Strike","level":{"index":"rogue-5","url":"/api/2024/classes/rogue/levels/5","name":"Rogue 5"},"class":{"index":"rogue","url":"/api/2024/classes/rogue","name":"Rogue"},"description":"You''ve developed cunning ways to use your Sneak Attack. When you deal Sneak Attack damage, you can add one of the following Cunning Strike effects.\n Each effect has a die cost, which is the number of Sneak Attack damage dice you must forgo to add the effect. You remove the die before rolling, and the effect occurs immediately after the attack''s damage is dealt. For example, if you add the Poison effect, remove 1d6 from the Sneak Attack''s damage before rolling.\n If a Cunning Strike effect requires a saving throw, the DC equals 8 plus your Dexterity modifier and Proficiency Bonus.\n Poison (Cost: 1d6). You add a toxin to your strike, forcing the target to make a Constitution saving throw. On a failed save, the target has the Poisoned condition for 1 minute. At the end of each of its turns, the Poisoned target repeats the save, ending the effect on itself on a success.\n To use this effect, you must have a Poisoner''s Kit on your person.\n Trip (Cost: 1d6). If the target is Large or smaller, it must succeed on a Dexterity saving throw or have the Prone condition.\n Withdraw (Cost: 1d6). Immediately after the attack, you move up to half your Speed without provoking Opportunity Attacks."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Uncanny Dodge","desc":"When an attacker that you can see hits you with an attack roll, you can take a Reaction to halve the attack''s damage against you (round down)."}'::jsonb, '{"index":"rogue-uncanny-dodge","url":"/api/2024/features/rogue-uncanny-dodge","name":"Uncanny Dodge","level":{"index":"rogue-5","url":"/api/2024/classes/rogue/levels/5","name":"Rogue 5"},"class":{"index":"rogue","url":"/api/2024/classes/rogue","name":"Rogue"},"description":"When an attacker that you can see hits you with an attack roll, you can take a Reaction to halve the attack''s damage against you (round down)."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Evasion","desc":"You can nimbly dodge out of the way of certain dangers.\n When you''re subjected to an effect that allows you to make a Dexterity saving throw to take only half damage, you instead take no damage if you succeed on the saving throw and only half damage if you fail. You can''t use this feature if you have the Incapacitated condition."}'::jsonb, '{"index":"rogue-evasion","url":"/api/2024/features/rogue-evasion","name":"Evasion","level":{"index":"rogue-7","url":"/api/2024/classes/rogue/levels/7","name":"Rogue 7"},"class":{"index":"rogue","url":"/api/2024/classes/rogue","name":"Rogue"},"description":"You can nimbly dodge out of the way of certain dangers.\n When you''re subjected to an effect that allows you to make a Dexterity saving throw to take only half damage, you instead take no damage if you succeed on the saving throw and only half damage if you fail. You can''t use this feature if you have the Incapacitated condition."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Reliable Talent","desc":"Whenever you make an ability check that uses one of your skill or tool proficiencies, you can treat a d20 roll of 9 or lower as a 10."}'::jsonb, '{"index":"rogue-reliable-talent","url":"/api/2024/features/rogue-reliable-talent","name":"Reliable Talent","level":{"index":"rogue-7","url":"/api/2024/classes/rogue/levels/7","name":"Rogue 7"},"class":{"index":"rogue","url":"/api/2024/classes/rogue","name":"Rogue"},"description":"Whenever you make an ability check that uses one of your skill or tool proficiencies, you can treat a d20 roll of 9 or lower as a 10."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Improved Cunning Strike","desc":"You can use up to two Cunning Strike effects when you deal Sneak Attack damage, paying the die cost for each effect."}'::jsonb, '{"index":"rogue-improved-cunning-strike","url":"/api/2024/features/rogue-improved-cunning-strike","name":"Improved Cunning Strike","level":{"index":"rogue-11","url":"/api/2024/classes/rogue/levels/11","name":"Rogue 11"},"class":{"index":"rogue","url":"/api/2024/classes/rogue","name":"Rogue"},"description":"You can use up to two Cunning Strike effects when you deal Sneak Attack damage, paying the die cost for each effect."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Devious Strikes","desc":"You''ve practiced new ways to use your Sneak Attack deviously. The following effects are now among your Cunning Strike options.\n Daze (Cost: 2d6). The target must succeed on a Constitution saving throw, or on its next turn, it can do only one of the following: move or take an action or a Bonus Action.\n Knock Out (Cost: 6d6). The target must succeed on a Constitution saving throw, or it has the Unconscious condition for 1 minute or until it takes any damage. The Unconscious target repeats the save at the end of each of its turns, ending the effect on itself on a success.\n Obscure (Cost: 3d6). The target must succeed on a Dexterity saving throw, or it has the Blinded condition until the end of its next turn."}'::jsonb, '{"index":"rogue-devious-strikes","url":"/api/2024/features/rogue-devious-strikes","name":"Devious Strikes","level":{"index":"rogue-14","url":"/api/2024/classes/rogue/levels/14","name":"Rogue 14"},"class":{"index":"rogue","url":"/api/2024/classes/rogue","name":"Rogue"},"description":"You''ve practiced new ways to use your Sneak Attack deviously. The following effects are now among your Cunning Strike options.\n Daze (Cost: 2d6). The target must succeed on a Constitution saving throw, or on its next turn, it can do only one of the following: move or take an action or a Bonus Action.\n Knock Out (Cost: 6d6). The target must succeed on a Constitution saving throw, or it has the Unconscious condition for 1 minute or until it takes any damage. The Unconscious target repeats the save at the end of each of its turns, ending the effect on itself on a success.\n Obscure (Cost: 3d6). The target must succeed on a Dexterity saving throw, or it has the Blinded condition until the end of its next turn."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Slippery Mind","desc":"Your cunning mind is exceptionally difficult to control.\n You gain proficiency in Wisdom and Charisma saving throws."}'::jsonb, '{"index":"rogue-slippery-mind","url":"/api/2024/features/rogue-slippery-mind","name":"Slippery Mind","level":{"index":"rogue-15","url":"/api/2024/classes/rogue/levels/15","name":"Rogue 15"},"class":{"index":"rogue","url":"/api/2024/classes/rogue","name":"Rogue"},"description":"Your cunning mind is exceptionally difficult to control.\n You gain proficiency in Wisdom and Charisma saving throws."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Elusive","desc":"You''re so evasive that attackers rarely gain the upper hand against you. No attack roll can have Advantage against you unless you have the Incapacitated condition."}'::jsonb, '{"index":"rogue-elusive","url":"/api/2024/features/rogue-elusive","name":"Elusive","level":{"index":"rogue-18","url":"/api/2024/classes/rogue/levels/18","name":"Rogue 18"},"class":{"index":"rogue","url":"/api/2024/classes/rogue","name":"Rogue"},"description":"You''re so evasive that attackers rarely gain the upper hand against you. No attack roll can have Advantage against you unless you have the Incapacitated condition."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Epic Boon","desc":"You gain an Epic Boon feat (see \"Feats\") or another feat of your choice for which you qualify. Boon of the Night Spirit is recommended."}'::jsonb, '{"index":"rogue-epic-boon","url":"/api/2024/features/rogue-epic-boon","name":"Epic Boon","level":{"index":"rogue-19","url":"/api/2024/classes/rogue/levels/19","name":"Rogue 19"},"class":{"index":"rogue","url":"/api/2024/classes/rogue","name":"Rogue"},"description":"You gain an Epic Boon feat (see \"Feats\") or another feat of your choice for which you qualify. Boon of the Night Spirit is recommended."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Stroke of Luck","desc":"You have a marvelous knack for succeeding when you need to. If you fail a D20 Test, you can turn the roll into a 20.\n Once you use this feature, you can''t use it again until you finish a Short or Long Rest."}'::jsonb, '{"index":"rogue-stroke-of-luck","url":"/api/2024/features/rogue-stroke-of-luck","name":"Stroke of Luck","level":{"index":"rogue-20","url":"/api/2024/classes/rogue/levels/20","name":"Rogue 20"},"class":{"index":"rogue","url":"/api/2024/classes/rogue","name":"Rogue"},"description":"You have a marvelous knack for succeeding when you need to. If you fail a D20 Test, you can turn the roll into a 20.\n Once you use this feature, you can''t use it again until you finish a Short or Long Rest."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Fast Hands","desc":"As a Bonus Action, you can do one of the following.\n Sleight of Hand. Make a Dexterity (Sleight of Hand) check to pick a lock or disarm a trap with Thieves'' Tools or to pick a pocket.\n Use an Object. Take the Utilize action, or take the Magic action to use a magic item that requires that action."}'::jsonb, '{"index":"thief-fast-hands","url":"/api/2024/features/thief-fast-hands","name":"Fast Hands","level":{"index":"rogue-3","url":"/api/2024/classes/rogue/levels/3","name":"Rogue 3"},"class":{"index":"rogue","url":"/api/2024/classes/rogue","name":"Rogue"},"subclass":{"index":"thief","url":"/api/2024/subclasses/thief","name":"Thief"},"description":"As a Bonus Action, you can do one of the following.\n Sleight of Hand. Make a Dexterity (Sleight of Hand) check to pick a lock or disarm a trap with Thieves'' Tools or to pick a pocket.\n Use an Object. Take the Utilize action, or take the Magic action to use a magic item that requires that action."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Second-Story Work","desc":"You''ve trained to get into especially hard-to-reach places, granting you these benefits.\n Climber. You gain a Climb Speed equal to your Speed.\n Jumper. You can determine your jump distance using your Dexterity rather than your Strength."}'::jsonb, '{"index":"thief-second-story-work","url":"/api/2024/features/thief-second-story-work","name":"Second-Story Work","level":{"index":"rogue-3","url":"/api/2024/classes/rogue/levels/3","name":"Rogue 3"},"class":{"index":"rogue","url":"/api/2024/classes/rogue","name":"Rogue"},"subclass":{"index":"thief","url":"/api/2024/subclasses/thief","name":"Thief"},"description":"You''ve trained to get into especially hard-to-reach places, granting you these benefits.\n Climber. You gain a Climb Speed equal to your Speed.\n Jumper. You can determine your jump distance using your Dexterity rather than your Strength."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Supreme Sneak","desc":"You gain the following Cunning Strike option.\n Stealth Attack (Cost: 1d6). If you have the Hide action''s Invisible condition, this attack doesn''t end that condition on you if you end the turn behind Three-Quarters Cover or Total Cover."}'::jsonb, '{"index":"thief-supreme-sneak","url":"/api/2024/features/thief-supreme-sneak","name":"Supreme Sneak","level":{"index":"rogue-9","url":"/api/2024/classes/rogue/levels/9","name":"Rogue 9"},"class":{"index":"rogue","url":"/api/2024/classes/rogue","name":"Rogue"},"subclass":{"index":"thief","url":"/api/2024/subclasses/thief","name":"Thief"},"description":"You gain the following Cunning Strike option.\n Stealth Attack (Cost: 1d6). If you have the Hide action''s Invisible condition, this attack doesn''t end that condition on you if you end the turn behind Three-Quarters Cover or Total Cover."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Use Magic Device","desc":"You''ve learned how to maximize use of magic items, granting you the following benefits.\n Attunement. You can attune to up to four magic items at once.\n Charges. Whenever you use a magic item property that expends charges, roll 1d6. On a roll of 6, you use the property without expending the charges.\n Scrolls. You can use any Spell Scroll, using Intelligence as your spellcasting ability for the spell. If the spell is a cantrip or a level 1 spell, you can cast it reliably.\n If the scroll contains a higher-level spell, you must first succeed on an Intelligence (Arcana) check (DC 10 plus the spell''s level). On a successful check, you cast the spell from the scroll. On a failed check, the scroll disintegrates."}'::jsonb, '{"index":"thief-use-magic-device","url":"/api/2024/features/thief-use-magic-device","name":"Use Magic Device","level":{"index":"rogue-13","url":"/api/2024/classes/rogue/levels/13","name":"Rogue 13"},"class":{"index":"rogue","url":"/api/2024/classes/rogue","name":"Rogue"},"subclass":{"index":"thief","url":"/api/2024/subclasses/thief","name":"Thief"},"description":"You''ve learned how to maximize use of magic items, granting you the following benefits.\n Attunement. You can attune to up to four magic items at once.\n Charges. Whenever you use a magic item property that expends charges, roll 1d6. On a roll of 6, you use the property without expending the charges.\n Scrolls. You can use any Spell Scroll, using Intelligence as your spellcasting ability for the spell. If the spell is a cantrip or a level 1 spell, you can cast it reliably.\n If the scroll contains a higher-level spell, you must first succeed on an Intelligence (Arcana) check (DC 10 plus the spell''s level). On a successful check, you cast the spell from the scroll. On a failed check, the scroll disintegrates."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Thief''s Reflexes","desc":"You are adept at laying ambushes and quickly escaping danger. You can take two turns during the first round of any combat. You take your first turn at your normal Initiative and your second turn at your Initiative minus 10."}'::jsonb, '{"index":"thief-thiefs-reflexes","url":"/api/2024/features/thief-thiefs-reflexes","name":"Thief''s Reflexes","level":{"index":"rogue-17","url":"/api/2024/classes/rogue/levels/17","name":"Rogue 17"},"class":{"index":"rogue","url":"/api/2024/classes/rogue","name":"Rogue"},"subclass":{"index":"thief","url":"/api/2024/subclasses/thief","name":"Thief"},"description":"You are adept at laying ambushes and quickly escaping danger. You can take two turns during the first round of any combat. You take your first turn at your normal Initiative and your second turn at your Initiative minus 10."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Spellcasting","desc":"Drawing from your innate magic, you can cast spells. See \"Spells\" for the rules on spellcasting. The information below details how you use those rules with Sorcerer spells, which appear in the Sorcerer spell list later in the class’s description.\nCantrips. You know four Sorcerer cantrips of your choice. Light, Prestidigitation, Shocking Grasp, and Sorcerous Burst are recommended. Whenever you gain a Sorcerer level, you can replace one of your cantrips from this feature with another Sorcerer cantrip of your choice.\nWhen you reach Sorcerer levels 4 and 10, you learn another Sorcerer cantrip of your choice, as shown in the Cantrips column of the Sorcerer Features table.\nSpell Slots. The Sorcerer Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest.\nPrepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose two level 1 Sorcerer spells. Burning Hands and Detect Magic are recommended.\nThe number of spells on your list increases as you gain Sorcerer levels, as shown in the Prepared Spells column of the Sorcerer Features table. Whenever that number increases, choose additional Sorcerer spells until the number of spells on your list matches the number in the Sorcerer Features table. The chosen spells must be of a level for which you have spell slots. For example, if you’re a level 3 Sorcerer, your list of prepared spells can include six Sorcerer spells of level 1 or 2 in any combination.\nIf another Sorcerer feature gives you spells that you always have prepared, those spells don’t count against the number of spells you can prepare with this feature, but those spells otherwise count as Sorcerer spells for you.\nChanging Your Prepared Spells. Whenever you gain a Sorcerer level, you can replace one spell on your list with another Sorcerer spell for which you have spell slots.\nSpellcasting Ability. Charisma is your spellcasting ability for your Sorcerer spells.\nSpellcasting Focus. You can use an Arcane Focus as a Spellcasting Focus for your Sorcerer spells."}'::jsonb, '{"index":"sorcerer-spellcasting","url":"/api/2024/features/sorcerer-spellcasting","name":"Spellcasting","level":{"index":"sorcerer-1","url":"/api/2024/classes/sorcerer/levels/1","name":"Sorcerer 1"},"class":{"index":"sorcerer","url":"/api/2024/classes/sorcerer","name":"Sorcerer"},"description":"Drawing from your innate magic, you can cast spells. See \"Spells\" for the rules on spellcasting. The information below details how you use those rules with Sorcerer spells, which appear in the Sorcerer spell list later in the class’s description.\nCantrips. You know four Sorcerer cantrips of your choice. Light, Prestidigitation, Shocking Grasp, and Sorcerous Burst are recommended. Whenever you gain a Sorcerer level, you can replace one of your cantrips from this feature with another Sorcerer cantrip of your choice.\nWhen you reach Sorcerer levels 4 and 10, you learn another Sorcerer cantrip of your choice, as shown in the Cantrips column of the Sorcerer Features table.\nSpell Slots. The Sorcerer Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest.\nPrepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose two level 1 Sorcerer spells. Burning Hands and Detect Magic are recommended.\nThe number of spells on your list increases as you gain Sorcerer levels, as shown in the Prepared Spells column of the Sorcerer Features table. Whenever that number increases, choose additional Sorcerer spells until the number of spells on your list matches the number in the Sorcerer Features table. The chosen spells must be of a level for which you have spell slots. For example, if you’re a level 3 Sorcerer, your list of prepared spells can include six Sorcerer spells of level 1 or 2 in any combination.\nIf another Sorcerer feature gives you spells that you always have prepared, those spells don’t count against the number of spells you can prepare with this feature, but those spells otherwise count as Sorcerer spells for you.\nChanging Your Prepared Spells. Whenever you gain a Sorcerer level, you can replace one spell on your list with another Sorcerer spell for which you have spell slots.\nSpellcasting Ability. Charisma is your spellcasting ability for your Sorcerer spells.\nSpellcasting Focus. You can use an Arcane Focus as a Spellcasting Focus for your Sorcerer spells."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Innate Sorcery","desc":"An event in your past left an indelible mark on you, infusing you with simmering magic. As a Bonus Action, you can unleash that magic for 1 minute, during which you gain the following benefits: - The spell save DC of your Sorcerer spells increases by 1.\n- You have Advantage on the attack rolls of Sorcerer spells you cast.\nYou can use this feature twice, and you regain all expended uses of it when you finish a Long Rest."}'::jsonb, '{"index":"sorcerer-innate-sorcery","url":"/api/2024/features/sorcerer-innate-sorcery","name":"Innate Sorcery","level":{"index":"sorcerer-1","url":"/api/2024/classes/sorcerer/levels/1","name":"Sorcerer 1"},"class":{"index":"sorcerer","url":"/api/2024/classes/sorcerer","name":"Sorcerer"},"description":"An event in your past left an indelible mark on you, infusing you with simmering magic. As a Bonus Action, you can unleash that magic for 1 minute, during which you gain the following benefits: - The spell save DC of your Sorcerer spells increases by 1.\n- You have Advantage on the attack rolls of Sorcerer spells you cast.\nYou can use this feature twice, and you regain all expended uses of it when you finish a Long Rest."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Font of Magic","desc":"You can tap into the wellspring of magic within yourself. This wellspring is represented by Sorcery Points, which allow you to create a variety of magical effects.\nYou have 2 Sorcery Points, and you gain more as you reach higher levels, as shown in the Sorcery Points column of the Sorcerer Features table. You can’t have more Sorcery Points than the number shown in the table for your level. You regain all expended Sorcery Points when you finish a Long Rest.\nYou can use your Sorcery Points to fuel the options below, along with other features, such as Metamagic, that use those points.\nConverting Spell Slots to Sorcery Points. You can expend a spell slot to gain a number of Sorcery Points equal to the slot’s level (no action required).\nCreating Spell Slots. As a Bonus Action, you can transform unexpended Sorcery Points into one spell slot. The Creating Spell Slots table shows the cost of creating a spell slot of a given level, and it lists the minimum Sorcerer level you must be to create a slot. You can create a spell slot no higher than level 5.\nAny spell slot you create with this feature vanishes when you finish a Long Rest.\nCreating Spell Slots Spell Slot Level | Sorcery Point Cost | Min. Sorcerer Level\n1 | 2 | 2\n2 | 3 | 3\n3 | 5 | 5\n4 | 6 | 7\n5 | 7 | 9"}'::jsonb, '{"index":"sorcerer-font-of-magic","url":"/api/2024/features/sorcerer-font-of-magic","name":"Font of Magic","level":{"index":"sorcerer-2","url":"/api/2024/classes/sorcerer/levels/2","name":"Sorcerer 2"},"class":{"index":"sorcerer","url":"/api/2024/classes/sorcerer","name":"Sorcerer"},"description":"You can tap into the wellspring of magic within yourself. This wellspring is represented by Sorcery Points, which allow you to create a variety of magical effects.\nYou have 2 Sorcery Points, and you gain more as you reach higher levels, as shown in the Sorcery Points column of the Sorcerer Features table. You can’t have more Sorcery Points than the number shown in the table for your level. You regain all expended Sorcery Points when you finish a Long Rest.\nYou can use your Sorcery Points to fuel the options below, along with other features, such as Metamagic, that use those points.\nConverting Spell Slots to Sorcery Points. You can expend a spell slot to gain a number of Sorcery Points equal to the slot’s level (no action required).\nCreating Spell Slots. As a Bonus Action, you can transform unexpended Sorcery Points into one spell slot. The Creating Spell Slots table shows the cost of creating a spell slot of a given level, and it lists the minimum Sorcerer level you must be to create a slot. You can create a spell slot no higher than level 5.\nAny spell slot you create with this feature vanishes when you finish a Long Rest.\nCreating Spell Slots Spell Slot Level | Sorcery Point Cost | Min. Sorcerer Level\n1 | 2 | 2\n2 | 3 | 3\n3 | 5 | 5\n4 | 6 | 7\n5 | 7 | 9"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Metamagic","desc":"Because your magic flows from within, you can alter your spells to suit your needs; you gain two Metamagic options of your choice from \"Metamagic Options\" later in this class’s description. You use the chosen options to temporarily modify spells you cast. To use an option, you must spend the number of Sorcery Points that it costs.\nYou can use only one Metamagic option on a spell when you cast it unless otherwise noted in one of those options.\nWhenever you gain a Sorcerer level, you can replace one of your Metamagic options with one you don’t know. You gain two more options at Sorcerer level 10 and two more at Sorcerer level 17."}'::jsonb, '{"index":"sorcerer-metamagic","url":"/api/2024/features/sorcerer-metamagic","name":"Metamagic","level":{"index":"sorcerer-2","url":"/api/2024/classes/sorcerer/levels/2","name":"Sorcerer 2"},"class":{"index":"sorcerer","url":"/api/2024/classes/sorcerer","name":"Sorcerer"},"description":"Because your magic flows from within, you can alter your spells to suit your needs; you gain two Metamagic options of your choice from \"Metamagic Options\" later in this class’s description. You use the chosen options to temporarily modify spells you cast. To use an option, you must spend the number of Sorcery Points that it costs.\nYou can use only one Metamagic option on a spell when you cast it unless otherwise noted in one of those options.\nWhenever you gain a Sorcerer level, you can replace one of your Metamagic options with one you don’t know. You gain two more options at Sorcerer level 10 and two more at Sorcerer level 17."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Sorcerer Subclass","desc":"You gain a Sorcerer subclass of your choice. The Draconic Sorcery subclass is detailed after this class’s description. A subclass is a specialization that grants you features at certain Sorcerer levels.\nFor the rest of your career, you gain each of your subclass’s features that are of your Sorcerer level or lower."}'::jsonb, '{"index":"sorcerer-subclass","url":"/api/2024/features/sorcerer-subclass","name":"Sorcerer Subclass","level":{"index":"sorcerer-3","url":"/api/2024/classes/sorcerer/levels/3","name":"Sorcerer 3"},"class":{"index":"sorcerer","url":"/api/2024/classes/sorcerer","name":"Sorcerer"},"description":"You gain a Sorcerer subclass of your choice. The Draconic Sorcery subclass is detailed after this class’s description. A subclass is a specialization that grants you features at certain Sorcerer levels.\nFor the rest of your career, you gain each of your subclass’s features that are of your Sorcerer level or lower."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Ability Score Improvement","desc":"You gain the Ability Score Improvement feat (see \"Feats\") or another feat of your choice for which you qualify. You gain this feature again at Sorcerer levels 8, 12, and 16."}'::jsonb, '{"index":"sorcerer-ability-score-improvement","url":"/api/2024/features/sorcerer-ability-score-improvement","name":"Ability Score Improvement","level":{"index":"sorcerer-4","url":"/api/2024/classes/sorcerer/levels/4","name":"Sorcerer 4"},"class":{"index":"sorcerer","url":"/api/2024/classes/sorcerer","name":"Sorcerer"},"description":"You gain the Ability Score Improvement feat (see \"Feats\") or another feat of your choice for which you qualify. You gain this feature again at Sorcerer levels 8, 12, and 16."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Sorcerous Restoration","desc":"When you finish a Short Rest, you can regain expended Sorcery Points, but no more than a number equal to half your Sorcerer level (round down). Once you use this feature, you can’t do so again until you finish a Long Rest."}'::jsonb, '{"index":"sorcerer-sorcerous-restoration","url":"/api/2024/features/sorcerer-sorcerous-restoration","name":"Sorcerous Restoration","level":{"index":"sorcerer-5","url":"/api/2024/classes/sorcerer/levels/5","name":"Sorcerer 5"},"class":{"index":"sorcerer","url":"/api/2024/classes/sorcerer","name":"Sorcerer"},"description":"When you finish a Short Rest, you can regain expended Sorcery Points, but no more than a number equal to half your Sorcerer level (round down). Once you use this feature, you can’t do so again until you finish a Long Rest."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Sorcery Incarnate","desc":"If you have no uses of Innate Sorcery left, you can use it if you spend 2 Sorcery Points when you take the Bonus Action to activate it.\nIn addition, while your Innate Sorcery feature is active, you can use up to two of your Metamagic options on each spell you cast."}'::jsonb, '{"index":"sorcerer-sorcery-incarnate","url":"/api/2024/features/sorcerer-sorcery-incarnate","name":"Sorcery Incarnate","level":{"index":"sorcerer-7","url":"/api/2024/classes/sorcerer/levels/7","name":"Sorcerer 7"},"class":{"index":"sorcerer","url":"/api/2024/classes/sorcerer","name":"Sorcerer"},"description":"If you have no uses of Innate Sorcery left, you can use it if you spend 2 Sorcery Points when you take the Bonus Action to activate it.\nIn addition, while your Innate Sorcery feature is active, you can use up to two of your Metamagic options on each spell you cast."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Epic Boon","desc":"You gain an Epic Boon feat (see \"Feats\") or another feat of your choice for which you qualify. Boon of Dimensional Travel is recommended."}'::jsonb, '{"index":"sorcerer-epic-boon","url":"/api/2024/features/sorcerer-epic-boon","name":"Epic Boon","level":{"index":"sorcerer-19","url":"/api/2024/classes/sorcerer/levels/19","name":"Sorcerer 19"},"class":{"index":"sorcerer","url":"/api/2024/classes/sorcerer","name":"Sorcerer"},"description":"You gain an Epic Boon feat (see \"Feats\") or another feat of your choice for which you qualify. Boon of Dimensional Travel is recommended."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Arcane Apotheosis","desc":"While your Innate Sorcery feature is active, you can use one Metamagic option on each of your turns without spending Sorcery Points on it."}'::jsonb, '{"index":"sorcerer-arcane-apotheosis","url":"/api/2024/features/sorcerer-arcane-apotheosis","name":"Arcane Apotheosis","level":{"index":"sorcerer-20","url":"/api/2024/classes/sorcerer/levels/20","name":"Sorcerer 20"},"class":{"index":"sorcerer","url":"/api/2024/classes/sorcerer","name":"Sorcerer"},"description":"While your Innate Sorcery feature is active, you can use one Metamagic option on each of your turns without spending Sorcery Points on it."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Draconic Resilience","desc":"The magic in your body manifests physical traits of your draconic gift. Your Hit Point maximum increases by 3, and it increases by 1 whenever you gain another Sorcerer level.\nParts of you are also covered by dragon-like scales. While you aren’t wearing armor, your base Armor Class equals 10 plus your Dexterity and Charisma modifiers."}'::jsonb, '{"index":"draconic-sorcery-draconic-resilience","url":"/api/2024/features/draconic-sorcery-draconic-resilience","name":"Draconic Resilience","level":{"index":"sorcerer-3","url":"/api/2024/classes/sorcerer/levels/3","name":"Sorcerer 3"},"class":{"index":"sorcerer","url":"/api/2024/classes/sorcerer","name":"Sorcerer"},"subclass":{"index":"draconic-sorcery","url":"/api/2024/subclasses/draconic-sorcery","name":"Draconic Sorcery"},"description":"The magic in your body manifests physical traits of your draconic gift. Your Hit Point maximum increases by 3, and it increases by 1 whenever you gain another Sorcerer level.\nParts of you are also covered by dragon-like scales. While you aren’t wearing armor, your base Armor Class equals 10 plus your Dexterity and Charisma modifiers."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Draconic Spells","desc":"When you reach a Sorcerer level specified in the Draconic Spells table, you thereafter always have the listed spells prepared.\nDraconic Spells Sorcerer Level | Spells\n3 | Alter Self, Chromatic Orb, Command, Dragon’s Breath\n5 | Fear, Fly 7 | Arcane Eye, Charm Monster\n9 | Legend Lore, Summon Dragon"}'::jsonb, '{"index":"draconic-sorcery-draconic-spells","url":"/api/2024/features/draconic-sorcery-draconic-spells","name":"Draconic Spells","level":{"index":"sorcerer-3","url":"/api/2024/classes/sorcerer/levels/3","name":"Sorcerer 3"},"class":{"index":"sorcerer","url":"/api/2024/classes/sorcerer","name":"Sorcerer"},"subclass":{"index":"draconic-sorcery","url":"/api/2024/subclasses/draconic-sorcery","name":"Draconic Sorcery"},"description":"When you reach a Sorcerer level specified in the Draconic Spells table, you thereafter always have the listed spells prepared.\nDraconic Spells Sorcerer Level | Spells\n3 | Alter Self, Chromatic Orb, Command, Dragon’s Breath\n5 | Fear, Fly 7 | Arcane Eye, Charm Monster\n9 | Legend Lore, Summon Dragon"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Elemental Affinity","desc":"Your draconic magic has an affinity with a damage type associated with dragons. Choose one of those types: Acid, Cold, Fire, Lightning, or Poison.\nYou have Resistance to that damage type, and when you cast a spell that deals damage of that type, you can add your Charisma modifier to one damage roll of that spell."}'::jsonb, '{"index":"draconic-sorcery-elemental-affinity","url":"/api/2024/features/draconic-sorcery-elemental-affinity","name":"Elemental Affinity","level":{"index":"sorcerer-6","url":"/api/2024/classes/sorcerer/levels/6","name":"Sorcerer 6"},"class":{"index":"sorcerer","url":"/api/2024/classes/sorcerer","name":"Sorcerer"},"subclass":{"index":"draconic-sorcery","url":"/api/2024/subclasses/draconic-sorcery","name":"Draconic Sorcery"},"description":"Your draconic magic has an affinity with a damage type associated with dragons. Choose one of those types: Acid, Cold, Fire, Lightning, or Poison.\nYou have Resistance to that damage type, and when you cast a spell that deals damage of that type, you can add your Charisma modifier to one damage roll of that spell."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Dragon Wings","desc":"As a Bonus Action, you can cause draconic wings to appear on your back. The wings last for 1 hour or until you dismiss them (no action required). For the duration, you have a Fly Speed of 60 feet.\nOnce you use this feature, you can’t use it again until you finish a Long Rest unless you spend 3 Sorcery Points (no action required) to restore your use of it."}'::jsonb, '{"index":"draconic-sorcery-dragon-wings","url":"/api/2024/features/draconic-sorcery-dragon-wings","name":"Dragon Wings","level":{"index":"sorcerer-14","url":"/api/2024/classes/sorcerer/levels/14","name":"Sorcerer 14"},"class":{"index":"sorcerer","url":"/api/2024/classes/sorcerer","name":"Sorcerer"},"subclass":{"index":"draconic-sorcery","url":"/api/2024/subclasses/draconic-sorcery","name":"Draconic Sorcery"},"description":"As a Bonus Action, you can cause draconic wings to appear on your back. The wings last for 1 hour or until you dismiss them (no action required). For the duration, you have a Fly Speed of 60 feet.\nOnce you use this feature, you can’t use it again until you finish a Long Rest unless you spend 3 Sorcery Points (no action required) to restore your use of it."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Dragon Companion","desc":"You can cast Summon Dragon without a Material component. You can also cast it once without a spell slot, and you regain the ability to cast it in this way when you finish a Long Rest.\nWhenever you start casting the spell, you can modify it so that it doesn’t require Concentration. If you do so, the spell’s duration becomes 1 minute for that casting."}'::jsonb, '{"index":"draconic-sorcery-dragon-companion","url":"/api/2024/features/draconic-sorcery-dragon-companion","name":"Dragon Companion","level":{"index":"sorcerer-18","url":"/api/2024/classes/sorcerer/levels/18","name":"Sorcerer 18"},"class":{"index":"sorcerer","url":"/api/2024/classes/sorcerer","name":"Sorcerer"},"subclass":{"index":"draconic-sorcery","url":"/api/2024/subclasses/draconic-sorcery","name":"Draconic Sorcery"},"description":"You can cast Summon Dragon without a Material component. You can also cast it once without a spell slot, and you regain the ability to cast it in this way when you finish a Long Rest.\nWhenever you start casting the spell, you can modify it so that it doesn’t require Concentration. If you do so, the spell’s duration becomes 1 minute for that casting."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Eldritch Invocations","desc":"You have unearthed Eldritch Invocations, pieces of forbidden knowledge that imbue you with an abiding magical ability or other lessons. You gain one invocation of your choice, such as Pact of the Tome. Invocations are described in the \"Eldritch Invocation Options\" section later in this class''s description.\nPrerequisites. If an invocation has a prerequisite, you must meet it to learn that invocation. For example, if an invocation requires you to be a level 5+ Warlock, you can select the invocation once you reach Warlock level 5.\nReplacing and Gaining Invocations. Whenever you gain a Warlock level, you can replace one of your invocations with another one for which you qualify. You can''t replace an invocation if it''s a prerequisite for another invocation that you have.\nWhen you gain certain Warlock levels, you gain more invocations of your choice, as shown in the Invocations column of the Warlock Features table.\nYou can''t pick the same invocation more than once unless its description says otherwise."}'::jsonb, '{"index":"warlock-eldritch-invocations","url":"/api/2024/features/warlock-eldritch-invocations","name":"Eldritch Invocations","level":{"index":"warlock-1","url":"/api/2024/classes/warlock/levels/1","name":"Warlock 1"},"class":{"index":"warlock","url":"/api/2024/classes/warlock","name":"Warlock"},"description":"You have unearthed Eldritch Invocations, pieces of forbidden knowledge that imbue you with an abiding magical ability or other lessons. You gain one invocation of your choice, such as Pact of the Tome. Invocations are described in the \"Eldritch Invocation Options\" section later in this class''s description.\nPrerequisites. If an invocation has a prerequisite, you must meet it to learn that invocation. For example, if an invocation requires you to be a level 5+ Warlock, you can select the invocation once you reach Warlock level 5.\nReplacing and Gaining Invocations. Whenever you gain a Warlock level, you can replace one of your invocations with another one for which you qualify. You can''t replace an invocation if it''s a prerequisite for another invocation that you have.\nWhen you gain certain Warlock levels, you gain more invocations of your choice, as shown in the Invocations column of the Warlock Features table.\nYou can''t pick the same invocation more than once unless its description says otherwise."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Pact Magic","desc":"Through occult ceremony, you have formed a pact with a mysterious entity to gain magical powers.\nThe entity is a voice in the shadows—its identity unclear—but its boon to you is concrete: the ability to cast spells. See \"Spells\" for the rules on spellcasting.\nThe information below details how you use those rules with Warlock spells, which appear in the Warlock spell list later in the class''s description.\nCantrips. You know two Warlock cantrips of your choice. Eldritch Blast and Prestidigitation are recommended.\nWhenever you gain a Warlock level, you can replace one of your cantrips from this feature with another Warlock cantrip of your choice.\nWhen you reach Warlock levels 4 and 10, you learn another Warlock cantrip of your choice, as shown in the Cantrips column of the Warlock Features table.\nSpell Slots. The Warlock Features table shows how many spell slots you have to cast your Warlock spells of levels 1–5. The table also shows the level of those slots, all of which are the same level. You regain all expended Pact Magic spell slots when you finish a Short or Long Rest.\nFor example, when you''re a level 5 Warlock, you have two level 3 spell slots. To cast the level 1 spell Charm Person, you must spend one of those slots, and you cast it as a level 3 spell.\nPrepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose two level 1 Warlock spells. Charm Person and Hex are recommended.\nThe number of spells on your list increases as you gain Warlock levels, as shown in the Prepared Spells column of the Warlock Features table. Whenever that number increases, choose additional Warlock spells until the number of spells on your list matches the number in the table. The chosen spells must be of a level no higher than what''s shown in the table''s Slot Level column for your level. When you reach level 6, for example, you learn a new Warlock spell, which can be of levels 1–3.\nIf another Warlock feature gives you spells that you always have prepared, those spells don''t count against the number of spells you can prepare with this feature, but those spells otherwise count as Warlock spells for you.\nChanging Your Prepared Spells. Whenever you gain a Warlock level, you can replace one spell on your list with another Warlock spell of an eligible level.\nSpellcasting Ability. Charisma is the spellcasting ability for your Warlock spells.\nSpellcasting Focus. You can use an Arcane Focus as a Spellcasting Focus for your Warlock spells."}'::jsonb, '{"index":"warlock-pact-magic","url":"/api/2024/features/warlock-pact-magic","name":"Pact Magic","level":{"index":"warlock-1","url":"/api/2024/classes/warlock/levels/1","name":"Warlock 1"},"class":{"index":"warlock","url":"/api/2024/classes/warlock","name":"Warlock"},"description":"Through occult ceremony, you have formed a pact with a mysterious entity to gain magical powers.\nThe entity is a voice in the shadows—its identity unclear—but its boon to you is concrete: the ability to cast spells. See \"Spells\" for the rules on spellcasting.\nThe information below details how you use those rules with Warlock spells, which appear in the Warlock spell list later in the class''s description.\nCantrips. You know two Warlock cantrips of your choice. Eldritch Blast and Prestidigitation are recommended.\nWhenever you gain a Warlock level, you can replace one of your cantrips from this feature with another Warlock cantrip of your choice.\nWhen you reach Warlock levels 4 and 10, you learn another Warlock cantrip of your choice, as shown in the Cantrips column of the Warlock Features table.\nSpell Slots. The Warlock Features table shows how many spell slots you have to cast your Warlock spells of levels 1–5. The table also shows the level of those slots, all of which are the same level. You regain all expended Pact Magic spell slots when you finish a Short or Long Rest.\nFor example, when you''re a level 5 Warlock, you have two level 3 spell slots. To cast the level 1 spell Charm Person, you must spend one of those slots, and you cast it as a level 3 spell.\nPrepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose two level 1 Warlock spells. Charm Person and Hex are recommended.\nThe number of spells on your list increases as you gain Warlock levels, as shown in the Prepared Spells column of the Warlock Features table. Whenever that number increases, choose additional Warlock spells until the number of spells on your list matches the number in the table. The chosen spells must be of a level no higher than what''s shown in the table''s Slot Level column for your level. When you reach level 6, for example, you learn a new Warlock spell, which can be of levels 1–3.\nIf another Warlock feature gives you spells that you always have prepared, those spells don''t count against the number of spells you can prepare with this feature, but those spells otherwise count as Warlock spells for you.\nChanging Your Prepared Spells. Whenever you gain a Warlock level, you can replace one spell on your list with another Warlock spell of an eligible level.\nSpellcasting Ability. Charisma is the spellcasting ability for your Warlock spells.\nSpellcasting Focus. You can use an Arcane Focus as a Spellcasting Focus for your Warlock spells."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Magical Cunning","desc":"You can perform an esoteric rite for 1 minute. At the end of it, you regain expended Pact Magic spell slots but no more than a number equal to half your maximum (round up). Once you use this feature, you can''t do so again until you finish a Long Rest."}'::jsonb, '{"index":"warlock-magical-cunning","url":"/api/2024/features/warlock-magical-cunning","name":"Magical Cunning","level":{"index":"warlock-2","url":"/api/2024/classes/warlock/levels/2","name":"Warlock 2"},"class":{"index":"warlock","url":"/api/2024/classes/warlock","name":"Warlock"},"description":"You can perform an esoteric rite for 1 minute. At the end of it, you regain expended Pact Magic spell slots but no more than a number equal to half your maximum (round up). Once you use this feature, you can''t do so again until you finish a Long Rest."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Warlock Subclass","desc":"You gain a Warlock subclass of your choice. The Fiend Patron subclass is detailed after this class''s description. A subclass is a specialization that grants you features at certain Warlock levels. For the rest of your career, you gain each of your subclass''s features that are of your Warlock level or lower."}'::jsonb, '{"index":"warlock-subclass","url":"/api/2024/features/warlock-subclass","name":"Warlock Subclass","level":{"index":"warlock-3","url":"/api/2024/classes/warlock/levels/3","name":"Warlock 3"},"class":{"index":"warlock","url":"/api/2024/classes/warlock","name":"Warlock"},"description":"You gain a Warlock subclass of your choice. The Fiend Patron subclass is detailed after this class''s description. A subclass is a specialization that grants you features at certain Warlock levels. For the rest of your career, you gain each of your subclass''s features that are of your Warlock level or lower."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Ability Score Improvement","desc":"You gain the Ability Score Improvement feat (see \"Feats\") or another feat of your choice for which you qualify. You gain this feature again at Warlock levels 8, 12, and 16."}'::jsonb, '{"index":"warlock-ability-score-improvement","url":"/api/2024/features/warlock-ability-score-improvement","name":"Ability Score Improvement","level":{"index":"warlock-4","url":"/api/2024/classes/warlock/levels/4","name":"Warlock 4"},"class":{"index":"warlock","url":"/api/2024/classes/warlock","name":"Warlock"},"description":"You gain the Ability Score Improvement feat (see \"Feats\") or another feat of your choice for which you qualify. You gain this feature again at Warlock levels 8, 12, and 16."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Contact Patron","desc":"In the past, you usually contacted your patron through intermediaries. Now you can communicate directly; you always have the Contact Other Plane spell prepared. With this feature, you can cast the spell without expending a spell slot to contact your patron, and you automatically succeed on the spell''s saving throw.\nOnce you cast the spell with this feature, you can''t do so in this way again until you finish a Long Rest."}'::jsonb, '{"index":"warlock-contact-patron","url":"/api/2024/features/warlock-contact-patron","name":"Contact Patron","level":{"index":"warlock-9","url":"/api/2024/classes/warlock/levels/9","name":"Warlock 9"},"class":{"index":"warlock","url":"/api/2024/classes/warlock","name":"Warlock"},"description":"In the past, you usually contacted your patron through intermediaries. Now you can communicate directly; you always have the Contact Other Plane spell prepared. With this feature, you can cast the spell without expending a spell slot to contact your patron, and you automatically succeed on the spell''s saving throw.\nOnce you cast the spell with this feature, you can''t do so in this way again until you finish a Long Rest."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Mystic Arcanum","desc":"Your patron grants you a magical secret called an arcanum. Choose one level 6 Warlock spell as this arcanum.\nYou can cast your arcanum spell once without expending a spell slot, and you must finish a Long Rest before you can cast it in this way again.\nAs shown in the Warlock Features table, you gain another Warlock spell of your choice that can be cast in this way when you reach Warlock levels 13 (level 7 spell), 15 (level 8 spell), and 17 (level 9 spell). You regain all uses of your Mystic Arcanum when you finish a Long Rest.\nWhenever you gain a Warlock level, you can replace one of your arcanum spells with another Warlock spell of the same level."}'::jsonb, '{"index":"warlock-mystic-arcanum","url":"/api/2024/features/warlock-mystic-arcanum","name":"Mystic Arcanum","level":{"index":"warlock-11","url":"/api/2024/classes/warlock/levels/11","name":"Warlock 11"},"class":{"index":"warlock","url":"/api/2024/classes/warlock","name":"Warlock"},"description":"Your patron grants you a magical secret called an arcanum. Choose one level 6 Warlock spell as this arcanum.\nYou can cast your arcanum spell once without expending a spell slot, and you must finish a Long Rest before you can cast it in this way again.\nAs shown in the Warlock Features table, you gain another Warlock spell of your choice that can be cast in this way when you reach Warlock levels 13 (level 7 spell), 15 (level 8 spell), and 17 (level 9 spell). You regain all uses of your Mystic Arcanum when you finish a Long Rest.\nWhenever you gain a Warlock level, you can replace one of your arcanum spells with another Warlock spell of the same level."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Epic Boon","desc":"You gain an Epic Boon feat (see \"Feats\") or another feat of your choice for which you qualify. Boon of Fate is recommended."}'::jsonb, '{"index":"warlock-epic-boon","url":"/api/2024/features/warlock-epic-boon","name":"Epic Boon","level":{"index":"warlock-19","url":"/api/2024/classes/warlock/levels/19","name":"Warlock 19"},"class":{"index":"warlock","url":"/api/2024/classes/warlock","name":"Warlock"},"description":"You gain an Epic Boon feat (see \"Feats\") or another feat of your choice for which you qualify. Boon of Fate is recommended."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Eldritch Master","desc":"When you use your Magical Cunning feature, you regain all your expended Pact Magic spell slots."}'::jsonb, '{"index":"warlock-eldritch-master","url":"/api/2024/features/warlock-eldritch-master","name":"Eldritch Master","level":{"index":"warlock-20","url":"/api/2024/classes/warlock/levels/20","name":"Warlock 20"},"class":{"index":"warlock","url":"/api/2024/classes/warlock","name":"Warlock"},"description":"When you use your Magical Cunning feature, you regain all your expended Pact Magic spell slots."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Dark One''s Blessing","desc":"When you reduce an enemy to 0 Hit Points, you gain Temporary Hit Points equal to your Charisma modifier plus your Warlock level (minimum of 1 Temporary Hit Point). You also gain this benefit if someone else reduces an enemy within 10 feet of you to 0 Hit Points."}'::jsonb, '{"index":"fiend-patron-dark-ones-blessing","url":"/api/2024/features/fiend-patron-dark-ones-blessing","name":"Dark One''s Blessing","level":{"index":"warlock-3","url":"/api/2024/classes/warlock/levels/3","name":"Warlock 3"},"class":{"index":"warlock","url":"/api/2024/classes/warlock","name":"Warlock"},"subclass":{"index":"fiend-patron","url":"/api/2024/subclasses/fiend-patron","name":"Fiend Patron"},"description":"When you reduce an enemy to 0 Hit Points, you gain Temporary Hit Points equal to your Charisma modifier plus your Warlock level (minimum of 1 Temporary Hit Point). You also gain this benefit if someone else reduces an enemy within 10 feet of you to 0 Hit Points."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Fiend Spells","desc":"The magic of your patron ensures you always have certain spells ready; when you reach a Warlock level specified in the Fiend Spells table, you thereafter always have the listed spells prepared.\nFiend Spells Warlock Level | Spells\n3 | Burning Hands, Command, Scorching Ray, Suggestion\n5 | Fireball, Stinking Cloud\n7 | Fire Shield, Wall of Fire\n9 | Geas, Insect Plague"}'::jsonb, '{"index":"fiend-patron-fiend-spells","url":"/api/2024/features/fiend-patron-fiend-spells","name":"Fiend Spells","level":{"index":"warlock-3","url":"/api/2024/classes/warlock/levels/3","name":"Warlock 3"},"class":{"index":"warlock","url":"/api/2024/classes/warlock","name":"Warlock"},"subclass":{"index":"fiend-patron","url":"/api/2024/subclasses/fiend-patron","name":"Fiend Patron"},"description":"The magic of your patron ensures you always have certain spells ready; when you reach a Warlock level specified in the Fiend Spells table, you thereafter always have the listed spells prepared.\nFiend Spells Warlock Level | Spells\n3 | Burning Hands, Command, Scorching Ray, Suggestion\n5 | Fireball, Stinking Cloud\n7 | Fire Shield, Wall of Fire\n9 | Geas, Insect Plague"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Dark One''s Own Luck","desc":"You can call on your fiendish patron to alter fate in your favor. When you make an ability check or a saving throw, you can use this feature to add 1d10 to your roll. You can do so after seeing the roll but before any of the roll''s effects occur.\nYou can use this feature a number of times equal to your Charisma modifier (minimum of once), but you can use it no more than once per roll. You regain all expended uses when you finish a Long Rest."}'::jsonb, '{"index":"fiend-patron-dark-ones-own-luck","url":"/api/2024/features/fiend-patron-dark-ones-own-luck","name":"Dark One''s Own Luck","level":{"index":"warlock-6","url":"/api/2024/classes/warlock/levels/6","name":"Warlock 6"},"class":{"index":"warlock","url":"/api/2024/classes/warlock","name":"Warlock"},"subclass":{"index":"fiend-patron","url":"/api/2024/subclasses/fiend-patron","name":"Fiend Patron"},"description":"You can call on your fiendish patron to alter fate in your favor. When you make an ability check or a saving throw, you can use this feature to add 1d10 to your roll. You can do so after seeing the roll but before any of the roll''s effects occur.\nYou can use this feature a number of times equal to your Charisma modifier (minimum of once), but you can use it no more than once per roll. You regain all expended uses when you finish a Long Rest."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Fiendish Resilience","desc":"Choose one damage type, other than Force, whenever you finish a Short or Long Rest. You have Resistance to that damage type until you choose a different one with this feature."}'::jsonb, '{"index":"fiend-patron-fiendish-resilience","url":"/api/2024/features/fiend-patron-fiendish-resilience","name":"Fiendish Resilience","level":{"index":"warlock-10","url":"/api/2024/classes/warlock/levels/10","name":"Warlock 10"},"class":{"index":"warlock","url":"/api/2024/classes/warlock","name":"Warlock"},"subclass":{"index":"fiend-patron","url":"/api/2024/subclasses/fiend-patron","name":"Fiend Patron"},"description":"Choose one damage type, other than Force, whenever you finish a Short or Long Rest. You have Resistance to that damage type until you choose a different one with this feature."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Hurl Through Hell","desc":"Once per turn when you hit a creature with an attack roll, you can try to instantly transport the target through the Lower Planes. The target must succeed on a Charisma saving throw against your spell save DC, or the target disappears and hurtles through a nightmare landscape. The target takes 8d10 Psychic damage if it isn''t a Fiend, and it has the Incapacitated condition until the end of your next turn, when it returns to the space it previously occupied or the nearest unoccupied space.\nOnce you use this feature, you can''t use it again until you finish a Long Rest unless you expend a Pact Magic spell slot (no action required) to restore your use of it."}'::jsonb, '{"index":"fiend-patron-hurl-through-hell","url":"/api/2024/features/fiend-patron-hurl-through-hell","name":"Hurl Through Hell","level":{"index":"warlock-14","url":"/api/2024/classes/warlock/levels/14","name":"Warlock 14"},"class":{"index":"warlock","url":"/api/2024/classes/warlock","name":"Warlock"},"subclass":{"index":"fiend-patron","url":"/api/2024/subclasses/fiend-patron","name":"Fiend Patron"},"description":"Once per turn when you hit a creature with an attack roll, you can try to instantly transport the target through the Lower Planes. The target must succeed on a Charisma saving throw against your spell save DC, or the target disappears and hurtles through a nightmare landscape. The target takes 8d10 Psychic damage if it isn''t a Fiend, and it has the Incapacitated condition until the end of your next turn, when it returns to the space it previously occupied or the nearest unoccupied space.\nOnce you use this feature, you can''t use it again until you finish a Long Rest unless you expend a Pact Magic spell slot (no action required) to restore your use of it."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Spellcasting","desc":"As a student of arcane magic, you have learned to cast spells. See \"Spells\" for the rules on spellcasting.\nThe information below details how you use those rules with Wizard spells, which appear in the Wizard spell list later in the class’s description.\nCantrips. You know three Wizard cantrips of your choice. Light, Mage Hand, and Ray of Frost are recommended.\nWhenever you finish a Long Rest, you can replace one of your cantrips from this feature with another Wizard cantrip of your choice.\nanother Wizard cantrip of your choice, as shown in the Cantrips column of the Wizard Features table.\nSpellbook. Your wizardly apprenticeship culminated in the creation of a unique book: your spellbook. It is a Tiny object that weighs 3 pounds, contains 100 pages, and can be read only by you or someone casting Identify. You determine the book’s appearance and materials, such as a gilt-edged tome or a collection of vellum bound with twine.\nThe book contains the level 1+ spells you know. It starts with six level 1 Wizard spells of your choice.\nDetect Magic, Feather Fall, Mage Armor, Magic Missile, Sleep, and Thunderwave are recommended.\nWhenever you gain a Wizard level after 1, add two Wizard spells of your choice to your spellbook. Each of these spells must be of a level for which you have spell slots, as shown in the Wizard Features table.\nThe spells are the culmination of arcane research you do regularly.\nSpell Slots. The Wizard Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest.\nPrepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To do so, choose four spells from your spellbook. The chosen spells must be of a level for which you have spell slots.\nThe number of spells on your list increases as you gain Wizard levels, as shown in the Prepared Spells column of the Wizard Features table. Whenever that number increases, choose additional Wizard spells until the number of spells on your list matches the number in the table. The chosen spells must be of a level for which you have spell slots. For example, if you’re a level 3 Wizard, your list of prepared spells can include six spells of levels 1 and 2 in any combination, chosen from your spellbook.\nIf another Wizard feature gives you spells that you always have prepared, those spells don’t count against the number of spells you can prepare with this feature, but those spells otherwise count as Wizard spells for you.\nChanging Your Prepared Spells. Whenever you finish a Long Rest, you can change your list of prepared spells, replacing any of the spells there with spells from your spellbook.\nSpellcasting Ability. Intelligence is your spellcasting ability for your Wizard spells.\nSpellcasting Focus. You can use an Arcane Focus or your spellbook as a Spellcasting Focus for your Wizard spells."}'::jsonb, '{"index":"wizard-spellcasting","url":"/api/2024/features/wizard-spellcasting","name":"Spellcasting","level":{"index":"wizard-1","url":"/api/2024/classes/wizard/levels/1","name":"Wizard 1"},"class":{"index":"wizard","url":"/api/2024/classes/wizard","name":"Wizard"},"description":"As a student of arcane magic, you have learned to cast spells. See \"Spells\" for the rules on spellcasting.\nThe information below details how you use those rules with Wizard spells, which appear in the Wizard spell list later in the class’s description.\nCantrips. You know three Wizard cantrips of your choice. Light, Mage Hand, and Ray of Frost are recommended.\nWhenever you finish a Long Rest, you can replace one of your cantrips from this feature with another Wizard cantrip of your choice.\nanother Wizard cantrip of your choice, as shown in the Cantrips column of the Wizard Features table.\nSpellbook. Your wizardly apprenticeship culminated in the creation of a unique book: your spellbook. It is a Tiny object that weighs 3 pounds, contains 100 pages, and can be read only by you or someone casting Identify. You determine the book’s appearance and materials, such as a gilt-edged tome or a collection of vellum bound with twine.\nThe book contains the level 1+ spells you know. It starts with six level 1 Wizard spells of your choice.\nDetect Magic, Feather Fall, Mage Armor, Magic Missile, Sleep, and Thunderwave are recommended.\nWhenever you gain a Wizard level after 1, add two Wizard spells of your choice to your spellbook. Each of these spells must be of a level for which you have spell slots, as shown in the Wizard Features table.\nThe spells are the culmination of arcane research you do regularly.\nSpell Slots. The Wizard Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest.\nPrepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To do so, choose four spells from your spellbook. The chosen spells must be of a level for which you have spell slots.\nThe number of spells on your list increases as you gain Wizard levels, as shown in the Prepared Spells column of the Wizard Features table. Whenever that number increases, choose additional Wizard spells until the number of spells on your list matches the number in the table. The chosen spells must be of a level for which you have spell slots. For example, if you’re a level 3 Wizard, your list of prepared spells can include six spells of levels 1 and 2 in any combination, chosen from your spellbook.\nIf another Wizard feature gives you spells that you always have prepared, those spells don’t count against the number of spells you can prepare with this feature, but those spells otherwise count as Wizard spells for you.\nChanging Your Prepared Spells. Whenever you finish a Long Rest, you can change your list of prepared spells, replacing any of the spells there with spells from your spellbook.\nSpellcasting Ability. Intelligence is your spellcasting ability for your Wizard spells.\nSpellcasting Focus. You can use an Arcane Focus or your spellbook as a Spellcasting Focus for your Wizard spells."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Ritual Adept","desc":"You can cast any spell as a Ritual if that spell has the Ritual tag and the spell is in your spellbook. You needn’t have the spell prepared, but you must read from the book to cast a spell in this way."}'::jsonb, '{"index":"wizard-ritual-adept","url":"/api/2024/features/wizard-ritual-adept","name":"Ritual Adept","level":{"index":"wizard-1","url":"/api/2024/classes/wizard/levels/1","name":"Wizard 1"},"class":{"index":"wizard","url":"/api/2024/classes/wizard","name":"Wizard"},"description":"You can cast any spell as a Ritual if that spell has the Ritual tag and the spell is in your spellbook. You needn’t have the spell prepared, but you must read from the book to cast a spell in this way."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Arcane Recovery","desc":"You can regain some of your magical energy by studying your spellbook. When you finish a Short Rest, you can choose expended spell slots to recover.\nThe spell slots can have a combined level equal to no more than half your Wizard level (round up), and none of the slots can be level 6 or higher.\nFor example, if you’re a level 4 Wizard, you can recover up to two levels’ worth of spell slots, regaining either one level 2 spell slot or two level 1 spell slots.\nOnce you use this feature, you can’t do so again until you finish a Long Rest."}'::jsonb, '{"index":"wizard-arcane-recovery","url":"/api/2024/features/wizard-arcane-recovery","name":"Arcane Recovery","level":{"index":"wizard-1","url":"/api/2024/classes/wizard/levels/1","name":"Wizard 1"},"class":{"index":"wizard","url":"/api/2024/classes/wizard","name":"Wizard"},"description":"You can regain some of your magical energy by studying your spellbook. When you finish a Short Rest, you can choose expended spell slots to recover.\nThe spell slots can have a combined level equal to no more than half your Wizard level (round up), and none of the slots can be level 6 or higher.\nFor example, if you’re a level 4 Wizard, you can recover up to two levels’ worth of spell slots, regaining either one level 2 spell slot or two level 1 spell slots.\nOnce you use this feature, you can’t do so again until you finish a Long Rest."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Scholar","desc":"While studying magic, you also specialized in another field of study. Choose one of the following skills in which you have proficiency: Arcana, History, Investigation, Medicine, Nature, or Religion.\nYou have Expertise in the chosen skill."}'::jsonb, '{"index":"wizard-scholar","url":"/api/2024/features/wizard-scholar","name":"Scholar","level":{"index":"wizard-2","url":"/api/2024/classes/wizard/levels/2","name":"Wizard 2"},"class":{"index":"wizard","url":"/api/2024/classes/wizard","name":"Wizard"},"description":"While studying magic, you also specialized in another field of study. Choose one of the following skills in which you have proficiency: Arcana, History, Investigation, Medicine, Nature, or Religion.\nYou have Expertise in the chosen skill."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Wizard Subclass","desc":"You gain a Wizard subclass of your choice. The Evoker subclass is detailed after this class’s description.\nA subclass is a specialization that grants you features at certain Wizard levels. For the rest of your career, you gain each of your subclass’s features that are of your Wizard level or lower."}'::jsonb, '{"index":"wizard-subclass","url":"/api/2024/features/wizard-subclass","name":"Wizard Subclass","level":{"index":"wizard-3","url":"/api/2024/classes/wizard/levels/3","name":"Wizard 3"},"class":{"index":"wizard","url":"/api/2024/classes/wizard","name":"Wizard"},"description":"You gain a Wizard subclass of your choice. The Evoker subclass is detailed after this class’s description.\nA subclass is a specialization that grants you features at certain Wizard levels. For the rest of your career, you gain each of your subclass’s features that are of your Wizard level or lower."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Ability Score Improvement","desc":"You gain the Ability Score Improvement feat (see \"Feats\") or another feat of your choice for which you qualify. You gain this feature again at Wizard levels 8, 12, and 16."}'::jsonb, '{"index":"wizard-ability-score-improvement","url":"/api/2024/features/wizard-ability-score-improvement","name":"Ability Score Improvement","level":{"index":"wizard-4","url":"/api/2024/classes/wizard/levels/4","name":"Wizard 4"},"class":{"index":"wizard","url":"/api/2024/classes/wizard","name":"Wizard"},"description":"You gain the Ability Score Improvement feat (see \"Feats\") or another feat of your choice for which you qualify. You gain this feature again at Wizard levels 8, 12, and 16."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Memorize Spell","desc":"Whenever you finish a Short Rest, you can study your spellbook and replace one of the level 1+ Wizard spells you have prepared for your Spellcasting feature with another level 1+ spell from the book."}'::jsonb, '{"index":"wizard-memorize-spell","url":"/api/2024/features/wizard-memorize-spell","name":"Memorize Spell","level":{"index":"wizard-5","url":"/api/2024/classes/wizard/levels/5","name":"Wizard 5"},"class":{"index":"wizard","url":"/api/2024/classes/wizard","name":"Wizard"},"description":"Whenever you finish a Short Rest, you can study your spellbook and replace one of the level 1+ Wizard spells you have prepared for your Spellcasting feature with another level 1+ spell from the book."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Spell Mastery","desc":"You have achieved such mastery over certain spells that you can cast them at will. Choose a level 1 and a level 2 spell in your spellbook that have a casting time of an action. You always have those spells prepared, and you can cast them at their lowest level without expending a spell slot. To cast either spell at a higher level, you must expend a spell slot.\nWhenever you finish a Long Rest, you can study your spellbook and replace one of those spells with an eligible spell of the same level from the book."}'::jsonb, '{"index":"wizard-spell-mastery","url":"/api/2024/features/wizard-spell-mastery","name":"Spell Mastery","level":{"index":"wizard-18","url":"/api/2024/classes/wizard/levels/18","name":"Wizard 18"},"class":{"index":"wizard","url":"/api/2024/classes/wizard","name":"Wizard"},"description":"You have achieved such mastery over certain spells that you can cast them at will. Choose a level 1 and a level 2 spell in your spellbook that have a casting time of an action. You always have those spells prepared, and you can cast them at their lowest level without expending a spell slot. To cast either spell at a higher level, you must expend a spell slot.\nWhenever you finish a Long Rest, you can study your spellbook and replace one of those spells with an eligible spell of the same level from the book."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Epic Boon","desc":"You gain an Epic Boon feat (see \"Feats\") or another feat of your choice for which you qualify. Boon of Spell Recall is recommended."}'::jsonb, '{"index":"wizard-epic-boon","url":"/api/2024/features/wizard-epic-boon","name":"Epic Boon","level":{"index":"wizard-19","url":"/api/2024/classes/wizard/levels/19","name":"Wizard 19"},"class":{"index":"wizard","url":"/api/2024/classes/wizard","name":"Wizard"},"description":"You gain an Epic Boon feat (see \"Feats\") or another feat of your choice for which you qualify. Boon of Spell Recall is recommended."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Signature Spells","desc":"Choose two level 3 spells in your spellbook as your signature spells. You always have these spells prepared, and you can cast each of them once at level 3 without expending a spell slot. When you do so, you can’t cast them in this way again until you finish a Short or Long Rest. To cast either spell at a higher level, you must expend a spell slot."}'::jsonb, '{"index":"wizard-signature-spells","url":"/api/2024/features/wizard-signature-spells","name":"Signature Spells","level":{"index":"wizard-20","url":"/api/2024/classes/wizard/levels/20","name":"Wizard 20"},"class":{"index":"wizard","url":"/api/2024/classes/wizard","name":"Wizard"},"description":"Choose two level 3 spells in your spellbook as your signature spells. You always have these spells prepared, and you can cast each of them once at level 3 without expending a spell slot. When you do so, you can’t cast them in this way again until you finish a Short or Long Rest. To cast either spell at a higher level, you must expend a spell slot."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Evocation Savant","desc":"Choose two Wizard spells from the Evocation school, each of which must be no higher than level 2, and add them to your spellbook for free.\nIn addition, whenever you gain access to a new level of spell slots in this class, you can add one Wizard spell from the Evocation school to your spellbook for free. The chosen spell must be of a level for which you have spell slots."}'::jsonb, '{"index":"evoker-evocation-savant","url":"/api/2024/features/evoker-evocation-savant","name":"Evocation Savant","level":{"index":"wizard-3","url":"/api/2024/classes/wizard/levels/3","name":"Wizard 3"},"class":{"index":"wizard","url":"/api/2024/classes/wizard","name":"Wizard"},"subclass":{"index":"evoker","url":"/api/2024/subclasses/evoker","name":"Evoker"},"description":"Choose two Wizard spells from the Evocation school, each of which must be no higher than level 2, and add them to your spellbook for free.\nIn addition, whenever you gain access to a new level of spell slots in this class, you can add one Wizard spell from the Evocation school to your spellbook for free. The chosen spell must be of a level for which you have spell slots."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Potent Cantrip","desc":"Your damaging cantrips affect even creatures that avoid the brunt of the effect. When you cast a cantrip at a creature and you miss with the attack roll or the target succeeds on a saving throw against the cantrip, the target takes half the cantrip’s damage (if any) but suffers no additional effect from the cantrip."}'::jsonb, '{"index":"evoker-potent-cantrip","url":"/api/2024/features/evoker-potent-cantrip","name":"Potent Cantrip","level":{"index":"wizard-3","url":"/api/2024/classes/wizard/levels/3","name":"Wizard 3"},"class":{"index":"wizard","url":"/api/2024/classes/wizard","name":"Wizard"},"subclass":{"index":"evoker","url":"/api/2024/subclasses/evoker","name":"Evoker"},"description":"Your damaging cantrips affect even creatures that avoid the brunt of the effect. When you cast a cantrip at a creature and you miss with the attack roll or the target succeeds on a saving throw against the cantrip, the target takes half the cantrip’s damage (if any) but suffers no additional effect from the cantrip."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Sculpt Spells","desc":"You can create pockets of relative safety within the effects of your evocations. When you cast an Evocation spell that affects other creatures that you can see, you can choose a number of them equal to 1 plus the spell’s level. The chosen creatures automatically succeed on their saving throws against the spell, and they take no damage if they would normally take half damage on a successful save."}'::jsonb, '{"index":"evoker-sculpt-spells","url":"/api/2024/features/evoker-sculpt-spells","name":"Sculpt Spells","level":{"index":"wizard-6","url":"/api/2024/classes/wizard/levels/6","name":"Wizard 6"},"class":{"index":"wizard","url":"/api/2024/classes/wizard","name":"Wizard"},"subclass":{"index":"evoker","url":"/api/2024/subclasses/evoker","name":"Evoker"},"description":"You can create pockets of relative safety within the effects of your evocations. When you cast an Evocation spell that affects other creatures that you can see, you can choose a number of them equal to 1 plus the spell’s level. The chosen creatures automatically succeed on their saving throws against the spell, and they take no damage if they would normally take half damage on a successful save."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Empowered Evocation","desc":"Whenever you cast a Wizard spell from the Evocation school, you can add your Intelligence modifier to one damage roll of that spell."}'::jsonb, '{"index":"evoker-empowered-evocation","url":"/api/2024/features/evoker-empowered-evocation","name":"Empowered Evocation","level":{"index":"wizard-10","url":"/api/2024/classes/wizard/levels/10","name":"Wizard 10"},"class":{"index":"wizard","url":"/api/2024/classes/wizard","name":"Wizard"},"subclass":{"index":"evoker","url":"/api/2024/subclasses/evoker","name":"Evoker"},"description":"Whenever you cast a Wizard spell from the Evocation school, you can add your Intelligence modifier to one damage roll of that spell."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'features', '{"name":"Overchannel","desc":"You can increase the power of your spells. When you cast a Wizard spell with a spell slot of levels 1–5 that deals damage, you can deal maximum damage with that spell on the turn you cast it.\nThe first time you do so, you suffer no adverse effect.\nIf you use this feature again before you finish a Long Rest, you take 2d12 Necrotic damage for each level of the spell slot immediately after you cast it.\nThis damage ignores Resistance and Immunity.\nEach time you use this feature again before finishing a Long Rest, the Necrotic damage per spell level increases by 1d12."}'::jsonb, '{"index":"evoker-overchannel","url":"/api/2024/features/evoker-overchannel","name":"Overchannel","level":{"index":"wizard-14","url":"/api/2024/classes/wizard/levels/14","name":"Wizard 14"},"class":{"index":"wizard","url":"/api/2024/classes/wizard","name":"Wizard"},"subclass":{"index":"evoker","url":"/api/2024/subclasses/evoker","name":"Evoker"},"description":"You can increase the power of your spells. When you cast a Wizard spell with a spell slot of levels 1–5 that deals damage, you can deal maximum damage with that spell on the turn you cast it.\nThe first time you do so, you suffer no adverse effect.\nIf you use this feature again before you finish a Long Rest, you take 2d12 Necrotic damage for each level of the spell slot immediately after you cast it.\nThis damage ignores Resistance and Immunity.\nEach time you use this feature again before finishing a Long Rest, the Necrotic damage per spell level increases by 1d12."}'::jsonb);
insert into ruleset_entries (ruleset_id, entry_type, human_readable, structured_data)
values
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'languages', '{"name":"Common","desc":null}'::jsonb, '{"index":"common","name":"Common","is_rare":false,"note":"","url":"/api/2024/languages/common"}'::jsonb),
