insert into ruleset_entries (ruleset_id, entry_type, human_readable, structured_data)
values
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'monsters', '{"name":"Aboleth","desc":null}'::jsonb, '{"index":"aboleth","name":"Aboleth","size":"Large","type":"aberration","alignment":"lawful evil","armor_class":[{"type":"natural","value":17}],"hit_points":150,"hit_dice":"20d10","hit_points_roll":"20d10+40","speed":{"walk":"10 ft.","swim":"40 ft."},"strength":21,"dexterity":9,"constitution":15,"intelligence":18,"wisdom":15,"charisma":18,"proficiencies":[{"value":6,"proficiency":{"index":"saving-throw-con","name":"Saving Throw: CON","url":"/api/2024/proficiencies/saving-throw-con"}},{"value":8,"proficiency":{"index":"saving-throw-int","name":"Saving Throw: INT","url":"/api/2024/proficiencies/saving-throw-int"}},{"value":6,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2024/proficiencies/saving-throw-wis"}},{"value":12,"proficiency":{"index":"skill-history","name":"Skill: History","url":"/api/2024/proficiencies/skill-history"}},{"value":10,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2024/proficiencies/skill-perception"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":[],"condition_immunities":[],"senses":{"darkvision":"120 ft.","passive_perception":20},"languages":"Deep Speech, telepathy 120 ft.","challenge_rating":10,"proficiency_bonus":4,"xp":5900,"xp_in_lair":7200,"special_abilities":[{"name":"Amphibious","desc":"The aboleth can breathe air and water."},{"name":"Eldritch Restoration","desc":"If destroyed, the aboleth gains a new body in 5d10 days, reviving with all its Hit Points in the Far Realm or another location chosen by the GM."},{"name":"Legendary Resistance","desc":"If the aboleth fails a saving throw, it can choose to succeed instead.","usage":{"type":"per day","times":3,"times_in_lair":4}},{"name":"Mucous Cloud","desc":"While underwater, the aboleth is surrounded by mucus. Constitution Saving Throw: DC 14,each creature in a 5-foot Emanation originating from the aboleth at the end of the aboleth''s turn. Failure: The target is cursed. Until the curse ends, the target''s skin becomes slimy, the target can breathe air and water, and it can''t regain Hit Points unless it is underwater. \nWhile the cursed creature is outside a body of water, the creature takes 6 (1d12) Acid damage at the end of every 10 minutes unless moisture is applied to its skin before those minutes have passed.","dc":{"dc_type":{"index":"con","name":"CON","url":"/api/2024/ability-scores/con"},"dc_value":14,"success_type":"none"}},{"name":"Probing Telepathy","desc":"If a creature the aboleth can see communicates telepathically with the aboleth, the aboleth learns the creature''s greatest desires."}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The aboleth makes two Tentacle attacks and uses either Consume Memories or Dominate Mind if available.","actions":[{"action_name":"Tentacle","count":2,"type":"melee"}],"action_options":{"choose":1,"type":"action","from":{"option_set_type":"options_array","options":[{"option_type":"action","action_name":"Consume Memories","count":1,"type":"special"},{"option_type":"action","action_name":"Dominate Mind","count":1,"type":"special"}]}}},{"name":"Tentacle","desc":"Melee Attack Roll: +9, reach 15 ft. Hit: 12 (2d6 + 5) Bludgeoning damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 14) from one of four tentacles.","attack_bonus":9,"dc":{"dc_type":{"index":"str","name":"STR","url":"/api/2024/ability-scores/str"},"dc_value":14,"success_type":"none"},"damage":[{"damage_type":{"index":"bludgeoning","name":"Bludgeoning","url":"/api/2024/damage-types/bludgeoning"},"damage_dice":"2d6+5"}]},{"name":"Consume Memories.","desc":" Intelligence Saving Throw: DC 16, one creature within 30 feet that is Charmed or Grappled by the aboleth. Failure: 10 (3d6) Psychic damage. Success: Half damage. Failure or Success: The aboleth gains the target''s memories if the target is a Humanoid and is reduced to 0 Hit Points by this action.","dc":{"dc_type":{"index":"int","name":"INT","url":"/api/2024/ability-scores/int"},"dc_value":16,"success_type":"half"},"damage":[{"damage_type":{"index":"psychic","name":"Psychic","url":"/api/2024/damage-types/psychic"},"damage_dice":"3d6"}]},{"name":"Dominate Mind","desc":"Wisdom Saving Throw: DC 16, one creature the aboleth can see within 30 feet. Failure: The target has the Charmed condition until the aboleth dies or is on a different plane of existence from the target. While Charmed, the target acts as an\nally to the aboleth and is under its control while within 60 feet of it. In addition, the aboleth and the target\ncan communicate telepathically with each other over any distance.\nThe target repeats the save whenever it takes damage as well as after every 24 hours it spends at least 1 mile away from the aboleth, ending the effect on itself on a success.","usage":{"type":"per day","times":2},"dc":{"dc_type":{"index":"wis","name":"WIS","url":"/api/2024/ability-scores/wis"},"dc_value":16,"success_type":"none"}}],"legendary_actions":[{"name":"Lash","desc":"The aboleth makes one Tentacle attack."},{"name":"Psychic Drain","desc":"If the aboleth has at least one creature Charmed or Grappled, it uses Consume Memories and regains 5 (1d10) Hit Points."}],"image":"/api/images/monsters/aboleth.png","url":"/api/2024/monsters/aboleth"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'monsters', '{"name":"Adult Black Dragon","desc":null}'::jsonb, '{"index":"adult-black-dragon","name":"Adult Black Dragon","size":"Huge","type":"dragon","alignment":"chaotic evil","armor_class":[{"type":"natural","value":19}],"hit_points":195,"hit_dice":"17d12","hit_points_roll":"17d12+85","speed":{"walk":"40 ft.","fly":"80 ft.","swim":"40 ft."},"strength":23,"dexterity":14,"constitution":21,"intelligence":14,"wisdom":13,"charisma":19,"proficiencies":[{"value":7,"proficiency":{"index":"saving-throw-dex","name":"Saving Throw: DEX","url":"/api/2024/proficiencies/saving-throw-dex"}},{"value":6,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2024/proficiencies/saving-throw-wis"}},{"value":11,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2024/proficiencies/skill-perception"}},{"value":7,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2024/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":["acid"],"condition_immunities":[],"senses":{"blindsight":"60 ft.","darkvision":"120 ft.","passive_perception":21},"languages":"Common, Draconic","challenge_rating":14,"proficiency_bonus":5,"xp":11500,"xp_in_lair":13000,"special_abilities":[{"name":"Amphibious","desc":"The dragon can breathe air and water."},{"name":"Legendary Resistance","desc":"If the dragon fails a saving throw, it can choose to succeed instead.","usage":{"type":"per day","times":3,"times_in_lair":4}}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The dragon makes three Rend attacks. It can replace one attack with a use of Spellcasting to cast Acid Arrow (level 3 version).","actions":[{"action_name":"Rend","count":2,"type":"melee"}],"action_options":{"choose":1,"type":"action","from":{"option_set_type":"options_array","options":[{"option_type":"action","action_name":"Rend","count":1,"type":"melee"},{"option_type":"action","action_name":"Acid Arrow","count":1,"type":"ranged"}]}}},{"name":"Rend","desc":"Melee Attack Roll: +11, reach 10 ft. Hit: 13 (2d6 + 6) Slashing damage plus 4 (1d8) Acid damage","attack_bonus":11,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2024/damage-types/slashing"},"damage_dice":"2d6+6"},{"damage_type":{"index":"acid","name":"Acid","url":"/api/2024/damage-types/acid"},"damage_dice":"1d8"}]},{"name":"Acid Breath","desc":"Dexterity Saving Throw: DC 18, each creature in a 60-foot-long, 5-footwide Line. Failure: 54 (12d8) Acid damage. Success: Half damage.","usage":{"type":"recharge on roll","dice":"1d6","min_value":5},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2024/ability-scores/dex"},"dc_value":18,"success_type":"half"},"damage":[{"damage_type":{"index":"acid","name":"Acid","url":"/api/2024/damage-types/acid"},"damage_dice":"12d8"}]},{"name":"Spellcasting","desc":"The dragon casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 17, +9 to hit with spell attacks):","spellcasting":{"ability":{"index":"cha","name":"CHA","url":"/api/2024/ability-scores/cha"},"dc":17,"modifier":9,"components_required":[],"spells":[{"index":"acid-arrow","name":"Acid Arrow","level":3,"url":"/api/2024/spells/acid-arrow-nyi","usage":{"type":"at will"}},{"index":"detect-magic","name":"Detect Magic","level":1,"url":"/api/2024/spells/detect-magic-nyi","usage":{"type":"at will"}},{"index":"fear","name":"Fear","level":3,"url":"/api/2024/spells/fear-nyi","usage":{"type":"at will"}},{"index":"speak-with-dead","name":"Speak with Dead","level":3,"url":"/api/2024/spells/speak-with-dead-nyi","usage":{"type":"per day","times":1}},{"index":"vitriolic-sphere","name":"Vitriolic Sphere","level":4,"url":"/api/2024/spells/vitriolic-sphere-nyi","usage":{"type":"per day","times":1}}]}}],"legendary_actions":[{"name":"Cloud of Insects","desc":"Dexterity Saving Throw: DC 17, one creature the dragon can see within 120 feet. Failure: 22 (4d10) Poison damage, and the target has Disadvantage on saving throws to maintain Concentration until the end of its next turn. Failure or Success: The dragon can''t take this action again until the start of its next turn.","dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2024/ability-scores/dex"},"dc_value":17,"success_type":"none"},"damage":[{"damage_type":{"index":"poison","name":"Poison","url":"/api/2024/damage-types/poison"},"damage_dice":"4d10"}]},{"name":"Frightful Presence","desc":"The dragon uses Spellcasting to cast Fear. The dragon can''t take this action again until the start of its next turn."},{"name":"Pounce","desc":" The dragon moves up to half its Speed, and it makes one Rend attack."}],"image":"/api/images/monsters/adult-black-dragon.png","url":"/api/2024/monsters/adult-black-dragon"}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'monsters', '{"name":"Adult Blue Dragon","desc":null}'::jsonb, '{"index":"adult-blue-dragon","name":"Adult Blue Dragon","size":"Huge","type":"dragon","alignment":"lawful evil","armor_class":[{"type":"natural","value":19}],"hit_points":212,"hit_dice":"17d12","hit_points_roll":"17d12+102","speed":{"walk":"40 ft.","burrow":"30 ft.","fly":"80 ft."},"strength":25,"dexterity":10,"constitution":23,"intelligence":16,"wisdom":15,"charisma":20,"proficiencies":[{"value":5,"proficiency":{"index":"saving-throw-dex","name":"Saving Throw: DEX","url":"/api/2024/proficiencies/saving-throw-dex"}},{"value":7,"proficiency":{"index":"saving-throw-wis","name":"Saving Throw: WIS","url":"/api/2024/proficiencies/saving-throw-wis"}},{"value":12,"proficiency":{"index":"skill-perception","name":"Skill: Perception","url":"/api/2024/proficiencies/skill-perception"}},{"value":5,"proficiency":{"index":"skill-stealth","name":"Skill: Stealth","url":"/api/2024/proficiencies/skill-stealth"}}],"damage_vulnerabilities":[],"damage_resistances":[],"damage_immunities":["lightning"],"condition_immunities":[],"senses":{"blindsight":"60 ft.","darkvision":"120 ft.","passive_perception":22},"languages":"Common, Draconic","challenge_rating":16,"proficiency_bonus":5,"xp":15000,"xp_in_lair":18000,"special_abilities":[{"name":"Legendary Resistance","desc":"If the dragon fails a saving throw, it can choose to succeed instead.","usage":{"type":"per day","times":3,"times_in_lair":4}}],"actions":[{"name":"Multiattack","multiattack_type":"actions","desc":"The dragon makes three Rend attacks. It can replace one attack with a use of Spellcasting to cast Shatter.","actions":[{"action_name":"Rend","count":2,"type":"melee"}],"action_options":{"choose":1,"type":"action","from":{"option_set_type":"options_array","options":[{"option_type":"action","action_name":"Rend","count":1,"type":"melee"},{"option_type":"action","action_name":"Shatter","count":1,"type":"ranged"}]}}},{"name":"Rend","desc":"Melee Attack Roll: +12, reach 10 ft. Hit: 16 (2d8 + 7) Slashing damage plus 5 (1d10) Lightning damage","attack_bonus":12,"damage":[{"damage_type":{"index":"slashing","name":"Slashing","url":"/api/2024/damage-types/slashing"},"damage_dice":"2d8+7"},{"damage_type":{"index":"lightning","name":"Lightning","url":"/api/2024/damage-types/lightning"},"damage_dice":"1d10"}]},{"name":"Lightning Breath","desc":"Dexterity Saving Throw: DC 19, each creature in a 90-foot-long, 5-footwide Line. Failure: 60 (11d10) Lightning damage. Success: Half damage.","usage":{"type":"recharge on roll","dice":"1d6","min_value":5},"dc":{"dc_type":{"index":"dex","name":"DEX","url":"/api/2024/ability-scores/dex"},"dc_value":19,"success_type":"half"},"damage":[{"damage_type":{"index":"lightning","name":"Lightning","url":"/api/2024/damage-types/lightning"},"damage_dice":"11d10"}]},{"name":"Spellcasting","desc":"The dragon casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 18):","spellcasting":{"ability":{"index":"cha","name":"CHA","url":"/api/2024/ability-scores/cha"},"dc":18,"modifier":5,"components_required":[],"spells":[{"index":"acid-arrow","name":"Acid Arrow","level":3,"url":"/api/2024/spells/acid-arrow-nyi","usage":{"type":"at will"}},{"index":"detect-magic","name":"Detect Magic","level":1,"url":"/api/2024/spells/detect-magic-nyi","usage":{"type":"at will"}},{"index":"invisibility","name":"Invisibility","level":2,"url":"/api/2024/spells/invisibility-nyi","usage":{"type":"at will"}},{"index":"mage-hand","name":"Mage Hand","level":0,"url":"/api/2024/spells/mage-hand-nyi","usage":{"type":"at will"}},{"index":"shatter","name":"Shatter","level":2,"url":"/api/2024/spells/shatter-nyi","usage":{"type":"at will"}},{"index":"scrying","name":"Scrying","level":5,"url":"/api/2024/spells/scrying-nyi","usage":{"type":"per day","times":1}},{"index":"sending","name":"Sending","level":3,"url":"/api/2024/spells/sending-nyi","usage":{"type":"per day","times":1}}]}}],"legendary_actions":[{"name":"Cloaked Flight","desc":"The dragon uses Spellcasting to cast Invisibility on itself, and it can fly up to half its Fly Speed. The dragon can''t take this action again until the start of its next turn."},{"name":"Sonic Boom","desc":"The dragon uses Spellcasting to cast Shatter. The dragon can''t take this action again until the start of its next turn."},{"name":"Tail Swipe","desc":"The dragon makes one Rend attack."}],"image":"/api/images/monsters/adult-blue-dragon.png","url":"/api/2024/monsters/adult-blue-dragon"}'::jsonb);
insert into ruleset_entries (ruleset_id, entry_type, human_readable, structured_data)
values
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'poisons', '{"name":"Assassin''s Blood","desc":"A creature subjected to Assassin''s Blood makes a DC 10 Constitution saving throw. On a failed save, the creature takes 6 (1d12) Poison damage and has the Poisoned condition for 24 hours. On a successful save, the creature takes half as much damage only."}'::jsonb, '{"index":"assassins-blood","name":"Assassin''s Blood","url":"/api/2024/poisons/assassins-blood","cost":150,"type":"ingested","description":"A creature subjected to Assassin''s Blood makes a DC 10 Constitution saving throw. On a failed save, the creature takes 6 (1d12) Poison damage and has the Poisoned condition for 24 hours. On a successful save, the creature takes half as much damage only."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'poisons', '{"name":"Burnt Othur Fumes","desc":"A creature subjected to Burnt Othur Fumes must succeed on a DC 13 Constitution saving throw or take 10 (3d6) Poison damage, and it must repeat the save at the start of each of its turns. On each successive failed save, the creature takes 3 (1d6) Poison damage. After three successful saves, the poison ends."}'::jsonb, '{"index":"burnt-othur-fumes","name":"Burnt Othur Fumes","url":"/api/2024/poisons/burnt-othur-fumes","cost":500,"type":"inhaled","description":"A creature subjected to Burnt Othur Fumes must succeed on a DC 13 Constitution saving throw or take 10 (3d6) Poison damage, and it must repeat the save at the start of each of its turns. On each successive failed save, the creature takes 3 (1d6) Poison damage. After three successful saves, the poison ends."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'poisons', '{"name":"Crawler Mucus","desc":"A creature subjected to Crawler Mucus must succeed on a DC 13 Constitution saving throw or have the Poisoned condition for 1 minute. The creature also has the Paralyzed condition while Poisoned in this way. The creature repeats the save at the end of each of its turns, ending the effect on itself on a success."}'::jsonb, '{"index":"crawler-mucus","name":"Crawler Mucus","url":"/api/2024/poisons/crawler-mucus","cost":200,"type":"contact","description":"A creature subjected to Crawler Mucus must succeed on a DC 13 Constitution saving throw or have the Poisoned condition for 1 minute. The creature also has the Paralyzed condition while Poisoned in this way. The creature repeats the save at the end of each of its turns, ending the effect on itself on a success."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'poisons', '{"name":"Essence of Ether","desc":"A creature subjected to Essence of Ether must succeed on a DC 15 Constitution saving throw or have the Poisoned condition for 8 hours. The creature also has the Unconscious condition while Poisoned in this way. The creature wakes up if it takes damage or if another creature takes an action to shake it awake."}'::jsonb, '{"index":"essence-of-ether","name":"Essence of Ether","url":"/api/2024/poisons/essence-of-ether","cost":300,"type":"inhaled","description":"A creature subjected to Essence of Ether must succeed on a DC 15 Constitution saving throw or have the Poisoned condition for 8 hours. The creature also has the Unconscious condition while Poisoned in this way. The creature wakes up if it takes damage or if another creature takes an action to shake it awake."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'poisons', '{"name":"Malice","desc":"A creature subjected to Malice must succeed on a DC 15 Constitution saving throw or have the Poisoned condition for 1 hour. The creature also has the Blinded condition while Poisoned in this way."}'::jsonb, '{"index":"malice","name":"Malice","url":"/api/2024/poisons/malice","cost":250,"type":"inhaled","description":"A creature subjected to Malice must succeed on a DC 15 Constitution saving throw or have the Poisoned condition for 1 hour. The creature also has the Blinded condition while Poisoned in this way."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'poisons', '{"name":"Midnight Tears","desc":"A creature that ingests Midnight Tears suffers no effect until the stroke of midnight. Any effect that ends the Poisoned condition neutralizes this poison. If the poison hasn''t been neutralized before midnight, the creature makes a DC 17 Constitution saving throw, taking 31 (9d6) Poison damage on a failed save or half as much damage on a successful one."}'::jsonb, '{"index":"midnight-tears","name":"Midnight Tears","url":"/api/2024/poisons/midnight-tears","cost":1500,"type":"ingested","description":"A creature that ingests Midnight Tears suffers no effect until the stroke of midnight. Any effect that ends the Poisoned condition neutralizes this poison. If the poison hasn''t been neutralized before midnight, the creature makes a DC 17 Constitution saving throw, taking 31 (9d6) Poison damage on a failed save or half as much damage on a successful one."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'poisons', '{"name":"Oil of Taggit","desc":"A creature subjected to Oil of Taggit must succeed on a DC 13 Constitution saving throw or have the Poisoned condition for 24 hours. The creature also has the Unconscious condition while Poisoned in this way. It wakes up if it takes damage."}'::jsonb, '{"index":"oil-of-taggit","name":"Oil of Taggit","url":"/api/2024/poisons/oil-of-taggit","cost":400,"type":"contact","description":"A creature subjected to Oil of Taggit must succeed on a DC 13 Constitution saving throw or have the Poisoned condition for 24 hours. The creature also has the Unconscious condition while Poisoned in this way. It wakes up if it takes damage."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'poisons', '{"name":"Pale Tincture","desc":"A creature subjected to Pale Tincture must succeed on a DC 16 Constitution saving throw or take 3 (1d6) Poison damage and have the Poisoned condition. The Poisoned creature repeats the save every 24 hours, taking 3 (1d6) Poison damage on a failed save. The damage the poison deals can''t be healed by any means while the creature remains Poisoned. After seven successful saves against the poison, the creature is no longer Poisoned."}'::jsonb, '{"index":"pale-tincture","name":"Pale Tincture","url":"/api/2024/poisons/pale-tincture","cost":250,"type":"ingested","description":"A creature subjected to Pale Tincture must succeed on a DC 16 Constitution saving throw or take 3 (1d6) Poison damage and have the Poisoned condition. The Poisoned creature repeats the save every 24 hours, taking 3 (1d6) Poison damage on a failed save. The damage the poison deals can''t be healed by any means while the creature remains Poisoned. After seven successful saves against the poison, the creature is no longer Poisoned."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'poisons', '{"name":"Purple Worm Poison","desc":"A creature subjected to Purple Worm Poison makes a DC 21 Constitution saving throw, taking 35 (10d6) Poison damage on a failed save or half as much damage on a successful one."}'::jsonb, '{"index":"purple-worm-poison","name":"Purple Worm Poison","url":"/api/2024/poisons/purple-worm-poison","cost":2000,"type":"injury","description":"A creature subjected to Purple Worm Poison makes a DC 21 Constitution saving throw, taking 35 (10d6) Poison damage on a failed save or half as much damage on a successful one."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'poisons', '{"name":"Serpent Venom","desc":"A creature subjected to Serpent Venom must succeed on a DC 11 Constitution saving throw, taking 10 (3d6) Poison damage on a failed save or half as much damage on a successful one."}'::jsonb, '{"index":"serpent-venom","name":"Serpent Venom","url":"/api/2024/poisons/serpent-venom","cost":200,"type":"injury","description":"A creature subjected to Serpent Venom must succeed on a DC 11 Constitution saving throw, taking 10 (3d6) Poison damage on a failed save or half as much damage on a successful one."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'poisons', '{"name":"Spider''s Sting","desc":"A creature subjected to Spider''s Sting must succeed on a DC 13 Constitution saving throw or have the Poisoned condition for 1 hour. If the creature fails the save by 5 or more, the creature also has the Unconscious condition while Poisoned in this way. The creature wakes up if it takes damage or if another creature takes an action to shake it awake."}'::jsonb, '{"index":"spiders-sting","name":"Spider''s Sting","url":"/api/2024/poisons/spiders-sting","cost":200,"type":"injury","description":"A creature subjected to Spider''s Sting must succeed on a DC 13 Constitution saving throw or have the Poisoned condition for 1 hour. If the creature fails the save by 5 or more, the creature also has the Unconscious condition while Poisoned in this way. The creature wakes up if it takes damage or if another creature takes an action to shake it awake."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'poisons', '{"name":"Torpor","desc":"A creature subjected to Torpor poison must succeed on a DC 15 Constitution saving throw or have the Poisoned condition for 4d6 hours. The creature''s Speed is halved while the creature is Poisoned in this way."}'::jsonb, '{"index":"torpor","name":"Torpor","url":"/api/2024/poisons/torpor","cost":600,"type":"ingested","description":"A creature subjected to Torpor poison must succeed on a DC 15 Constitution saving throw or have the Poisoned condition for 4d6 hours. The creature''s Speed is halved while the creature is Poisoned in this way."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'poisons', '{"name":"Truth Serum","desc":"A creature subjected to Truth Serum must succeed on a DC 11 Constitution saving throw or have the Poisoned condition for 1 hour. The Poisoned creature can''t knowingly communicate a lie."}'::jsonb, '{"index":"truth-serum","name":"Truth Serum","url":"/api/2024/poisons/truth-serum","cost":150,"type":"ingested","description":"A creature subjected to Truth Serum must succeed on a DC 11 Constitution saving throw or have the Poisoned condition for 1 hour. The Poisoned creature can''t knowingly communicate a lie."}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'poisons', '{"name":"Wyvern Poison","desc":"A creature subjected to Wyvern Poison makes a DC 14 Constitution saving throw, taking 24 (7d6) Poison damage on a failed save or half as much damage on a successful one."}'::jsonb, '{"index":"wyvern-poison","name":"Wyvern Poison","url":"/api/2024/poisons/wyvern-poison","cost":1200,"type":"injury","description":"A creature subjected to Wyvern Poison makes a DC 14 Constitution saving throw, taking 24 (7d6) Poison damage on a failed save or half as much damage on a successful one."}'::jsonb);
