  ('336a0121-bb51-47b7-8125-a40673d53a77', 'species', '{"name":"Dragonborn","desc":null}'::jsonb, '{"index":"dragonborn","url":"/api/2024/species/dragonborn","name":"Dragonborn","type":"Humanoid","size":"Medium","speed":30,"subspecies":[{"index":"draconic-ancestor-black","url":"/api/2024/subspecies/draconic-ancestor-black","name":"Draconic Ancestor: Black"},{"index":"draconic-ancestor-blue","url":"/api/2024/subspecies/draconic-ancestor-blue","name":"Draconic Ancestor: Blue"},{"index":"draconic-ancestor-brass","url":"/api/2024/subspecies/draconic-ancestor-brass","name":"Draconic Ancestor: Brass"},{"index":"draconic-ancestor-bronze","url":"/api/2024/subspecies/draconic-ancestor-bronze","name":"Draconic Ancestor: Bronze"},{"index":"draconic-ancestor-copper","url":"/api/2024/subspecies/draconic-ancestor-copper","name":"Draconic Ancestor: Copper"},{"index":"draconic-ancestor-gold","url":"/api/2024/subspecies/draconic-ancestor-gold","name":"Draconic Ancestor: Gold"},{"index":"draconic-ancestor-green","url":"/api/2024/subspecies/draconic-ancestor-green","name":"Draconic Ancestor: Green"},{"index":"draconic-ancestor-red","url":"/api/2024/subspecies/draconic-ancestor-red","name":"Draconic Ancestor: Red"},{"index":"draconic-ancestor-silver","url":"/api/2024/subspecies/draconic-ancestor-silver","name":"Draconic Ancestor: Silver"},{"index":"draconic-ancestor-white","url":"/api/2024/subspecies/draconic-ancestor-white","name":"Draconic Ancestor: White"}],"traits":[{"index":"darkvision-60","url":"/api/2024/traits/darkvision-60","name":"Darkvision (60 ft.)"},{"index":"draconic-flight","url":"/api/2024/traits/draconic-flight","name":"Draconic Flight"}]}'::jsonb),
