  ('336a0121-bb51-47b7-8125-a40673d53a77', 'species', '{"name":"Gnome","desc":null}'::jsonb, '{"index":"gnome","url":"/api/2024/species/gnome","name":"Gnome","type":"Humanoid","size":"Small","speed":30,"traits":[{"index":"darkvision-60","url":"/api/2024/traits/darkvision-60","name":"Darkvision (60 ft.)"},{"index":"gnomish-cunning","url":"/api/2024/traits/gnomish-cunning","name":"Gnomish Cunning"},{"index":"gnomish-lineage","url":"/api/2024/traits/gnomish-lineage","name":"Gnomish Lineage"}],"subspecies":[{"index":"gnomish-lineage-forest-gnome","url":"/api/2024/subspecies/gnomish-lineage-forest-gnome","name":"Gnomish Lineage: Forest Gnome"},{"index":"gnomish-lineage-rock-gnome","url":"/api/2024/subspecies/gnomish-lineage-rock-gnome","name":"Gnomish Lineage: Rock Gnome"}]}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'species', '{"name":"Goliath","desc":null}'::jsonb, '{"index":"goliath","url":"/api/2024/species/goliath","name":"Goliath","type":"Humanoid","size":"Medium","speed":35,"traits":[{"index":"giant-ancestry","url":"/api/2024/traits/giant-ancestry","name":"Giant Ancestry"},{"index":"large-form","url":"/api/2024/traits/large-form","name":"Large Form"},{"index":"powerful-build","url":"/api/2024/traits/powerful-build","name":"Powerful Build"}],"subspecies":[{"index":"giant-ancestry-clouds-jaunt","url":"/api/2024/subspecies/giant-ancestry-clouds-jaunt","name":"Giant Ancestry: Cloud''s Jaunt"},{"index":"giant-ancestry-fires-burn","url":"/api/2024/subspecies/giant-ancestry-fires-burn","name":"Giant Ancestry: Fire''s Burn"},{"index":"giant-ancestry-frosts-chill","url":"/api/2024/subspecies/giant-ancestry-frosts-chill","name":"Giant Ancestry: Frost''s Chill"},{"index":"giant-ancestry-hills-tumble","url":"/api/2024/subspecies/giant-ancestry-hills-tumble","name":"Giant Ancestry: Hill''s Tumble"},{"index":"giant-ancestry-stones-endurance","url":"/api/2024/subspecies/giant-ancestry-stones-endurance","name":"Giant Ancestry: Stone''s Endurance"},{"index":"giant-ancestry-storms-thunder","url":"/api/2024/subspecies/giant-ancestry-storms-thunder","name":"Giant Ancestry: Storm''s Thunder"}]}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'species', '{"name":"Halfling","desc":null}'::jsonb, '{"index":"halfling","url":"/api/2024/species/halfling","name":"Halfling","type":"Humanoid","size":"Small","speed":30,"traits":[{"index":"brave","url":"/api/2024/traits/brave","name":"Brave"},{"index":"halfling-nimbleness","url":"/api/2024/traits/halfling-nimbleness","name":"Halfling Nimbleness"},{"index":"luck","url":"/api/2024/traits/luck","name":"Luck"},{"index":"naturally-stealthy","url":"/api/2024/traits/naturally-stealthy","name":"Naturally Stealthy"}]}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'species', '{"name":"Human","desc":null}'::jsonb, '{"index":"human","url":"/api/2024/species/human","name":"Human","type":"Humanoid","size":"Medium","speed":30,"traits":[{"index":"resourceful","url":"/api/2024/traits/resourceful","name":"Resourceful"},{"index":"skillful","url":"/api/2024/traits/skillful","name":"Skillful"},{"index":"versatile","url":"/api/2024/traits/versatile","name":"Versatile"}]}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'species', '{"name":"Orc","desc":null}'::jsonb, '{"index":"orc","url":"/api/2024/species/orc","name":"Orc","type":"Humanoid","size":"Medium","speed":30,"traits":[{"index":"adrenaline-rush","url":"/api/2024/traits/adrenaline-rush","name":"Adrenaline Rush"},{"index":"darkvision-120","url":"/api/2024/traits/darkvision-120","name":"Darkvision (120 ft.)"},{"index":"relentless-endurance","url":"/api/2024/traits/relentless-endurance","name":"Relentless Endurance"}]}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'species', '{"name":"Tiefling","desc":null}'::jsonb, '{"index":"tiefling","url":"/api/2024/species/tiefling","name":"Tiefling","type":"Humanoid","size_options":{"desc":"Choose a size when you select this species.","choose":1,"type":"size_categories","from":{"option_set_type":"options_array","options":[{"option_type":"size","size":"Small"},{"option_type":"size","size":"Medium"}]}},"speed":30,"traits":[{"index":"darkvision-60","url":"/api/2024/traits/darkvision-60","name":"Darkvision (60 ft.)"},{"index":"fiendish-legacy","url":"/api/2024/traits/fiendish-legacy","name":"Fiendish Legacy"},{"index":"otherworldly-presence","url":"/api/2024/traits/otherworldly-presence","name":"Otherworldly Presence"}],"subspecies":[{"index":"fiendish-legacy-abyssal","url":"/api/2024/subspecies/fiendish-legacy-abyssal","name":"Fiendish Legacy: Abyssal"},{"index":"fiendish-legacy-chthonic","url":"/api/2024/subspecies/fiendish-legacy-chthonic","name":"Fiendish Legacy: Chthonic"},{"index":"fiendish-legacy-infernal","url":"/api/2024/subspecies/fiendish-legacy-infernal","name":"Fiendish Legacy: Infernal"}]}'::jsonb);
insert into ruleset_entries (ruleset_id, entry_type, human_readable, structured_data)
values
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'subclasses', '{"name":"Path of the Berserker","desc":"Barbarians who walk the Path of the Berserker direct their Rage primarily toward violence. Their path is one of untrammeled fury, and they thrill in the chaos of battle as they allow their Rage to seize and empower them."}'::jsonb, '{"index":"path-of-the-berserker","url":"/api/2024/subclasses/path-of-the-berserker","name":"Path of the Berserker","class":{"index":"barbarian","url":"/api/2024/classes/barbarian","name":"Barbarian"},"summary":"Channel Rage into Violent Fury","description":"Barbarians who walk the Path of the Berserker direct their Rage primarily toward violence. Their path is one of untrammeled fury, and they thrill in the chaos of battle as they allow their Rage to seize and empower them.","features":[{"name":"Frenzy","level":3,"description":"If you use Reckless Attack while your Rage is active, you deal extra damage to the first target you hit on your turn with a Strength-based attack. To determine the extra damage, roll a number of d6s equal to your Rage Damage bonus, and add them together. The damage has the same type as the weapon or Unarmed Strike used for the attack."},{"name":"Mindless Rage","level":6,"description":"You have Immunity to the Charmed and Frightened conditions while your Rage is active. If you''re Charmed or Frightened when you enter your Rage, the condition ends on you."},{"name":"Retaliation","level":10,"description":"When you take damage from a creature that is within 5 feet of you, you can take a Reaction to make one melee attack against that creature, using a weapon or an Unarmed Strike."},{"name":"Intimidating Presence","level":14,"description":"As a Bonus Action, you can strike terror into others with your menacing presence and primal power.\nWhen you do so, each creature of your choice in a 30-foot Emanation originating from you must make a Wisdom saving throw (DC 8 plus your Strength modifier and Proficiency Bonus). On a failed save, a creature has the Frightened condition for 1 minute. At the end of each of the Frightened creature''s turns, the creature repeats the save, ending the effect on itself on a success.\n  Once you use this feature, you can''t use it again until you finish a Long Rest unless you expend a use of your Rage (no action required) to restore your use of it."}]}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'subclasses', '{"name":"College of Lore","desc":"Bards of the College of Lore collect spells and secrets from diverse sources, such as scholarly tomes, mystical rites, and peasant tales. The college''s members gather in libraries and universities to share their lore with one another. They also meet at festivals or affairs of state, where they can expose corruption, unravel lies, and poke fun at self-important figures of authority."}'::jsonb, '{"index":"college-of-lore","url":"/api/2024/subclasses/college-of-lore","name":"College of Lore","class":{"index":"bard","url":"/api/2024/classes/bard","name":"Bard"},"summary":"Plumb the Depths of Magical Knowledge","description":"Bards of the College of Lore collect spells and secrets from diverse sources, such as scholarly tomes, mystical rites, and peasant tales. The college''s members gather in libraries and universities to share their lore with one another. They also meet at festivals or affairs of state, where they can expose corruption, unravel lies, and poke fun at self-important figures of authority.","features":[{"name":"Bonus Proficiencies","level":3,"description":"You gain proficiency with three skills of your choice."},{"name":"Cutting Words","level":3,"description":"You learn to use your wit to supernaturally distract, confuse, and otherwise sap the confidence and competence of others. When a creature that you can see within 60 feet of yourself makes a damage roll or succeeds on an ability check or attack roll, you can take a Reaction to expend one use of your Bardic Inspiration; roll your Bardic Inspiration die, and subtract the number rolled from the creature''s roll, reducing the damage or potentially turning the success into a failure."},{"name":"Magical Discoveries","level":6,"description":"You learn two spells of your choice. These spells can come from the Cleric, Druid, or Wizard spell list or any combination thereof (see a class''s section for its spell list). A spell you choose must be a cantrip or a spell for which you have spell slots, as shown in the Bard Features table.\n  You always have the chosen spells prepared, and whenever you gain a Bard level, you can replace one of the spells with another spell that meets these requirements."},{"name":"Peerless Skill","level":14,"description":"When you make an ability check or attack roll and fail, you can expend one use of Bardic Inspiration; roll the Bardic Inspiration die, and add the number rolled to the d20, potentially turning a failure into a success. On a failure, the Bardic Inspiration isn''t expended."}]}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'subclasses', '{"name":"Life Domain","desc":"The Life Domain focuses on the positive energy that helps sustain all life in the multiverse. Clerics who tap into this domain are masters of healing, using that life force to cure many hurts.\n  Existence itself relies on the positive energy associated with this domain, so a Cleric of almost any religious tradition might choose it. This domain is particularly associated with agricultural deities, gods of healing or endurance, and gods of home and community. Religious orders of healing also seek the magic of this domain."}'::jsonb, '{"index":"life-domain","url":"/api/2024/subclasses/life-domain","name":"Life Domain","class":{"index":"cleric","url":"/api/2024/classes/cleric","name":"Cleric"},"summary":"Soothe the Hurts of the World","description":"The Life Domain focuses on the positive energy that helps sustain all life in the multiverse. Clerics who tap into this domain are masters of healing, using that life force to cure many hurts.\n  Existence itself relies on the positive energy associated with this domain, so a Cleric of almost any religious tradition might choose it. This domain is particularly associated with agricultural deities, gods of healing or endurance, and gods of home and community. Religious orders of healing also seek the magic of this domain.","features":[{"name":"Disciple of Life","level":3,"description":"When a spell you cast with a spell slot restores Hit Points to a creature, that creature regains additional Hit Points on the turn you cast the spell. The additional Hit Points equal 2 plus the spell slot''s level."},{"name":"Life Domain Spells","level":3,"description":"Your connection to this divine domain ensures you always have certain spells ready. When you reach a Cleric level specified in the Life Domain Spells table, you thereafter always have the listed spells prepared.\nLife Domain Spells\nCleric Level\nPrepared Spells\n3 Aid, Bless, Cure Wounds,\nLesser Restoration\n5 Mass Healing Word, Revivify\n7 Aura of Life, Death Ward\n9 Greater Restoration, Mass Cure Wounds"},{"name":"Preserve Life","level":3,"description":"As a Magic action, you present your Holy Symbol and expend a use of your Channel Divinity to evoke healing energy that can restore a number of Hit Points equal to five times your Cleric level. Choose Bloodied creatures within 30 feet of yourself (which can include you), and divide those Hit Points among them. This feature can restore a creature to no more than half its Hit Point maximum."},{"name":"Blessed Healer","level":6,"description":"The healing spells you cast on others heal you as well. Immediately after you cast a spell with a spell slot that restores Hit Points to one or more creatures other than yourself, you regain Hit Points equal to 2 plus the spell slot''s level."},{"name":"Supreme Healing","level":17,"description":"When you would normally roll one or more dice to restore Hit Points to a creature with a spell or Channel Divinity, don''t roll those dice for the healing; instead use the highest number possible for each die. For example, instead of restoring 2d6 Hit Points to a creature with a spell, you restore 12."}]}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'subclasses', '{"name":"Circle of the Land","desc":"The Circle of the Land comprises mystics and sages who safeguard ancient knowledge and rites. These Druids meet within sacred circles of trees or standing stones to whisper primal secrets in Druidic. The circle''s wisest members preside as the chief priests of their communities."}'::jsonb, '{"index":"circle-of-the-land","url":"/api/2024/subclasses/circle-of-the-land","name":"Circle of the Land","class":{"index":"druid","url":"/api/2024/classes/druid","name":"Druid"},"summary":"Celebrate Connection to the Natural World","description":"The Circle of the Land comprises mystics and sages who safeguard ancient knowledge and rites. These Druids meet within sacred circles of trees or standing stones to whisper primal secrets in Druidic. The circle''s wisest members preside as the chief priests of their communities.","features":[{"name":"Circle of the Land Spells Whenever you finish a Long Rest, choose one type of land: arid, polar, temperate, or tropical. Consult the table below that corresponds to the chosen type; you have the spells listed for your Druid level and lower prepared.","level":3,"description":"Arid Land\nDruid Level Circle Spells\n3 Blur, Burning Hands, Fire Bolt\n5 Fireball\n7 Blight\n9 Wall of Stone\nPolar Land\nDruid Level Circle Spells\n3 Fog Cloud, Hold Person, Ray of Frost\n5 Sleet Storm\n7 Ice Storm\n9 Cone of Cold\nTemperate Land\nDruid Level Circle Spells\n3 Misty Step, Shocking Grasp, Sleep\n5 Lightning Bolt\n7 Freedom of Movement\n9 Tree Stride\nTropical Land\nDruid Level Circle Spells\n3 Acid Splash, Ray of Sickness, Web\n5 Stinking Cloud\n7 Polymorph\n9 Insect Plague"},{"name":"Land''s Aid","level":3,"description":"As a Magic action, you can expend a use of your Wild Shape and choose a point within 60 feet of yourself. Vitality-giving flowers and life-draining thorns appear for a moment in a 10-foot-radius Sphere centered on that point. Each creature of your choice in the Sphere must make a Constitution saving throw against your spell save DC, taking 2d6 Necrotic damage on a failed save or half as much damage on a successful one. One creature of your choice in that area regains 2d6 Hit Points.\n  The damage and healing increase by 1d6 when you reach Druid levels 10 (3d6) and 14 (4d6)."},{"name":"Natural Recovery","level":6,"description":"You can cast one of the level 1+ spells that you have prepared from your Circle Spells feature without expending a spell slot, and you must finish a Long Rest before you do so again.\n  In addition, when you finish a Short Rest, you can choose expended spell slots to recover. The spell slots can have a combined level that is equal to or less than half your Druid level (round up), and none of them can be level 6+. For example, if you''re a level 6 Druid, you can recover up to three levels'' worth of spell slots. You can recover a level 3 spell slot, a level 2 and a level 1 spell slot, or three level 1 spell slots. Once you recover spell slots with this feature, you can''t do so again until you finish a Long Rest."},{"name":"Nature''s Ward","level":10,"description":"You are immune to the Poisoned condition, and you have Resistance to a damage type associated with your current land choice in the Circle Spells feature, as shown in the Nature''s Ward table.\nNature’s Ward\nLand Type Resistance\nArid Fire\nPolar Cold\nLand Type Resistance\nTemperate Lightning\nTropical Poison"},{"name":"Nature''s Sanctuary","level":14,"description":"As a Magic action, you can expend a use of your Wild Shape and cause spectral trees and vines to appear in a 15-foot Cube on the ground within 120 feet of yourself. They last there for 1 minute or until you have the Incapacitated condition or die. You and your allies have Half Cover while in that area, and your allies gain the current Resistance of your Nature''s Ward while there.\n  As a Bonus Action, you can move the Cube up to 60 feet to ground within 120 feet of yourself."}]}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'subclasses', '{"name":"Champion","desc":"A Champion focuses on the development of martial prowess in a relentless pursuit of victory. Champions combine rigorous training with physical excellence to deal devastating blows, withstand peril, and garner glory. Whether in athletic contests or bloody battle, Champions strive for the crown of the victor."}'::jsonb, '{"index":"champion","url":"/api/2024/subclasses/champion","name":"Champion","class":{"index":"fighter","url":"/api/2024/classes/fighter","name":"Fighter"},"summary":"Pursue Physical Excellence in Combat","description":"A Champion focuses on the development of martial prowess in a relentless pursuit of victory. Champions combine rigorous training with physical excellence to deal devastating blows, withstand peril, and garner glory. Whether in athletic contests or bloody battle, Champions strive for the crown of the victor.","features":[{"name":"Improved Critical","level":3,"description":"Your attack rolls with weapons and Unarmed Strikes can score a Critical Hit on a roll of 19 or 20 on the d20."},{"name":"Remarkable Athlete","level":3,"description":"Thanks to your athleticism, you have Advantage on Initiative rolls and Strength (Athletics) checks.\n  In addition, immediately after you score a Critical Hit, you can move up to half your Speed without provoking Opportunity Attacks."},{"name":"Additional Fighting Style","level":7,"description":"You gain another Fighting Style feat of your choice."},{"name":"Heroic Warrior","level":10,"description":"The thrill of battle drives you toward victory. During combat, you can give yourself Heroic Inspiration whenever you start your turn without it."},{"name":"Superior Critical","level":15,"description":"Your attack rolls with weapons and Unarmed Strikes can now score a Critical Hit on a roll of 18-20 on the d20."},{"name":"Survivor","level":18,"description":"You attain the pinnacle of resilience in battle, giving you these benefits.\n  Defy Death. You have Advantage on Death Saving Throws. Moreover, when you roll 18-20 on a Death Saving Throw, you gain the benefit of rolling a 20 on it.\n  Heroic Rally. At the start of each of your turns, you regain Hit Points equal to 5 plus your Constitution modifier if you are Bloodied and have at least 1 Hit Point."}]}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'subclasses', '{"name":"Warrior of the Open Hand","desc":"Warriors of the Open Hand are masters of unarmed combat. They learn techniques to push and trip their opponents and manipulate their own energy to protect themselves from harm."}'::jsonb, '{"index":"warrior-of-the-open-hand","url":"/api/2024/subclasses/warrior-of-the-open-hand","name":"Warrior of the Open Hand","class":{"index":"monk","url":"/api/2024/classes/monk","name":"Monk"},"summary":"Master Unarmed Combat Techniques","description":"Warriors of the Open Hand are masters of unarmed combat. They learn techniques to push and trip their opponents and manipulate their own energy to protect themselves from harm.","features":[{"name":"Open Hand Technique","level":3,"description":"Whenever you hit a creature with an attack granted by your Flurry of Blows, you can impose one of the following effects on that target.\n  Addle. The target can''t make Opportunity Attacks until the start of its next turn.\n Push. The target must succeed on a Strength saving throw or be pushed up to 15 feet away from you.\n  Topple. The target must succeed on a Dexterity saving throw or have the Prone condition."},{"name":"Wholeness of Body","level":6,"description":"You gain the ability to heal yourself. As a Bonus Action, you can roll your Martial Arts die. You regain a number of Hit Points equal to the number rolled\nplus your Wisdom modifier (minimum of 1 Hit Point regained).\n  You can use this feature a number of times equal to your Wisdom modifier (minimum of once), and you regain all expended uses when you finish a Long Rest."},{"name":"Fleet Step","level":11,"description":"When you take a Bonus Action other than Step of the Wind, you can also use Step of the Wind immediately after that Bonus Action."},{"name":"Quivering Palm","level":17,"description":"You gain the ability to set up lethal vibrations in someone''s body. When you hit a creature with an Unarmed Strike, you can expend 4 Focus Points to start these imperceptible vibrations, which last\nfor a number of days equal to your Monk level. The vibrations are harmless unless you take an action to end them. Alternatively, when you take the Attack action on your turn, you can forgo one of the attacks to end the vibrations. To end them, you and the target must be on the same plane of existence. When you end them, the target must make a Constitution saving throw, taking 10d12 Force damage on a failed save or half as much damage on a successful one.\n  You can have only one creature under the effect of this feature at a time. You can end the vibrations harmlessly (no action required)."}]}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'subclasses', '{"name":"Oath of Devotion","desc":"The Oath of Devotion binds Paladins to the ideals of justice and order. These Paladins meet the archetype of the knight in shining armor. They hold themselves to the highest standards of conduct, and some-for better or worse-hold the rest of the world to the same standards.\n  Many who swear this oath are devoted to gods of law and good and use their gods'' tenets as the\nmeasure of personal devotion. Others hold angels as their ideals and incorporate images of angelic wings into their helmets or coats of arms.\nThese paladins share the following tenets:\n- Let your word be your promise.\n- Protect the weak and never fear to act.\n- Let your honorable deeds be an example."}'::jsonb, '{"index":"oath-of-devotion","url":"/api/2024/subclasses/oath-of-devotion","name":"Oath of Devotion","class":{"index":"paladin","url":"/api/2024/classes/paladin","name":"Paladin"},"summary":"Uphold the Ideals of Justice and Order","description":"The Oath of Devotion binds Paladins to the ideals of justice and order. These Paladins meet the archetype of the knight in shining armor. They hold themselves to the highest standards of conduct, and some-for better or worse-hold the rest of the world to the same standards.\n  Many who swear this oath are devoted to gods of law and good and use their gods'' tenets as the\nmeasure of personal devotion. Others hold angels as their ideals and incorporate images of angelic wings into their helmets or coats of arms.\nThese paladins share the following tenets:\n- Let your word be your promise.\n- Protect the weak and never fear to act.\n- Let your honorable deeds be an example.","features":[{"name":"Oath of Devotion Spells","level":3,"description":"The magic of your oath ensures you always have certain spells ready; when you reach a Paladin level specified in the Oath of Devotion Spells table, you thereafter always have the listed spells prepared.\n   Oath of Devotion Spells\nPaladin Level Spells\nLevel 3 Paladin Spells\nSpell School Special\n5 Aid, Zone of Truth\n \nDaylight Evocation -\nMagic Circle Abjuration M\nRevivify Necromancy M\nLevel 4 Paladin Spells\nSpell School Special\nBanishment Abjuration C\nLocate Creature Divination C\nLevel 5 Paladin Spells\nSpell School Special\nGeas Enchantment -\nRaise Dead Necromancy M\n13 Freedom of Movement, Guardian of Faith"},{"name":"Sacred Weapon","level":3,"description":"When you take the Attack action, you can expend one use of your Channel Divinity to imbue one Melee weapon that you are holding with positive energy. For 10 minutes or until you use this feature again, you add your Charisma modifier to attack rolls you make with that weapon (minimum bonus of +1), and each time you hit with it, you cause it to deal its normal damage type or Radiant damage.\n  The weapon also emits Bright Light in a 20-foot radius and Dim Light 20 feet beyond that.\n  You can end this effect early (no action required). This effect also ends if you aren''t carrying the weapon."},{"name":"Aura of Devotion","level":7,"description":"You and your allies have Immunity to the Charmed condition while in your Aura of Protection. If a Charmed ally enters the aura, that condition has no effect on that ally while there."},{"name":"Smite of Protection","level":15,"description":"Your magical smite now radiates protective energy. Whenever you cast Divine Smite, you and your allies have Half Cover while in your Aura of Protection.\nThe aura has this benefit until the start of your next turn."},{"name":"Holy Nimbus","level":20,"description":"As a Bonus Action, you can imbue your Aura of Protection with holy power, granting the benefits below for 10 minutes or until you end them (no action required). Once you use this feature, you can''t use it again until you finish a Long Rest. You can also restore your use of it by expending a level 5 spell slot (no action required).\n  Holy Ward. You have Advantage on any saving throw you are forced to make by a Fiend or an Undead.\n  Radiant Damage. Whenever an enemy starts its turn in the aura, that creature takes Radiant damage equal to your Charisma modifier plus your Proficiency Bonus.\n  Sunlight. The aura is filled with Bright Light that is sunlight."}]}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'subclasses', '{"name":"Hunter","desc":"You stalk prey in the wilds and elsewhere, using your abilities as a Hunter to protect nature and people everywhere from forces that would destroy them."}'::jsonb, '{"index":"hunter","url":"/api/2024/subclasses/hunter","name":"Hunter","class":{"index":"ranger","url":"/api/2024/classes/ranger","name":"Ranger"},"summary":"Protect Nature and People from Destruction","description":"You stalk prey in the wilds and elsewhere, using your abilities as a Hunter to protect nature and people everywhere from forces that would destroy them.","features":[{"name":"Hunter''s Lore","level":3,"description":"You can call on the forces of nature to reveal certain strengths and weaknesses of your prey. While a creature is marked by your Hunter''s Mark, you know whether that creature has any Immunities, Resistances, or Vulnerabilities, and if the creature has any, you know what they are."},{"name":"Hunter''s Prey","level":3,"description":"You gain one of the following feature options of your choice. Whenever you finish a Short or Long Rest, you can replace the chosen option with the other one.\n  Colossus Slayer. Your tenacity can wear down even the most resilient foes. When you hit a creature with a weapon, the weapon deals an extra 1d8 damage to the target if it''s missing any of its Hit Points. You can deal this extra damage only once per turn.\n  Horde Breaker. Once on each of your turns when you make an attack with a weapon, you can make another attack with the same weapon against a different creature that is within 5 feet of the original target, that is within the weapon''s range, and that you haven''t attacked this turn."},{"name":"Defensive Tactics","level":7,"description":"You gain one of the following feature options of your choice. Whenever you finish a Short or Long Rest, you can replace the chosen option with the other one.\n  Escape the Horde. Opportunity Attacks have Disadvantage against you.\n  Multiattack Defense. When a creature hits you with an attack roll, that creature has Disadvantage on all other attack rolls against you this turn."},{"name":"Superior Hunter''s Prey","level":11,"description":"Once per turn when you deal damage to a creature marked by your Hunter''s Mark, you can also deal that spell''s extra damage to a different creature that you can see within 30 feet of the first creature."},{"name":"Superior Hunter''s Defense","level":15,"description":"When you take damage, you can take a Reaction to give yourself Resistance to that damage and any other damage of the same type until the end of the current turn."}]}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'subclasses', '{"name":"Thief","desc":"A mix of burglar, treasure hunter, and explorer, you are the epitome of an adventurer. In addition to improving your agility and stealth, you gain abilities useful for delving into ruins and getting maximum benefit from the magic items you find there."}'::jsonb, '{"index":"thief","url":"/api/2024/subclasses/thief","name":"Thief","class":{"index":"rogue","url":"/api/2024/classes/rogue","name":"Rogue"},"summary":"Hunt for Treasure as a Classic Adventurer","description":"A mix of burglar, treasure hunter, and explorer, you are the epitome of an adventurer. In addition to improving your agility and stealth, you gain abilities useful for delving into ruins and getting maximum benefit from the magic items you find there.","features":[{"name":"Fast Hands","level":3,"description":"As a Bonus Action, you can do one of the following.\n  Sleight of Hand. Make a Dexterity (Sleight of Hand) check to pick a lock or disarm a trap with Thieves'' Tools or to pick a pocket.\n  Use an Object. Take the Utilize action, or take the Magic action to use a magic item that requires that action."},{"name":"Second-Story Work","level":3,"description":"You''ve trained to get into especially hard-to-reach places, granting you these benefits.\n  Climber. You gain a Climb Speed equal to your Speed.\n  Jumper. You can determine your jump distance using your Dexterity rather than your Strength."},{"name":"Supreme Sneak","level":9,"description":"You gain the following Cunning Strike option.\n  Stealth Attack (Cost: 1d6). If you have the Hide action''s Invisible condition, this attack doesn''t end that condition on you if you end the turn behind Three-Quarters Cover or Total Cover."},{"name":"Use Magic Device","level":13,"description":"You''ve learned how to maximize use of magic items, granting you the following benefits.\n  Attunement. You can attune to up to four magic items at once.\n  Charges. Whenever you use a magic item property that expends charges, roll 1d6. On a roll of 6, you use the property without expending the charges.\n  Scrolls. You can use any Spell Scroll, using Intelligence as your spellcasting ability for the spell. If the spell is a cantrip or a level 1 spell, you can cast it reliably. If the scroll contains a higher-level spell, you must first succeed on an Intelligence (Arcana) check (DC 10 plus the spell''s level). On a successful check, you cast the spell from the scroll. On a failed check, the scroll disintegrates."},{"name":"Thief''s Reflexes","level":17,"description":"You are adept at laying ambushes and quickly escaping danger. You can take two turns during the first round of any combat. You take your first turn at your normal Initiative and your second turn at your Initiative minus 10."}]}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'subclasses', '{"name":"Draconic Sorcery","desc":"Your innate magic comes from the gift of a dragon. Perhaps an ancient dragon facing death bequeathed some of its magical power to you or your ancestor. You might have absorbed magic from a site infused with dragons'' power. Or perhaps you handled a treasure taken from a dragon''s hoard that was steeped in draconic power. Or you might have a dragon for an ancestor."}'::jsonb, '{"index":"draconic-sorcery","url":"/api/2024/subclasses/draconic-sorcery","name":"Draconic Sorcery","class":{"index":"sorcerer","url":"/api/2024/classes/sorcerer","name":"Sorcerer"},"summary":"Breathe the Magic of Dragons","description":"Your innate magic comes from the gift of a dragon. Perhaps an ancient dragon facing death bequeathed some of its magical power to you or your ancestor. You might have absorbed magic from a site infused with dragons'' power. Or perhaps you handled a treasure taken from a dragon''s hoard that was steeped in draconic power. Or you might have a dragon for an ancestor.","features":[{"name":"Draconic Resilience","level":3,"description":"The magic in your body manifests physical traits of your draconic gift. Your Hit Point maximum increases by 3, and it increases by 1 whenever you gain another Sorcerer level.\n  Parts of you are also covered by dragon-like scales. While you aren''t wearing armor, your base Armor Class equals 10 plus your Dexterity and Charisma modifiers."},{"name":"Draconic Spells","level":3,"description":"When you reach a Sorcerer level specified in the Draconic Spells table, you thereafter always have the listed spells prepared.\nDraconic Spells\nSorcerer\nLevel Spells\n3 Alter Self, Chromatic Orb, Command,\nDragon’s Breath\n5 Fear, Fly\n7 Arcane Eye, Charm Monster\n9 Legend Lore, Summon Dragon"},{"name":"Elemental Affinity","level":6,"description":"Your draconic magic has an affinity with a damage type associated with dragons. Choose one of those types: Acid, Cold, Fire, Lightning, or Poison.\n  You have Resistance to that damage type, and when you cast a spell that deals damage of that type, you can add your Charisma modifier to one damage roll of that spell."},{"name":"Dragon Wings","level":14,"description":"As a Bonus Action, you can cause draconic wings to appear on your back. The wings last for 1 hour or until you dismiss them (no action required). For the duration, you have a Fly Speed of 60 feet.\n  Once you use this feature, you can''t use it again until you finish a Long Rest unless you spend 3 Sorcery Points (no action required) to restore your use of it."},{"name":"Dragon Companion","level":18,"description":"You can cast Summon Dragon without a Material component. You can also cast it once without a spell slot, and you regain the ability to cast it in this way when you finish a Long Rest.\n  Whenever you start casting the spell, you can modify it so that it doesn''t require Concentration. If you do so, the spell''s duration becomes 1 minute for that casting."}]}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'subclasses', '{"name":"Fiend Patron","desc":"Your pact draws on the Lower Planes, the realms of perdition. You might forge a bargain with a demon lord, an archdevil, or another fiend that is especially mighty. That patron''s aims are evil-the corruption or destruction of all things, ultimately including you-and your path is defined by the extent to which you strive against those aims."}'::jsonb, '{"index":"fiend-patron","url":"/api/2024/subclasses/fiend-patron","name":"Fiend Patron","class":{"index":"warlock","url":"/api/2024/classes/warlock","name":"Warlock"},"summary":"Make a Deal with the Lower Planes","description":"Your pact draws on the Lower Planes, the realms of perdition. You might forge a bargain with a demon lord, an archdevil, or another fiend that is especially mighty. That patron''s aims are evil-the corruption or destruction of all things, ultimately including you-and your path is defined by the extent to which you strive against those aims.","features":[{"name":"Dark One''s Blessing","level":3,"description":"When you reduce an enemy to 0 Hit Points, you gain Temporary Hit Points equal to your Charisma modifier plus your Warlock level (minimum of 1 Temporary Hit Point). You also gain this benefit if someone else reduces an enemy within 10 feet of you to 0 Hit Points."},{"name":"Fiend Spells","level":3,"description":"The magic of your patron ensures you always have certain spells ready; when you reach a Warlock level specified in the Fiend Spells table, you thereafter always have the listed spells prepared.\nFiend Spells\nWarlock Level Spells\n3 Burning Hands, Command,\nScorching Ray, Suggestion\n5 Fireball, Stinking Cloud\n7 Fire Shield, Wall of Fire\n9 Geas, Insect Plague"},{"name":"Dark One''s Own Luck","level":6,"description":"You can call on your fiendish patron to alter fate in your favor. When you make an ability check or a saving throw, you can use this feature to add 1d10 to your roll. You can do so after seeing the roll but before any of the roll''s effects occur.\n  You can use this feature a number of times equal to your Charisma modifier (minimum of once), but you can use it no more than once per roll. You regain all expended uses when you finish a Long Rest."},{"name":"Fiendish Resilience","level":10,"description":"Choose one damage type, other than Force, whenever you finish a Short or Long Rest. You have Resistance to that damage type until you choose a different one with this feature."},{"name":"Hurl Through Hell","level":14,"description":"Once per turn when you hit a creature with an attack roll, you can try to instantly transport the target through the Lower Planes. The target must succeed on a Charisma saving throw against your spell save DC, or the target disappears and hurtles through a nightmare landscape. The target takes 8d10 Psychic damage if it isn''t a Fiend, and it has the Incapacitated condition until the end of your next turn, when it returns to the space it previously occupied or the nearest unoccupied space.\n  Once you use this feature, you can''t use it again until you finish a Long Rest unless you expend a Pact Magic spell slot (no action required) to restore your use of it."}]}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'subclasses', '{"name":"Evoker","desc":"Your studies focus on magic that creates powerful elemental effects such as bitter cold, searing flame, rolling thunder, crackling lightning, and burning acid. Some Evokers find employment in military forces, serving as artillery to blast armies from afar. Others use their power to protect others, while some seek their own gain."}'::jsonb, '{"index":"evoker","url":"/api/2024/subclasses/evoker","name":"Evoker","class":{"index":"wizard","url":"/api/2024/classes/wizard","name":"Wizard"},"summary":"Create Explosive Elemental Effects","description":"Your studies focus on magic that creates powerful elemental effects such as bitter cold, searing flame, rolling thunder, crackling lightning, and burning acid. Some Evokers find employment in military forces, serving as artillery to blast armies from afar. Others use their power to protect others, while some seek their own gain.","features":[{"name":"Evocation Savant","level":3,"description":"Choose two Wizard spells from the Evocation school, each of which must be no higher than level 2, and add them to your spellbook for free.\n  In addition, whenever you gain access to a new level of spell slots in this class, you can add one Wizard spell from the Evocation school to your spellbook for free. The chosen spell must be of a level for which you have spell slots."},{"name":"Potent Cantrip","level":3,"description":"Your damaging cantrips affect even creatures that avoid the brunt of the effect. When you cast a cantrip at a creature and you miss with the attack roll or the target succeeds on a saving throw against the cantrip, the target takes half the cantrip''s damage (if any) but suffers no additional effect from the cantrip."},{"name":"Sculpt Spells","level":6,"description":"You can create pockets of relative safety within the effects of your evocations. When you cast an Evocation spell that affects other creatures that you can see, you can choose a number of them equal to 1 plus the spell''s level. The chosen creatures automatically succeed on their saving throws against the spell, and they take no damage if they would normally take half damage on a successful save."},{"name":"Empowered Evocation","level":10,"description":"Whenever you cast a Wizard spell from the Evocation school, you can add your Intelligence modifier to one damage roll of that spell."},{"name":"Overchannel","level":14,"description":"You can increase the power of your spells. When you cast a Wizard spell with a spell slot of levels 1-5 that deals damage, you can deal maximum damage with that spell on the turn you cast it.\n  The first time you do so, you suffer no adverse effect. If you use this feature again before you finish a Long Rest, you take 2d12 Necrotic damage for each level of the spell slot immediately after you cast it. This damage ignores Resistance and Immunity.\n  Each time you use this feature again before finishing a Long Rest, the Necrotic damage per spell level increases by 1d12."}]}'::jsonb);
