  ('336a0121-bb51-47b7-8125-a40673d53a77', 'subspecies', '{"name":"Draconic Ancestor: Copper","desc":null}'::jsonb, '{"index":"draconic-ancestor-copper","url":"/api/2024/subspecies/draconic-ancestor-copper","name":"Draconic Ancestor: Copper","damage_type":{"index":"acid","name":"Acid","url":"/api/2024/damage-types/acid"},"species":{"index":"dragonborn","name":"Dragonborn","url":"/api/2024/species/dragonborn"},"traits":[{"index":"draconic-breath-weapon-acid","url":"/api/2024/traits/draconic-breath-weapon-acid","name":"Breath Weapon: Acid","level":1},{"index":"draconic-damage-resistance-acid","url":"/api/2024/traits/draconic-damage-resistance-acid","name":"Damage Resistance: Acid","level":1}]}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'subspecies', '{"name":"Draconic Ancestor: Gold","desc":null}'::jsonb, '{"index":"draconic-ancestor-gold","url":"/api/2024/subspecies/draconic-ancestor-gold","name":"Draconic Ancestor: Gold","damage_type":{"index":"fire","name":"Fire","url":"/api/2024/damage-types/fire"},"species":{"index":"dragonborn","name":"Dragonborn","url":"/api/2024/species/dragonborn"},"traits":[{"index":"draconic-breath-weapon-fire","url":"/api/2024/traits/draconic-breath-weapon-fire","name":"Breath Weapon: Fire","level":1},{"index":"draconic-damage-resistance-fire","url":"/api/2024/traits/draconic-damage-resistance-fire","name":"Damage Resistance: Fire","level":1}]}'::jsonb),
