  ('336a0121-bb51-47b7-8125-a40673d53a77', 'subspecies', '{"name":"Draconic Ancestor: Silver","desc":null}'::jsonb, '{"index":"draconic-ancestor-silver","url":"/api/2024/subspecies/draconic-ancestor-silver","name":"Draconic Ancestor: Silver","damage_type":{"index":"cold","name":"Cold","url":"/api/2024/damage-types/cold"},"species":{"index":"dragonborn","name":"Dragonborn","url":"/api/2024/species/dragonborn"},"traits":[{"index":"draconic-breath-weapon-cold","url":"/api/2024/traits/draconic-breath-weapon-cold","name":"Breath Weapon: Cold","level":1},{"index":"draconic-damage-resistance-cold","url":"/api/2024/traits/draconic-damage-resistance-cold","name":"Damage Resistance: Cold","level":1}]}'::jsonb),
  ('336a0121-bb51-47b7-8125-a40673d53a77', 'subspecies', '{"name":"Draconic Ancestor: White","desc":null}'::jsonb, '{"index":"draconic-ancestor-white","url":"/api/2024/subspecies/draconic-ancestor-white","name":"Draconic Ancestor: White","damage_type":{"index":"cold","name":"Cold","url":"/api/2024/damage-types/cold"},"species":{"index":"dragonborn","name":"Dragonborn","url":"/api/2024/species/dragonborn"},"traits":[{"index":"draconic-breath-weapon-cold","url":"/api/2024/traits/draconic-breath-weapon-cold","name":"Breath Weapon: Cold","level":1},{"index":"draconic-damage-resistance-cold","url":"/api/2024/traits/draconic-damage-resistance-cold","name":"Damage Resistance: Cold","level":1}]}'::jsonb),
